#!/usr/bin/env node

// 加载自动训练和智能CPU配置
import { loadAutoTrainConfig, saveAutoTrainConfig, getCpuUsage, getSmartCpuThreshold } from './auto_train_config.js';

// ESM模块中启用 require()（兼容原有CommonJS代码）
import { createRequire } from 'module';
const require = createRequire(import.meta.url);

// 初始化全局自动训练配置(默认开启)
global.xgboostAutoTrainConfig = {
  autoTrain: true,
  startDelayMs: 60000,
  modelsToAutoTrain: ['xgboost', 'lightgbm', 'randomforest']
};

// 全局动态CPU阈值
global.dynamicCpuThreshold = 80;

// 加载自动训练配置
loadAutoTrainConfig();

// 定时更新智能CPU阈值(每1分钟)
setInterval(() => {
  global.dynamicCpuThreshold = getSmartCpuThreshold();
  console.log(`[Smart CPU] 动态阈值更新为: ${global.dynamicCpuThreshold}%`);
}, 60 * 1000);

// 启动时立即更新一次
global.dynamicCpuThreshold = getSmartCpuThreshold();

// 北京时间工具(所有时间戳统一使用 Asia/Shanghai UTC+8)
const TZ_OFFSET = 8 * 60; // UTC+8,单位分钟
function toBeijingTime(date) {
  if (!date) return toBeijingTime(new Date());
  // 字符串/数字 → 转换为Date对象后再处理
  if (typeof date !== 'object' || !(date instanceof Date)) {
    date = new Date(date);
  }
  if (isNaN(date.getTime())) return toBeijingTime(new Date()); // 无效日期用当前时间
  const utc = date.getTime() + date.getTimezoneOffset() * 60000;
  return new Date(utc + TZ_OFFSET * 60000);
}
function bjISO(date) {
  const d = toBeijingTime(date || new Date());
  const pad = n => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) + 'T' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds()) + '.000+08:00';
}
// 确保关键工具函数在全局可用(修复ESM模块加载时序问题)
globalThis.bjISO = bjISO;
globalThis.bjNow = bjNow;
globalThis.toBeijingTime = toBeijingTime;
// 北京时间紧凑字符串(用于文件名等): 'YYYYMMDDHHMMSS'
function bjNowStr() {
  const d = toBeijingTime(new Date());
  const pad = n => String(n).padStart(2, '0');
  return d.getFullYear() + pad(d.getMonth()+1) + pad(d.getDate()) + pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds());
}
globalThis.bjNowStr = bjNowStr;
// 北京时间字符串,兼容SQLite datetime格式: 'YYYY-MM-DD HH:MM:SS'
function bjNow() {
  const d = toBeijingTime(new Date());
  const pad = n => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}
// 北京时间偏移字符串(替代 datetime('now', '+N hours')):'YYYY-MM-DD HH:MM:SS'
function bjFuture(hours) {
  const d = toBeijingTime(new Date(Date.now() + hours * 3600000));
  const pad = n => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}
// 北京时间过去偏移字符串(替代 datetime('now', '-N day')):'YYYY-MM-DD HH:MM:SS'
function bjPast(days) {
  const d = toBeijingTime(new Date(Date.now() - days * 86400000));
  const pad = n => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}
// 【涨停阈值】根据股票代码返回涨停幅度百分比
// 主板:10%, 创业板(300/301):20%, 科创板(688/689):20%, 北交所(8/4开头6位):30%, ST股:5%
function getLimitPct(code, name) {
  if (!code) return 10;
  const c = String(code).replace(/^(sh|sz)/, '');
  if ((name && (name.includes('ST') || name.includes('*ST')))) return 5;
  if (c.startsWith('300') || c.startsWith('301')) return 20; // 创业板
  if (c.startsWith('688') || c.startsWith('689')) return 20; // 科创板
  if (c.startsWith('8') || c.startsWith('4')) return 30;   // 北交所
  return 10; // 主板
}
// 判断是否涨停/跌停(考虑板块差异)
function isLimitPrice(code, changePercent, name) {
  const limitPct = getLimitPct(code, name);
  return Math.abs(changePercent) >= limitPct - 0.5; // 留0.5%误差
}

// 【交易时段限制】判断当前是否为A股交易时段
function isTradingHours() {
  const now = toBeijingTime(new Date()); // 强制北京时间,兼容非东八区服务器
  const day = now.getDay(); // 0=周日, 6=周六
  const h = now.getHours();
  const m = now.getMinutes();

  // 周末不是交易日,直接返回false
  if (day === 0 || day === 6) return false;
  // A股: 9:00-11:30 | 13:00-15:00(北京时间)
  const morning = (h === 9) || (h === 10) || (h === 11 && m < 30);
  const afternoon = (h === 13) || (h === 14) || (h === 15 && m === 0);
  const isTradeTime = morning || afternoon;

  // 【BUG修复 2026-04-30】交易时段直接返回true,不再被缓存覆盖
  // 旧Bug: global._offHoursTrading=false 缓存后导致永远返回false,交易时段也被拦截
  if (isTradeTime) return true;

  // 非交易时段:检查是否允许盘后交易(每次查库,不缓存)
  try {
    const row = db.prepare("SELECT value FROM yaodi_config WHERE key='allow_offhours_trading'").get();
    return row ? (row.value === 'true' || row.value === '1' || row.value === '1.0') : false;
  } catch(e) { return false; }
}
function bjDate(date) { return toBeijingTime(date || new Date()).toISOString().split('T')[0]; }
// 确保 bjDate 在全局可用
globalThis.bjDate = bjDate;

// ═════════════════════════════════════════════════════════════════════════════════
// A股交易规则工具函数
// ═════════════════════════════════════════════════════════════════════════════════

// A股T+1检查:当日买入的股票不能卖出
function canSellByT1(buyDateStr) {
  if (!buyDateStr) return true; // 无买入日期记录的旧数据允许卖出
  const buyDate = buyDateStr.split(' ')[0] || buyDateStr.split('T')[0]; // 取日期部分
  const today = bjDate(); // 北京时间日期
  return buyDate < today; // 买入日期严格早于今天才可卖
}

// A股涨跌停价格计算
function getPriceLimit(code, currentPrice) {
  if (!code || !currentPrice || currentPrice <= 0) return { limitUp: currentPrice * 1.1, limitDown: currentPrice * 0.9, pct: 10 };
  let pct = 10; // 主板默认±10%
  // 科创板(688xxx)和创业板(300xxx/301xxx)±20%
  if (code.startsWith('688') || code.startsWith('300') || code.startsWith('301')) pct = 20;
  // 北交所(8xxxxx/4xxxxx)±30%
  else if (code.startsWith('8') || code.startsWith('4')) pct = 30;
  // ST股±5%(通过名称判断)
  const nameRow = db.prepare("SELECT name FROM shundi_mock_holdings WHERE code=?").get(code)
    || db.prepare("SELECT name FROM stock_realtime WHERE code=?").get(code);
  if (nameRow && nameRow.name && (nameRow.name.startsWith('ST') || nameRow.name.startsWith('*ST'))) pct = 5;

  return {
    limitUp: Math.round(currentPrice * (1 + pct / 100) * 100) / 100,
    limitDown: Math.round(currentPrice * (1 - pct / 100) * 100) / 100,
    pct
  };
}

// A股合规交易成本计算(佣金万2.5最低5元 + 印花税千1卖出 + 过户费十万分之1.5)
function calcAStockCost(amount, direction) {
  const commission = Math.max(5, amount * 0.00025);         // 佣金:万2.5,最低5元
  const stampTax = direction === 'sell' ? amount * 0.001 : 0; // 印花税:千1,仅卖出
  const transferFee = amount * 0.000015;                      // 过户费:十万分之1.5
  return {
    commission,
    stampTax,
    transferFee,
    total: commission + stampTax + transferFee
  };
}

// A股交易合规检查(买入前综合校验)
function validateAStockBuy(code, price, shares, available) {
  const amount = price * shares;
  const cost = calcAStockCost(amount, 'buy');
  const errors = [];

  if (!isTradingHours()) errors.push('非交易时段');
  if (shares % 100 !== 0) errors.push('买入数量必须为100的整数倍');
  if (shares < 100) errors.push('买入最少100股');
  if (amount + cost.total > available) errors.push('资金不足(含手续费)');

  return { valid: errors.length === 0, errors, cost };
}

// A股交易合规检查(卖出前综合校验)
function validateAStockSell(code, price, shares, holding) {
  const cost = calcAStockCost(price * shares, 'sell');
  const errors = [];

  if (!isTradingHours()) errors.push('非交易时段');
  if (!holding) { errors.push('无持仓'); return { valid: false, errors, cost }; }
  if (shares > holding.shares) errors.push('卖出数量超过持仓');

  // T+1检查
  if (!canSellByT1(holding.buy_date)) errors.push('T+1限制:当日买入不可卖出');

  // 零股检查:只有清仓时才能卖不足100股的尾数
  const remaining = holding.shares - shares;
  if (remaining > 0 && remaining < 100) errors.push('剩余股份不足100股,只能全部卖出或卖出整手');

  return { valid: errors.length === 0, errors, cost };
}



// ─── 回测引擎(四种策略)─────────────────────────────────────────────────────
function backtestStock(rows, strategies = ['ma_cross', 'macd_cross', 'rsi_reversal', 'bollinger']) {
  const results = {};
  const closes = rows.map(r => r.close);

  const sma = (arr, n, endIdx) => {
    if (endIdx < n) return arr[endIdx];
    return arr.slice(endIdx - n, endIdx).reduce((a, b) => a + b, 0) / n;
  };
  const ema = (arr, n, endIdx) => {
    if (endIdx < 1) return arr[endIdx];
    const k = 2 / (n + 1);
    let result = arr[endIdx - 1];
    for (let i = endIdx - 2; i >= Math.max(0, endIdx - n * 3); i--) {
      result = arr[i] * k + result * (1 - k);
    }
    return result;
  };

  // 均线交叉策略
  if (strategies.includes('ma_cross')) {
    let trades = 0, wins = 0, totalRet = 0, pos = null;
    for (let i = 21; i < rows.length; i++) {
      const ma5prev = sma(closes, 5, i - 1), ma20prev = sma(closes, 20, i - 1);
      const ma5cur = sma(closes, 5, i), ma20cur = sma(closes, 20, i);
      if (ma5prev <= ma20prev && ma5cur > ma20cur && !pos) { pos = { buy: closes[i] }; }
      else if (ma5prev >= ma20prev && ma5cur < ma20cur && pos) {
        const ret = (closes[i] - pos.buy) / pos.buy * 100;
        totalRet += ret; trades++; if (ret > 0) wins++; pos = null;
      }
    }
    if (pos) { const ret = (closes[closes.length-1] - pos.buy) / pos.buy * 100; totalRet += ret; trades++; if (ret > 0) wins++; }
    results['ma_cross'] = { success: trades > 0, total_trades: trades, won_trades: wins, win_rate: trades > 0 ? Number((wins/trades*100).toFixed(1)) : 0, total_return: parseFloat(totalRet.toFixed(2)), avg_return: trades > 0 ? parseFloat((totalRet/trades).toFixed(2)) : 0 };
  }

  // MACD金叉死叉策略
  if (strategies.includes('macd_cross')) {
    let trades = 0, wins = 0, totalRet = 0, pos = null;
    for (let i = 35; i < rows.length; i++) {
      const e12p = ema(closes, 12, i - 1), e26p = ema(closes, 26, i - 1);
      const e12c = ema(closes, 12, i), e26c = ema(closes, 26, i);
      const difP = e12p - e26p, difC = e12c - e26c;
      if (difP <= 0 && difC > 0 && !pos) { pos = { buy: closes[i] }; }
      else if (difP >= 0 && difC < 0 && pos) {
        const ret = (closes[i] - pos.buy) / pos.buy * 100;
        totalRet += ret; trades++; if (ret > 0) wins++; pos = null;
      }
    }
    if (pos) { const ret = (closes[closes.length-1] - pos.buy) / pos.buy * 100; totalRet += ret; trades++; if (ret > 0) wins++; }
    results['macd_cross'] = { success: trades > 0, total_trades: trades, won_trades: wins, win_rate: trades > 0 ? Number((wins/trades*100).toFixed(1)) : 0, total_return: parseFloat(totalRet.toFixed(2)), avg_return: trades > 0 ? parseFloat((totalRet/trades).toFixed(2)) : 0 };
  }

  // RSI超买超卖反转策略
  if (strategies.includes('rsi_reversal')) {
    let trades = 0, wins = 0, totalRet = 0, pos = null;
    for (let i = 15; i < rows.length; i++) {
      const slice = closes.slice(i - 14, i + 1);
      const gains = [], losses = [];
      for (let j = 1; j < slice.length; j++) {
        const d = slice[j] - slice[j-1];
        if (d > 0) gains.push(d); else if (d < 0) losses.push(-d);
      }
      const avgGain = gains.length ? gains.reduce((a,b)=>a+b)/14 : 0;
      const avgLoss = losses.length ? losses.reduce((a,b)=>a+b)/14 : 0;
      const rsi = avgLoss > 0 ? 100 - 100/(1 + avgGain/avgLoss) : 50;
      if (rsi < 30 && !pos) { pos = { buy: closes[i] }; }
      else if (rsi > 65 && pos) {
        const ret = (closes[i] - pos.buy) / pos.buy * 100;
        totalRet += ret; trades++; if (ret > 0) wins++; pos = null;
      }
    }
    if (pos) { const ret = (closes[closes.length-1] - pos.buy) / pos.buy * 100; totalRet += ret; trades++; if (ret > 0) wins++; }
    results['rsi_reversal'] = { success: trades > 0, total_trades: trades, won_trades: wins, win_rate: trades > 0 ? Number((wins/trades*100).toFixed(1)) : 0, total_return: parseFloat(totalRet.toFixed(2)), avg_return: trades > 0 ? parseFloat((totalRet/trades).toFixed(2)) : 0 };
  }

  // 布林带突破策略
  if (strategies.includes('bollinger')) {
    let trades = 0, wins = 0, totalRet = 0, pos = null;
    for (let i = 21; i < rows.length; i++) {
      const slice = closes.slice(i - 20, i + 1);
      const mean = slice.reduce((a,b)=>a+b,0)/20;
      const variance = slice.reduce((a,c)=>a+(c-mean)**2,0)/20;
      const lower = mean - 2 * Math.sqrt(variance);
      const upper = mean + 2 * Math.sqrt(variance);
      if (closes[i] <= lower && !pos) { pos = { buy: closes[i] }; }
      else if (closes[i] >= upper && pos) {
        const ret = (closes[i] - pos.buy) / pos.buy * 100;
        totalRet += ret; trades++; if (ret > 0) wins++; pos = null;
      }
    }
    if (pos) { const ret = (closes[closes.length-1] - pos.buy) / pos.buy * 100; totalRet += ret; trades++; if (ret > 0) wins++; }
    results['bollinger'] = { success: trades > 0, total_trades: trades, won_trades: wins, win_rate: trades > 0 ? Number((wins/trades*100).toFixed(1)) : 0, total_return: parseFloat(totalRet.toFixed(2)), avg_return: trades > 0 ? parseFloat((totalRet/trades).toFixed(2)) : 0 };
  }

  return results;
}

// ─── 工具函数 ─────────────────────────────────────────────────────────────────

// ── 【Phase1进化 2026-07-06】市场格局识别引擎 ──────────────────────────────────
// 判断依据: 上证指数 + 深证成指 + 创业板指的均线排列、BOLL带宽、RSI
// 输出4种格局: BULL(多头) / BEAR(空头) / RANGE(震荡) / HIGH_VOL(高波动)
function detectMarketRegime() {
  try {
    // 读取上证指数近120日K线
    const idxRows = db.prepare(`
      SELECT date, open, high, low, close, volume
      FROM stock_history WHERE code='sh000001'
      ORDER BY date DESC LIMIT 120
    `).all().reverse();

    if (idxRows.length < 60) return 'RANGE'; // 数据不足默认震荡

    // 计算MA
    const ma = (rows, period) => {
      const slice = rows.slice(-period);
      if (slice.length < period) return null;
      return slice.reduce((s, r) => s + r.close, 0) / period;
    };
    const ma5  = ma(idxRows, 5);
    const ma20 = ma(idxRows, 20);
    const ma60 = ma(idxRows, 60);
    const ma120 = ma(idxRows, 120);
    const current = idxRows[idxRows.length - 1]?.close || 0;
    const prev20  = idxRows[idxRows.length - 21]?.close || current;

    // RSI(14)
    const gains = [], losses = [];
    for (let i = idxRows.length - 14; i < idxRows.length; i++) {
      const chg = idxRows[i].close - (idxRows[i-1]?.close || idxRows[i].close);
      gains.push(Math.max(chg, 0));
      losses.push(Math.max(-chg, 0));
    }
    const avgGain = gains.reduce((s,v)=>s+v,0)/14;
    const avgLoss = losses.reduce((s,v)=>s+v,0)/14;
    const rs = avgLoss > 0 ? avgGain/avgLoss : 100;
    const rsi = 100 - 100/(1+rs);

    // BOLL带宽（波动率）
    const recent20 = idxRows.slice(-20);
    const mean20 = recent20.reduce((s,r)=>s+r.close,0)/20;
    const std20 = Math.sqrt(recent20.reduce((s,r)=>s+(r.close-mean20)**2,0)/20);
    const bollingerWidth = std20 / mean20;
    const histWidths = recent20.map((_, i) => {
      const w = i < 19 ? recent20.slice(i,i+20) : recent20;
      const m = w.reduce((s,r)=>s+r.close,0)/w.length;
      return Math.sqrt(w.reduce((s,r)=>s+(r.close-m)**2,0)/w.length)/m;
    });
    const medianWidth = histWidths.sort((a,b)=>a-b)[Math.floor(histWidths.length/2)] || bollingerWidth;
    const widthPct = bollingerWidth / medianWidth; // 当前/历史中位数

    // ADX近似（用动量代替方向性）
    const momentum = (current - prev20) / prev20; // 20日动量

    // ── 格局判断 ──
    let regime = 'RANGE';
    const upCount = (db.prepare("SELECT COUNT(*) as c FROM market_stats ORDER BY id DESC LIMIT 1").get()?.up_count || 0);
    const totalCount = (db.prepare("SELECT COUNT(*) as c FROM market_stats ORDER BY id DESC LIMIT 1").get()?.total_count || 1);
    const upRatio = upCount / Math.max(totalCount, 1);
    const idxChg = db.prepare("SELECT change_percent FROM stock_realtime WHERE code='sh000001' LIMIT 1").get()?.change_percent || 0;

    if (widthPct > 1.25) {
      regime = 'HIGH_VOL'; // BOLL带宽扩大=高波动
    } else if (ma5 > ma20 && ma20 > ma60 && ma120 > 0 && current > ma5 && rsi < 80) {
      regime = 'BULL'; // 多头排列
    } else if ((ma5 < ma20 || current < ma5) && rsi > 55) {
      regime = 'BEAR'; // 【修正】非多头+RSI偏高=空头倾向（RSI>65偏贵，上涨难）
    } else if (ma5 < ma20 && ma20 < ma60 && current < ma5 && rsi > 20) {
      regime = 'BEAR'; // 经典空头排列
    } else {
      regime = 'RANGE'; // 震荡
    }

    // 覆盖逻辑：大盘崩跌时强制BEAR
    if (idxChg < -2 || upRatio < 0.30) {
      regime = 'BEAR';
    }
    // 大盘暴涨时强化BULL
    if (idxChg > 2 && upRatio > 0.70) {
      regime = 'BULL';
    }

    const regimeEmoji = { BULL:'🟢', BEAR:'🔴', RANGE:'🟡', HIGH_VOL:'⚡' };
    console.log(`[市场格局] ${regimeEmoji[regime]} ${regime} | MA5=${ma5?.toFixed(1)}, MA20=${ma20?.toFixed(1)}, MA60=${ma60?.toFixed(1)}, RSI=${rsi.toFixed(1)}, 宽度比=${widthPct.toFixed(2)}, 指数涨跌=${idxChg.toFixed(2)}%, 涨跌比=${(upRatio*100).toFixed(0)}%`);
    return regime;
  } catch(e) {
    console.log('[市场格局] 检测异常:', e.message);
    return 'RANGE';
  }
}

// ── 【Phase1进化】格局驱动的舜帝选股参数 ────────────────────────────────────────
function getRegimeTradingParams(regime) {
  const PARAMS = {
    BULL: {
      buyThreshold: 50,     // 降低买入门槛（顺势而为）
      stopLossPct: -5,      // 宽松止损
      takeProfitPct: 12,     // 扩大止盈（让利润奔跑）
      maxPosition: 100,     // 满仓操作
      shortSelling: false,
      desc: '🟢 多头格局: 追涨杀跌，顺势而为'
    },
    BEAR: {
      buyThreshold: 72,      // 提高买入门槛（严格筛选）
      stopLossPct: -3,      // 严格止损
      takeProfitPct: 6,      // 保守止盈
      maxPosition: 30,       // 轻仓
      shortSelling: false,
      desc: '🔴 空头格局: 严格止损，轻仓快进快出'
    },
    RANGE: {
      buyThreshold: 60,      // 中等门槛
      stopLossPct: -4,      // 标准止损
      takeProfitPct: 8,      // 标准止盈
      maxPosition: 60,      // 半仓
      shortSelling: false,
      desc: '🟡 震荡格局: 高抛低吸，网格交易'
    },
    HIGH_VOL: {
      buyThreshold: 75,      // 等待方向明确
      stopLossPct: -3,      // 极严格止损
      takeProfitPct: 5,      // 快速止盈
      maxPosition: 20,      // 极轻仓
      shortSelling: false,
      desc: '⚡ 高波动格局: 等待BOLL收口，缩量整理后介入'
    }
  };
  return PARAMS[regime] || PARAMS['RANGE'];
}

// ═══════════════════════════════════════════════════════════════════
// Phase 2 板块相对强弱引擎 (2026-07-06)
// ═══════════════════════════════════════════════════════════════════

// 板块强弱缓存（5分钟更新一次）
let _sectorStrengthCache = { sectors: [], strongSectors: [], weakSectors: [], updatedAt: null };

function getStrongSectors() {
  // 返回今日强势板块列表（近5日累计涨幅排行前30%，momentum='偏强'）
  const today = bjISO().slice(0, 10);
  const recent = bjPast(5); // 近5天
  const rows = db.prepare(`
    SELECT sector_code, sector_name,
           AVG(cycle_change) as avg_change,
           MAX(cycle_rank) as cycle_rank,
           (SELECT MAX(cycle_date) FROM sector_history sh2 WHERE sh2.sector_code = sh.sector_code) as latest_date
    FROM sector_history sh
    WHERE cycle_date >= ?
    GROUP BY sector_code
    ORDER BY AVG(cycle_change) DESC
  `).all(recent.slice(0, 10)); // avg_change 来自AVG(cycle_change)计算，非存储列

  if (!rows || rows.length === 0) {
    // 回退：用最新一天数据
    const latest = db.prepare(`
      SELECT sector_code, sector_name, avg_change, momentum, cycle_rank
      FROM sector_rotation WHERE date = ?
      ORDER BY avg_change DESC
    `).all(today);
    if (latest && latest.length > 0) {
      const strong = latest.slice(0, Math.max(1, Math.floor(latest.length * 0.3)));
      const weak = latest.slice(-Math.max(1, Math.floor(latest.length * 0.3)));
      _sectorStrengthCache = {
        sectors: latest,
        strongSectors: strong,
        weakSectors: weak,
        updatedAt: bjISO()
      };
      return { sectors: latest, strongSectors: strong, weakSectors: weak };
    }
    return _sectorStrengthCache;
  }

  // 按近5日平均涨幅排序，取前30%为强势，后30%为弱势
  rows.sort((a, b) => (b.avg_change || 0) - (a.avg_change || 0));
  const cutoff = Math.max(1, Math.floor(rows.length * 0.3));
  const strong = rows.slice(0, cutoff).map(r => ({ code: r.sector_code, name: r.sector_name, change: r.avg_change || 0 }));
  const weak = rows.slice(-cutoff).map(r => ({ code: r.sector_code, name: r.sector_name, change: r.avg_change || 0 }));

  _sectorStrengthCache = { sectors: rows, strongSectors: strong, weakSectors: weak, updatedAt: bjISO() };
  return _sectorStrengthCache;
}

function getSectorStrength(sectorCode) {
  // 判断某板块属于强势/弱势/中性
  if (!_sectorStrengthCache.sectors || _sectorStrengthCache.sectors.length === 0) {
    // 触发缓存更新
    getStrongSectors();
  }
  const strong = _sectorStrengthCache.strongSectors.some(s => s.code === sectorCode);
  const weak = _sectorStrengthCache.weakSectors.some(s => s.code === sectorCode);
  if (strong) return 'strong';
  if (weak) return 'weak';
  return 'neutral';
}

function getSectorMomentumDesc() {
  const { strongSectors, weakSectors } = _sectorStrengthCache;
  if (!strongSectors || !weakSectors || strongSectors.length === 0) return null;
  const strongNames = strongSectors.slice(0, 3).map(s => s.name).join('、');
  const weakNames = weakSectors.slice(0, 3).map(s => s.name).join('、');
  return { strongNames, weakNames, updatedAt: _sectorStrengthCache.updatedAt };
}

function isSectorsFresh() {
  if (!_sectorStrengthCache.updatedAt) return false;
  return (Date.now() - new Date(_sectorStrengthCache.updatedAt).getTime()) < 5 * 60 * 1000;
}

// 定时更新板块强弱（每5分钟，交易时段）
function scheduleSectorStrengthUpdate() {
  setInterval(() => {
    if (!isTradingHours()) return;
    if (isSectorsFresh()) return;
    try {
      getStrongSectors();
      console.log(`[板块轮动] 强势:${_sectorStrengthCache.strongSectors.map(s=>s.name).join(',') || '无'} | 弱势:${_sectorStrengthCache.weakSectors.map(s=>s.name).join(',') || '无'}`);
    } catch(e) {
      console.log(`[板块轮动] 更新失败: ${e.message}`);
    }
  }, 5 * 60 * 1000); // 5分钟
}

function computeFactorStats(stockPool) {
  if (!stockPool || stockPool.length === 0) return {};
  const factors = ['value_score', 'momentum_score', 'quality_score', 'volatility_score', 'size_score'];
  const stats = {};
  for (const f of factors) {
    const vals = stockPool.map(s => s[f] || 0).sort((a, b) => a - b);
    const n = vals.length;
    const mean = vals.reduce((a, b) => a + b, 0) / n;
    const p50 = n % 2 === 0 ? (vals[n / 2 - 1] + vals[n / 2]) / 2 : vals[Math.floor(n / 2)];
    const p25 = vals[Math.floor(n * 0.25)];
    const p75 = vals[Math.floor(n * 0.75)];
    stats[f] = { mean: parseFloat(mean.toFixed(2)), p25: parseFloat(p25.toFixed(2)), p50: parseFloat(p50.toFixed(2)), p75: parseFloat(p75.toFixed(2)), min: parseFloat(vals[0].toFixed(2)), max: parseFloat(vals[n - 1].toFixed(2)) };
    stats[f + '_strong'] = vals.filter(v => v >= 70).length;
    stats[f + '_weak'] = vals.filter(v => v <= 30).length;
    const sorted = [...stockPool].sort((a, b) => (b[f] || 0) - (a[f] || 0));
    stats[f + '_top3'] = sorted.slice(0, 3).map(s => ({ code: s.code, name: s.name || s.code, score: parseFloat((s[f] || 0).toFixed(2)) }));
  }
  const l1Scores = stockPool.map(s => s.l1_total_score || 0).sort((a, b) => a - b);
  const n = l1Scores.length;
  stats['l1_total_score'] = {
    mean: parseFloat((l1Scores.reduce((a, b) => a + b, 0) / n).toFixed(2)),
    p50: parseFloat((n % 2 === 0 ? (l1Scores[n / 2 - 1] + l1Scores[n / 2]) / 2 : l1Scores[Math.floor(n / 2)]).toFixed(2)),
    min: parseFloat(l1Scores[0].toFixed(2)), max: parseFloat(l1Scores[n - 1].toFixed(2)),
  };
  stats._count = n;
  return stats;
}

