// ═══════════════════════════════════════════════════════════════
// 【新增 2026-05-07】统一HTTP请求封装 - 解决fetch兼容性问题
// ═══════════════════════════════════════════════════════════════
async function safeHttpFetch(url, options = {}) {
  const { headers = {}, timeout = 8000, responseType = 'json' } = options;

  // 优先使用axios(更稳定)
  try {
    const response = await axios({
      method: options.method || 'GET',
      url,
      headers,
      timeout,
      responseType: responseType === 'text' ? 'text' : 'json',
      validateStatus: (status) => status < 500 // 不抛出HTTP错误
    });

    // 返回类fetch Response对象
    return {
      ok: response.status >= 200 && response.status < 300,
      status: response.status,
      statusText: response.statusText,
      json: async () => response.data,
      text: async () => typeof response.data === 'string' ? response.data : JSON.stringify(response.data),
      _axios: true
    };
  } catch (e) {
    // axios失败,尝试原生fetch
    if (typeof fetch === 'function') {
      try {
        const res = await fetch(url, { ...options, headers });
        if (res && typeof res.json === 'function') {
          return res;
        }
      } catch (fetchErr) {
        console.log(`[HTTP] axios和fetch均失败: ${url} - ${fetchErr.message}`);
      }
    }
    throw e;
  }
}

