// 【尧帝自主数据获取】使用 /usr/bin/curl 异步执行(避免 Node.js fetch 的 SSL 问题)
// 传入 async 函数,在其中使用 exec(异步),通过 AbortSignal 实现真正的超时取消
function withTimeout(fn, ms) {
  return Promise.race([fn(), new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms))]);
}
function execCurlAsync(url, options = {}) {
  const headers = options.headers || {};
  const headerParts = Object.entries(headers).map(([k, v]) => `-H "${k}: ${v}"`).join(' ');
  const cmd = `/usr/bin/curl -s --max-time 5 ${headerParts} "${url}"`;
  const { exec } = require('child_process');
  return new Promise((resolve, reject) => {
    exec(cmd, { encoding: 'utf8', timeout: 8000 }, (err, stdout, stderr) => {
      if (err) { resolve(''); return; } // curl 错误 → 返回空字符串
      resolve(stdout);
    });
  });
}

// 【关键】使用 curl 替代 Node.js fetch,避免 SSL 证书问题
function execCurl(url, options = {}) {
  try {
    const headers = options.headers || {};
    const headerStr = Object.entries(headers).map(([k, v]) => `-H "${k}: ${v}"`).join(' ');
    const cmd = `/usr/bin/curl -s --max-time 5 ${headerStr} "${url}"`;
    const { execSync } = require('child_process');
    const result = execSync(cmd, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'], timeout: 8000 });
    return result;
  } catch (e) {
    return '';
  }
}

