// ═══════════════════════════════════════════════════════════════
// 单次请求超时(毫秒)
const REQUEST_TIMEOUT = 5000;

// 连续失败阈值(超过此数标记为不健康,降权使用)
const FAILURE_THRESHOLD = 3;

// 【新增】数据源健康检查间隔(每5分钟)
const DATASOURCE_HEALTH_CHECK_INTERVAL = 5 * 60 * 1000;

// 【新增】数据源状态持久化
