// 新闻情绪分析
function analyzeNewsSentiment(title) {
  if (!title) return 0;

  const positiveKeywords = ['上涨', '利好', '突破', '新高', '反弹', '走强', '流入', '增持', '看好', '涨', '牛', '盈利', '增长', '突破'];
  const negativeKeywords = ['下跌', '利空', '暴跌', '新低', '跳水', '走弱', '流出', '减持', '看空', '跌', '熊', '亏损', '下滑', '破位'];

  let score = 0;
  positiveKeywords.forEach(kw => {
    if (title.includes(kw)) score += 0.1;
  });
  negativeKeywords.forEach(kw => {
    if (title.includes(kw)) score -= 0.1;
  });

  return Math.max(-1, Math.min(1, score));
}

// 获取综合新闻(多源聚合)
// 【尧帝自主数据获取】fetchAllNews
// 使用多源级联降级框架,任一源成功即返回,全部失败返回 null(符合铁律)
async function fetchAllNews() {
  const now = bjDate();

  // 检查缓存
  if (newsCache.data.length > 0 && now - newsCache.lastUpdate < newsCache.ttl) {
    return newsCache.data;
  }

  console.log('📰 正在获取财经新闻(尧帝自主选择最优源)...');

  // ── 策略1:多源级联降级(自动找可用源)──
  const newsFromBest = await fetchWithFallback('news', { label: '新闻' });

  // ── 策略2:若级联降级失败,尝试逐个轮询所有源(收集所有可用的数据)──
  let allNews = [];
  if (newsFromBest && newsFromBest.length > 0) {
    allNews = newsFromBest;
  } else {
    // 所有源级联都失败 → 逐个备用源尝试收集数据
    const backupSources = [
      fetchNewsFromEastMoney_bak(),
      fetchNewsFromSina(),
      fetchNewsFromTencent(),
      fetchNewsFromNetEase_bak(),
      fetchNewsFromCaixin_bak(),
      fetchNewsFromPhoenix_bak()
    ];
    const results = await Promise.allSettled(backupSources);
    const validResults = results
      .filter(r => r.status === 'fulfilled' && Array.isArray(r.value) && r.value.length > 0)
      .map(r => r.value);
    allNews = validResults.flat();
    if (allNews.length > 0) {
      console.log(`🔧 [新闻] 备用源轮询成功,共收集 ${allNews.length} 条`);
    }
  }

  // 合并去重
  const seen = new Set();
  const uniqueNews = allNews.filter(item => {
    if (!item?.title) return false;
    if (seen.has(item.title)) return false;
    seen.add(item.title);
    return true;
  });

  // 按热度排序
  uniqueNews.sort((a, b) => {
    if (a.hot && !b.hot) return -1;
    if (!a.hot && b.hot) return 1;
    return Math.abs(b.sentiment || 0) - Math.abs(a.sentiment || 0);
  });

  // 更新缓存(即使为空也记录,避免无限重试)
  newsCache.data = uniqueNews.slice(0, 50);
  newsCache.lastUpdate = now;

  if (newsCache.data.length > 0) {
    console.log(`✅ 📰 新闻获取完成: ${newsCache.data.length}条`);
  } else {
    console.warn(`⚠️ 📰 新闻获取完成: 0条(所有数据源均失败)`);
  }

  return newsCache.data;
}

