// 获取港股行情(恒生指数)
async function fetchHKMarket() {
  try {
    const axios = (await import('axios')).default;
    // 新浪港股API
    const response = await axios.get('https://hq.sinajs.cn/list=hkHSI', {
      headers: { 'Referer': 'https://finance.sina.com.cn' },
      timeout: 5000
    });

    const data = response.data;
    const match = data.match(/hkHSI="(.*)"/);
    if (match) {
      const parts = match[1].split(',');
      const name = parts[0]; // 恒生指数
      const price = parseFloat(parts[6]);
      const change = parseFloat(parts[7]);
      const changePercent = parseFloat(parts[8]);
      return {
        index: '恒生指数',
        code: 'HSI',
        price,
        change,
        changePercent,
        status: 'open'
      };
    }
    return null;
  } catch (e) {
    console.error('港股行情获取失败:', e.message);
    return null;
  }
}

