// 获取全部跨市场数据
async function fetchAllCrossMarket() {
  const now = bjDate();

  // 检查缓存
  if (crossMarketCache.data && now - crossMarketCache.lastUpdate < crossMarketCache.ttl) {
    return crossMarketCache.data;
  }

  console.log('🌍 正在获取跨市场行情...');

  const [hk, us, commodities] = await Promise.all([
    fetchHKMarket(),
    fetchUSMarket(),
    fetchCommodities()
  ]);

  const result = {
    hk: hk,
    us: us,
    commodities: commodities,
    timestamp: bjISO()
  };

  // 更新缓存
  crossMarketCache.data = result;
  crossMarketCache.lastUpdate = now;

  console.log('🌍 跨市场行情获取完成');
  return result;
}

