// 社交情绪缓存
let socialSentimentCache = {
  data: null,
  lastUpdate: 0,
  ttl: 5 * 60 * 1000 // 5分钟缓存
};

// 情绪分析函数
// ═══════════════════════════════════════════════════════════════
// 【感知层增强v2】精细化情绪分析(优化维度1)
// 升级:从简单的bullish/bearish二分类 → 6维情绪精细化分析
// 支持:恐慌/贪婪/政策预期/技术回调/机构动向/市场总览
// ═══════════════════════════════════════════════════════════════

/**
 * 精细化情绪词典(6大类)
 * - fear: 恐慌情绪(暴跌/踩踏/闪崩)
 * - greed: 贪婪情绪(涨停/疯涨/爆发)
 * - policy: 政策预期(降息/加息/补贴/监管)
 * - technical: 技术回调意愿(超买/超卖/背离)
 * - institutional: 机构动向(增持/减持/回购/IPO)
 * - macro: 宏观情绪(经济/外贸/汇率)
 */
const EMOTION_DICTIONARY = {
  fear: {
    keywords: ['暴跌', '闪崩', '踩踏', '恐慌', '崩盘', '溃败', '大跌', '重挫', '跳水', '砸盘', '恐慌性', '踩踏式', '系统性风险', '全面暴跌', '集体跌停'],
    weight: -1.0
  },
  greed: {
    keywords: ['涨停', '疯涨', '爆发', '狂飙', '井喷', '涨停潮', '集体涨停', '全线飘红', '普涨', '大涨', '拉升', '收涨', '创新高', '历史新高'],
    weight: 1.0
  },
  policy: {
    keywords: ['降息', '加息', '降准', '升准', '宽松', '收紧', '补贴', '减税', '免税', '监管', '整改', '暂停IPO', '注册制', '退市', '处罚', '调查', '问询函', '政策支持', '政策利好', '一行两会', '国务院', '证监会', '银保监会'],
    weight: 0.8
  },
  technical: {
    keywords: ['超买', '超卖', '背离', '金叉', '死叉', 'MACD', 'KDJ', 'RSI', '放量', '缩量', '突破', '破位', '支撑', '阻力', '洗盘', '震仓'],
    weight: 0.5
  },
  institutional: {
    keywords: ['增持', '减持', '回购', 'IPO', '定增', '配股', '大宗交易', '机构调研', 'QFII', '北上资金', '南下资金', '社保', '基金', '保险资金', '举牌'],
    weight: 0.7
  },
  macro: {
    keywords: ['经济', 'GDP', 'CPI', 'PPI', '出口', '进口', '贸易战', '汇率', '美联储', '美股', '港股', '欧洲', '原油', '黄金', '大宗商品', '地缘', '制裁', '俄乌', '中东', '供应链'],
    weight: 0.6
  }
};

/**
 * 精细化情绪分析(6维评分)
 * @param {string} text - 待分析文本
 * @returns {object} 6维情绪评分 + 综合情绪
 */
function analyzeSentimentFineGrained(text) {
  if (!text || typeof text !== 'string') {
    return { fear: 0, greed: 0, policy: 0, technical: 0, institutional: 0, macro: 0, total: 0, dominant: 'neutral', confidence: 0 };
  }

  const scores = {};
  const counts = {};
  let maxScore = 0;
  let dominant = 'neutral';

  for (const [emotion, data] of Object.entries(EMOTION_DICTIONARY)) {
    let score = 0;
    let count = 0;
    data.keywords.forEach(kw => {
      const regex = new RegExp(kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
      const matches = text.match(regex);
      if (matches) {
        count += matches.length;
        score += matches.length * data.weight;
      }
    });
    scores[emotion] = score;
    counts[emotion] = count;
    if (Math.abs(score) > Math.abs(maxScore)) {
      maxScore = score;
      dominant = score > 0 ? emotion : 'fear';
    }
  }

  // 综合情绪 = 加权平均(归一化到-100~100)
  const total = Math.max(-100, Math.min(100,
    (scores.fear * -1 + scores.greed + scores.policy * 0.8 + scores.technical * 0.5 + scores.institutional * 0.7 + scores.macro * 0.6) * 5
  ));

  const totalCount = Object.values(counts).reduce((a, b) => a + b, 0);
  const confidence = Math.min(1, totalCount / 5); // 置信度:匹配词越多越可信

  return { ...scores, counts, total, dominant, confidence };
}

/**
 * 新闻标题NLP分析(生成式语义理解)
 * 替代简单的关键词匹配,用正则捕捉语义模式
 * @param {string} title - 新闻标题
 * @returns {object} 语义分析结果
 */
function analyzeNewsTitle(title) {
  if (!title) return { sentiment: 0, category: 'unknown', entities: [], summary: '', _source: 'llm_simulation' };

  // 语义模式匹配
  const patterns = {
    // 强烈利好
    positiveStrong: [/(?:突破|创新高|历史新高|涨停潮?|大涨|井喷|爆发)/],
    // 轻微利好
    positiveMild: [/(?:上涨?|增长|回升|回暖|反弹)/],
    // 强烈利空
    negativeStrong: [/(?:暴跌|闪崩|崩盘|踩踏|集体跌停|重大亏损|债务违约)/],
    // 轻微利空
    negativeMild: [/(?:下跌?|回调|调整|走弱|业绩下滑)/],
    // 政策相关
    policyNews: [/(?:政策|降息|加息|降准|监管|证监会|银保监|国务院|一行两会|退市|注册)/],
    // 机构动向
    instNews: [/(?:增持|减持|回购|QFII|北上|社保|基金|举牌|IPO|定增)/],
    // 宏观
    macroNews: [/(?:经济|CPI|PPI|贸易战|美联储|地缘|制裁|原油|黄金)/]
  };

  let sentiment = 0;
  let category = 'neutral';
  const categories = [];

  // 检测模式
  if (patterns.positiveStrong.some(r => r.test(title))) { sentiment = 2; category = 'strongly_bullish'; categories.push('strong_bull'); }
  else if (patterns.positiveMild.some(r => r.test(title))) { sentiment = 1; category = 'mildly_bullish'; categories.push('mild_bull'); }
  else if (patterns.negativeStrong.some(r => r.test(title))) { sentiment = -2; category = 'strongly_bearish'; categories.push('strong_bear'); }
  else if (patterns.negativeMild.some(r => r.test(title))) { sentiment = -1; category = 'mildly_bearish'; categories.push('mild_bear'); }
  else if (patterns.policyNews.some(r => r.test(title))) { sentiment = 0; category = 'policy'; categories.push('policy'); }
  else if (patterns.instNews.some(r => r.test(title))) { sentiment = 0; category = 'institutional'; categories.push('institutional'); }
  else if (patterns.macroNews.some(r => r.test(title))) { sentiment = 0; category = 'macro'; categories.push('macro'); }

  // 实体提取(股票代码/板块名称)
  const entities = {
    stocks: (title.match(/[(\(【][^)\]】]{2,10}[)\]】]/g) || []).map(s => s.slice(1, -1)),
    sectors: extractSectorFromTitle(title)
  };

  // 模拟摘要(取标题核心词)
  const summary = title.length > 30 ? title.slice(0, 28) + '...' : title;

  return { sentiment, category, categories, entities, summary, _source: 'llm_simulation' };
}

/**
 * 从标题提取板块关键词
 */
function extractSectorFromTitle(title) {
  const sectorKeywords = ['半导体', '新能源', '医药', '白酒', '银行', '地产', '军工', '消费', '科技', '汽车', '电力', '化工', '煤炭', '有色', '农业', '券商', '保险', '基建', '家电', '纺织'];
  return sectorKeywords.filter(s => title.includes(s));
}

// 【向下兼容】旧接口保留(内部改调用精细化版本)
function analyzeSentiment(text) {
  if (!text || typeof text !== 'string') {
    return { bullish: 0, bearish: 0, sentiment: 0 };
  }
  const fine = analyzeSentimentFineGrained(text);
  const bullish = Math.max(0, fine.greed + fine.institutional + fine.policy * 0.5);
  const bearish = Math.max(0, fine.fear + Math.abs(Math.min(0, fine.policy)) * 0.5);
  return {
    bullish: Math.round(bullish),
    bearish: Math.round(bearish),
    sentiment: fine.total,
    dominant: fine.dominant,
    confidence: fine.confidence,
    _source: 'fine_grained_v2'
  };
}

// 解析东方财富返回的JS变量格式
function parseEastMoneyJSResponse(text) {
  try {
    // 格式: var ajaxResult={"rc":1,"LivesList":[...]}
    const match = text.match(/var\s+ajaxResult\s*=\s*({[\s\S]+})/);
    if (match) {
      return JSON.parse(match[1]);
    }
  } catch (e) {
    console.error('解析东方财富响应失败:', e.message);
  }
  return null;
}

// ═══════════════════════════════════════════════════════════════
// safeFetch - 容错fetch封装,自动降级到axios
// 修复: Node.js v22 内置fetch在某些环境下返回ok/status=undefined
// ═══════════════════════════════════════════════════════════════
async function safeFetch(url, options = {}) {
  try {
    const res = await fetch(url, options);
    if (res && res.ok !== undefined) {
      return res; // 正常fetch
    }
  } catch (e) {
    console.log(`[safeFetch] fetch异常: ${e.message.slice(0, 80)}`);
  }
  // 降级到axios
  try {
    const axios = (await import('axios')).default;
    const axRes = await axios.get(url, {
      timeout: options.timeout || 8000,
      headers: options.headers || {},
      responseType: 'text'
    });
    // 构造一个类Response对象
    return {
      ok: axRes.status >= 200 && axRes.status < 300,
      status: axRes.status,
      headers: { get: (k) => axRes.headers?.[k?.toLowerCase()] || null },
      json: async () => typeof axRes.data === 'string' ? JSON.parse(axRes.data) : axRes.data,
      text: async () => typeof axRes.data === 'string' ? axRes.data : JSON.stringify(axRes.data),
      _fromAxios: true
    };
  } catch (axErr) {
    console.error(`[safeFetch] axios降级也失败: ${axErr.message.slice(0, 80)}`);
    return null;
  }
}

