// 新增:板块热度情绪(基于板块涨跌)
// 【BUG修复】板块情绪:用东财板块涨跌(push2delay已验证有效)
async function fetchSectorSentiment() {
  try {
    const res = await safeFetch(
      'https://push2delay.eastmoney.com/api/qt/clist/get?pn=1&pz=50&po=1&np=1&fltt=2&invt=2&fid=f3&fs=m%3A90%2Bt%3A2&fields=f12%2Cf14%2Cf2%2Cf3',
      { headers: { 'User-Agent': 'Mozilla/5.0', 'Referer': 'https://quote.eastmoney.com/' } }
    );
    if (!res || !res.ok) throw new Error('HTTP ' + (res?.status || 'unknown'));
    const json = await res.json();
    const sectors = json?.data?.diff || [];
    if (sectors.length === 0) return null;
    let up = 0, down = 0;
    const topSectors = [];
    sectors.forEach(s => {
      const pct = s.f3 || 0;
      if (pct > 0) up++;
      else if (pct < 0) down++;
    });
    sectors.sort((a, b) => (b.f3 || 0) - (a.f3 || 0)).slice(0, 5).forEach(s => {
      topSectors.push({ name: s.f14 || s.f12, change: s.f3 || 0 });
    });
    const total = up + down || 1;
    return { source: '东财板块热度', bullish: up, bearish: down, sentiment: (up - down) / total, topSectors, _source: 'EastMoney_Sector' };
  } catch (e) { console.error('板块情绪获取失败:', e.message.slice(0, 100)); return null; }
}

// 从东方财富获取单只股票的行业/板块信息
async function fetchStockSectorFromEM(code) {
  try {
    const res = await safeFetch(
      `https://push2delay.eastmoney.com/api/qt/stock/get?secid=${code.startsWith('6') ? '1.' : '0.'}${code}&fields=f127,f128`,
      { headers: { 'User-Agent': 'Mozilla/5.0', 'Referer': 'https://quote.eastmoney.com/' }, timeout: 5000 }
    );
    if (!res || !res.ok) return null;
    const json = await res.json();
    // f127=行业, f128=板块概念
    const industry = json?.data?.f127 || '';
    const concept = json?.data?.f128 || '';
    // 返回行业(如有)或板块概念
    return industry || concept || null;
  } catch (e) {
    console.error('获取股票行业失败:', code, e.message.slice(0, 50));
    return null;
  }
}

// 涨跌停数据(市场情绪指标)
async function fetchEastMoneyLimitUpDown() {
  try {
    const axios = (await import('axios')).default;

    // 新浪财经涨幅榜(涨停股通常在前面)
    const limitUpResponse = await axios.get('https://vip.stock.finance.sina.com.cn/quotes_service/api/json_v2.php/Market_Center.getHQNodeData', {
      params: {
        page: 1,
        num: 100,
        sort: 'changepercent',
        asc: 0, // 降序
        node: 'hs_a',
        symbol: '',
        _s_r_a: 'page'
      },
      timeout: 10000,
      headers: {
        'Referer': 'https://finance.sina.com.cn/'
      }
    });

    // 新浪财经跌幅榜
    const limitDownResponse = await axios.get('https://vip.stock.finance.sina.com.cn/quotes_service/api/json_v2.php/Market_Center.getHQNodeData', {
      params: {
        page: 1,
        num: 100,
        sort: 'changepercent',
        asc: 1, // 升序
        node: 'hs_a',
        symbol: '',
        _s_r_a: 'page'
      },
      timeout: 10000,
      headers: {
        'Referer': 'https://finance.sina.com.cn/'
      }
    });

    const limitUpList = limitUpResponse.data || [];
    const limitDownList = limitDownResponse.data || [];

    // 筛选涨停(接近10%或20%,ST股5%)
    const limitUpStocks = limitUpList.filter(s => isLimitPrice(s.code, s.changepercent, s.name) && s.changepercent > 0).length;
    const limitDownStocks = limitDownList.filter(s => isLimitPrice(s.code, s.changepercent, s.name) && s.changepercent < 0).length;

    // 获取涨停股票名称
    const hotStocks = limitUpList.filter(s => isLimitPrice(s.code, s.changepercent, s.name) && s.changepercent > 0).slice(0, 5).map(s => s.name);

    return {
      source: '新浪涨跌停',
      limitUp: limitUpStocks,
      limitDown: limitDownStocks,
      sentiment: (limitUpStocks - limitDownStocks) / (limitUpStocks + limitDownStocks + 1),
      hotStocks: hotStocks,
      _source: 'Sina_Limit'
    };
  } catch (e) {
    console.error('涨跌停数据获取失败:', e.message);
    return null;
  }
}

// ═══════════════════════════════════════════════════════════════
// 大盘总览:指数 + 涨跌停 + 市场宽度
// ═══════════════════════════════════════════════════════════════
async function fetchMarketOverview() {
  const cacheKey = 'market_overview';
  const now = bjDate();
  if (global._apiCache && global._apiCache[cacheKey] && now - global._apiCache[cacheKey].ts < 60000) {
    return global._apiCache[cacheKey].data;
  }

  const axios = (await import('axios')).default;
  const result = {
    timestamp: bjISO(),
    indices: [],
    limitUpDown: null,
    breadth: null,
  };

  // 指数名称映射(腾讯GBK解码降级方案)
  const INDEX_NAME_MAP = {
    '000001': '上证指数', '000300': '沪深300', '399001': '深证成指',
    '399006': '创业板指', '000688': '科创50', '000016': '上证50', '000905': '中证500'
  };

  // 1. 腾讯财经:获取主要指数(axios + GBK解码)
  try {
    const resp = await axios.get('http://qt.gtimg.cn/q=sh000001,sh000300,sz399001,sz399006,sh000688,sh000016,sh000905', {
      timeout: 10000,
      responseType: 'arraybuffer',
      headers: { 'Referer': 'http://finance.qq.com/', 'User-Agent': 'Mozilla/5.0' }
    });
    // axios 默认用 UTF-8 解码,但腾讯是 GBK;arraybuffer 时拿到原始 Buffer
    const rawBuf = Buffer.isBuffer(resp.data) ? resp.data : Buffer.from(resp.data);
    const rawText = rawBuf.toString('binary');
    for (const line of rawText.split('\n')) {
      const m = line.match(/v_[a-z]+(\d+)="([^"]+)"/);
      if (!m) continue;
      const code = m[1], val = m[2];
      const p = val.split('~');
      if (p.length < 5 || !p[3]) continue;
      result.indices.push({
        code,
        name: INDEX_NAME_MAP[code] || code,
        price: parseFloat(p[3]),
        change: parseFloat(p[4]) || 0,
        changePercent: parseFloat(p[32]) || 0,
        volume: parseFloat(p[36]) || 0,
        amount: parseFloat(p[37]) || 0,
        amplitude: parseFloat(p[43]) || 0,
        pe: parseFloat(p[39]) || null,
      });
    }
  } catch (e) {
    console.error('指数数据获取失败:', e.message);
  }

  console.log('[大盘总览] 获取到指数:', result.indices.length, '条', JSON.stringify(result.indices.map(i => ({ n: i.name, p: i.price, c: i.changePercent }))));

  // 2. 涨跌停数据(复用已有的fetchEastMoneyLimitUpDown)
  try {
    result.limitUpDown = await fetchEastMoneyLimitUpDown();
  } catch (e) {
    console.error('涨跌停获取失败:', e.message);
  }

  // 3. 市场宽度(上涨/下跌/平盘家数)
  try {
    const resp2 = await axios.get(
      'http://push2delay.eastmoney.com/api/qt/clist/get?pn=1&pz=100&po=1&np=1&fltt=2&invt=2&fid=f3&fs=m:0+t:6,m:1+t:2&fields=f3&ut=fa5fd1943c7b386f172d6893dbfba10b',
      { timeout: 6000, headers: { 'Referer': 'http://quote.eastmoney.com/' } }
    );
    const raw = resp2.data?.data?.diff || [];
    const up = raw.filter(s => s.f3 > 0).length;
    const down = raw.filter(s => s.f3 < 0).length;
    const limitUp = raw.filter(s => isLimitPrice(s.code || '', s.f3, s.name)).length;
    const limitDown = raw.filter(s => isLimitPrice(s.code || '', s.f3, s.name) && s.f3 < 0).length;
    result.breadth = { up, down, flat: 0, limitUp, limitDown, total: raw.length };
  } catch (e) {
    if (result.limitUpDown) {
      const lu = result.limitUpDown.limitUp;
      const ld = result.limitUpDown.limitDown;
      result.breadth = { up: lu * 15, down: ld * 15, flat: 1000, limitUp: lu, limitDown: ld, total: 5000 };
    }
  }

  // 4. 社交情绪数据(多源聚合)
  try {
    const sentimentData = await fetchAllSocialSentiment();
    if (sentimentData) {
      result.sentiment = {
        bullish: sentimentData.news?.bullish || 0,
        bearish: sentimentData.news?.bearish || 0,
        combined: sentimentData.combined || 0,
        sources: sentimentData.news?.sources?.map(s => s.source) || [],
        hotTopics: sentimentData.news?.hotTopics?.slice(0, 5) || []
      };
    }
  } catch (e) {
    console.error('社交情绪获取失败:', e.message);
  }

  if (!global._apiCache) global._apiCache = {};
  global._apiCache[cacheKey] = { data: result, ts: now };
  return result;
}

