// ═══════════════════════════════════════════════════════════════
// 北向资金(沪深港通)- 多数据源整合
// 优先级: push2his(东方财富历史) > 新浪沪深港通 > 腾讯ETF备用
// ═══════════════════════════════════════════════════════════════
async function fetchNorthFlow() {
  const cacheKey = 'north_flow';
  const now = bjDate();
  if (global._apiCache && global._apiCache[cacheKey] && now - global._apiCache[cacheKey].ts < 300000) {
    return global._apiCache[cacheKey].data;
  }
  const axios = (await import('axios')).default;
  const result = { history: [], today: null, timestamp: bjISO(), _note: '多数据源整合' };

  // ── 源1: push2his 东方财富历史K线(每日更新,最可靠) ──
  try {
    const resp = await axios.get('https://push2his.eastmoney.com/api/qt/stock/fflow/daykline/get', {
      params: { lmt: 30, klt: 101, secid: '116.00719', fields1: 'f1,f2,f3,f7', fields2: 'f51,f52,f53,f54,f55,f56,f57,f58,f59,f60,f61,f62,f63' },
      timeout: 10000,
      headers: { 'Referer': 'https://data.eastmoney.com/hsgt/', 'User-Agent': 'Mozilla/5.0' }
    });
    if (resp.data?.data?.klines && resp.data.data.klines.length > 0) {
      const klines = resp.data.data.klines;
      result.history = klines.slice(-30).map(line => {
        const p = line.split(',');
        return {
          date: p[0],
          value: parseFloat(p[1]) / 1e8,
          hkToSh: parseFloat(p[2]) / 1e8,
          hkToSz: parseFloat(p[3]) / 1e8,
          ma5: parseFloat(p[6]) / 1e8
        };
      });
      const last = klines[klines.length - 1].split(',');
      const todayVal = parseFloat(last[1]) / 1e8;
      result.today = {
        hkToSh: todayVal,
        hkToSz: parseFloat(last[3]) / 1e8 || null,
        estimate: todayVal > 0 ? '净买入' : todayVal < 0 ? '净卖出' : '持平',
        activity: Math.abs(todayVal) > 100 ? '活跃' : Math.abs(todayVal) > 50 ? '一般' : '低迷',
        note: '东方财富历史K线数据'
      };
      if (!global._apiCache) global._apiCache = {};
      global._apiCache[cacheKey] = { data: result, ts: now };
      return result;
    }
  } catch (e1) {
    console.error('北向资金源1(push2his)失败:', e1.message);
  }

  // ── 源2: 新浪财经 沪深港通资金流 ──
  try {
    const resp = await axios.get('https://money.finance.sina.com.cn/quotes_service/api/json_v2.php/MoneyFlow.ssi_ssfund_detail', {
      params: { day: bjDate() },
      timeout: 8000,
      headers: { 'Referer': 'https://finance.sina.com.cn/', 'User-Agent': 'Mozilla/5.0' }
    });
    const raw = Array.isArray(resp.data) ? resp.data : resp.data?.result;
    if (Array.isArray(raw) && raw.length > 0) {
      const item = raw[raw.length - 1];
      const netIn = parseFloat(item?.hgt) || parseFloat(item?.money) || 0;
      if (netIn !== 0) {
        result.today = {
          hkToSh: netIn / 1e8,
          hkToSz: parseFloat(item?.sgt) / 1e8 || null,
          estimate: netIn > 0 ? '净买入' : '净卖出',
          activity: Math.abs(netIn / 1e8) > 100 ? '活跃' : Math.abs(netIn / 1e8) > 50 ? '一般' : '低迷',
          note: '新浪财经沪深港通'
        };
        result._note = '新浪财经数据';
        if (!global._apiCache) global._apiCache = {};
        global._apiCache[cacheKey] = { data: result, ts: now };
        return result;
      }
    }
  } catch (e2) {
    console.error('北向资金源2(新浪)失败:', e2.message);
  }

  // ── 源3: 腾讯ETF成交额估算(最后备用) ──
  try {
    const resp = await axios.get('http://qt.gtimg.cn/q=sh510310,sz159920,sh510900', {
      timeout: 8000, responseType: 'arraybuffer',
      headers: { 'Referer': 'http://finance.qq.com/' }
    });
    const buf = Buffer.isBuffer(resp.data) ? resp.data : Buffer.from(resp.data);
    const rawText = buf.toString('binary');
    const etfs = [];
    for (const line of rawText.split('\n')) {
      const p = line.split('~');
      if (p.length > 37 && p[3] && p[3] !== '0.00') {
        etfs.push({ name: p[1], price: parseFloat(p[3]), changePercent: parseFloat(p[32]) || 0, amount: (parseFloat(p[37]) || 0) / 1e8 });
      }
    }
    const hs300etf = etfs[0];
    if (hs300etf) {
      result.today = {
        hkToSh: null, hkToSz: null,
        estimate: hs300etf.changePercent > 0 ? '净买入倾向' : hs300etf.changePercent < 0 ? '净卖出倾向' : '持平',
        hs300etf,
        activity: hs300etf.amount > 50 ? '活跃' : hs300etf.amount > 20 ? '一般' : '低迷',
        note: '沪深300ETF成交额估算(北向代理)'
      };
      result._note = '沪深300ETF成交额估算';
    }
  } catch (e3) {
    console.error('北向ETF估算失败:', e3.message);
  }

  // ── 源4: 同花顺iFinD北向资金(备用1) ──
  try {
    const resp = await axios.get('https://d.10jqka.com.cn/v6/line/hsgt_00/01/last20.js', {
      timeout: 8000,
      headers: { 'Referer': 'https://data.10jqka.com.cn/funds/hsgt/', 'User-Agent': 'Mozilla/5.0' }
    });
    if (resp.data && resp.data.includes('\n')) {
      const lines = resp.data.trim().split('\n');
      const latest = lines[lines.length - 1].split(',');
      const netIn = parseFloat(latest[1]) || 0;
      if (netIn !== 0) {
        result.today = {
          hkToSh: netIn / 1e8,
          hkToSz: null,
          estimate: netIn > 0 ? '净买入' : '净卖出',
          activity: Math.abs(netIn / 1e8) > 100 ? '活跃' : Math.abs(netIn / 1e8) > 50 ? '一般' : '低迷',
          note: '同花顺iFinD北向资金'
        };
        result._note = '同花顺数据';
        if (!global._apiCache) global._apiCache = {};
        global._apiCache[cacheKey] = { data: result, ts: now };
        return result;
      }
    }
  } catch (e4) {
    console.error('北向资金源4(同花顺)失败:', e4.message);
  }

  // ── 源5: 东方财富实时北向资金流(备用2) ──
  try {
    const resp = await axios.get('https://push2delay.eastmoney.com/api/qt/kamt.rtmin/get', {
      params: { ut: 'b2884a393a59ad64002292a3e90d46a5', fields1: 'f1,f2,f3,f4', fields2: 'f51,f52,f53,f54,f55' },
      timeout: 8000,
      headers: { 'Referer': 'https://data.eastmoney.com/hsgt/', 'User-Agent': 'Mozilla/5.0' }
    });
    if (resp.data?.data) {
      const d = resp.data.data;
      const netIn = parseFloat(d.f3) || 0;
      result.today = {
        hkToSh: netIn / 1e8,
        hkToSz: parseFloat(d.f4) / 1e8 || null,
        estimate: netIn > 0 ? '净买入' : netIn < 0 ? '净卖出' : '持平',
        activity: Math.abs(netIn / 1e8) > 100 ? '活跃' : Math.abs(netIn / 1e8) > 50 ? '一般' : '低迷',
        note: '东方财富实时北向资金'
      };
      result._note = '东方财富实时数据';
      if (!global._apiCache) global._apiCache = {};
      global._apiCache[cacheKey] = { data: result, ts: now };
      return result;
    }
  } catch (e5) {
    console.error('北向资金源5(东方财富实时)失败:', e5.message);
  }

  // ── 源6: 雪球北向资金数据(最后备用) ──
  try {
    const resp = await axios.get('https://stock.xueqiu.com/v5/stock/hkstock/hsgt/list.json', {
      params: { page: 1, size: 5 },
      timeout: 8000,
      headers: { 'Referer': 'https://xueqiu.com/', 'User-Agent': 'Mozilla/5.0', 'Cookie': 'xq_a_token=test' }
    });
    if (resp.data?.data?.items) {
      const items = resp.data.data.items;
      const totalNetIn = items.reduce((s, i) => s + (parseFloat(i.net_in) || 0), 0);
      if (totalNetIn !== 0) {
        result.today = {
          hkToSh: null,
          hkToSz: null,
          estimate: totalNetIn > 0 ? '净买入' : '净卖出',
          activity: Math.abs(totalNetIn / 1e8) > 100 ? '活跃' : Math.abs(totalNetIn / 1e8) > 50 ? '一般' : '低迷',
          note: '雪球北向资金'
        };
        result._note = '雪球数据';
      }
    }
  } catch (e6) {
    console.error('北向资金源6(雪球)失败:', e6.message);
  }

  if (!global._apiCache) global._apiCache = {};
  global._apiCache[cacheKey] = { data: result, ts: now };
  return result;
}

// 获取综合社交情绪// 获取综合社交情绪(多数据源融合)
async function fetchAllSocialSentiment() {
  const now = bjDate();

  // 检查缓存
  if (socialSentimentCache.data && now - socialSentimentCache.lastUpdate < socialSentimentCache.ttl) {
    return socialSentimentCache.data;
  }

  console.log('💬 正在获取多源社交情绪...');

  // 并行获取所有数据源
  const [emNews, sinaNews, tencentNews, reportSent, sectorSent, limitData] = await Promise.all([
    fetchEastMoneyNewsSentiment().catch(() => null),
    fetchSinaNewsSentiment().catch(() => null),
    fetchTencentNewsSentiment().catch(() => null),
    fetchReportSentiment().catch(() => null),
    fetchSectorSentiment().catch(() => null),
    fetchEastMoneyLimitUpDown().catch(() => null)
  ]);

  // 聚合所有数据源
  const allSources = [emNews, sinaNews, tencentNews, reportSent, sectorSent].filter(Boolean);

  if (allSources.length === 0 && !limitData) {
    // 【铁律】数据源全部不可用时:返回 null,绝不伪造数据
    console.log('⚠️ 所有情绪API失败,返回 null(铁律禁止伪造数据)');
    return {
      news: null,
      limit: null,
      combined: null,
      timestamp: bjISO(),
      _fallback: true,
      _error: '所有情绪数据源不可用'
    };
  }

  // 加权聚合情绪
  let totalBullish = 0, totalBearish = 0;
  const allTopics = [];
  const sourceDetails = [];

  allSources.forEach(src => {
    totalBullish += src.bullish || 0;
    totalBearish += src.bearish || 0;
    if (src.hotTopics) allTopics.push(...src.hotTopics.slice(0, 5));
    sourceDetails.push({ source: src.source, bullish: src.bullish, bearish: src.bearish, sentiment: src.sentiment });
  });

  const total = totalBullish + totalBearish || 1;
  const combinedNewsSentiment = (totalBullish - totalBearish) / total;

  // 综合情绪计算(新闻权重60%,涨跌停权重20%,板块权重20%)
  let combined = combinedNewsSentiment * 0.6;
  let weights = 0.6;

  if (limitData) {
    combined += limitData.sentiment * 0.2;
    weights += 0.2;
  }
  if (sectorSent) {
    combined += sectorSent.sentiment * 0.2;
    weights += 0.2;
  }

  // ── 【感知层增强v2】精细化情绪聚合 ──
  // 汇总所有数据源的6维情绪(从hotTopics中提取fine数据)
  const fineAggregate = { fear: 0, greed: 0, policy: 0, technical: 0, institutional: 0, macro: 0 };
  let fineCount = 0;
  allTopics.forEach(topic => {
    if (topic.fear !== undefined) {
      Object.keys(fineAggregate).forEach(k => { fineAggregate[k] += topic[k] || 0; });
      fineCount++;
    }
  });
  const fineAvg = fineCount > 0
    ? Object.fromEntries(Object.entries(fineAggregate).map(([k, v]) => [k, Math.round(v / fineCount * 10) / 10]))
    : fineAggregate;
  const dominantEmotion = Object.entries(fineAggregate).sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))[0]?.[0] || 'neutral';

  const result = {
    news: {
      source: '多源聚合',
      bullish: totalBullish,
      bearish: totalBearish,
      sentiment: combinedNewsSentiment,
      hotTopics: allTopics.sort((a, b) => (b.sentimentScore || 0) - (a.sentimentScore || 0)).slice(0, 10),
      sources: sourceDetails,
      newsCount: allSources.reduce((sum, s) => sum + (s.newsCount || s.reportCount || 0), 0)
    },
    // 【感知层增强v2】新增:6维精细化情绪
    fine: {
      fear: fineAvg.fear,
      greed: fineAvg.greed,
      policy: fineAvg.policy,
      technical: fineAvg.technical,
      institutional: fineAvg.institutional,
      macro: fineAvg.macro,
      dominant: dominantEmotion,
      total: combinedNewsSentiment,
      _note: '6维精细化情绪:fear/greed/policy/technical/institutional/macro'
    },
    limit: limitData,
    sector: sectorSent,
    report: reportSent,
    combined: weights > 0 ? combined / weights : 0,
    timestamp: bjISO()
  };

  socialSentimentCache.data = result;
  socialSentimentCache.lastUpdate = now;

  console.log(`💬 社交情绪聚合: 利好${totalBullish}/利空${totalBearish} | 综合情绪${(result.combined * 100).toFixed(1)}% | 数据源${allSources.length}个`);

  return result;
}

