// ═══════════════════════════════════════════════════════════════
// 个股主力资金历史数据(东方财富日线)
// ═══════════════════════════════════════════════════════════════
// 【新增 2026-05-08】个股主力资金流向获取 + 存储
async function fetchStockMainFlow(code, days = 30) {
  const secid = code.startsWith('6') ? `1.${code}` : `0.${code}`;
  const rows = [];

  // 方案1: push2delay 实时API + f178历史5日
  try {
    const resp = await axios.get(`https://push2delay.eastmoney.com/api/qt/stock/get`, {
      params: {
        secid,
        fields: 'f57,f58,f43,f169,f170,f171,f174,f175,f178,f184',
        ut: 'bd1d9ddb04089700cf9c27f6f7426281'
      },
      timeout: 10000,
      headers: { 'Referer': 'https://quote.eastmoney.com/', 'User-Agent': 'Mozilla/5.0' }
    });

    if (resp.data?.data) {
      const d = resp.data.data;
      const today = bjISO().slice(0, 10);

      // 今日主力数据 (f169=主力净流入万元, f170=主力净占比‰, f171=超大单净流入万元)
      if (d.f169 !== undefined && d.f169 !== null) {
        rows.push({
          code,
          date: today,
          main_inflow: d.f169 * 10000,        // 万元转元
          main_ratio: d.f170 / 10,             // ‰转%
          super_inflow: (d.f174 || 0) * 10000, // 超大单万元转元
          retail_inflow: (d.f175 || 0) * 10000,// 大单万元转元
          price: (d.f43 || 0) / 100,           // 分转元
          change_percent: 0,
          turnover_rate: d.f184 || 0
        });
      }

      // f178: 近5日主力净流入历史 (JSON数组, 单位:元)
      if (d.f178) {
        try {
          const hist = JSON.parse(d.f178);
          for (const h of hist) {
            if (h.date && h.mainNetAmt !== undefined) {
              rows.push({
                code,
                date: h.date,
                main_inflow: h.mainNetAmt,
                main_ratio: 0,
                super_inflow: 0,
                retail_inflow: 0,
                price: 0,
                change_percent: 0
              });
            }
          }
        } catch (e) { /* JSON解析失败忽略 */ }
      }
    }

    // 按日期降序排列
    rows.sort((a, b) => b.date.localeCompare(a.date));

    // 批量写入数据库
    if (rows.length > 0) {
      const stmt = db.prepare(`INSERT OR REPLACE INTO stock_main_flow
        (code, date, main_inflow, super_inflow, retail_inflow, main_ratio, price, change_percent)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)`);
      const insertMany = db.transaction((items) => {
        for (const item of items) stmt.run(item.code, item.date, item.main_inflow, item.super_inflow, item.retail_inflow, item.main_ratio, item.price, item.change_percent);
      });
      insertMany(rows);
      console.log(`[主力资金] ${code} 获取 ${rows.length} 条 (push2delay)`);
    }
    return rows;
  } catch (e) {
    console.error(`[主力资金] push2delay获取${code}失败:`, e.message);
  }

  return rows;
}

