// 从腾讯财经获取真实数据(支持 GBK 编码)
async function fetchAllStocksFromTencent() {
  console.log('\n📡 [腾讯财经] 正在获取全市场股票数据...');

  const http = await import('http');
  const stocks = [];

  // 腾讯财经 API 格式: http://qt.gtimg.cn/q=sh600000,sh600001...
  // 分批获取,每批100只股票

  const codes = [];

  // ═════════════════════════════════════════════════════════
  // 全市场股票代码覆盖(约5400只A股)
  // ═════════════════════════════════════════════════════════

  // 1. 沪市主板 (600000-689999) 约2500只
  for (let i = 600000; i <= 689999; i++) {
    // 跳过科创板(688xxx单独处理)
    if (i >= 688000 && i <= 689999) continue;
    codes.push('sh' + i);
  }

  // 2. 科创板 (688xxx) 约500只
  for (let i = 688000; i <= 689999; i++) {
    codes.push('sh' + i);
  }

  // 3. 深市主板 (000001-002999) 约1500只
  for (let i = 1; i <= 2999; i++) {
    codes.push('sz' + String(i).padStart(6, '0'));
  }

  // 4. 创业板 (300001-301999) 约1200只
  for (let i = 300001; i <= 301999; i++) {
    codes.push('sz' + i);
  }

  // 5. 北交所 (430001-873999) 约200只
  for (let i = 430001; i <= 439999; i++) {
    codes.push('bj' + i);
  }
  for (let i = 830001; i <= 873999; i++) {
    codes.push('bj' + i);
  }

  console.log(`  📊 准备获取全市场 ${codes.length.toLocaleString()} 只股票数据...`);

  // 分批请求(全量获取,无限制)
  const batchSize = 100;
  const maxRequests = codes.length; // 移除1000只限制
  for (let i = 0; i < maxRequests; i += batchSize) {
    const batch = codes.slice(i, i + batchSize);
    const url = 'http://qt.gtimg.cn/q=' + batch.join(',');

    try {
      const data = await new Promise((resolve, reject) => {
        const req = http.default.get(url, { timeout: 10000 }, (res) => {
          let chunks = [];
          res.on('data', chunk => chunks.push(chunk));
          res.on('end', () => {
            const buffer = Buffer.concat(chunks);
            resolve(iconv.decode(buffer, 'gbk'));
          });
        });
        req.on('error', reject);
        req.setTimeout(10000, () => {
          req.destroy();
          reject(new Error('Timeout'));
        });
      });

      // 解析数据
      for (const line of data.split('\n')) {
        const match = line.match(/v_([a-z]+)(\d+)="([^"]+)"/);
        if (!match) continue;

        const parts = match[3].split('~');
        if (parts.length < 10) continue;

        const name = parts[1];
        const code = parts[2];
        const price = parseFloat(parts[3]) || 0;
        const changePct = parseFloat(parts[32]) || 0;
        const change = parseFloat(parts[4]) || 0;
        const high = parseFloat(parts[33]) || price;
        const low = parseFloat(parts[34]) || price;
        const volume = parseFloat(parts[36]) || 0;
        const amount = parseFloat(parts[37]) || 0;

        if (name && price > 0 && !name.includes('指数')) {
          stocks.push({
            code: code,
            name: name,
            price: price,
            changePercent: changePct,
            change: change,
            high: high,
            low: low,
            volume: volume,
            amount: amount
          });
        }
      }

      // 进度日志(每500只)
      if (stocks.length % 500 === 0 || i + batchSize >= maxRequests) {
        console.log(`  📊 已获取 ${stocks.length.toLocaleString()} 只股票...`);
      }
    } catch (e) {
      // 忽略单批错误,继续下一批
    }

    // 添加延迟避免API限流(每批请求后等待50ms)
    await new Promise(resolve => setTimeout(resolve, 50));
  }

  console.log(`  📊 腾讯财经共获取 ${stocks.length} 只股票`);
  return stocks;
}



