// ── 预警首次触发时间追踪(key = "code:type", value = ISO时间戳)──
const alertFirstSeen = new Map();
const ALERT_FIRST_SEEN_MAX = 500; // 最多追踪500条
function getAlertTime(code, type) {
  const key = `${code}:${type}`;
  if (!alertFirstSeen.has(key)) {
    if (alertFirstSeen.size >= ALERT_FIRST_SEEN_MAX) {
      // 清理最旧的1/4
      const keys = [...alertFirstSeen.keys()];
      for (let i = 0; i < Math.floor(keys.length / 4); i++) alertFirstSeen.delete(keys[i]);
    }
    alertFirstSeen.set(key, bjISO());
  }
  return alertFirstSeen.get(key);
}
function pruneStaleAlerts(activeKeys) {
  // 清除当前不活跃的预警(已消失的条件)
  for (const k of alertFirstSeen.keys()) {
    if (!activeKeys.has(k)) alertFirstSeen.delete(k);
  }
}

