// ============================================================
// 守护进程模块 - Watchdog Guardian
// 目标:监控 7 大定时器 + 内存 + HTTP 健康,发现崩溃自动重启
// ============================================================

// 重启标记文件(检测当前进程是否由 Watchdog 重启产生)
const RESTART_MARKER = join(__dirname, '../.watchdog_restart');
const isRestartedProcess = () => fs.existsSync(RESTART_MARKER);

// 全局开关(重启时控制各引擎是否自动恢复)
let REDQUEEN_BOOT      = true;
let SHUNDI_BOOT        = true;
let YAODI_BOOT         = true;
let EVOLUTION_BOOT     = true;

// 定时器引用(供守护进程使用)
let watchdogInterval    = null;
let memoryAlertSent    = false;
let restartCount24h    = 0;  // 24小时内重启次数
let lastRestartTime    = 0;

// ----------------- 内存监控 -----------------
// ═══ 系统健康检测（卡死/断网）═══════════════════════════════
let _lastSystemCheck = Date.now();
let _systemFreezeCount = 0;
let _networkDownCount = 0;

async function checkSystemHealth() {
  const now = Date.now();
  const result = { healthy: true, reason: '', shouldStopService: false };

  try {
    // 1. 检测事件循环是否卡死（主线程阻塞）
    const eventLoopDelay = now - _lastSystemCheck;
    if (eventLoopDelay > 60000) { // 超过60秒未执行检查
      _systemFreezeCount++;
      console.error(`🚨 事件循环疑似卡死: 延迟 ${Math.round(eventLoopDelay/1000)}秒 (计数: ${_systemFreezeCount})`);
      
      if (_systemFreezeCount >= 3) {
        result.healthy = false;
        result.reason = `事件循环卡死 ${_systemFreezeCount} 次`;
        result.shouldStopService = true;
        return result;
      }
    } else {
      _systemFreezeCount = 0;
    }

    // 2. 检测网络连接（尝试访问外部API）
    const networkOk = await checkNetworkConnection();
    if (!networkOk) {
      _networkDownCount++;
      console.error(`🚨 网络连接失败 (计数: ${_networkDownCount})`);
      
      if (_networkDownCount >= 5) { // 连续5次失败
        result.healthy = false;
        result.reason = `网络连接失败 ${_networkDownCount} 次`;
        result.shouldStopService = true;
        return result;
      }
    } else {
      _networkDownCount = 0;
    }

    // 3. 检测CPU是否卡死（负载过高）
    const cpuUsage = getCpuUsage();
    if (cpuUsage > 95) {
      console.error(`🚨 CPU使用率过高: ${cpuUsage}%`);
      // CPU高负载不停止服务，只记录告警
    }

    _lastSystemCheck = now;
    return result;
  } catch (e) {
    console.error('[Watchdog] 系统健康检测失败:', e.message);
    return { healthy: true, reason: e.message, shouldStopService: false };
  }
}

// 检测网络连接
async function checkNetworkConnection() {
  return new Promise((resolve) => {
    const req = https.request('https://www.baidu.com', { method: 'HEAD', timeout: 3000 }, (res) => {
      resolve(res.statusCode === 200);
    });
    req.on('error', () => resolve(false));
    req.on('timeout', () => { req.destroy(); resolve(false); });
    req.end();
  });
}

// 优雅关闭所有服务
function gracefulShutdown(reason) {
  console.error(`\n══════════════════════════════════════`);
  console.error(`🛑 系统异常，准备关闭所有服务`);
  console.error(`原因: ${reason}`);
  console.error(`时间: ${new Date().toLocaleString('zh-CN')}`);
  console.error(`══════════════════════════════════════\n`);

  // 1. 停止所有定时器
  const timers = [
    'redqueenInterval', 'shundiInterval', 'yaodiInterval', 'evolutionInterval',
    'schedulerInterval', 'stopLossMonitorTimer', 'watchdogInterval',
    'globalMarketTimer', 'stockMainFlowTimer', 'northboundTimer',
    'longhubangTimer', 'researchSentimentTimer', 'socialSentimentTimer',
    'cpuMonitorInterval', 'mlAutoTrainScheduler'
  ];
  
  timers.forEach(name => {
    try {
      if (global[name]) {
        clearInterval(global[name]);
        clearTimeout(global[name]);
        console.log(`✅ 停止定时器: ${name}`);
      }
    } catch (e) {}
  });

  // 2. 关闭数据库连接
  try {
    if (db && db.close) {
      db.close();
      console.log('✅ 数据库已关闭');
    }
  } catch (e) {}

  // 3. 记录关闭日志
  const logPath = '/tmp/fqm_shutdown.log';
  fs.appendFileSync(logPath, 
    `[${new Date().toISOString()}] 系统关闭: ${reason}\n`
  );

  // 4. 退出进程
  console.log('\n👋 所有服务已停止，退出进程');
  process.exit(1);
}

function checkMemory() {
  const mem = process.memoryUsage();
  const heapUsed  = Math.round(mem.heapUsed / 1024 / 1024);   // MB
  const heapTotal = Math.round(mem.heapTotal / 1024 / 1024);  // MB
  const heapPct   = Math.round(heapUsed / heapTotal * 100);

  // 超过 800MB 或堆使用率超过 90% → 告警
  if (heapUsed > 800 || heapPct > 90) {
    if (!memoryAlertSent) {
      memoryAlertSent = true;
      console.warn(`⚠️  内存告警: heap=${heapUsed}MB/${heapTotal}MB (${heapPct}%)`);
      forceGC(); // 触发 V8 GC(如果可用)
      setTimeout(() => {
        if (process.memoryUsage().heapUsed / 1024 / 1024 > 800) {
          gracefulRestart('MEMORY_THRESHOLD');
        }
      }, 5000);
    }
  } else {
    memoryAlertSent = false;
  }

  return { heapUsed, heapTotal, heapPct };
}

function forceGC() {
  if (global.gc) { global.gc(); console.log('🗑️ 强制 GC 触发'); }
}

// ----------------- 健康检查(轮询 HTTP 端口)-----------------
// Watchdog 重启计数器(用于连续失败判断)
let _healthCheckFails = 0;
// ----------------- 健康检查(直接检查内部状态,避免HTTP自引用死锁)-----------------
function healthCheck() {
  // 【P0修复】不再通过HTTP调用自己的API,改为直接检查内部状态
  // 避免事件循环阻塞时HTTP回调无法处理导致死锁
  try {
    const engineHealth = getEngineHealth();
    const memUsage = process.memoryUsage();
    const heapUsedMB = Math.round(memUsage.heapUsed / 1024 / 1024);
    const heapTotalMB = Math.round(memUsage.heapTotal / 1024 / 1024);
    const memRatio = memUsage.heapUsed / memUsage.heapTotal;

    // 检查数据库是否可访问
    let dbOk = false;
    try {
      db.prepare('SELECT 1').get();
      dbOk = true;
    } catch (e) {
      console.error('[Watchdog] 数据库检查失败:', e.message);
    }

    // 检查关键引擎是否运行(仅检查已启用的引擎)
    // 【修复】演化引擎会被ML训练调度器临时暂停,不作为健康检查必选项
    const criticalEngines = [
      { name: 'redqueen', enabled: REDQUEEN_BOOT },
      { name: 'shundi', enabled: SHUNDI_BOOT },
      { name: 'yaodi', enabled: YAODI_BOOT }
      // evolution 引擎排除: 会被ML训练/高CPU临时暂停,属于正常行为
    ];
    const enabledEngines = criticalEngines.filter(e => e.enabled);
    const enginesOk = enabledEngines.length === 0 || enabledEngines.every(e => engineHealth[e.name]?.running);

    // 如果没有启用任何引擎,跳过引擎检查
    const skipEngineCheck = enabledEngines.length === 0;

    // 内存使用率警告(>90%视为不健康)
    // 【修复】内存阈值放宽: heapTotal<64MB时用绝对值判断(>56MB告警), 否则用95%比例
    const memOk = (heapTotalMB < 64) ? (heapUsedMB < 56) : (memRatio < 0.95);

    const ok = dbOk && enginesOk && memOk;

    if (ok) {
      _healthCheckFails = 0;
    } else {
      _healthCheckFails++;
      console.warn(`[Watchdog] 健康检查失败: db=${dbOk} engines=${enginesOk} mem=${(memRatio*100).toFixed(1)}%`);
    }

    return Promise.resolve({
      ok,
      data: {
        db: dbOk,
        engines: engineHealth,
        memory: { usedMB: heapUsedMB, totalMB: heapTotalMB, ratio: memRatio }
      }
    });
  } catch (e) {
    console.error('[Watchdog] 健康检查异常:', e.message);
    return Promise.resolve({ ok: false, error: e.message });
  }
}

// ----------------- 各引擎健康状态 -----------------
function getEngineHealth() {
  return {
    redqueen:   { running: redqueenRunning,    interval: 30000 },
    shundi:     { running: shundiRunning,      interval: 60000 },
    yaodi:      { running: yaodiEvolutionRunning, interval: 5 * 60000 },
    evolution:  { running: evolutionInterval !== null, interval: null },
    scheduler:  { running: schedulerInterval !== null,  interval: null },
  };
}

// ----------------- 核心:自动重启逻辑 -----------------
function gracefulRestart(reason) {
  const now = bjDate();
  const hoursSinceRestart = (now - lastRestartTime) / 3600000;

  // 重启冷却:1 小时内最多 3 次
  if (hoursSinceRestart < 1 && restartCount24h >= 3) {
    console.error(`🚨 重启过于频繁(1小时内${restartCount24h}次),进入安全暂停模式`);
    // 只停止高频定时器,降低服务器负载,不完全退出
    if (schedulerInterval) { clearInterval(schedulerInterval); schedulerInterval = null; }
    if (evolutionInterval) { clearInterval(evolutionInterval); evolutionInterval = null; }
    if (yaodiEvolutionTimer){ clearInterval(yaodiEvolutionTimer); yaodiEvolutionTimer = null; }
    if (adversarialAutoInterval){ clearInterval(adversarialAutoInterval); adversarialAutoInterval = null; }
    console.warn('⏸ 高频定时器已暂停,等待手动恢复或自然冷却');
    return;
  }

  restartCount24h++;
  lastRestartTime = now;

  // 重启前清空BUG队列,防止重启后继续累积
  bugQueue = [];
  bugHistory = bugHistory.slice(-20); // 只保留最近20条
  systemHealthScore = 100; // 重置健康分数

  console.error(`\n========================================`);
  console.error(`🔄 Watchdog 重启: ${reason}`);
  console.error(`   24h重启次数: ${restartCount24h} | 进程ID: ${process.pid}`);
  console.error(`   内存: ${Math.round(process.memoryUsage().heapUsed/1024/1024)}MB`);
  console.error(`   各引擎状态:`, getEngineHealth());
  console.error(`========================================\n`);

  // 写入重启日志到数据库(持久化追踪)
  try {
    db.prepare(`
      INSERT OR IGNORE INTO yaodi_evolution_log (branch_id, evolution_type, accuracy_before, accuracy_after, environment, notes)
      VALUES (0, 'watchdog_restart', 0, 0, ?, ?)
    `).run(reason, bjISO());
  } catch {}

  // 优雅退出:关闭所有定时器 → 2秒后自动拉起新进程
  stopAllEngines();

  setTimeout(() => {
    console.log('🔄 正在重启服务器...');
    // 写入重启标记(告诉新进程:需要恢复引擎)
    try {
      fs.writeFileSync(RESTART_MARKER, JSON.stringify({
        reason,
        time: bjISO(),
        restartCount: restartCount24h,
        memory: Math.round(process.memoryUsage().heapUsed / 1024 / 1024)
      }));
    } catch (e) { console.error('写入重启标记失败:', e.message); }

    // 自守护:自动 spawn 新进程
    const scriptPath = typeof __filename !== 'undefined' ? __filename : process.argv[1] || process.argv[0];
    const child = spawn(process.argv[0], [scriptPath], {
      detached: true,
      stdio: 'ignore',
      cwd: process.cwd(),
      env: { ...process.env }
    });
    child.unref(); // 父进程不等子进程
    console.log(`🌱 已启动子进程 ${child.pid},父进程即将退出`);
    process.exit(0);
  }, 2000);
}

