// ----------------- 重启后自动恢复引擎 -----------------
function restoreEngines() {
  // 清除 24h 重启计数器(新进程重新计数)
  restartCount24h = 0;
  if (REDQUEEN_BOOT)    { try { startRedQueen(); }          catch (e) { console.error('恢复红后失败:', e.message); } }
  if (YAODI_BOOT)      { try { startYaodiEvolution(); }    catch (e) { console.error('恢复尧帝失败:', e.message); } }
  if (EVOLUTION_BOOT)  { try { startEvolutionEngine(); }   catch (e) { console.error('恢复演化失败:', e.message); } }
  if (SHUNDI_BOOT)     { try { startShundiEngine(); }     catch (e) { console.error('恢复舜帝失败:', e.message); } }
  try { startStopLossMonitor(); } catch (e) { console.error('恢复止损监控失败:', e.message); } // 止损监控始终恢复
  // 【修复】热重启时也恢复ML自动训练调度器(冷启动在!wasRestarted分支处理)
  if (global.xgboostAutoTrainConfig?.autoTrain) {
    try { startMlAutoTrain(); console.log('[AutoTrain] ✅ 热重启已恢复ML自动训练调度器'); }
    catch (e) { console.error('[AutoTrain] ❌ 热重启恢复ML训练调度器失败:', e.message); }
  }
}

// ----------------- 启动守护进程 -----------------
function startWatchdog() {
  if (watchdogInterval) clearInterval(watchdogInterval);

  // 【修复】启动时立即同步一次状态,避免前端显示 unknown
  const syncModuleStatus = () => {
    YaodiBrain.systemModules.watchdog.status    = 'online';
    YaodiBrain.systemModules.watchdog.health    = 100;
    YaodiBrain.systemModules.watchdog.lastCheck = bjISO();

    YaodiBrain.systemModules.dataServer.status    = 'online';
    YaodiBrain.systemModules.dataServer.health    = 100;
    YaodiBrain.systemModules.dataServer.lastCheck = bjISO();

    YaodiBrain.systemModules.database.status    = 'online';
    YaodiBrain.systemModules.database.health    = 100;
    YaodiBrain.systemModules.database.lastCheck = bjISO();

    YaodiBrain.systemModules.yaodiAgent.status    = yaodiEvolutionRunning ? 'online' : 'standby';
    YaodiBrain.systemModules.yaodiAgent.health    = yaodiEvolutionRunning ? 100 : 50;
    YaodiBrain.systemModules.yaodiAgent.lastCheck = bjISO();

    YaodiBrain.systemModules.shundiEngine.status    = shundiRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.shundiEngine.health    = shundiRunning ? 100 : 0;
    YaodiBrain.systemModules.shundiEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.redqueenEngine.status    = redqueenRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.redqueenEngine.health    = redqueenRunning ? 100 : 0;
    YaodiBrain.systemModules.redqueenEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.evolutionEngine.status    = evolutionInterval !== null ? 'online' : 'standby';
    YaodiBrain.systemModules.evolutionEngine.health    = evolutionInterval !== null ? 100 : 50;
    YaodiBrain.systemModules.evolutionEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.stopLossMonitor.status    = stopLossMonitorRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.stopLossMonitor.health    = stopLossMonitorRunning ? 100 : 0;
    YaodiBrain.systemModules.stopLossMonitor.lastCheck = bjISO();

    YaodiBrain.systemModules.frontend.status    = 'online';
    YaodiBrain.systemModules.frontend.health    = 100;
  };
  syncModuleStatus(); // 立即同步一次

  // Watchdog 检查间隔:从 30s 放宽到 60s,减少碰撞
  watchdogInterval = setInterval(async () => {
    // 0. 同步 Watchdog 自身状态到 YaodiBrain.systemModules
    syncModuleStatus(); // 使用统一的状态同步函数

    YaodiBrain.systemModules.dataSource.status    = 'online';
    YaodiBrain.systemModules.dataSource.health    = 100;
    YaodiBrain.systemModules.dataSource.lastCheck = bjISO();

    YaodiBrain.systemModules.learningSystem.status    = 'online';
    YaodiBrain.systemModules.learningSystem.health    = 100;
    YaodiBrain.systemModules.learningSystem.lastCheck = bjISO();

    YaodiBrain.systemModules.branchManager.status    = 'online';
    YaodiBrain.systemModules.branchManager.health    = 100;
    YaodiBrain.systemModules.branchManager.lastCheck = bjISO();

    // 0.5 系统卡死/断网检测
    const systemHealth = await checkSystemHealth();
    if (!systemHealth.healthy) {
      console.error(`🚨 系统健康检测失败: ${systemHealth.reason}`);
      if (systemHealth.shouldStopService) {
        console.error('🛑 系统卡死或断网，自动停止FQMSystem服务...');
        gracefulShutdown('SYSTEM_FREEZE_OR_NETWORK_DOWN');
        return;
      }
    }

    // 1. 内存检查
    checkMemory();

    // 2. HTTP 健康检查(宽容策略:连续 2 次失败才重启)
    const health = await healthCheck();
    if (!health.ok) {
      _healthCheckFails++;
      if (_healthCheckFails >= 2) {
        console.error(`🚨 HTTP 健康检查连续失败 ${_healthCheckFails} 次,重启服务器`);
        gracefulRestart('HEALTH_CHECK_FAILED');
        _healthCheckFails = 0;
      } else {
        console.warn(`⚠️ HTTP 健康检查失败(第${_healthCheckFails}次,宽容模式,等下次确认)`);
      }
      return;
    } else {
      _healthCheckFails = 0; // 成功即重置
    }

    // 3. 引擎失活检测(定时器理论上在跑但实际卡死的情况)
    const engines = getEngineHealth();
    for (const [name, info] of Object.entries(engines)) {
      if (info.running) {
        // 检查心跳:上次日志时间超过 interval 的 2 倍 → 疑似卡死
        const lastLog = getLastLogTime(name);
        if (lastLog && Date.now() - lastLog > info.interval * 2) {
          console.warn(`⚠️ ${name} 引擎疑似卡死(${info.interval * 2 / 1000}s 无日志),尝试恢复`);
          try {
            if (name === 'redqueen')   { stopRedQueen(); startRedQueen(); }
            if (name === 'shundi')     { stopShundiEngine(); startShundiEngine(); }
            if (name === 'yaodi')      { stopYaodiEvolution(); startYaodiEvolution(); }
            if (name === 'evolution')   { stopEvolutionEngine(); startEvolutionEngine(); }
            if (name === 'scheduler')  { /* scheduler 只打印日志,无单独启动函数 */ }
          } catch (e) {
            console.error(`${name} 引擎恢复失败:`, e.message);
          }
        }
      }
    }
  }, 30000); // 每 30 秒检查一次

  // 24 小时自动重置计数器

setInterval(() => { restartCount24h = 0; }, 24 * 3600 * 1000);

  console.log('🛡️  Watchdog 守护进程已启动(每30秒检查健康)');
}

