// ----------------- 辅助:获取各引擎最后日志时间 -----------------
// 各引擎在写日志时会调用 addXXXLog / addRedQueenLog / console.log
// 守护进程通过追踪这些函数的最后调用时间来判定是否卡死
const engineHeartbeats = {};
function recordHeartbeat(engine) { engineHeartbeats[engine] = Date.now(); }
function getLastLogTime(engine)  { return engineHeartbeats[engine] || null; }

// ----------------- 在各引擎循环中植入心跳 -----------------
// (在 yaodiAutoEvolve / shundiAutoCycle / redqueenAutoCycle
//   / evolutionInterval 中已内置 try-catch,
//   守护进程补充外层监控)

// 注册 Node.js 全局异常捕获(最后防线)
// 🔧 修复EPIPE死循环: 不用console.error(向已关闭stdout写入会抛EPIPE→死循环)
process.on('uncaughtException', (err) => {
  try {
    const fs = require('fs');
    const fd = fs.openSync(path.join(PROJECT_ROOT, 'logs', 'uncaught_exception.log'), 'a');
    fs.writeSync(fd, `\n[${new Date().toISOString()}] 💥 未捕获异常: ${err.message}\n${err.stack || ''}\n`);
    fs.closeSync(fd);
  } catch(e) { /* 忽略写日志失败 */ }
  try { gracefulRestart('UNCAUGHT_EXCEPTION: ' + err.message); } catch(e) {}
  setTimeout(() => process.exit(1), 1000);
});

process.on('unhandledRejection', (reason, promise) => {
  const err = reason instanceof Error ? reason : new Error(String(reason));
  console.error('💥 未处理 Promise 拒绝:', err.message);
  console.error('💥 堆栈:', err.stack);
  gracefulRestart('UNHANDLED_REJECTION: ' + err.message);
});

