// 从东方财富获取上交所股票(6开头)- 分页获取
async function fetchFromSSE() {
  console.log('\n📡 [上交所验证数据] 正在获取...');

  try {
    const allStocks = [];

    // 分页获取,每页100条
    for (let page = 1; page <= 20; page++) {
      const url = `http://push2delay.eastmoney.com/api/qt/clist/get?pn=${page}&pz=100&po=1&np=1&fltt=2&invt=2&fid=f3&fs=m:0+t:6,m:0+t:80&fields=f12,f14&_=${Date.now()}`;

      const data = await fetchWithHeaders(url, {});
      const json = JSON.parse(data);

      if (json.data && json.data.diff && json.data.diff.length > 0) {
        for (const item of json.data.diff) {
          if (item.f12 && item.f14) {
            allStocks.push({
              code: String(item.f12).padStart(6, '0'),
              name: item.f14,
              source: 'SSE'
            });
          }
        }
        if (json.data.diff.length < 100) break; // 不足100条,说明已获取完毕
      } else {
        break;
      }
    }

    console.log(`  ✅ 上交所获取 ${allStocks.length} 只股票`);
    DATA_SOURCES.sse.lastSuccess = bjISO();
    DATA_SOURCES.sse.status = 'healthy';

    return allStocks;

  } catch (error) {
    console.log(`  ❌ 上交所获取失败: ${error.message}`);
    DATA_SOURCES.sse.lastFailure = bjISO();
    DATA_SOURCES.sse.failureCount++;
    DATA_SOURCES.sse.status = 'failed';

    return [];
  }
}

