// 带自定义headers的fetch
async function fetchWithHeaders(url, headers, retries = 3) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      return await new Promise((resolve, reject) => {
        const protocol = url.startsWith('https') ? https : http;
        const req = protocol.get(url, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
            'Accept': '*/*',
            'Accept-Language': 'zh-CN,zh;q=0.9',
            ...headers
          }
        }, (res) => {
          let data = '';
          res.setEncoding('utf8');
          res.on('data', chunk => data += chunk);
          res.on('end', () => resolve(data));
        });
        req.on('error', (e) => {
          // 【优化 2026-05-07】socket hang up时重试
          if (e.code === 'ECONNRESET' || e.message.includes('hang up')) {
            reject(new Error(`连接重置(尝试${attempt}/${retries})`));
          } else {
            reject(e);
          }
        });
        req.setTimeout(15000, () => {
          req.destroy();
          reject(new Error(`Timeout(尝试${attempt}/${retries})`));
        });
      });
    } catch (e) {
      if (attempt === retries) throw e;
      // 等待后重试
      await new Promise(r => setTimeout(r, 1000 * attempt));
    }
  }
  throw new Error('所有重试失败');
}

