// 交叉验证数据
async function validateDataWithExchange(mainData, exchangeData, exchangeName) {
  console.log(`\n🔍 使用 ${exchangeName} 数据进行交叉验证...`);

  const result = {
    total: mainData.length,
    verified: 0,
    mismatch: 0,
    missing: 0,
    accuracy: 0,
    details: []
  };

  // 创建交易所数据的映射
  const exchangeMap = new Map();
  exchangeData.forEach(s => exchangeMap.set(s.code, s));

  // 验证每只股票
  for (const stock of mainData) {
    const exchangeStock = exchangeMap.get(stock.code);

    if (exchangeStock) {
      result.verified++;

      // 检查名称是否一致
      if (stock.name !== exchangeStock.name) {
        result.mismatch++;
        result.details.push({
          code: stock.code,
          field: 'name',
          mainValue: stock.name,
          exchangeValue: exchangeStock.name
        });
      }
    } else {
      // 主数据中存在但交易所数据中不存在
      result.missing++;
      result.details.push({
        code: stock.code,
        issue: 'not_in_exchange',
        name: stock.name
      });
    }
  }

  // 计算准确率
  result.accuracy = (result.verified / result.total * 100).toFixed(2);

  console.log(`  ✅ 验证完成: ${result.verified}/${result.total} (${result.accuracy}%)`);
  if (result.mismatch > 0) {
    console.log(`  ⚠️  不一致: ${result.mismatch} 条`);
  }
  if (result.missing > 0) {
    console.log(`  ⚠️  缺失: ${result.missing} 条`);
  }

  return result;
}

// 执行完整验证流程
async function performDataValidation(mainData) {
  console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  console.log('🔍 数据验证流程启动');
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

  const validationResults = {
    timestamp: bjISO(),
    main_source: '聚合平台',
    exchange_validation: {}
  };

  // 1. 获取上交所数据并验证
  const sseData = await fetchFromSSE();
  if (sseData.length > 0) {
    const sseResult = await validateDataWithExchange(
      mainData.filter(s => s.code.startsWith('6')),  // 只验证上交所股票
      sseData,
      '上交所'
    );
    validationResults.exchange_validation.SSE = sseResult;
  }

  // 2. 获取深交所数据并验证
  const szseData = await fetchFromSZSE();
  if (szseData.length > 0) {
    const szseResult = await validateDataWithExchange(
      mainData.filter(s => s.code.startsWith('0') || s.code.startsWith('3')),  // 只验证深交所股票
      szseData,
      '深交所'
    );
    validationResults.exchange_validation.SZSE = szseResult;
  }

  // 3. 保存验证结果到数据库
  try {
    db.prepare(`
      INSERT INTO data_validation_log
      (timestamp, validation_results, main_count, sse_count, szse_count)
      VALUES (?, ?, ?, ?, ?)
    `).run(
      validationResults.timestamp,
      JSON.stringify(validationResults),
      mainData.length,
      sseData.length,
      szseData.length
    );
  } catch (e) {
    // 表不存在则创建
    db.exec(`
      CREATE TABLE IF NOT EXISTS data_validation_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,
        validation_results TEXT,
        main_count INTEGER,
        sse_count INTEGER,
        szse_count INTEGER
      )
    `);

    db.prepare(`
      INSERT INTO data_validation_log
      (timestamp, validation_results, main_count, sse_count, szse_count)
      VALUES (?, ?, ?, ?, ?)
    `).run(
      validationResults.timestamp,
      JSON.stringify(validationResults),
      mainData.length,
      sseData.length,
      szseData.length
    );
  }

  return validationResults;
}

