// 持仓股票实时价格更新
async function updateHoldingPrices() {
  try {
    // 获取所有持仓股票代码(主账户 mock_holdings + 舜帝 shundi_mock_holdings)
    const mainHoldings = db.prepare('SELECT DISTINCT code FROM mock_holdings WHERE code IS NOT NULL').all();
    const shundiHoldings = db.prepare('SELECT DISTINCT code FROM shundi_mock_holdings WHERE code IS NOT NULL').all();
    const allCodes = [...new Set([...mainHoldings.map(h => h.code), ...shundiHoldings.map(h => h.code)])];
    if (allCodes.length === 0) {
      console.log('📊 无持仓股票,跳过价格更新');
      return;
    }

    console.log(`📊 更新${allCodes.length}只持仓股票实时价格...`);

    // 批量获取实时价格(腾讯API)
    const batchSize = 100;
    for (let i = 0; i < allCodes.length; i += batchSize) {
      const batch = allCodes.slice(i, i + batchSize);
      const prefixBatch = batch.map(c => {
        if (c.startsWith('6')) return 'sh' + c;
        if (c.startsWith('0') || c.startsWith('3')) return 'sz' + c;
        return 'bj' + c;
      });

      const url = 'https://qt.gtimg.cn/q=' + prefixBatch.join(',');

      try {
        const data = await new Promise((resolve, reject) => {
          https.get(url, { timeout: 5000 }, (res) => {
            let chunks = [];
            res.on('data', chunk => chunks.push(chunk));
            res.on('end', () => {
              const buffer = Buffer.concat(chunks);
              resolve(iconv.decode(buffer, 'gbk'));
            });
          }).on('error', reject);
        });

        // 解析并更新
        for (const line of data.split('\n')) {
          const match = line.match(/v_([a-z]+)(\d+)="([^"]+)"/);
          if (!match) continue;

          const parts = match[3].split('~');
          if (parts.length < 35) continue;

          const code = parts[2];
          const price = parseFloat(parts[3]) || 0;
          const changePct = parseFloat(parts[32]) || 0;
          const change = parseFloat(parts[31]) || 0;
          const high = parseFloat(parts[33]) || 0;
          const low = parseFloat(parts[34]) || 0;
          const volume = parseFloat(parts[36]) || 0;
          const preClose = parseFloat(parts[4]) || 0;

          if (price > 0) {
            db.prepare(`
              INSERT OR REPLACE INTO stock_realtime
              (code, name, price, change, change_percent, high, low, volume, pre_close, update_time)
              VALUES (?, (SELECT name FROM stocks WHERE code = ?), ?, ?, ?, ?, ?, ?, ?, ?)
            `).run(code, code, price, change, changePct, high, low, volume, preClose, bjNow());

            // 【修复】舜帝持仓实时价格同步更新(无需等待refreshShundiHoldingsValue定时器)
            const shundiHolding = db.prepare('SELECT shares, avg_cost FROM shundi_mock_holdings WHERE code = ?').get(code);
            if (shundiHolding) {
              const marketVal = shundiHolding.shares * price;
              const profit = (price - shundiHolding.avg_cost) * shundiHolding.shares;
              const profitPct = shundiHolding.avg_cost > 0 ? ((price - shundiHolding.avg_cost) / shundiHolding.avg_cost * 100) : 0;
              db.prepare("UPDATE shundi_mock_holdings SET current_price = ?, market_value = ?, profit = ?, profit_percent = ?, pnl = ?, update_time = ? WHERE code = ?")
                .run(price, marketVal, profit, profitPct, profit, bjNow(), code);
            }
          }
        }
      } catch (e) {
        console.log(`  批次获取失败: ${e.message}`);
      }

      await new Promise(r => setTimeout(r, 100));
    }

    console.log(`✅ 持仓价格更新完成`);
  } catch (e) {
    console.log(`❌ 持仓价格更新失败: ${e.message}`);
  }
}

function startScheduler() {
  console.log('\n🔄 智能调度器启动');

  // 【P2修复2026-05-06】从实时行情生成今日K线
  const updateStockHistory = async () => {
    console.log('\n📈 开始更新历史K线数据...');
    try {
      // 获取持仓股代码
      const holdingCodes = db.prepare("SELECT DISTINCT code FROM shundi_mock_holdings").all().map(r => r.code);
      const poolCodes = db.prepare("SELECT DISTINCT code FROM user_stock_pool WHERE user_deleted=0").all().map(r => r.code);
      const allCodes = [...new Set([...holdingCodes, ...poolCodes])];

      if (allCodes.length === 0) {
        console.log('  无需更新的股票');
        return;
      }

      const today = toBeijingTime(new Date()).toISOString().slice(0, 10);
      // 【P2修复2026-06-15】跳过非交易日（周六/周日/节假日）
      const dow = new Date(toBeijingTime(new Date()).getTime()).getDay();
      if (dow === 0 || dow === 6) {
        console.log(`[K线更新] 今日(${today})是${dow===0?'周日':'周六'},跳过K线更新`);
        return;
      }
      let updatedCount = 0;

      for (const code of allCodes) {
        try {
          // 从实时行情获取今日数据
          const realtime = db.prepare("SELECT * FROM stock_realtime WHERE code = ?").get(code);
          if (!realtime || !realtime.price || realtime.price === 0) continue;

          // 检查是否已存在今日K线
          const existing = db.prepare("SELECT id FROM stock_history WHERE code = ? AND date = ?").get(code, today);
          if (existing) continue; // 已存在则跳过

          // 插入今日K线
          db.prepare(`
            INSERT INTO stock_history (code, name, date, open, high, low, close, volume, amount, change_percent)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          `).run(
            code,
            realtime.name || '',
            today,
            realtime.pre_close || realtime.price, // open = 昨收
            realtime.high || realtime.price,
            realtime.low || realtime.price,
            realtime.price,
            realtime.volume || 0,
            realtime.amount || 0,
            realtime.change_percent || 0
          );
          updatedCount++;
        } catch (e) {
          console.error(`  更新${code}失败:`, e.message);
        }
      }

      console.log(`  ✅ 更新 ${updatedCount} 条K线记录`);
    } catch (e) {
      console.log(`  ❌ K线更新失败: ${e.message}`);
    }
  };

  // 启动时执行一次 K 线更新
  setTimeout(updateStockHistory, 5000);

  // 每天 15:30(收盘后)执行一次
  const checkAndUpdateKlines = () => {
    const now = toBeijingTime(new Date());
    const hour = now.getHours();
    const minute = now.getMinutes();
    // 每天 15:30 执行
    if (hour === 15 && minute >= 30 && minute < 35) {
      updateStockHistory();
    }
  };
  // 【时段管控】交易时段5分钟/非交易时段1小时
  (function klineLoop() {
    checkAndUpdateKlines();
    const next = isTradingHours() ? 5 * 60 * 1000 : 60 * 60 * 1000;
    setTimeout(klineLoop, next);
  })();

  // 【时段管控】日批次L1排程:仅交易日9:00-11:30/13:00-15:00执行
  // 早盘9:00 + 尾盘15:35 自动触发L1全量筛选
  const scheduleDailyL1Batch = () => {
    const now = toBeijingTime(new Date());
    const hour = now.getHours();
    const minute = now.getMinutes();
    const isWeekday = now.getDay() >= 1 && now.getDay() <= 5;
    if (!isWeekday) return; // 非交易日不执行
    // 早盘9:00触发L1全量筛选
    if (hour === 9 && minute >= 0 && minute < 5) {
      if (yaodiV2Core) {
        console.log('🌅 [尧帝V2] 早盘9:00 L1全市场筛选...');
        yaodiV2Core.runDailyBatch().then(() => {
          const status = yaodiV2Core.getEngineStatus();
          console.log(`✅ [尧帝V2] 早盘筛选完成: L1=${status.l1Count}, L2=${status.l2Count}, L3=${status.l3Count}`);
        }).catch(e => {
          console.error('❌ [尧帝V2] 早盘筛选失败:', e.message);
        });
      }
    }
    // 尾盘15:35触发L1全量筛选(收盘后5分钟,确保行情数据完整)
    if (hour === 15 && minute >= 35 && minute < 40) {
      if (yaodiV2Core) {
        console.log('🔄 [尧帝V2] 收盘后L1全市场重新筛选...');
        yaodiV2Core.runDailyBatch().then(() => {
          const status = yaodiV2Core.getEngineStatus();
          console.log(`✅ [尧帝V2] 收盘后筛选完成: L1=${status.l1Count}, L2=${status.l2Count}, L3=${status.l3Count}`);
        }).catch(e => {
          console.error('❌ [尧帝V2] 收盘后筛选失败:', e.message);
        });
      }
    }
  };
  setInterval(scheduleDailyL1Batch, 5 * 60 * 1000); // 每5分钟检查一次

  // 【Phase2 板块轮动】每5分钟更新板块强弱
  scheduleSectorStrengthUpdate();
  // 初始化立即计算一次
  try { getStrongSectors(); } catch(e) {}

  // 根据当前时段确定间隔
  // 【时段管控】交易日9:00-11:30/13:00-15:00→1分钟,其余→30分钟
  const interval = isTradingHours() ? 1 * 60 * 1000 : 30 * 60 * 1000;
  console.log(`⏰ 当前间隔: ${interval / 60000} 分钟`);

  // 启动定时获取
  schedulerInterval = setInterval(async () => {
    const _schedStart = Date.now();
    console.log('\n⏰ 定时数据更新...');
    try {
      const stocks = await fetchAllStocks();
      saveData(stocks);
      calculateStats(stocks);

      // 【P1修复】定期执行尧帝智能选股,将L3信号转化为交易信号
      try {
        const signals = smartStockSelection(10, 'buy');
        if (signals.length > 0) {
          console.log(`[调度器] 尧帝生成 ${signals.length} 条交易信号`);
        }
      } catch (e) {
        console.log(`[调度器] 尧帝选股失败: ${e.message}`);
      }
    } catch (e) {
      console.log(`❌ 更新失败: ${e.message}`);
    }
    const _schedMs = Date.now() - _schedStart;
    if (_schedMs > 100) console.log(`⏱️ [CPU] schedulerInterval: ${_schedMs}ms`);
  }, interval);

  // 【时段管控】持仓价格:仅交易日9:00-11:30/13:00-15:00更新,3秒间隔;非交易时段用缓存
  setInterval(() => {
    if (!isTradingHours()) return; // 非交易时段用后台缓存数据
    updateHoldingPrices();
  }, 3 * 1000);

  // 【时段管控】收藏股快速刷新:仅交易日9:00-11:30/13:00-15:00,3秒
  setInterval(() => {
    if (!isTradingHours()) return; // 非交易时段不刷新
    try {
      const pool = db.prepare("SELECT code FROM user_stock_pool WHERE user_deleted=0").all();
      if (!pool.length) return;
      const codes = pool.map(p => p.code);
      const prefixCodes = codes.map(c => c.startsWith('6') ? 'sh' + c : (c.startsWith('0') || c.startsWith('3') ? 'sz' + c : 'bj' + c));
      const url = 'https://qt.gtimg.cn/q=' + prefixCodes.join(',');
      https.get(url, { timeout: 3000 }, (res) => {
        let chunks = [];
        res.on('data', chunk => chunks.push(chunk));
        res.on('end', () => {
          try {
            const buf = Buffer.concat(chunks);
            const txt = iconv.decode(buf, 'gbk');
            for (const line of txt.split('\n')) {
              const m = line.match(/v_([a-z]+)(\d+)=\"([^\"]+)\"/);
              if (!m) continue;
              const parts = m[3].split('~');
              if (parts.length < 35) continue;
              const code = parts[2];
              const price = parseFloat(parts[3]) || 0;
              if (!price) continue;
              db.prepare(`INSERT OR REPLACE INTO stock_realtime (code, name, price, change, change_percent, high, low, volume, pre_close, update_time) VALUES (?, (SELECT name FROM stocks WHERE code = ?), ?, ?, ?, ?, ?, ?, ?, ?)`).run(
                code, code, price, parseFloat(parts[31]) || 0, parseFloat(parts[32]) || 0,
                parseFloat(parts[33]) || 0, parseFloat(parts[34]) || 0,
                parseFloat(parts[36]) || 0, parseFloat(parts[4]) || 0, bjNow()
              );
            }
          } catch (e) { /* silent */ }
        });
      }).on('error', () => { /* silent */ });
    } catch (e) { /* silent */ }
  }, 3 * 1000);

  // ═══════════════════════════════════════════════════════════════
  // 主力资金采集系统 v3 (2026-06-03 重构)
  // 三种模式: 历史全量 / 日常实时 / 每日校验补缺
  // ═══════════════════════════════════════════════════════════════

  const MF_BATCH_SIZE = 200;   // 每批采集数量
  const MF_TOTAL_STOCKS = 5437; // 全市场可交易个股数

  // 缓存股票代码列表
  let cachedStockCodes = null;
  let cacheTime = 0;
  const CACHE_TTL = 300000;

  const getStockCodes = () => {
    const now = Date.now();
    if (!cachedStockCodes || now - cacheTime > CACHE_TTL) {
      try {
        const rows = db.prepare(`
          SELECT code FROM stocks
          WHERE code GLOB '6*' OR code GLOB '0*' OR code GLOB '3*' OR code GLOB '68*'
        `).all().map(r => r.code);
        cachedStockCodes = rows;
        cacheTime = now;
        console.log(`[主力资金] 股票代码缓存: ${cachedStockCodes.length} 只`);
      } catch (e) {
        console.log(`[主力资金] 缓存失败: ${e.message}`);
        cachedStockCodes = [];
      }
    }
    return cachedStockCodes;
  };

  // ── 获取个股历史主力资金(交易时段:push2his 30天K线; 非交易时段:push2delay 今日+5日) ──
  async function fetchMainFlowHistory(code) {
    const secid = code.startsWith('6') ? `1.${code}` : `0.${code}`;
    const inTrading = isTradingHours();

    // 交易时段: 尝试push2his历史K线API(30天)
    if (inTrading) {
      try {
        const resp = await axios.get('https://push2his.eastmoney.com/api/qt/stock/fflow/daykline/get', {
          params: {
            lmt: 30, klt: 101, secid,
            fields1: 'f1,f2,f3,f7',
            fields2: 'f51,f52,f53,f54,f55,f56,f57,f58,f59,f60,f61,f62,f63'
          },
          timeout: 10000,
          headers: { 'Referer': 'https://data.eastmoney.com/', 'User-Agent': 'Mozilla/5.0' }
        });
        const klines = resp.data?.data?.klines;
        if (klines && klines.length > 0) {
          const stmt = db.prepare(`INSERT OR REPLACE INTO stock_main_flow
            (code, date, main_inflow, super_inflow, retail_inflow, main_ratio, price, change_percent)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)`);
          const insertMany = db.transaction((items) => {
            for (const item of items) stmt.run(item.code, item.date, item.main_inflow, item.super_inflow, item.retail_inflow, item.main_ratio, item.price, item.change_percent);
          });
          const rows = klines.map(line => {
            const p = line.split(',');
            return {
              code, date: p[0],
              main_inflow: parseFloat(p[1]) || 0,
              super_inflow: parseFloat(p[2]) || 0,
              retail_inflow: parseFloat(p[3]) || 0,
              main_ratio: parseFloat(p[6]) || 0,
              price: parseFloat(p[11]) || 0,
              change_percent: parseFloat(p[12]) || 0
            };
          });
          insertMany(rows);
          return rows.length;
        }
      } catch (e) { /* push2his失败,回退push2delay */ }
    }

    // 非交易时段或push2his失败: 回退push2delay(今日+5日)
    try {
      const data = await fetchStockMainFlow(code, 1);
      return data && data.length > 0 ? data.length : 0;
    } catch (e) {
      return -1;
    }
  }

  // ── 模式1: 历史全量采集(仅首次运行或手动触发) ──
  let mfHistoryCursor = 0;
  let mfHistoryRunning = false;

  const collectMainFlowHistory = async () => {
    if (mfHistoryRunning) return;
    mfHistoryRunning = true;

    try {
      // 检查已覆盖数量
      const covered = db.prepare('SELECT COUNT(DISTINCT code) as cnt FROM stock_main_flow').get()?.cnt || 0;
      if (covered >= MF_TOTAL_STOCKS) {
        console.log(`[主力资金] 历史数据已完整(${covered}/${MF_TOTAL_STOCKS}), 跳过全量采集`);
        mfHistoryRunning = false;
        return;
      }

      // 找出缺失的股票
      const allCodes = getStockCodes();
      const existingCodes = new Set(db.prepare('SELECT DISTINCT code FROM stock_main_flow').all().map(r => r.code));
      const missingCodes = allCodes.filter(c => !existingCodes.has(c));

      console.log(`💰 [历史全量] 缺失 ${missingCodes.length} 只, 已覆盖 ${existingCodes.size} 只`);

      if (missingCodes.length === 0) {
        mfHistoryRunning = false;
        return;
      }

      // 分批采集,每批200只
      const batch = missingCodes.slice(mfHistoryCursor, mfHistoryCursor + MF_BATCH_SIZE);
      if (batch.length === 0) {
        mfHistoryCursor = 0; // 重置游标
        mfHistoryRunning = false;
        return;
      }

      let ok = 0, fail = 0;
      for (const code of batch) {
        // 先尝试历史K线API(30天),再补充实时API(今日+5日)
        let count = await fetchMainFlowHistory(code);
        if (count > 0) { ok++; }
        else {
          // 历史API失败,回退实时API
          try {
            const data = await fetchStockMainFlow(code, 1);
            if (data && data.length > 0) ok++; else fail++;
          } catch (e) { fail++; }
        }
        await new Promise(r => setTimeout(r, 150));
      }

      mfHistoryCursor += batch.length;
      const newCovered = db.prepare('SELECT COUNT(DISTINCT code) as cnt FROM stock_main_flow').get()?.cnt || 0;
      console.log(`✅ [历史全量] 本批: 成功${ok}/失败${fail} | 总覆盖: ${newCovered}/${MF_TOTAL_STOCKS} | 游标: ${mfHistoryCursor}`);

      // 已全部完成
      if (newCovered >= MF_TOTAL_STOCKS || mfHistoryCursor >= missingCodes.length) {
        console.log(`🏁 [历史全量] 采集完成! 覆盖 ${newCovered} 只`);
        mfHistoryCursor = 0;
      }
    } catch (e) {
      console.log(`❌ [历史全量] 失败: ${e.message}`);
    }
    mfHistoryRunning = false;
  };

  // ── 模式2: 日常实时采集(仅当日数据) ──
  let mfRealtimeCursor = 0;

  const collectMainFlowRealtime = async () => {
    try {
      const allStocks = getStockCodes();
      if (allStocks.length === 0) return;

      // 游标越界则重置
      if (mfRealtimeCursor >= allStocks.length) {
        mfRealtimeCursor = 0;
        console.log(`[主力资金-实时] 新一轮开始, 共 ${allStocks.length} 只`);
      }

      const batch = allStocks.slice(mfRealtimeCursor, mfRealtimeCursor + MF_BATCH_SIZE);
      let ok = 0, fail = 0;

      for (const code of batch) {
        try {
          const data = await fetchStockMainFlow(code, 1);
          if (data && data.length > 0) ok++;
          await new Promise(r => setTimeout(r, 100));
        } catch (e) { fail++; }
      }

      mfRealtimeCursor += batch.length;
      console.log(`✅ [主力资金-实时] 成功${ok}/失败${fail} | 进度 ${Math.min(mfRealtimeCursor, allStocks.length)}/${allStocks.length}`);
    } catch (e) {
      console.log(`❌ [主力资金-实时] 失败: ${e.message}`);
    }
  };

  // ── 模式3: 每日校验补缺(检查覆盖完整性) ──
  const validateMainFlowCoverage = async () => {
    try {
      const allCodes = getStockCodes();
      const existingCodes = new Set(db.prepare('SELECT DISTINCT code FROM stock_main_flow').all().map(r => r.code));
      const missing = allCodes.filter(c => !existingCodes.has(c));

      if (missing.length === 0) {
        console.log(`✅ [主力资金-校验] 覆盖完整 ${existingCodes.size}/${allCodes.length}`);
        return;
      }

      console.log(`⚠️ [主力资金-校验] 缺失 ${missing.length} 只, 开始补采...`);

      let ok = 0, fail = 0;
      // 分批补采,每批200只
      for (let i = 0; i < missing.length; i += MF_BATCH_SIZE) {
        const batch = missing.slice(i, i + MF_BATCH_SIZE);
        for (const code of batch) {
          let count = await fetchMainFlowHistory(code);
          if (count > 0) { ok++; }
          else {
            try {
              const data = await fetchStockMainFlow(code, 1);
              if (data && data.length > 0) ok++; else fail++;
            } catch (e) { fail++; }
          }
          await new Promise(r => setTimeout(r, 150));
        }
        // 批次间休息2秒避免限流
        if (i + MF_BATCH_SIZE < missing.length) {
          await new Promise(r => setTimeout(r, 2000));
        }
      }

      const newCovered = db.prepare('SELECT COUNT(DISTINCT code) as cnt FROM stock_main_flow').get()?.cnt || 0;
      console.log(`✅ [主力资金-校验] 补采完成: 成功${ok}/失败${fail} | 总覆盖: ${newCovered}/${allCodes.length}`);
    } catch (e) {
      console.log(`❌ [主力资金-校验] 失败: ${e.message}`);
    }
  };

  // ── 统一调度 ──
  // 判断历史数据是否已完整
  const isMainFlowHistoryComplete = () => {
    const covered = db.prepare('SELECT COUNT(DISTINCT code) as cnt FROM stock_main_flow').get()?.cnt || 0;
    return covered >= MF_TOTAL_STOCKS;
  };

  // 调度: 历史未完成→全时段采集(push2delay全天可用); 历史已完成→仅交易时段实时采集
  setInterval(() => {
    if (!isMainFlowHistoryComplete()) {
      collectMainFlowHistory(); // 非交易时段也用push2delay采集,全时段
    } else if (isTradingHours()) {
      collectMainFlowRealtime(); // 历史完成后,仅交易时段采实时数据
    }
  }, 2 * 60 * 1000);

  // 每日校验: 每天9:05运行一次
  const scheduleDailyValidation = () => {
    const now = new Date();
    const bjHour = (now.getUTCHours() + 8) % 24;
    const bjMin = now.getUTCMinutes();
    let delayMs;
    const targetMinutes = 9 * 60 + 5;
    const currentMinutes = bjHour * 60 + bjMin;
    if (currentMinutes < targetMinutes) {
      delayMs = (targetMinutes - currentMinutes) * 60000;
    } else {
      delayMs = (24 * 60 - currentMinutes + targetMinutes) * 60000;
    }
    setTimeout(async () => {
      await validateMainFlowCoverage();
      setInterval(validateMainFlowCoverage, 24 * 60 * 60 * 1000);
    }, delayMs);
  };
  scheduleDailyValidation();

  // 启动时立即采集(不限制交易时段,因为push2delay全天可用)
  setTimeout(() => {
    if (!isMainFlowHistoryComplete()) {
      collectMainFlowHistory();
    } else if (isTradingHours()) {
      collectMainFlowRealtime();
    }
  }, 15000);

  // 首次立即获取
  setTimeout(async () => {
    // 先更新持仓价格(快速)
    await updateHoldingPrices();
    // 再更新全市场(慢速)
    const stocks = await fetchAllStocks();
    saveData(stocks);
    calculateStats(stocks);
  }, 2000);
}

// ═══════════════════════════════════════════════════════════════
// 尧帝智能体演化引擎
// ═══════════════════════════════════════════════════════════════

// 演化引擎状态
let evolutionEngineRunning = false;
let evolutionInterval = null;

// 校验尧帝数据真实性
function validateYaodiData() {
  const branches = db.prepare('SELECT * FROM yaodi_branch WHERE active = 1').all();
  const main = db.prepare('SELECT * FROM yaodi_main LIMIT 1').get();

  const issues = [];
  const techBranches = branches.filter(b => b.is_tech_model === 1);
  const strategyBranches = branches.filter(b => b.is_tech_model !== 1);

  // 检查准确率是否合理
  branches.forEach(b => {
    if (b.accuracy > 95) {
      issues.push({ type: 'accuracy', id: b.id, name: b.name, value: b.accuracy, message: '准确率过高,不符合实际' });
    }
    if (b.reliability_score > 0.95) {
      issues.push({ type: 'reliability', id: b.id, name: b.name, value: b.reliability_score, message: '可靠度过高,缺乏梯度' });
    }
  });

  // 检查演化等级分布
  const evolutionLevels = branches.map(b => b.evolution_level);
  const maxLevel = Math.max(...evolutionLevels);
  const minLevel = Math.min(...evolutionLevels);

  // 统计技术分析和策略分支
  const techCount = techBranches.length;
  const strategyCount = strategyBranches.length;

  return {
    success: true,
    totalBranches: branches.length,
    techBranches: techCount,
    strategyBranches: strategyCount,
    issues: issues,
    dataQuality: issues.length === 0 ? '良好' : '存在问题',
    evolutionLevelRange: { min: minLevel, max: maxLevel },
    avgAccuracy: (branches.reduce((sum, b) => sum + b.accuracy, 0) / branches.length).toFixed(2),
    avgReliability: (branches.reduce((sum, b) => sum + b.reliability_score, 0) / branches.length).toFixed(2)
  };
}

// 校正尧帝数据到合理范围
// 🔧 全局标志:防止 calibrateYaodiData 重复执行破坏数据
let yaodiCalibrated = false;

function calibrateYaodiData() {
  if (yaodiCalibrated) {
    console.log('✅ 尧帝数据校准已跳过(已在本会话执行)');
    return;
  }
  yaodiCalibrated = true;

  // 异步执行校准,不阻塞API服务
  setImmediate(() => {
    console.log('\n🔧 开始异步尧帝数据校准...');

    try {
      // 🔧 1. 从 evolution_history 恢复被破坏的准确率(子分支的 accuracy_before = 原始准确率)
      try {
        const restored = db.prepare(`
          UPDATE yaodi_branch SET accuracy = (
            SELECT eh.accuracy_before
            FROM evolution_history eh
            WHERE eh.parent_id = yaodi_branch.id
            ORDER BY eh.id DESC LIMIT 1
          )
          WHERE active = 1
          AND EXISTS (
            SELECT 1 FROM evolution_history eh2
            WHERE eh2.parent_id = yaodi_branch.id LIMIT 1
          )
          AND accuracy < 60
        `).run();
        if (restored?.changes > 0) console.log(`🔄 从演化历史恢复 ${restored.changes} 个分支的原始准确率`);
      } catch(e) { console.error('恢复准确率失败:', e.message); }

      // 🔧 2. 只对原始种子分支做一次性的合理校准(evolution_level=1,无演化历史的)
      // 改为有条件更新:只在值异常(<50)时才修正,不触碰正常值
      db.prepare(`
        UPDATE yaodi_branch SET
          accuracy = MAX(55, MIN(85, accuracy)),
          reliability_score = MAX(0.50, MIN(0.90, reliability_score)),
          evolution_level = MAX(1, evolution_level)
        WHERE active = 1
        AND evolution_level <= 2
        AND NOT EXISTS (
          SELECT 1 FROM evolution_history eh3
          WHERE eh3.parent_id = yaodi_branch.id LIMIT 1
        )
        AND accuracy < 50
      `).run();

      // 🔧 3. 校正尧帝主数据(幂等保护:仅在值为0/NULL时才覆盖)
      const main = db.prepare('SELECT * FROM yaodi_main LIMIT 1').get();
      console.log('[TRACE] calibrate main_version BEFORE=', main?.main_version, 'evo=', main?.evolution_count);
      if (main) {
        // 【P1修复】尧帝胜率来自舜帝已平仓卖出交易(非全量交易)
        // 关键:只有卖出交易才有pnl意义,买入交易pnl=0不应计入胜率统计
        const shundiTradeStats = db.prepare(`
          SELECT COUNT(*) as cnt,
                 SUM(CASE WHEN pnl > 0 THEN 1 ELSE 0 END) as wins,
                 SUM(pnl) as total_pnl,
                 AVG(pnl) as avg_pnl
          FROM shundi_mock_trades
          WHERE status='filled' AND type IN ('sell','卖出','止损','止盈','shundi_stoploss','部分止盈')
        `).get();
        const shundiCnt = shundiTradeStats?.cnt || 0;
        const shundiWins = shundiTradeStats?.wins || 0;
        // 舜帝胜率:只统计已平仓卖出交易
        const shundiWinRate = shundiCnt > 0 ? parseFloat(((shundiWins / shundiCnt) * 100).toFixed(1)) : 0;

        // 【尧帝分支统计】永远从分支实时计算
        const branchAvg = db.prepare('SELECT AVG(accuracy) as avg_acc, AVG(win_rate) as avg_wr FROM yaodi_branch WHERE active = 1').get();
        const realAccuracy = parseFloat((branchAvg?.avg_acc ?? 60).toFixed(1));
        const branchWinRate = parseFloat((branchAvg?.avg_wr ?? 60).toFixed(1));
        // 【修复】total_trades 只用舜帝实际交易笔数
        const totalTrades = shundiCnt;

        // 【P1修复】尧帝综合胜率权重调整
        // 有真实卖出交易时:舜帝真实胜率权重70% + 分支平均胜率权重30%
        // 无真实交易时:使用分支平均胜率(回测参考值)
        let realWinRate;
        if (shundiCnt > 0) {
          realWinRate = parseFloat((shundiWinRate * 0.7 + branchWinRate * 0.3).toFixed(1));
        } else {
          realWinRate = branchWinRate;
        }

        // 【修复】avg_return = 分支性能平均盈利率(百分比,不依赖舜帝绝对金额)
        const branchPerfStats = db.prepare('SELECT AVG(profit_rate) as avg, MIN(profit_rate) as min FROM branch_performance').get();
        // 【修复】avg_return 使用舜帝真实交易平均盈亏(不再使用分支回测数据)
        const realAvgReturn = shundiTradeStats?.avg_pnl != null ? parseFloat(shundiTradeStats.avg_pnl.toFixed(2)) : 0;

        // 【其他字段】舜帝数据优先,否则保留已有值
        const evoHistoryCount = db.prepare('SELECT COUNT(*) as cnt FROM evolution_history').get()?.cnt || 0;
        const keepVersion = main.main_version || 1;
        const speed = main.evolution_speed <= 1 ? 50 : main.evolution_speed;
        const realActiveDays = main.active_days || 14;
        // 【修复】从舜帝真实交易计算夏普比率和最大回撤,禁止硬编码
        const shundiAllPnl = db.prepare("SELECT pnl FROM shundi_mock_trades WHERE status='filled' AND type IN ('sell','卖出','止损','止盈','shundi_stoploss','部分止盈') AND pnl IS NOT NULL ORDER BY created_at ASC").all();
        let realSharpe = -1.82; // 默认保守值
        let realMaxDrawdown = -21419.24; // 默认真实值
        if (shundiAllPnl.length > 1) {
          const mean = shundiAllPnl.reduce((s, r) => s + r.pnl, 0) / shundiAllPnl.length;
          const variance = shundiAllPnl.reduce((s, r) => s + (r.pnl - mean) ** 2, 0) / shundiAllPnl.length;
          const std = Math.sqrt(variance);
          realSharpe = std > 0 ? parseFloat((mean / std).toFixed(2)) : 0;
          // 最大回撤
          let cum = 0, peak = 0, maxDD = 0;
          shundiAllPnl.forEach(r => {
            cum += r.pnl;
            if (cum > peak) peak = cum;
            const dd = peak - cum;
            if (dd > maxDD) maxDD = dd;
          });
          realMaxDrawdown = parseFloat(maxDD.toFixed(2));
          // 也更新 yaodi_main 中的 avg_return 为真实平均每笔盈亏
          db.prepare('UPDATE yaodi_main SET avg_return = ?, sharpe_ratio = ?, max_drawdown = ? WHERE id = 1').run(
            parseFloat(mean.toFixed(2)), realSharpe, -Math.abs(realMaxDrawdown)
          );
          console.log(`[校准] 真实数据: avg_pnl=${mean.toFixed(2)}, sharpe=${realSharpe}, maxDD=${realMaxDrawdown}`);
        }

        if (main.evolution_speed <= 1) {
          db.prepare("UPDATE yaodi_main SET evolution_speed = 50 WHERE id = 1").run();
          console.log(`⚠️ 演化速度已自动提升 1→50`);
        }

        // 【修复】直接写入真实值,不使用幂等保护(幂等保护会导致负值被跳过)
        // 之前COALESCE(NULLIF(...))逻辑过于保守,校准只在首次启动执行
        const existingAcc = main.accuracy || 0;
        db.prepare(`
          UPDATE yaodi_main SET
            accuracy       = ?,
            avg_return     = ?,
            win_rate       = ?,
            total_trades   = ?,
            evolution_count = ?,
            main_version   = ?,
            evolution_speed = ?,
            active_days    = ?,
            sharpe_ratio   = ?,
            max_drawdown   = ?,
            win_count      = ?
          WHERE id = 1
        `).run(
          realAccuracy, realAvgReturn, realWinRate, totalTrades,
          evoHistoryCount, keepVersion, speed, realActiveDays,
          realSharpe, -Math.abs(realMaxDrawdown), shundiWins
        );
                const branchTrades = db.prepare('SELECT SUM(trades) as s FROM yaodi_branch WHERE active=1').get()?.s || 0;
        console.log(`🔧 尧帝数据已同步(幂等):acc=${realAccuracy}% win=${realWinRate}% ret=${realAvgReturn}% trades=${totalTrades}(舜${shundiCnt}+分${branchTrades}) wins=${shundiWins}`);
      }
      console.log('✅ 尧帝数据已校正(幂等保护:仅首次执行)');
    } catch (e) {
      console.error('尧帝数据校准失败:', e.message);
    }
  });
}

