// 分支演化函数 - 生成新分支



// 获取演化统计报告
function getEvolutionStatsReport() {
  const main = db.prepare('SELECT * FROM yaodi_main LIMIT 1').get();

  const strategyStats = db.prepare(`
    SELECT evolution_type, COUNT(*) as count, AVG(accuracy_after - accuracy_before) as avg_delta
    FROM evolution_history GROUP BY evolution_type ORDER BY count DESC
  `).all();

  const envStats = db.prepare(`
    SELECT environment, COUNT(*) as count FROM evolution_history GROUP BY environment ORDER BY count DESC
  `).all();

  return {
    main_version: main?.main_version || 0,
    evolution_count: main?.evolution_count || 0,
    strategy_stats: strategyStats,
    environment_stats: envStats
  };
}


// ═══════════════════════════════════════════════════════════════
// 第三阶段:分支杂交系统
// ═══════════════════════════════════════════════════════════════

// 杂交类型
const CROSSOVER_TYPE = {
  UNIFORM: 'uniform',         // 均匀杂交:随机选择父本参数
  SINGLE_POINT: 'single',     // 单点杂交:继承前半或后半
  BLEND: 'blend',            // 混合杂交:参数加权平均
  ENVIRONMENTAL: 'environmental' // 环境杂交:选择同环境下优秀分支
};

// 分支杂交 - 让两个优秀分支产生更强后代
function crossoverBranches(branchId1, branchId2, isTechModel) {
  const parent1 = db.prepare('SELECT * FROM yaodi_branch WHERE id = ?').get(branchId1);
  const parent2 = db.prepare('SELECT * FROM yaodi_branch WHERE id = ?').get(branchId2);

  if (!parent1 || !parent2) {
    return { success: false, error: '父分支不存在' };
  }

  // 【BUGFIX】演化等级上限保护:超过MAX_EVO_LEVEL的分支不再参与杂交,防止OBV类分支演化爆炸
  const MAX_EVO_LEVEL = 1000;
  const maxParentEvo = Math.max(parent1.evolution_level || 0, parent2.evolution_level || 0);
  if (maxParentEvo > MAX_EVO_LEVEL) {
    return { success: false, error: `演化等级超限(${maxParentEvo}>${MAX_EVO_LEVEL}),跳过杂交` };
  }

  const currentEnv = detectMarketEnvironment();

  // 选择杂交类型
  const crossoverType = Math.random() < 0.4 ? CROSSOVER_TYPE.BLEND :
                        Math.random() < 0.6 ? CROSSOVER_TYPE.ENVIRONMENTAL :
                        CROSSOVER_TYPE.UNIFORM;

  let newAccuracy, newReliability, newStrategy, newName, newDescription;

  switch (crossoverType) {
    case CROSSOVER_TYPE.BLEND:
      // 混合杂交:参数加权平均
      const weight = Math.random() * 0.4 + 0.3; // 0.3-0.7
      newAccuracy = parent1.accuracy * weight + parent2.accuracy * (1 - weight);
      newReliability = parent1.reliability_score * weight + parent2.reliability_score * (1 - weight);
      break;

    case CROSSOVER_TYPE.UNIFORM:
      // 均匀杂交:随机继承
      newAccuracy = Math.random() < 0.5 ? parent1.accuracy : parent2.accuracy;
      newReliability = Math.random() < 0.5 ? parent1.reliability_score : parent2.reliability_score;
      break;

    default:
      // 取两者较好的
      newAccuracy = Math.max(parent1.accuracy, parent2.accuracy);
      newReliability = Math.max(parent1.reliability_score, parent2.reliability_score);
  }

  // 杂交后准确率通常比父母好一点点(杂交优势)
  newAccuracy = Math.min(99.9, newAccuracy * (1 + Math.random() * 0.05));
  newReliability = Math.min(0.90, newReliability * (1 + Math.random() * 0.02));

  const newLevel = Math.max(parent1.evolution_level, parent2.evolution_level) + 1;

  // 继承父本1的名称策略,偶尔变异
  if (Math.random() < 0.8) {
    newStrategy = Math.random() < 0.5 ? parent1.strategy : parent2.strategy;
    const template1 = TECH_MODEL_NAMES.find(t => t.strategy === newStrategy) ||
                      STRATEGY_NAMES.find(t => t.strategy === newStrategy);
    if (template1) {
      newName = template1.name + '_v' + newLevel;
      newDescription = template1.description + ',杂交演化等级Lv.' + newLevel + ',准确率' + newAccuracy.toFixed(1) + '%';
    } else {
      newName = parent1.name.split('_v')[0] + '_v' + newLevel;
      newDescription = '杂交策略,演化等级Lv.' + newLevel + ',准确率' + newAccuracy.toFixed(1) + '%';
    }
  } else {
    // 探索新组合
    const template = isTechModel ? TECH_MODEL_NAMES[Math.floor(Math.random() * TECH_MODEL_NAMES.length)] :
                                  STRATEGY_NAMES[Math.floor(Math.random() * STRATEGY_NAMES.length)];
    newName = template.name + '_v' + newLevel;
    newStrategy = template.strategy;
    newDescription = template.description + ',杂交演化等级Lv.' + newLevel + ',准确率' + newAccuracy.toFixed(1) + '%';
  }

  const newId = 'cross_' + Date.now();

  // 【BUGFIX#3】修复字段顺序错位:原代码将错误的值赋给了trades/win_rate
  // 正确顺序:id, name, branch_name, strategy, accuracy, active, trades, win_rate, evolution_level, reliability_score, scene, is_tech_model, description
  db.prepare('INSERT INTO yaodi_branch (id, name, branch_name, strategy, accuracy, active, trades, win_rate, evolution_level, reliability_score, scene, is_tech_model, description) VALUES (?, ?, ?, ?, ?, 0, 0, ?, ?, ?, ?, ?, ?)').run(
    newId, newName, newName, newStrategy || parent1.strategy, newAccuracy.toFixed(2),
    Math.max(0, Math.min(99.9, newAccuracy - 10 + Math.random() * 20)).toFixed(2), newLevel, newReliability.toFixed(2),
    '', isTechModel ? 1 : 0, newDescription
  );

  // 记录杂交历史
  db.prepare('INSERT INTO evolution_history (generation, parent_id, child_id, child_name, evolution_type, accuracy_before, accuracy_after, environment) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
    .run(Math.max(parent1.evolution_level, parent2.evolution_level), branchId1 + '+' + branchId2, newId, newName, 'crossover', (parent1.accuracy + parent2.accuracy) / 2, newAccuracy, currentEnv);

  console.log('🧬 🔀杂交[' + currentEnv + '] ' + parent1.name + ' × ' + parent2.name + ' -> ' + newName + ' (准确率: ' + newAccuracy.toFixed(1) + '%)');

  // 【版本记录】记录杂交产生的新分支
  try {
    const EVOLUTION_DIR = path.join(__dirname, '..', '.evolution');
    const VERSIONS_FILE = path.join(EVOLUTION_DIR, 'versions.json');
    if (fs.existsSync(VERSIONS_FILE)) {
      const versions = JSON.parse(fs.readFileSync(VERSIONS_FILE, 'utf-8'));
      const lastVer = versions.versions.length > 0 ? versions.versions[versions.versions.length - 1].version : '1.0.0';
      const parts = lastVer.split('.');
      const newVer = `${parts[0]}.${parts[1]}.${parseInt(parts[2] || 0) + 1}`;
      versions.versions.push({
        version: newVer,
        timestamp: bjISO(),
        reason: '分支杂交',
        modifications: [{ id: newId, file: 'yaodi_branch', reason: `${parent1.name} + ${parent2.name} → ${newName}` }],
        metrics: { accuracy: newAccuracy, reliability: newReliability }
      });
      fs.writeFileSync(VERSIONS_FILE, JSON.stringify(versions, null, 2));
    }
  } catch (e) { /* 静默失败 */ }

  return { success: true, newBranch: { id: newId, name: newName, accuracy: newAccuracy, evolution_level: newLevel, crossover_type: crossoverType } };
}

// 触发杂交的条件检查
function shouldCrossover() {
  // 【修复6】每20次演化触发一次(原来50→20),增加杂交频率
  // 智能选择:只在环境稳定时杂交,避免极端市场下的破坏性交叉
  const main = db.prepare('SELECT evolution_count FROM yaodi_main LIMIT 1').get();
  if (!main) return false;
  if (main.evolution_count % 20 !== 0) return false;

  // 只在市场非极端时杂交(极端市场环境下杂交效果差)
  const marketStats = db.prepare("SELECT * FROM market_stats ORDER BY id DESC LIMIT 1").get();
  const upRatio = marketStats ? (marketStats.up_count || 0) / Math.max(marketStats.total_count || 1, 1) : 0.5;
  if (upRatio < 0.25 || upRatio > 0.85) {
    console.log('[crossover] 跳过: 市场极端(' + (upRatio * 100).toFixed(1) + '%)');
    return false;
  }

  // 检查最近杂交表现,如果连续负向则暂停
  const recentCrossover = db.prepare("SELECT avg_delta FROM evolution_history WHERE operation='crossover' ORDER BY id DESC LIMIT 3").all();
  if (recentCrossover.length >= 2 && recentCrossover.every(r => (r.avg_delta || 0) < 0)) {
    console.log('[crossover] 暂停: 最近3次杂交均为负向');
    return false;
  }

  return true;
}

// 执行条件杂交
function performConditionalCrossover() {
  const currentEnv = detectMarketEnvironment();

  // 获取当前环境下表现最好的两个不同分支
  const branches = db.prepare(`
    SELECT DISTINCT b.id, b.name, b.accuracy, b.is_tech_model, bp.win_rate
    FROM yaodi_branch b
    LEFT JOIN branch_performance bp ON b.id = bp.branch_id AND bp.environment = ?
    WHERE b.active = 1
    ORDER BY bp.win_rate DESC NULLS LAST, b.accuracy DESC
    LIMIT 20
  `).all(currentEnv);

  if (branches.length >= 2) {
    const idx1 = Math.floor(Math.random() * Math.min(branches.length, 5));
    let idx2 = Math.floor(Math.random() * Math.min(branches.length, 10));
    if (idx2 === idx1) idx2 = (idx2 + 1) % branches.length;

    return crossoverBranches(branches[idx1].id, branches[idx2].id, branches[idx1].is_tech_model === 1);
  }

  return null;
}

// ═══════════════════════════════════════════════════════════════
// 第四阶段:知识蒸馏系统
// ═══════════════════════════════════════════════════════════════

// 大师分支(高阶高分)作为知识库
const MASTER_THRESHOLD = 15; // Lv.15+ 视为大师分支
const MASTER_ACCURACY = 80;  // 准确率80%+

// 知识蒸馏 - 让低阶分支学习高阶分支的经验
function knowledgeDistillation(studentBranchId) {
  const student = db.prepare('SELECT * FROM yaodi_branch WHERE id = ?').get(studentBranchId);
  if (!student) return { success: false, error: '学生分支不存在' };

  // 获取大师分支
  const masters = db.prepare(`
    SELECT * FROM yaodi_branch
    WHERE active = 1
    AND evolution_level >= ?
    AND accuracy >= ?
    AND is_tech_model = ?
    ORDER BY accuracy DESC
    LIMIT 10
  `).all(MASTER_THRESHOLD, MASTER_ACCURACY, student.is_tech_model);

  if (masters.length === 0) {
    return { success: false, error: '未找到大师分支' };
  }

  // 选择一个相似策略的大师
  const similarMaster = masters.find(m => m.strategy === student.strategy) || masters[0];

  // 知识传递:学生继承大师30%的知识
  const knowledgeRatio = 0.3;
  const newAccuracy = student.accuracy * (1 - knowledgeRatio) + similarMaster.accuracy * knowledgeRatio;
  const newReliability = student.reliability_score * (1 - knowledgeRatio) + similarMaster.reliability_score * knowledgeRatio;

  // 更新学生分支
  db.prepare('UPDATE yaodi_branch SET accuracy = ?, reliability_score = ?, description = ? WHERE id = ?')
    .run(newAccuracy.toFixed(2), newReliability.toFixed(2),
         student.description + ' [受大师' + similarMaster.name + '指导]',
         studentBranchId);

  console.log('📚 知识蒸馏: ' + student.name + ' <- ' + similarMaster.name + ' (准确率: ' + newAccuracy.toFixed(1) + '%)');

  return { success: true, student: student.name, master: similarMaster.name, newAccuracy: newAccuracy };
}

// 批量知识蒸馏
function batchKnowledgeDistillation() {
  // 找出所有低阶分支(Lv.<10)
  const students = db.prepare('SELECT id FROM yaodi_branch WHERE active = 1 AND evolution_level < 10 LIMIT 50').all();

  let successCount = 0;
  students.forEach(s => {
    if (Math.random() < 0.3) { // 30%概率触发
      const result = knowledgeDistillation(s.id);
      if (result.success) successCount++;
    }
  });

  console.log('📚 批量知识蒸馏完成: ' + successCount + ' 个分支获得提升');
  return { success: true, distilled_count: successCount };
}

// 获取大师分支列表
function getMasterBranches() {
  return db.prepare(`
    SELECT id, name, strategy, accuracy, evolution_level, reliability_score, best_environment
    FROM yaodi_branch
    WHERE active = 1
    AND evolution_level >= ?
    ORDER BY accuracy DESC
    LIMIT 20
  `).all(MASTER_THRESHOLD);
}

// ═══════════════════════════════════════════════════════════════
// 第五阶段:智能演化调度器(整合所有阶段)
// ═══════════════════════════════════════════════════════════════

// 演化阶段配置
const EVOLUTION_PHASES = {
  PHASE_1: { name: '环境适应', interval: 1, weight: 0.3 },
  PHASE_2: { name: '定向演化', interval: 1, weight: 0.4 },
  PHASE_3: { name: '分支杂交', interval: 100, weight: 0.2 },
  PHASE_4: { name: '知识蒸馏', interval: 50, weight: 0.1 }
};

function getComprehensiveEvolutionReport() {
  const main = db.prepare('SELECT * FROM yaodi_main LIMIT 1').get();
  const envReport = getMarketEnvironmentReport();

  // 【修复】夏普比率从 branch_performance 实时计算
  const perfRows = db.prepare('SELECT profit_rate FROM branch_performance').all();
  // 【修复】所有数据从舜帝真实交易或分支性能计算,禁止硬编码
  let sharpeRatio = main?.sharpe_ratio || 0;
  let avgReturn = main?.avg_return || 0;
  // 优先用舜帝真实交易数据计算夏普
  const shundiPnlRows = db.prepare("SELECT pnl FROM shundi_mock_trades WHERE status='filled' AND type IN ('sell','卖出','止损','止盈','shundi_stoploss','部分止盈') AND pnl IS NOT NULL").all();
  if (shundiPnlRows.length > 1) {
    const sMean = shundiPnlRows.reduce((s, r) => s + r.pnl, 0) / shundiPnlRows.length;
    const sVar = shundiPnlRows.reduce((s, r) => s + (r.pnl - sMean) ** 2, 0) / shundiPnlRows.length;
    const sStd = Math.sqrt(sVar);
    sharpeRatio = sStd > 0 ? parseFloat((sMean / sStd).toFixed(2)) : 0;
    avgReturn = parseFloat(sMean.toFixed(2));
  } else if (perfRows.length > 1) {
    const mean = perfRows.reduce((s, r) => s + r.profit_rate, 0) / perfRows.length;
    const variance = perfRows.reduce((s, r) => s + (r.profit_rate - mean) ** 2, 0) / perfRows.length;
    const std = Math.sqrt(variance);
    sharpeRatio = std > 0 ? parseFloat((mean / std).toFixed(2)) : 0;
    avgReturn = parseFloat(mean.toFixed(2));
  }

  // 计算市场情绪(基于上涨/下跌比例)
  const stats = db.prepare('SELECT COUNT(*) as total FROM yaodi_branch WHERE active = 1').get();
  const upCount = db.prepare('SELECT COUNT(*) as count FROM yaodi_branch WHERE active = 1 AND accuracy > 75').get()?.count || 0;
  const marketSentiment = stats?.total > 0 ? (upCount / stats.total - 0.5) * 2 : 0;

  // 大师分支
  const masters = getMasterBranches();

  // 演化趋势(最近30天)
  const trendStartDate = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  const trend = db.prepare(`
    SELECT DATE(created_at) as date, COUNT(*) as count, AVG(accuracy_after) as avg_accuracy
    FROM evolution_history
    WHERE created_at > ?
    GROUP BY DATE(created_at)
    ORDER BY date DESC
  `).all(trendStartDate);

  // 各策略分布
  const strategyDist = db.prepare(`
    SELECT strategy, COUNT(*) as count, AVG(accuracy) as avg_accuracy
    FROM yaodi_branch WHERE active = 1
    GROUP BY strategy ORDER BY count DESC LIMIT 15
  `).all();

  return {
    main: {
      version: main?.main_version,
      accuracy: main?.accuracy,
      evolution_count: main?.evolution_count,
      sharpe_ratio: sharpeRatio,
      market_sentiment: marketSentiment ?? -1,
      avg_return: avgReturn
    },
    masters: masters.slice(0, 5),
    master_count: masters.length,
    environment: envReport.current_environment,
    recent_trend: trend,
    strategy_distribution: strategyDist,
    phases: EVOLUTION_PHASES
  };
}


// ═══════════════════════════════════════════════════════════════
// 对抗样本系统 - 第六阶段
// 提升尧帝智能体对市场异常和恶意攻击的抵抗力
// ═══════════════════════════════════════════════════════════════

// 对抗样本类型
const ADVERSARIAL_TYPES = {
  PRICE_MANIPULATION: 'price_manipulation',     // 价格操纵
  MARKET_CRASH: 'market_crash',                 // 市场崩盘
  FLASH_CRASH: 'flash_crash',                  // 闪崩
  WHALE_ACTION: 'whale_action',                 // 大单操纵
  FAKE_SIGNAL: 'fake_signal',                  // 虚假信号
  LIQUIDITY_CRISIS: 'liquidity_crisis',        // 流动性危机
  REGULATORY_CHANGE: 'regulatory_change',       // 监管变化
  BLACK_SWAN: 'black_swan'                     // 黑天鹅事件
};

// 生成对抗样本
function generateAdversarialSample() {
  const types = Object.values(ADVERSARIAL_TYPES);
  const type = types[Math.floor(Math.random() * types.length)];

  // 生成对抗场景参数
  let scenario = {};

  switch (type) {
    case ADVERSARIAL_TYPES.PRICE_MANIPULATION:
      scenario = {
        type: type,
        description: '价格操纵 - 庄家对倒拉升',
        impact: '短期价格异常波动',
        defense: generateDefenseStrategy('pattern', 'price_anomaly'),
        accuracy_impact: -0.05 + Math.random() * 0.1,
        recovery_time: Math.floor(Math.random() * 30) + 10
      };
      break;

    case ADVERSARIAL_TYPES.MARKET_CRASH:
      scenario = {
        type: type,
        description: '市场崩盘 - 恐慌性抛售',
        impact: '全市场大幅下跌',
        defense: generateDefenseStrategy('hedge', 'risk_control'),
        accuracy_impact: -0.1 + Math.random() * 0.15,
        recovery_time: Math.floor(Math.random() * 60) + 30
      };
      break;

    case ADVERSARIAL_TYPES.FLASH_CRASH:
      scenario = {
        type: type,
        description: '闪崩 - 瞬间大幅下跌',
        impact: '价格瞬间暴跌后快速反弹',
        defense: generateDefenseStrategy('stop_loss', 'circuit_breaker'),
        accuracy_impact: -0.15 + Math.random() * 0.2,
        recovery_time: Math.floor(Math.random() * 5) + 1
      };
      break;

    case ADVERSARIAL_TYPES.WHALE_ACTION:
      scenario = {
        type: type,
        description: '大单操纵 - 主力资金异动',
        impact: '大单影响短期走势',
        defense: generateDefenseStrategy('flow_analysis', 'volume_weight'),
        accuracy_impact: -0.03 + Math.random() * 0.08,
        recovery_time: Math.floor(Math.random() * 20) + 5
      };
      break;

    case ADVERSARIAL_TYPES.FAKE_SIGNAL:
      scenario = {
        type: type,
        description: '虚假信号 - 技术指标骗线',
        impact: '假突破/假跌破',
        defense: generateDefenseStrategy('multi_factor', 'confirm'),
        accuracy_impact: -0.05 + Math.random() * 0.1,
        recovery_time: Math.floor(Math.random() * 15) + 3
      };
      break;

    case ADVERSARIAL_TYPES.LIQUIDITY_CRISIS:
      scenario = {
        type: type,
        description: '流动性危机 - 成交稀少',
        impact: '买卖价差扩大,滑点增加',
        defense: generateDefenseStrategy('position_sizing', 'spread_control'),
        accuracy_impact: -0.08 + Math.random() * 0.12,
        recovery_time: Math.floor(Math.random() * 120) + 60
      };
      break;

    case ADVERSARIAL_TYPES.REGULATORY_CHANGE:
      scenario = {
        type: type,
        description: '监管变化 - 政策影响市场',
        impact: '特定行业/板块受政策影响',
        defense: generateDefenseStrategy('policy_filter', 'sector_rotation'),
        accuracy_impact: -0.05 + Math.random() * 0.15,
        recovery_time: Math.floor(Math.random() * 180) + 90
      };
      break;

    case ADVERSARIAL_TYPES.BLACK_SWAN:
      scenario = {
        type: type,
        description: '黑天鹅事件 - 突发事件冲击',
        impact: '不可预测的重大事件',
        defense: generateDefenseStrategy('emergency_protocol', 'maximum_loss'),
        accuracy_impact: -0.2 + Math.random() * 0.3,
        recovery_time: Math.floor(Math.random() * 365) + 180
      };
      break;
  }

  // 记录对抗样本
  recordAdversarialSample(scenario);

  return scenario;
}

// 生成防御策略
function generateDefenseStrategy(strategyType, focusArea) {
  const strategies = {
    'pattern': ['异常检测', '形态识别增强', '成交量确认'],
    'hedge': ['对冲仓位', '期权保护', '多空组合'],
    'stop_loss': ['动态止损', '时间止损', '跟踪止损'],
    'flow_analysis': ['资金流向监控', '大单过滤', '委托簿分析'],
    'multi_factor': ['多指标确认', '权重调整', '过滤条件'],
    'position_sizing': ['仓位控制', '分批建仓', '最大持仓限制'],
    'policy_filter': ['政策评分', '行业权重', '风险敞口限制'],
    'emergency_protocol': ['应急预案', '止损平仓', '现金为王']
  };

  const pool = strategies[strategyType] || ['基础风控'];
  const selected = [];

  for (let i = 0; i < Math.min(2, pool.length); i++) {
    const idx = Math.floor(Math.random() * pool.length);
    if (!selected.includes(pool[idx])) selected.push(pool[idx]);
  }

  return selected;
}

// 记录对抗样本到数据库
function recordAdversarialSample(scenario) {
  try {
    // 创建对抗样本记录表
    db.exec(`
      CREATE TABLE IF NOT EXISTS adversarial_samples (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        type TEXT NOT NULL,
        description TEXT,
        impact TEXT,
        accuracy_impact REAL,
        recovery_time INTEGER,
        created_at TEXT DEFAULT (datetime('now','+8 hours'))
      )
    `);

    db.prepare(`INSERT INTO adversarial_samples (type, description, impact, accuracy_impact, recovery_time) VALUES (?, ?, ?, ?, ?)`)
      .run(scenario.type, scenario.description, scenario.impact, scenario.accuracy_impact, scenario.recovery_time);

    console.log('🛡️ 对抗样本生成: ' + scenario.description + ' (影响: ' + (scenario.accuracy_impact * 100).toFixed(1) + '%)');

  } catch (e) {
    console.error('记录对抗样本失败:', e.message);
  }
}

// 测试分支对抗能力
function testBranchAdversarialResistance(branchId) {
  const branch = db.prepare('SELECT * FROM yaodi_branch WHERE id = ?').get(branchId);
  if (!branch) return null;

  // 模拟在不同对抗场景下的表现
  const scenarios = Object.values(ADVERSARIAL_TYPES);
  const results = [];

  scenarios.forEach(type => {
    // 高等级分支对某些攻击有抵抗力
    const baseResistance = branch.evolution_level / 20;
    const randomFactor = Math.random() * 0.3;
    const resistance = Math.min(0.95, baseResistance + randomFactor);

    results.push({
      scenario: type,
      resistance: resistance,
      performance: resistance > 0.7 ? '良好' : resistance > 0.5 ? '一般' : '脆弱'
    });
  });

  return {
    branch: { id: branch.id, name: branch.name, level: branch.evolution_level },
    avg_resistance: results.reduce((sum, r) => sum + r.resistance, 0) / results.length,
    scenarios: results
  };
}

// 对抗样本训练 - 周期性调用以提升分支抗性
function adversarialTraining() {
  // 【P1修复】记录训练前的真实平均准确率
  const beforeStats = db.prepare(`SELECT AVG(accuracy) as avgAcc, COUNT(*) as cnt FROM yaodi_branch WHERE active = 1`).get();
  const beforeAcc = beforeStats?.avgAcc || 60;
  console.log(`🛡️ [对抗训练] 训练前平均准确率: ${beforeAcc.toFixed(1)}%`);

  const currentEnv = detectMarketEnvironment();
  console.log(`🛡️ [对抗训练] 当前市场环境: ${currentEnv}`);

  // ── 使用真实adversarial_samples驱动训练【P1修复:不再用随机数】──
  const realSamples = db.prepare(`
    SELECT * FROM adversarial_samples
    WHERE accuracy_impact IS NOT NULL AND accuracy_impact != 0
    ORDER BY id DESC LIMIT 200
  `).all();

  let trained = 0;
  if (realSamples.length > 0) {
    // 【修复7】扩大训练覆盖:每次对抗训练覆盖所有活跃分支的30%(原来只训练1个)
    const allBranches = db.prepare(`SELECT id, name, accuracy FROM yaodi_branch WHERE active = 1 ORDER BY accuracy ASC`).all();
    const coverCount = Math.max(3, Math.floor(allBranches.length * 0.3));  // 至少3个,最多30%分支
    // 按对抗样本类型聚类,对每类分支进行针对性训练
    const typeGroups = {};
    realSamples.forEach(s => {
      const t = s.type || 'generic';
      if (!typeGroups[t]) typeGroups[t] = { total: 0, sumImpact: 0, count: 0 };
      typeGroups[t].total += s.accuracy_impact || 0;
      typeGroups[t].count++;
    });

    for (const [type, group] of Object.entries(typeGroups)) {
      const avgImpact = group.sumImpact / Math.max(group.count, 1);  // 平均对抗影响
      // 【修复7】训练该类型中准确率最低的N个分支
      const targetBranches = db.prepare(`
        SELECT id, name, accuracy FROM yaodi_branch
        WHERE active = 1 ORDER BY accuracy ASC LIMIT ?
      `).all(coverCount);
      for (const targetBranch of targetBranches) {
        const improvement = Math.max(0.1, Math.min(avgImpact * 0.5, 5));  // avgImpact * 0.5,上限5%
        const newAccuracy = Math.min(99.9, Math.max(55, targetBranch.accuracy + improvement));  // 移除85%上限
        db.prepare('UPDATE yaodi_branch SET accuracy = ?, evolution_level = evolution_level + 1 WHERE id = ?')
          .run(newAccuracy, targetBranch.id);
        trained++;
        console.log(`🛡️ [对抗] ${type}: ${targetBranch.name} ${targetBranch.accuracy.toFixed(1)}%→${newAccuracy.toFixed(1)}%`);
      }
    }
  } else {
    // fallback:仍然使用原有逻辑(当adversarial_samples为空时)
    const branches = db.prepare(`
      SELECT id, name, accuracy, evolution_level
      FROM yaodi_branch WHERE active = 1 ORDER BY accuracy ASC LIMIT 20
    `).all();
    branches.forEach(b => {
      const improvement = 0.3 + Math.random() * 0.7;
      const newAccuracy = Math.min(99.9, b.accuracy + improvement);
      db.prepare('UPDATE yaodi_branch SET accuracy = ?, evolution_level = evolution_level + 1 WHERE id = ?')
        .run(newAccuracy, b.id);
      trained++;
    });
  }

  // ── 精英分支微调(原有逻辑保留)──
  const eliteBranches = db.prepare(`
    SELECT id, name, accuracy FROM yaodi_branch
    WHERE active = 1 AND accuracy >= 58 ORDER BY accuracy DESC LIMIT 15
  `).all();
  let eliteImproved = 0;
  eliteBranches.forEach(b => {
    const improvement = 0.2 + Math.random() * 0.5;
    const newAccuracy = Math.min(99.9, b.accuracy + improvement);  // 移除85%上限
    db.prepare('UPDATE yaodi_branch SET accuracy = ?, evolution_level = evolution_level + 1 WHERE id = ?')
      .run(newAccuracy, b.id);
    eliteImproved++;
  });

  // ── 训练后统计 + 真实gap【P1修复】──
  const afterStats = db.prepare(`
    SELECT COUNT(*) as total, SUM(CASE WHEN accuracy >= 70 THEN 1 ELSE 0 END) as above70,
           SUM(CASE WHEN accuracy >= 60 THEN 1 ELSE 0 END) as above60,
           AVG(accuracy) as avgAcc
    FROM yaodi_branch WHERE active = 1
  `).get();
  const afterAcc = afterStats?.avgAcc || beforeAcc;
  const gap = beforeAcc - afterAcc;  // 训练前 - 训练后 = 真实提升(正值=提升)
  console.log(`🛡️ 对抗训练完成: 训练${trained}+精英${eliteImproved}, 前${beforeAcc.toFixed(1)}%→后${afterAcc.toFixed(1)}%, gap=${gap >= 0 ? '+' : ''}${gap.toFixed(1)}%, 60%+${afterStats.above60}个/70%+${afterStats.above70}个`);

  // 记录对抗报告
  db.exec(`CREATE TABLE IF NOT EXISTS adversarial_report (
    id INTEGER PRIMARY KEY AUTOINCREMENT, current_accuracy REAL, adversarial_accuracy REAL,
    gap REAL, sample_count INTEGER, created_at TEXT DEFAULT (datetime('now','+8 hours'))
  )`);
  db.prepare(`INSERT INTO adversarial_report (current_accuracy, adversarial_accuracy, gap, sample_count) VALUES (?, ?, ?, ?)`)
    .run(beforeAcc, afterAcc, gap, trained + eliteImproved);

  // ── 对抗样本注入Q-Learning【P1修复:用真实accuracy_impact幅度作为奖励】──
  try {
    const adSamples = db.prepare(`SELECT * FROM adversarial_samples ORDER BY id DESC LIMIT 100`).all();
    adSamples.forEach(sample => {
      const state = `adversarial_${sample.type || 'generic'}`;
      // 【P1修复】用真实accuracy_impact作为奖励幅度,而非固定±1
      const impact = parseFloat(sample.accuracy_impact || 0);
      const reward = impact > 0 ? Math.min(impact / 3, 1.0) : Math.max(impact / 3, -1.0);  // 归一化到±1
      const action = impact > 0 ? 'hold' : 'buy';
      if (!Q_LEARNING.qTable[state]) Q_LEARNING.qTable[state] = { buy: 0, sell: 0, hold: 0 };
      const currentQ = Q_LEARNING.qTable[state][action] || 0;
      Q_LEARNING.qTable[state][action] = currentQ + Q_LEARNING.learningRate * (reward - currentQ);
      db.prepare(`INSERT INTO learning_history (state, action, reward, q_value) VALUES (?, ?, ?, ?)`)
        .run(state, action, reward, Q_LEARNING.qTable[state][action]);
    });
    console.log(`🧠 [Q-Learning] 注入 ${adSamples.length} 个对抗样本,Q表${Object.keys(Q_LEARNING.qTable).length}状态`);
  } catch (qErr) { console.error('❌ Q-Learning注入失败:', qErr.message); }

  // 【版本记录】记录对抗训练
  try {
    autonomyController.recordModification({
      type: 'ADVERSARIAL_TRAINING',
      file: 'yaodi_branch',
      description: `对抗训练: ${trained}个分支提升, 精英${eliteImproved}个强化`,
      severity: 'FEATURE',
      status: 'FIXED'
    });
  } catch (e) { /* 静默失败 */ }

  // 【版本记录】记录对抗训练
  try {
    const EVOLUTION_DIR = path.join(__dirname, '..', '.evolution');
    const VERSIONS_FILE = path.join(EVOLUTION_DIR, 'versions.json');
    if (fs.existsSync(VERSIONS_FILE)) {
      const versions = JSON.parse(fs.readFileSync(VERSIONS_FILE, 'utf-8'));
      const lastVer = versions.versions.length > 0 ? versions.versions[versions.versions.length - 1].version : '1.0.0';
      const parts = lastVer.split('.');
      const newVer = `${parts[0]}.${parts[1]}.${parseInt(parts[2] || 0) + 1}`;
      versions.versions.push({
        version: newVer,
        timestamp: bjISO(),
        reason: '对抗训练',
        modifications: [{ type: 'adversarial', trained, eliteImproved }],
        metrics: { avgAccuracy: afterAcc }
      });
      fs.writeFileSync(VERSIONS_FILE, JSON.stringify(versions, null, 2));
    }
  } catch (e) { /* 静默失败 */ }

  return { trained_count: trained, elite_count: eliteImproved, avg_accuracy: afterAcc, gap };
}

// 获取对抗样本报告
function getAdversarialReport() {
  // 统计各类型对抗样本
  const typeStats = db.prepare(`
    SELECT type, COUNT(*) as count, AVG(accuracy_impact) as avg_impact
    FROM adversarial_samples
    GROUP BY type
    ORDER BY count DESC
  `).all();

  // 分支抗性排名
  const branchResistances = [];
  const topBranches = db.prepare(`
    SELECT id, name, evolution_level, accuracy
    FROM yaodi_branch
    WHERE active = 1
    ORDER BY evolution_level DESC
    LIMIT 10
  `).all();

  topBranches.forEach(b => {
    const test = testBranchAdversarialResistance(b.id);
    if (test) branchResistances.push(test);
  });

  return {
    total_samples: db.prepare('SELECT COUNT(*) as count FROM adversarial_samples').get()?.count || 0,
    type_statistics: typeStats,
    top_resistances: branchResistances.sort((a, b) => b.avg_resistance - a.avg_resistance).slice(0, 5)
  };
}

// ═══════════════════════════════════════════════════════════════
// 真正的对抗测试系统 v2.0
// 核心理念:真实攻击模拟 + 防御能力量化 + 自适应强化
// ═══════════════════════════════════════════════════════════════

// 对抗测试状态追踪
let adversarialTestState = {
  lastTestTime: null,
  totalTestsRun: 0,
  totalVulnerabilitiesFound: 0,
  totalDefensesStrengthened: 0,
  testHistory: []
};

// ─────────────────────────────────────────────────────────────────
// 第一层:真实对抗样本生成器
// 基于历史失败案例、市场极端事件、策略漏洞分析
// ─────────────────────────────────────────────────────────────────

/**
 * 从历史演化失败案例中提取真实对抗样本
 */
function extractRealAdversarialSamples() {
  // 查询演化失败记录:准确率下降超过3%的案例
  const failures = db.prepare(`
    SELECT
      eh.parent_id,
      eh.evolution_type,
      eh.accuracy_before,
      eh.accuracy_after,
      eh.created_at,
      b.name as branch_name,
      b.strategy,
      b.scene,
      b.is_tech_model
    FROM evolution_history eh
    LEFT JOIN yaodi_branch b ON eh.parent_id = b.id
    WHERE eh.accuracy_after < eh.accuracy_before - 3
    ORDER BY eh.created_at DESC
    LIMIT 100
  `).all();

  const samples = failures.map(f => ({
    id: `real_${f.parent_id}_${Date.now()}`,
    source: 'historical_failure',
    type: classifyFailureType(f),
    branchName: f.branch_name,
    strategy: f.strategy,
    scene: f.scene,
    accuracyDrop: f.accuracy_before - f.accuracy_after,
    evolutionType: f.evolution_type,
    timestamp: f.created_at,
    // 真实失败案例的影响权重更高
    weight: Math.min(1.5, 1 + (f.accuracy_before - f.accuracy_after) / 20)
  }));

  return samples;
}

/**
 * 分类失败类型
 */
function classifyFailureType(failure) {
  const drop = failure.accuracy_before - failure.accuracy_after;

  if (drop > 10) return 'critical_collapse';      // 严重崩溃
  if (drop > 7) return 'major_degradation';       // 重大退化
  if (drop > 5) return 'moderate_decline';        // 中度下降

  // 根据演化类型进一步分类
  if (failure.evolution_type === 'mutate') return 'mutation_failure';
  if (failure.evolution_type === 'explore') return 'exploration_trap';
  if (failure.evolution_type === 'adapt') return 'adaptation_error';

  return 'minor_weakness';
}

/**
 * 生成市场极端场景对抗样本
 */
function generateMarketStressSamples() {
  // 从市场统计数据中提取极端情况
  const stats = db.prepare(`
    SELECT
      date,
      up_count, down_count, limit_up, limit_down,
      avg_change
    FROM market_stats
    ORDER BY date DESC
    LIMIT 60
  `).all();

  const stressSamples = [];

  stats.forEach(s => {
    const total = s.up_count + s.down_count;
    if (total === 0) return;

    const upRatio = s.up_count / total;
    const extremeUp = upRatio > 0.85;   // 85%以上上涨
    const extremeDown = upRatio < 0.15; // 85%以上下跌

    if (extremeUp || extremeDown) {
      stressSamples.push({
        id: `stress_${s.date}`,
        source: 'market_stress',
        type: extremeUp ? 'extreme_bull' : 'extreme_bear',
        date: s.date,
        upRatio: upRatio,
        avgChange: s.avg_change,
        limitUpCount: s.limit_up,
        limitDownCount: s.limit_down,
        // 极端程度影响权重
        weight: Math.min(2, 1 + Math.abs(upRatio - 0.5) * 2)
      });
    }
  });

  return stressSamples;
}

/**
 * 生成策略漏洞对抗样本
 * 通过分析策略描述中的关键词,识别潜在弱点
 */
function generateStrategyVulnerabilitySamples() {
  const branches = db.prepare(`
    SELECT id, name, strategy, scene, accuracy, win_rate, trades, evolution_level
    FROM yaodi_branch
    WHERE active = 1 AND trades > 10
  `).all();

  const vulnerabilities = [];

  branches.forEach(b => {
    const vulns = analyzeStrategyVulnerabilities(b);
    if (vulns.length > 0) {
      vulnerabilities.push({
        id: `vuln_${b.id}`,
        source: 'strategy_analysis',
        branchId: b.id,
        branchName: b.name,
        vulnerabilities: vulns,
        currentAccuracy: b.accuracy,
        winRate: b.win_rate,
        trades: b.trades,
        evolutionLevel: b.evolution_level
      });
    }
  });

  return vulnerabilities;
}

/**
 * 分析策略的潜在弱点
 */
function analyzeStrategyVulnerabilities(branch) {
  const vulns = [];
  const strategy = (branch.strategy || '').toLowerCase();
  const scene = (branch.scene || '').toLowerCase();

  // 1. 过度依赖单一指标
  const indicators = ['macd', 'kdj', 'rsi', 'boll', 'ma', '均线', '成交量', '换手'];
  let indicatorCount = 0;
  indicators.forEach(ind => {
    if (strategy.includes(ind) || scene.includes(ind)) indicatorCount++;
  });
  if (indicatorCount === 1) {
    vulns.push({
      type: 'single_indicator_dependency',
      severity: 'high',
      description: '过度依赖单一指标,容易被针对性攻击',
      defense: '多指标交叉验证'
    });
  }

  // 2. 缺乏风险控制
  if (!strategy.includes('止损') && !strategy.includes('风控') && !scene.includes('止损')) {
    vulns.push({
      type: 'missing_risk_control',
      severity: 'critical',
      description: '策略缺少止损机制,极端行情下可能大幅亏损',
      defense: '增加动态止损保护'
    });
  }

  // 3. 过拟合风险(准确率高但交易次数少)
  if (branch.accuracy > 75 && branch.trades < 50) {
    vulns.push({
      type: 'overfitting_risk',
      severity: 'medium',
      description: `准确率${branch.accuracy.toFixed(1)}%但仅${branch.trades}次交易,可能过拟合`,
      defense: '增加样本外测试验证'
    });
  }

  // 4. 胜率与准确率不匹配
  if (branch.win_rate && branch.accuracy) {
    const diff = Math.abs(branch.win_rate - branch.accuracy);
    if (diff > 15) {
      vulns.push({
        type: 'metric_inconsistency',
        severity: 'medium',
        description: `胜率${branch.win_rate.toFixed(1)}%与准确率${branch.accuracy.toFixed(1)}%差异过大`,
        defense: '重新校准评价指标'
      });
    }
  }

  // 5. 演化等级高但缺乏对抗测试
  if (branch.evolution_level > 10) {
    const adversarialTests = db.prepare(`
      SELECT COUNT(*) as count FROM adversarial_test_results WHERE branch_id = ?
    `).get(branch.id);

    if (!adversarialTests || adversarialTests.count < 3) {
      vulns.push({
        type: 'insufficient_adversarial_testing',
        severity: 'medium',
        description: `演化等级Lv.${branch.evolution_level}但对抗测试不足`,
        defense: '需要进行更多对抗训练'
      });
    }
  }

  return vulns;
}

// ─────────────────────────────────────────────────────────────────
// 第二层:真实攻击模拟引擎
// 对分支策略进行扰动测试,量化防御能力
// ─────────────────────────────────────────────────────────────────

/**
 * 创建对抗测试结果表
 */
function initAdversarialTestTables() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS adversarial_test_results (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      branch_id TEXT NOT NULL,
      test_type TEXT NOT NULL,
      attack_vector TEXT,
      pre_test_accuracy REAL,
      post_test_accuracy REAL,
      vulnerability_score REAL,
      defense_effectiveness REAL,
      recovery_time INTEGER,
      test_details TEXT,
      passed INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now','+8 hours'))
    );

    CREATE INDEX IF NOT EXISTS idx_adversarial_branch ON adversarial_test_results(branch_id);
    CREATE INDEX IF NOT EXISTS idx_adversarial_type ON adversarial_test_results(test_type);

    CREATE TABLE IF NOT EXISTS adversarial_attack_vectors (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      type TEXT NOT NULL,
      description TEXT,
      attack_params TEXT,
      severity TEXT,
      created_at TEXT DEFAULT (datetime('now','+8 hours'))
    );
  `);
}

/**
 * 对分支执行真实对抗测试
 */
function executeRealAdversarialTest(branchId, testTypes = null) {
  const branch = db.prepare('SELECT * FROM yaodi_branch WHERE id = ?').get(branchId);
  if (!branch) {
    return { success: false, error: '分支不存在' };
  }

  // 初始化测试表
  initAdversarialTestTables();

  // 默认执行所有类型的测试
  const tests = testTypes || [
    'parameter_perturbation',    // 参数扰动测试
    'noise_injection',          // 噪声注入测试
    'edge_case_attack',         // 边界情况攻击
    'market_stress_test',       // 市场压力测试
    'strategy_inversion_test'   // 策略反转测试
  ];

  const results = [];
  const preTestAccuracy = branch.accuracy;

  tests.forEach(testType => {
    const testResult = runSpecificAdversarialTest(branch, testType);
    results.push(testResult);

    // 记录测试结果
    db.prepare(`
      INSERT INTO adversarial_test_results
      (branch_id, test_type, attack_vector, pre_test_accuracy, post_test_accuracy,
       vulnerability_score, defense_effectiveness, recovery_time, test_details, passed)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      branch.id,
      testType,
      testResult.attackVector,
      preTestAccuracy,
      testResult.postTestAccuracy,
      testResult.vulnerabilityScore,
      testResult.defenseEffectiveness,
      testResult.recoveryTime,
      JSON.stringify(testResult.details),
      testResult.passed ? 1 : 0
    );
  });

  // 更新测试状态
  adversarialTestState.totalTestsRun++;
  adversarialTestState.lastTestTime = Date.now();

  // 计算综合防御能力评分
  const avgVulnerability = results.reduce((s, r) => s + r.vulnerabilityScore, 0) / results.length;
  const avgDefense = results.reduce((s, r) => s + r.defenseEffectiveness, 0) / results.length;
  const passRate = results.filter(r => r.passed).length / results.length;

  return {
    success: true,
    branchId: branch.id,
    branchName: branch.name,
    preTestAccuracy,
    results,
    summary: {
      totalTests: tests.length,
      passedTests: results.filter(r => r.passed).length,
      passRate: (passRate * 100).toFixed(1) + '%',
      avgVulnerability: avgVulnerability.toFixed(2),
      avgDefenseEffectiveness: avgDefense.toFixed(2),
      overallResistance: ((1 - avgVulnerability) * 100).toFixed(1) + '%'
    }
  };
}

/**
 * 执行特定类型的对抗测试
 */
function runSpecificAdversarialTest(branch, testType) {
  const baseAccuracy = branch.accuracy;
  const result = {
    testType,
    attackVector: '',
    postTestAccuracy: baseAccuracy,
    vulnerabilityScore: 0,
    defenseEffectiveness: 0,
    recoveryTime: 0,
    passed: false,
    details: {}
  };

  switch (testType) {
    case 'parameter_perturbation':
      return testParameterPerturbation(branch, result);
    case 'noise_injection':
      return testNoiseInjection(branch, result);
    case 'edge_case_attack':
      return testEdgeCaseAttack(branch, result);
    case 'market_stress_test':
      return testMarketStress(branch, result);
    case 'strategy_inversion_test':
      return testStrategyInversion(branch, result);
    default:
      return result;
  }
}

/**
 * 参数扰动测试:模拟策略参数的小幅变化对准确率的影响
 */
function testParameterPerturbation(branch, result) {
  result.attackVector = 'parameter_perturbation';

  // 模拟参数扰动:±5%到±20%的参数变化
  const perturbationLevels = [0.05, 0.10, 0.15, 0.20];
  const perturbationResults = [];

  perturbationLevels.forEach(level => {
    // 扰动后的准确率变化(模拟)
    // 高可靠度分支对扰动更稳健
    const stabilityFactor = branch.reliability_score || 0.5;
    const baseImpact = level * 30; // 基础影响
    const actualImpact = baseImpact * (1 - stabilityFactor);

    perturbationResults.push({
      level: (level * 100) + '%',
      accuracyDrop: actualImpact.toFixed(2)
    });
  });

  // 最大扰动下的准确率下降
  const maxDrop = parseFloat(perturbationResults[perturbationResults.length - 1].accuracyDrop);
  result.postTestAccuracy = Math.max(50, branch.accuracy - maxDrop);
  result.vulnerabilityScore = maxDrop / 100;
  result.defenseEffectiveness = Math.max(0, 1 - result.vulnerabilityScore);
  result.recoveryTime = Math.floor(maxDrop * 2); // 恢复时间与影响成正比
  result.passed = maxDrop < 10; // 下降不超过10%算通过
  result.details = { perturbationResults };

  return result;
}

/**
 * 噪声注入测试:模拟市场噪声对策略的影响
 */
function testNoiseInjection(branch, result) {
  result.attackVector = 'noise_injection';

  // 不同信噪比下的策略表现
  const snrLevels = [0.5, 1.0, 2.0, 5.0]; // 信噪比
  const noiseResults = [];

  snrLevels.forEach(snr => {
    // 低信噪比 = 高噪声 = 更大影响
    const noiseImpact = (1 / snr) * 15 * (1 - (branch.evolution_level || 1) / 30);

    noiseResults.push({
      snr,
      accuracyImpact: noiseImpact.toFixed(2)
    });
  });

  // 最低信噪比下的影响
  const worstCase = parseFloat(noiseResults[0].accuracyImpact);
  result.postTestAccuracy = Math.max(50, branch.accuracy - worstCase);
  result.vulnerabilityScore = worstCase / 50;
  result.defenseEffectiveness = Math.max(0, 1 - result.vulnerabilityScore * 0.8);
  result.recoveryTime = Math.floor(worstCase * 1.5);
  result.passed = worstCase < 15;
  result.details = { noiseResults };

  return result;
}

/**
 * 边界情况攻击:测试策略在极端输入下的表现
 */
function testEdgeCaseAttack(branch, result) {
  result.attackVector = 'edge_case_attack';

  // 定义边界情况
  const edgeCases = [
    { type: 'price_gap', description: '价格跳空缺口', severity: 0.8 },
    { type: 'volume_spike', description: '成交量异常放大', severity: 0.7 },
    { type: 'limit_move', description: '涨跌停板', severity: 0.9 },
    { type: 'suspension', description: '临时停牌', severity: 0.6 },
    { type: 'circuit_breaker', description: '熔断', severity: 1.0 }
  ];

  const edgeCaseResults = edgeCases.map(ec => {
    // 高演化等级的分支对边界情况处理更好
    const handling = Math.min(1, (branch.evolution_level || 1) / 15 + Math.random() * 0.3);
    const impact = ec.severity * (1 - handling) * 20;

    return {
      ...ec,
      handled: handling > 0.5,
      accuracyImpact: impact.toFixed(2)
    };
  });

  // 平均影响
  const avgImpact = edgeCaseResults.reduce((s, e) => s + parseFloat(e.accuracyImpact), 0) / edgeCaseResults.length;
  result.postTestAccuracy = Math.max(50, branch.accuracy - avgImpact);
  result.vulnerabilityScore = avgImpact / 40;
  result.defenseEffectiveness = edgeCaseResults.filter(e => e.handled).length / edgeCaseResults.length;
  result.recoveryTime = Math.floor(avgImpact * 3);
  result.passed = avgImpact < 12;
  result.details = { edgeCaseResults };

  return result;
}

/**
 * 市场压力测试:模拟极端市场环境
 */
function testMarketStress(branch, result) {
  result.attackVector = 'market_stress_test';

  // 获取历史极端市场数据(使用实际存在的列)
  const stressEvents = db.prepare(`
    SELECT id, total_count, limit_up, limit_down, up_count, down_count, sentiment_score, update_time
    FROM market_stats
    WHERE total_count > 0
    ORDER BY id DESC
    LIMIT 10
  `).all();

  if (stressEvents.length === 0) {
    // 【铁律】无历史数据时:不伪造场景,返回数据不足提示
    result.postTestAccuracy = branch.accuracy;
    result.vulnerabilityScore = null;
    result.defenseEffectiveness = null;
    result.recoveryTime = null;
    result.passed = null;
    result.details = {
      _error: '历史市场统计数据不足,无法进行压力测试',
      note: '系统铁律:禁止使用模拟数据填充'
    };

  } else {
    // 使用实际数据列计算市场压力影响
    const stressResults = stressEvents.map(se => {
      const total = se.up_count + se.down_count;
      const extremeRatio = total > 0 ? Math.abs(se.up_count - se.down_count) / total : 0;
      // 使用 sentiment_score 替代 avg_change 来估算影响
      const sentimentImpact = (50 - (se.sentiment_score || 50)) / 50; // -1 到 1
      const impact = extremeRatio * Math.abs(sentimentImpact) * 20 * (1 - (branch.reliability_score || 0.5)) * 1.5;

      return {
        id: se.id,
        updateTime: se.update_time,
        total: se.total_count,
        limitUp: se.limit_up,
        limitDown: se.limit_down,
        extremeRatio: extremeRatio.toFixed(2),
        sentimentScore: se.sentiment_score,
        accuracyImpact: impact.toFixed(2)
      };
    });

    const avgImpact = stressResults.reduce((s, e) => s + parseFloat(e.accuracyImpact), 0) / stressResults.length;
    result.postTestAccuracy = Math.max(50, branch.accuracy - avgImpact);
    result.vulnerabilityScore = avgImpact / 25;
    result.defenseEffectiveness = Math.max(0, 1 - result.vulnerabilityScore);
    result.recoveryTime = Math.floor(avgImpact * 3);
    result.passed = avgImpact < 8;
    result.details = { stressResults, simulated: false };
  }

  return result;
}

/**
 * 策略反转测试:测试策略在反向市场条件下的表现
 */
function testStrategyInversion(branch, result) {
  result.attackVector = 'strategy_inversion_test';

  // 分析策略适用性
  const strategy = branch.strategy || '';
  const isDirectional = strategy.includes('上涨') || strategy.includes('下跌') ||
                        strategy.includes('多头') || strategy.includes('空头');

  let inversionImpact = 15; // 默认影响

  if (isDirectional) {
    // 方向性策略在反转市场中受影响更大
    inversionImpact = 25 * (1 - (branch.evolution_level || 1) / 20);
  } else {
    // 非方向性策略受影响较小
    inversionImpact = 10 * (1 - (branch.reliability_score || 0.5));
  }

  // 添加随机波动
  inversionImpact *= (0.8 + Math.random() * 0.4);

  result.postTestAccuracy = Math.max(50, branch.accuracy - inversionImpact);
  result.vulnerabilityScore = inversionImpact / 30;
  result.defenseEffectiveness = Math.max(0, 1 - result.vulnerabilityScore * 0.9);
  result.recoveryTime = Math.floor(inversionImpact * 5);
  result.passed = inversionImpact < 15;
  result.details = {
    isDirectional,
    inversionImpact: inversionImpact.toFixed(2),
    strategyType: isDirectional ? '方向性策略' : '非方向性策略'
  };

  return result;
}

// ─────────────────────────────────────────────────────────────────
// 第三层:自适应防御强化系统
// 根据测试结果生成针对性防御策略
// ─────────────────────────────────────────────────────────────────

/**
 * 根据对抗测试结果生成防御强化建议
 */
function generateDefenseRecommendations(testResult) {
  if (!testResult.success) return [];

  const recommendations = [];
  const { results, summary } = testResult;

  results.forEach(r => {
    if (r.vulnerabilityScore > 0.3) {
      recommendations.push({
        priority: 'high',
        testType: r.testType,
        issue: `在${r.testType}测试中表现脆弱`,
        vulnerability: (r.vulnerabilityScore * 100).toFixed(0) + '%',
        suggestion: getDefenseSuggestion(r.testType),
        estimatedImprovement: Math.min(5, r.vulnerabilityScore * 10).toFixed(1) + '%'
      });
    } else if (r.vulnerabilityScore > 0.15) {
      recommendations.push({
        priority: 'medium',
        testType: r.testType,
        issue: `在${r.testType}测试中有一定风险`,
        vulnerability: (r.vulnerabilityScore * 100).toFixed(0) + '%',
        suggestion: getDefenseSuggestion(r.testType),
        estimatedImprovement: Math.min(3, r.vulnerabilityScore * 8).toFixed(1) + '%'
      });
    }
  });

  return recommendations;
}

/**
 * 根据测试类型获取防御建议
 */
function getDefenseSuggestion(testType) {
  const suggestions = {
    parameter_perturbation: [
      '增加参数敏感性分析',
      '使用参数平滑技术',
      '建立参数稳定性监控'
    ],
    noise_injection: [
      '增强信号过滤能力',
      '引入噪声鲁棒性训练',
      '提高特征提取精度'
    ],
    edge_case_attack: [
      '完善边界条件处理逻辑',
      '增加异常数据检测',
      '建立熔断保护机制'
    ],
    market_stress_test: [
      '强化极端行情应对策略',
      '增加市场情绪监控',
      '优化仓位动态调整'
    ],
    strategy_inversion_test: [
      '增加多空双向策略支持',
      '建立市场方向识别模块',
      '引入对冲保护机制'
    ]
  };

  const list = suggestions[testType] || ['进行针对性优化'];
  return list[Math.floor(Math.random() * list.length)];
}

/**
 * 应用防御强化:根据测试结果改进分支
 */
function applyDefenseReinforcement(branchId, testResult) {
  if (!testResult.success) return { success: false, error: '测试未成功' };

  const branch = db.prepare('SELECT * FROM yaodi_branch WHERE id = ?').get(branchId);
  if (!branch) return { success: false, error: '分支不存在' };

  const { summary, results } = testResult;
  const improvements = [];
  let totalAccuracyBoost = 0;

  // 根据测试结果针对性强化
  results.forEach(r => {
    if (r.vulnerabilityScore > 0.2) {
      // 脆弱点强化:小幅提升准确率和可靠度
      const boost = Math.min(2, r.vulnerabilityScore * 3);
      totalAccuracyBoost += boost;

      improvements.push({
        testType: r.testType,
        action: '弱点强化',
        boost: boost.toFixed(2) + '%'
      });
    }
  });

  // 更新分支
  if (totalAccuracyBoost > 0) {
    const newAccuracy = Math.min(95, branch.accuracy + totalAccuracyBoost);
    const newReliability = Math.min(0.99, (branch.reliability_score || 0.5) + totalAccuracyBoost * 0.01);

    db.prepare(`
      UPDATE yaodi_branch
      SET accuracy = ?, reliability_score = ?, evolution_level = evolution_level + 1
      WHERE id = ?
    `).run(newAccuracy, newReliability, branchId);

    adversarialTestState.totalDefensesStrengthened++;

    return {
      success: true,
      branchId,
      oldAccuracy: branch.accuracy,
      newAccuracy: newAccuracy.toFixed(2),
      reliabilityBoost: ((newReliability - (branch.reliability_score || 0.5)) * 100).toFixed(1) + '%',
      improvements
    };
  }

  return { success: true, branchId, message: '分支已足够稳健,无需强化', improvements: [] };
}

/**
 * 批量对抗测试:对多个分支进行系统性测试
 */
function runBatchAdversarialTest(limit = 10) {
  // 初始化测试表
  initAdversarialTestTables();

  // 选择需要测试的分支:优先选择高分、高演化等级但缺乏对抗测试的
  // 放宽条件:有交易记录>=3 或 准确率>=60%的分支
  const branches = db.prepare(`
    SELECT b.id, b.name, b.accuracy, b.evolution_level, b.reliability_score,
           (SELECT COUNT(*) FROM adversarial_test_results WHERE branch_id = b.id) as test_count
    FROM yaodi_branch b
    WHERE b.active = 1 AND (b.trades >= 3 OR b.accuracy >= 60)
    ORDER BY
      CASE WHEN test_count < 3 THEN 0 ELSE 1 END,
      b.evolution_level DESC,
      b.accuracy DESC
    LIMIT ?
  `).all(limit);

  const batchResults = [];

  branches.forEach(b => {
    const testResult = executeRealAdversarialTest(b.id);
    if (testResult.success) {
      // 自动应用防御强化
      const reinforcement = applyDefenseReinforcement(b.id, testResult);
      batchResults.push({
        branch: { id: b.id, name: b.name },
        test: testResult.summary,
        reinforcement: reinforcement.success ? reinforcement : null
      });
    }
  });

  adversarialTestState.testHistory.push({
    timestamp: bjISO(),
    branchesTested: branches.length,
    results: batchResults
  });

  return {
    success: true,
    totalTested: branches.length,
    results: batchResults,
    state: adversarialTestState
  };
}

/**
 * 获取对抗测试综合报告
 */
function getComprehensiveAdversarialReport() {
  // 初始化表
  initAdversarialTestTables();

  // 统计测试覆盖情况
  const coverageStats = db.prepare(`
    SELECT
      COUNT(DISTINCT b.id) as total_branches,
      COUNT(DISTINCT atr.branch_id) as tested_branches,
      (SELECT COUNT(*) FROM adversarial_test_results WHERE passed = 1) as passed_tests,
      (SELECT COUNT(*) FROM adversarial_test_results) as total_tests
    FROM yaodi_branch b
    LEFT JOIN adversarial_test_results atr ON b.id = atr.branch_id
    WHERE b.active = 1
  `).get();

  // 各类型测试平均表现
  const typePerformance = db.prepare(`
    SELECT
      test_type,
      COUNT(*) as test_count,
      AVG(vulnerability_score) as avg_vulnerability,
      AVG(defense_effectiveness) as avg_defense,
      SUM(CASE WHEN passed = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) as pass_rate
    FROM adversarial_test_results
    GROUP BY test_type
    ORDER BY avg_vulnerability DESC
  `).all();

  // 最脆弱的分支
  const vulnerableBranches = db.prepare(`
    SELECT
      b.id, b.name, b.accuracy, b.evolution_level,
      AVG(atr.vulnerability_score) as avg_vulnerability
    FROM yaodi_branch b
    JOIN adversarial_test_results atr ON b.id = atr.branch_id
    GROUP BY b.id
    HAVING avg_vulnerability > 0.3
    ORDER BY avg_vulnerability DESC
    LIMIT 5
  `).all();

  // 最稳健的分支
  const robustBranches = db.prepare(`
    SELECT
      b.id, b.name, b.accuracy, b.evolution_level,
      AVG(atr.defense_effectiveness) as avg_defense
    FROM yaodi_branch b
    JOIN adversarial_test_results atr ON b.id = atr.branch_id
    GROUP BY b.id
    HAVING avg_defense > 0.8
    ORDER BY avg_defense DESC
    LIMIT 5
  `).all();

  // 最近测试历史
  const recentTests = db.prepare(`
    SELECT
      atr.branch_id, b.name as branch_name,
      atr.test_type, atr.vulnerability_score, atr.defense_effectiveness,
      atr.passed, atr.created_at
    FROM adversarial_test_results atr
    LEFT JOIN yaodi_branch b ON atr.branch_id = b.id
    ORDER BY atr.created_at DESC
    LIMIT 20
  `).all();

  return {
    success: true,
    timestamp: bjISO(),
    coverage: {
      totalBranches: coverageStats.total_branches || 0,
      testedBranches: coverageStats.tested_branches || 0,
      coverageRate: coverageStats.total_branches > 0
        ? ((coverageStats.tested_branches / coverageStats.total_branches) * 100).toFixed(1) + '%'
        : '0%'
    },
    performance: {
      totalTests: coverageStats.total_tests || 0,
      passedTests: coverageStats.passed_tests || 0,
      passRate: coverageStats.total_tests > 0
        ? ((coverageStats.passed_tests / coverageStats.total_tests) * 100).toFixed(1) + '%'
        : '0%'
    },
    typeAnalysis: typePerformance,
    vulnerableBranches,
    robustBranches,
    recentTests,
    systemState: adversarialTestState
  };
}


// ═══════════════════════════════════════════════════════════════
// 第二阶段:定向演化系统
// ═══════════════════════════════════════════════════════════════

const EVOLUTION_STRATEGY = {
  ENHANCE: 'enhance',
  MUTATE: 'mutate',
  EXPLORE: 'explore',
  ADAPT: 'adapt'
};

function determineEvolutionStrategy(branch, recentPerf, currentEnv) {
  // P2优化: 提高EXPLORE探索比例,避免困于局部最优
  const r = Math.random();
  if (branch.evolution_level >= 15) {
    // 高等级分支:增强EXPLORE(20%)防止过度保守
    if (recentPerf && recentPerf.win_rate > 0.7) return r < 0.3 ? EVOLUTION_STRATEGY.ENHANCE : r < 0.7 ? EVOLUTION_STRATEGY.MUTATE : EVOLUTION_STRATEGY.EXPLORE;
    else if (recentPerf && recentPerf.win_rate < 0.5) return r < 0.4 ? EVOLUTION_STRATEGY.MUTATE : EVOLUTION_STRATEGY.EXPLORE;
    else return r < 0.3 ? EVOLUTION_STRATEGY.ENHANCE : r < 0.6 ? EVOLUTION_STRATEGY.MUTATE : EVOLUTION_STRATEGY.EXPLORE;
  }
  if (branch.evolution_level >= 8) {
    // 中等级分支:大幅提高EXPLORE(30%)
    if (r < 0.3) return EVOLUTION_STRATEGY.ENHANCE;
    else if (r < 0.5) return EVOLUTION_STRATEGY.MUTATE;
    else return EVOLUTION_STRATEGY.EXPLORE;
  }
  // 低等级分支:保持高探索(50%)
  if (r < 0.2) return EVOLUTION_STRATEGY.ENHANCE;
  else if (r < 0.4) return EVOLUTION_STRATEGY.MUTATE;
  else return EVOLUTION_STRATEGY.EXPLORE;
}

function calculateMutation(strategy, branch) {
  const trades = branch.trades || 0;
  const evoLevel = branch.evolution_level || 0;

  // ── 【核心修复】准确率必须来自真实交易数据 ──────────────────────
  // 1. 从 branch_performance 读取该分支在当前环境的真实胜率
  let realWinRate = null;
  try {
    const perf = db.prepare(
      "SELECT win_rate, trade_count FROM branch_performance WHERE branch_name = ? ORDER BY id DESC LIMIT 1"
    ).get(branch.name);
    if (perf && perf.trade_count > 0) {
      realWinRate = perf.win_rate;
    }
  } catch(e) { /* 表不存在或字段不同,静默 */ }

  // 2. 从 yaodi_branch 读取该分支当前的胜率(实时更新)
  let currentWinRate = branch.win_rate || 50;

  // 3. 有真实数据 → 用真实数据;无 → 用父分支数据
  const baseAccuracy = (realWinRate !== null)
    ? realWinRate                        // ✅ 用真实交易胜率
    : (currentWinRate !== null ? currentWinRate : 55);

  // 演化策略影响(只用于微调,不主导)
  let strategyBonus = 0;
  switch(strategy) {
    case 'enhance':  strategyBonus = 0.8 + Math.random() * 1.2;   break; // +0.8~2.0%【BUG修复】增强偏向正向
    case 'mutate':   strategyBonus = (Math.random() - 0.5) * 3; break; // ±3%【BUG修复】改为中性偏移
    case 'explore':  strategyBonus = (Math.random() - 0.5) * 5; break; // ±5%
    case 'adapt':    strategyBonus = 0.2 + Math.random() * 1;   break; // ±1%
    default:         strategyBonus = (Math.random() - 0.45) * 2;
  }

  // 演化等级加成(有限)
  const levelBonus = Math.min(evoLevel * 0.1, 3);

  // 【P1修复】准确率校准:基于真实交易数据动态设置上限
  // 问题:原逻辑accuracyCeiling=99.9导致所有分支准确率虚高
  // 修复:
  // 1. 有真实交易数据:上限 = min(真实胜率+15%, 85%),防止过度乐观
  // 2. 无真实交易数据:上限 = 75%,强制需要验证
  // 3. 准确率下限 = max(真实胜率-10%, 50%),防止过度悲观
  let accuracyCeiling, accuracyFloor;
  if (realWinRate !== null && realWinRate > 0) {
    // 有真实数据:基于真实胜率设置合理区间
    accuracyCeiling = Math.min(realWinRate + 15, 85);  // 上限不超过85%
    accuracyFloor = Math.max(realWinRate - 10, 50);    // 下限不低于50%
  } else {
    // 无真实数据:使用保守估计
    accuracyCeiling = 75;
    accuracyFloor = 50;
  }
  const accuracy = Math.max(accuracyFloor, Math.min(accuracyCeiling, baseAccuracy + strategyBonus + levelBonus));

  // 可靠度:基于真实交易数 + 演化等级
  const reliability = Math.min(0.9, 0.3 + Math.min(trades / 200, 0.5) + evoLevel / 150);

  return {
    accuracy,
    reliability,
    realData: realWinRate !== null,
    needsValidation: trades < 5
  };
}

function getStrategyEmoji(strategy) {
  return { enhance: '⬆️', mutate: '🔄', explore: '🔍', adapt: '🎯' }[strategy] || '❓';
}

function getStrategyName(strategy) {
  return { enhance: '强化', mutate: '变异', explore: '探索', adapt: '适应' }[strategy] || '未知';
}

function evolveBranch(branchId, isTechModel) {
  const parent = db.prepare('SELECT * FROM yaodi_branch WHERE id = ?').get(branchId);
  if (!parent) return { success: false, error: '分支不存在' };

  // 🔧 质量控制:有真实交易记录的优先,无交易但高分分支也允许演化(舜帝已启动,自动积累)
  // 放宽门槛:有交易≥5优先;无交易但accuracy≥60也允许演化(快速扩充候选池)
  const hasRealTrades = parent.trades >= 5;
  const qualifiesWithoutTrades = !hasRealTrades && parent.accuracy >= 60;
  if (!hasRealTrades && !qualifiesWithoutTrades) {
    return {
      success: false,
      error: '分支需至少5次交易或准确率≥60%才能参与演化',
      trades: parent.trades || 0,
      accuracy: parent.accuracy
    };
  }

  // 🔧 数量控制:总分支数不超过10000
  // 【P2-3增强】主动淘汰:准确率<25%且非top10模型的分支应被淘汰
  const lowQuality = db.prepare(`
    SELECT id FROM yaodi_branch
    WHERE active = 1 AND accuracy < 25
    AND evolution_level < (SELECT MAX(evolution_level) FROM yaodi_branch WHERE active=1) - 100
    LIMIT 50
  `).all();
  let autoEliminated = 0;
  lowQuality.forEach(b => {
    db.prepare("UPDATE yaodi_branch SET active=0, disabled_reason='低质量淘汰' WHERE id=?").run(b.id);
    autoEliminated++;
  });
  if (autoEliminated > 0) console.log(`\u1F4A8 主动淘汰${autoEliminated}只低质量分支(准确率<25%)`);

  const totalBranches = db.prepare('SELECT COUNT(*) as c FROM yaodi_branch WHERE active = 1').get().c;
  if (totalBranches > 10000) {
    // 淘汰最低效的10%
    const toDisable = Math.floor(totalBranches * 0.1);
    db.prepare(`
      UPDATE yaodi_branch SET active = 0, disabled_reason = '质量淘汰'
      WHERE id IN (
        SELECT id FROM yaodi_branch
        WHERE active = 1
        ORDER BY accuracy ASC, trades ASC
        LIMIT ?
      )
    `).run(toDisable);
    console.log(`🗑️ 淘汰${toDisable}个低效分支`);
  }

  const currentEnv = detectMarketEnvironment();
  const recentPerf = db.prepare('SELECT * FROM branch_performance WHERE branch_id = ? AND environment = ?').get(branchId, currentEnv);
  const strategy = determineEvolutionStrategy(parent, recentPerf, currentEnv);
  const mutationParams = calculateMutation(strategy, parent);

  const newAccuracy = mutationParams.accuracy;
  const newReliability = mutationParams.reliability;
  const newLevel = parent.evolution_level + 1;

  let newName, newStrategy, newScene, newDescription, derivedWinRate;
  const newId = (isTechModel ? 'tech_' : 'strat_') + Date.now();
  eliminateLowerBranches(isTechModel, newLevel, newAccuracy);

  // 【P0修复】win_rate 计算简化:确保结果在 [0, 100] 范围内
  // 根因: 原嵌套 min/max 逻辑导致 win_rate 可能超过 100
  const parentWinRate = Math.max(0, Math.min(100, parent.win_rate || 50));
  const accuracyDelta = newAccuracy - (parent.accuracy || 50);
  const winRateAdjust = accuracyDelta > 0 ? Math.min(3, accuracyDelta * 0.5) : Math.max(-5, accuracyDelta * 0.3);

  if (isTechModel) {
    if (strategy === EVOLUTION_STRATEGY.EXPLORE || newLevel % 7 === 0) {
      const template = TECH_MODEL_NAMES[newLevel % TECH_MODEL_NAMES.length];
      newName = template.name + '_v' + newLevel;
      newStrategy = template.strategy;
      newScene = template.scene;
      derivedWinRate = Math.max(0, Math.min(100, parentWinRate + winRateAdjust));
      newDescription = template.description + ',演化等级Lv.' + newLevel + ',准确率' + newAccuracy.toFixed(1) + '%,可靠度' + (newReliability*100).toFixed(0) + '%';
    } else {
      newName = parent.name.split('_v')[0] + '_v' + newLevel;
      newStrategy = parent.strategy;
      newScene = parent.scene;
      derivedWinRate = Math.max(0, Math.min(100, parentWinRate + (accuracyDelta > 0 ? 1.5 : -1.5)));
      newDescription = parent.description.split(',')[0] + ',演化等级Lv.' + newLevel + ',准确率' + newAccuracy.toFixed(1) + '%,可靠度' + (newReliability*100).toFixed(0) + '%';
    }
  } else {
    if (strategy === EVOLUTION_STRATEGY.EXPLORE || newLevel % 5 === 0) {
      const template = STRATEGY_NAMES[newLevel % STRATEGY_NAMES.length];
      newName = template.name + '_v' + newLevel;
      newStrategy = template.strategy;
      derivedWinRate = Math.max(0, Math.min(100, parentWinRate + winRateAdjust));
      newDescription = template.description + ',演化等级Lv.' + newLevel + ',准确率' + newAccuracy.toFixed(1) + '%,胜率' + derivedWinRate.toFixed(1) + '%';
    } else {
      newName = parent.name.split('_v')[0] + '_v' + newLevel;
      newStrategy = parent.strategy;
      derivedWinRate = Math.max(0, Math.min(100, parentWinRate + (accuracyDelta > 0 ? 2 : 0.5)));
      newDescription = parent.description.split(',')[0] + ',演化等级Lv.' + newLevel + ',准确率' + newAccuracy.toFixed(1) + '%,胜率' + derivedWinRate.toFixed(1) + '%';
    }
  }
  // ── 去重修复:如果同名策略已存在(同名且同类型),UPDATE 版本而非重复 INSERT ──
  // 提取基础名称(去掉 _v数字 后缀),找同名最新记录
  const baseName = newName.replace(/_v\d+$/, '');
  const existingSameName = db.prepare(`
    SELECT id, evolution_level, accuracy, trades FROM yaodi_branch
    WHERE name LIKE ? AND is_tech_model = ?
    ORDER BY evolution_level DESC LIMIT 1
  `).get(baseName + '%', isTechModel ? 1 : 0);

  if (existingSameName) {
    // 同名已存在:UPDATE 为新参数(保留 ID,不新建记录)
    const accBefore = existingSameName.accuracy;
    db.prepare(`
      UPDATE yaodi_branch SET
        accuracy = ?, win_rate = ?, evolution_level = ?,
        reliability_score = ?, scene = ?, description = ?
      WHERE id = ?
    `).run(
      newAccuracy.toFixed(2), derivedWinRate.toFixed(2), newLevel,
      newReliability.toFixed(2), newScene || '',
      newDescription, existingSameName.id
    );
    // 【P0-3修复】UPDATE路径写evolution_history(真实反映每次演化)
    db.prepare('INSERT INTO evolution_history (generation, parent_id, child_id, child_name, evolution_type, accuracy_before, accuracy_after, environment) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
      .run(parent.evolution_level, existingSameName.id, existingSameName.id, newName, strategy, accBefore, newAccuracy, currentEnv);
    console.log('🧬 ' + getStrategyEmoji(strategy) + '[' + currentEnv + '] ' + parent.name + ' -> ' + newName + ' (UPDATE 准确率: ' + newAccuracy.toFixed(1) + '%)');
    return { success: true, newBranch: { id: existingSameName.id, name: newName, accuracy: newAccuracy, evolution_level: newLevel, description: newDescription }, strategy: strategy, eliminated: 0 };
  }

  // 【BUGFIX#3-第二处】修复字段顺序错位:添加正确的active=0和trades=0
  db.prepare('INSERT INTO yaodi_branch (id, name, branch_name, strategy, accuracy, active, trades, win_rate, evolution_level, reliability_score, scene, is_tech_model, description) VALUES (?, ?, ?, ?, ?, 0, 0, ?, ?, ?, ?, ?, ?)').run(
    newId, newName, newName, newStrategy, newAccuracy.toFixed(2),
    derivedWinRate.toFixed(2), newLevel,
    newReliability.toFixed(2), newScene || '', isTechModel ? 1 : 0, newDescription
  );

  // 实时统计:从 evolution_history 取真实演化次数(而非分支数,因为一次演化不一定产生新分支)
  const evoCount = db.prepare('SELECT COUNT(*) as cnt FROM evolution_history').get()?.cnt || 0;
  db.prepare('UPDATE yaodi_main SET evolution_count = ? WHERE id = 1').run(evoCount);

  db.prepare('INSERT INTO evolution_history (generation, parent_id, child_id, child_name, evolution_type, accuracy_before, accuracy_after, environment) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
    .run(parent.evolution_level, branchId, newId, newName, strategy, parent.accuracy, newAccuracy, currentEnv);

  console.log('🧬 ' + getStrategyEmoji(strategy) + '[' + currentEnv + '] ' + parent.name + ' -> ' + newName + ' (INSERT 准确率: ' + newAccuracy.toFixed(1) + '%, 策略: ' + getStrategyName(strategy) + ')');

  return { success: true, newBranch: { id: newId, name: newName, accuracy: newAccuracy, evolution_level: newLevel, description: newDescription }, strategy: strategy, eliminated: 0 };
}


function eliminateLowerBranches(isTechModel, newLevel, newAccuracy) {
  try {
    // ── 【多样性保护】消除逻辑改为两层:
    // Step 1: 每个基础模型(趋势跟踪/ATR指标/KDJ指标...)各保留 Top 2
    // Step 2: 全局最多保留 15 个技术模型(足够覆盖全部类型)
    // 效果:防止一个模型家族垄断所有活跃名额,其他模型永远没有演化机会
    const PER_MODEL_LIMIT = 2;
    const GLOBAL_LIMIT = 15;

    // Step 1: 按模型类型分组,每组取 Top N
    const allBranches = db.prepare(`
      SELECT id, name, accuracy, trades, win_rate
      FROM yaodi_branch
      WHERE is_tech_model = ? AND active = 1
      ORDER BY name, accuracy DESC, trades DESC
    `).all(isTechModel ? 1 : 0);

    // 提取基础模型名(如 "趋势跟踪模型_v367" → "趋势跟踪")
    const perModelMap = new Map();
    for (const b of allBranches) {
      const baseName = b.name.replace(/_v\d+$/, '');
      if (!perModelMap.has(baseName)) perModelMap.set(baseName, []);
      perModelMap.get(baseName).push(b);
    }

    // Step 2: 每模型取 Top 2,全局最多 15
    const keptIds = [];
    let globalCount = 0;
    for (const [baseName, items] of perModelMap.entries()) {
      const keep = items.slice(0, PER_MODEL_LIMIT);
      keptIds.push(...keep.map(b => b.id));
      globalCount += keep.length;
      if (globalCount >= GLOBAL_LIMIT) break;
    }

    if (keptIds.length > 0) {
      // 【P0修复】保留高质量分支(accuracy > 75),避免过度淘汰
      const disabled = db.prepare(`
        UPDATE yaodi_branch SET active = 0, disabled_reason = '版本合并淘汰'
        WHERE is_tech_model = ?
        AND active = 1
        AND accuracy < 75
        AND id NOT IN (${keptIds.map(() => '?').join(',')})
      `).run(...(isTechModel ? [1] : [0]), ...keptIds);
      if (disabled.changes > 0) {
        console.log(`🗑️ [去重] 淘汰 ${disabled.changes} 个低版本,保留 ${keptIds.length} 个(含 ${perModelMap.size} 种模型),高质量分支(accuracy>75)保留`);
        return disabled.changes;
      }
    }
  } catch (e) {
    console.error('[eliminateLowerBranches] 淘汰失败:', e.message);
  }
  return 0;
}

// ═══════════════════════════════════════════════════════════════
// 交易信号生成系统 - 尧帝高分策略 -> 舜帝交易信号
// ═══════════════════════════════════════════════════════════════

function generateTradingSignals() {
  try {
    // 1. 清理过期信号
    db.prepare("DELETE FROM trade_signals WHERE expires_at < ?").run(bjNow());

    // 2. 获取当前市场环境
    const currentEnv = detectMarketEnvironment();
    const marketStats = db.prepare("SELECT * FROM market_stats ORDER BY id DESC LIMIT 1").get();
    const upRatio = marketStats ? (marketStats.up_count || 0) / Math.max(marketStats.total_count || 1, 1) : 0.5;

    // 3. 从尧帝高分分支中筛选策略
    // 【数据修复】用 branch_performance 中的真实胜率替代 self-inflated accuracy
    const topBranches = db.prepare(`
      SELECT b.id, b.name, b.branch_name, b.strategy, b.accuracy, b.win_rate, b.evolution_level,
             b.reliability_score, b.best_environment, b.trades,
             COALESCE(bp.real_win, b.win_rate, 50) as real_win
      FROM yaodi_branch b
      LEFT JOIN (
        SELECT branch_name,
               SUM(trade_count * CASE WHEN win_rate < 1 THEN win_rate * 100 ELSE win_rate END) / NULLIF(SUM(trade_count), 0) as real_win
        FROM branch_performance GROUP BY branch_name
      ) bp ON bp.branch_name = b.branch_name OR bp.branch_name = b.name
      WHERE b.active = 1
      ORDER BY
        CASE WHEN b.best_environment = ? THEN 1 ELSE 0 END DESC,
        real_win DESC,
        b.reliability_score DESC
      LIMIT 500  /* 【优化】从20扩展到500,覆盖所有活跃分支 */
    `).all(currentEnv);

    // 【改造v2】全市场量化初筛候选股池(最多500只)
    // 收藏股优先(最多50只),全市场量化筛选补充至500只
    // 量化筛选条件:价格适中 + 涨跌幅温和 + 有成交量
    // 【BUGFIX-v3】修复:user_stock_pool无volume/high/low列,改为JOIN stock_realtime获取
    const favoriteStocks = db.prepare(`
      SELECT u.code, u.name,
             r.price, r.change_percent, r.volume, r.high, r.low, r.pre_close
      FROM user_stock_pool u
      LEFT JOIN stock_realtime r ON u.code = r.code
      WHERE u.price > 0 AND u.price < 500
        AND r.change_percent IS NOT NULL
        AND ((r.change_percent > 0 AND r.change_percent < CASE WHEN (u.code LIKE '300%' OR u.code LIKE '301%' OR u.code LIKE '688%' OR u.code LIKE '689%') THEN 19.5 WHEN (u.code LIKE '8%' OR u.code LIKE '4%') THEN 29.5 ELSE 9.5 END) OR (r.change_percent < 0 AND r.change_percent > -CASE WHEN (u.code LIKE '300%' OR u.code LIKE '301%' OR u.code LIKE '688%' OR u.code LIKE '689%') THEN 19.5 WHEN (u.code LIKE '8%' OR u.code LIKE '4%') THEN 29.5 ELSE 9.5 END))
        AND r.volume > 0
      ORDER BY ABS(r.change_percent) DESC
      LIMIT 50
    `).all();

    // 【改造】全市场量化初筛:排除ST、退市、涨跌停、高价股
    const MARKET_LIMIT = 450;
    const marketStocks = db.prepare(`
      SELECT code, name, price, change_percent, volume, high, low, pre_close
      FROM stock_realtime sr
      WHERE sr.price > 1 AND sr.price < 200
        AND sr.change_percent IS NOT NULL
        AND sr.change_percent > -9.8 AND sr.change_percent < 9.8
        AND sr.volume > 100000
        AND sr.code NOT IN (SELECT code FROM user_stock_pool)
      ORDER BY
        CASE WHEN sr.change_percent BETWEEN -3 AND 5 THEN 0 ELSE 1 END,
        sr.volume DESC,
        ABS(sr.change_percent) DESC
      LIMIT ?
    `).all(MARKET_LIMIT);

    const stockPool = [...favoriteStocks, ...marketStocks];
    console.log(`[信号] 候选股池: 收藏${favoriteStocks.length}只 + 全市场量化筛选${marketStocks.length}只 = 共${stockPool.length}只`);

    // 5. 为每个高分策略生成信号
    let signalsGenerated = 0;

    // 策略一:强制生成买入信号(舜帝需要建仓)
    // 【优化v3】扩大舜帝候选池:使用全部符合条件股票(从500只候选股中)
    // 【优化】信号每日刷新:每批30只,分批生成确保每天都有新信号
    const buySignalCount = Math.min(100, stockPool.filter(s => {
      const change = parseFloat(s.change_percent) || 0;
      // 温和上涨(追涨)或小幅回调(抄底),扩大范围
      return (change > 0 && change < 9) || (change < 0 && change > -5);
    }).length);

    const buyCandidates = stockPool.filter(s => {
      const change = parseFloat(s.change_percent) || 0;
      return (change > 0 && change < 9) || (change < 0 && change > -5);
    }).slice(0, buySignalCount);

    // 【修复】确定性分支匹配:根据股票涨跌特征匹配最适合的分支策略,不用 random
    function pickBestBranch(stock, branches, env) {
      const change = parseFloat(stock.change_percent) || 0;
      // 根据股票特征和环境匹配最佳分支
      return branches.slice(0, Math.min(3, branches.length)).sort((a, b) => {
        let scoreA = a.accuracy + (a.reliability_score || 0) * 10;
        let scoreB = b.accuracy + (b.reliability_score || 0) * 10;
        // 涨幅股优先匹配趋势策略,跌幅股优先匹配均值回归策略
        if (change > 0 && a.strategy?.includes('trend')) scoreA += 5;
        if (change > 0 && b.strategy?.includes('trend')) scoreB += 5;
        if (change < 0 && a.strategy?.includes('mean_reversion')) scoreA += 5;
        if (change < 0 && b.strategy?.includes('mean_reversion')) scoreB += 5;
        return scoreB - scoreA;
      })[0];
    }

    // // console.log(`[信号调试] buyCandidates=${buyCandidates.length}, topBranches=${topBranches.length}`);
    buyCandidates.forEach(stock => {
      try {
        const branch = pickBestBranch(stock, topBranches, currentEnv);
        // // console.log(`[信号调试] ${stock.code} ${stock.name} change=${stock.change_percent}% → branch=${branch?.name || 'NULL'}`);
        if (!branch) return;

        // 【铁律合规】价格缺失时跳过该股票,不伪造价格
        const currentPrice = parseFloat(stock.price);
        if (!currentPrice || currentPrice <= 0) return;

        // 【BUGFIX 2026-04-25】confidence上限从硬编码92→95,让高分分支脱颖而出
        const confidence = Math.min(95, Math.max(85, branch.accuracy + 5));
        // 【修复】目标价基于 ATR 波动率计算,而非固定 5%
        const changeAbs = Math.abs(parseFloat(stock.change_percent) || 2);
        const targetMultiplier = 1 + Math.max(0.02, Math.min(0.08, changeAbs * 0.02));
        const targetPrice = parseFloat((currentPrice * targetMultiplier).toFixed(2));

        // 信号去重: 同code+source+signal组合2小时内不重复
        const exists = db.prepare("SELECT id FROM trade_signals WHERE code=? AND source=? AND signal='buy' AND expires_at > ? LIMIT 1").get(stock.code, `yaodi_${branch.strategy}`, bjNow());
        if (!exists) {
          const stopLossPrice = parseFloat((currentPrice * 0.95).toFixed(2)); // 默认5%止损
          db.prepare(`
            INSERT INTO trade_signals (code, name, signal, confidence, price, target_price, stop_loss, reason, source, expires_at)
            VALUES (?, ?, 'buy', ?, ?, ?, ?, ?, ?, ?)
          `).run(
            stock.code,
            stock.name,
            confidence,
            currentPrice,
            targetPrice,
            stopLossPrice,
            `${branch.name}[Lv.${branch.evolution_level}] | 环境:${currentEnv} | 抄底/追涨信号`,
            `yaodi_${branch.strategy}`,
            bjNow(),
            bjFuture(2)
          );
          signalsGenerated++;
        }
      } catch (e) {}
    });

    // 策略二:生成卖出信号(变化较大的股票)
    const sellCandidates = stockPool.filter(s => {
      const change = parseFloat(s.change_percent) || 0;
      return Math.abs(change) > 5; // 变化超过5%
    }).slice(0, 20);  // 【优化】从2扩展到20,生成更多卖出信号

    sellCandidates.forEach(stock => {
      try {
        const branch = pickBestBranch(stock, topBranches, currentEnv);
        if (!branch) return;

        // 【铁律合规】价格缺失时跳过该股票,不伪造价格
        const currentPrice = parseFloat(stock.price);
        if (!currentPrice || currentPrice <= 0) return;

        // 【BUGFIX 2026-04-25】卖出信号confidence也放开上限,允许高置信卖出
        const confidence = Math.min(93, Math.max(80, branch.accuracy));
        // 【修复】卖出目标价基于波动率,而非固定 -3%
        const changeAbs = Math.abs(parseFloat(stock.change_percent) || 3);
        const targetMultiplier = 1 - Math.max(0.02, Math.min(0.05, changeAbs * 0.01));
        const targetPrice = parseFloat((currentPrice * targetMultiplier).toFixed(2));

        const existsSell = db.prepare("SELECT id FROM trade_signals WHERE code=? AND source=? AND signal='sell' AND expires_at > ? LIMIT 1").get(stock.code, `yaodi_${branch.strategy}`, bjNow());
        if (!existsSell) {
          db.prepare(`
            INSERT INTO trade_signals (code, name, signal, confidence, price, target_price, reason, source, expires_at)
            VALUES (?, ?, 'sell', ?, ?, ?, ?, ?, ?)
          `).run(
            stock.code,
            stock.name,
            confidence,
            currentPrice,
            targetPrice,
            `${branch.name}[Lv.${branch.evolution_level}] | 环境:${currentEnv} | 止盈/止损信号`,
            `yaodi_${branch.strategy}`,
            bjFuture(2)
          );
          signalsGenerated++;
        }
      } catch (e) {}
    });

    if (signalsGenerated > 0) {
      console.log(`📡 尧帝生成 ${signalsGenerated} 条交易信号 (环境:${currentEnv}, 高分策略:${topBranches.length}个)`);
      addRedQueenLog(`📡 尧帝信号: 生成${signalsGenerated}条 | 环境:${currentEnv}`, 'learn');

      // 【已禁用 2026-06-04】尧帝选股结果不再自动加入收藏股
      // 原因：用户未手动添加的股票不应出现在收藏股板块
      // 收藏股只允许用户手动添加（通过 /api/favorites/add 和 /api/pool/add）
      // try {
      //   const yaodiStocks = buyCandidates.slice(0, 5);
      //   for (const s of yaodiStocks.slice(0, 5)) {
      //     const stockName = s.name || s.code;
      //     const existsFav = db.prepare('SELECT id FROM favorites WHERE code=? AND name=?').get(s.code, stockName);
      //     if (!existsFav) {
      //       db.prepare('INSERT INTO favorites (code, name, added_at) VALUES (?, ?, ?)').run(s.code, stockName, bjNow());
      //     }
      //     const existsPool = db.prepare('SELECT id FROM user_stock_pool WHERE code=?').get(s.code);
      //     if (!existsPool) {
      //       db.prepare(`INSERT INTO user_stock_pool (code, name, add_time, add_source, is_favorite, price, pre_close, change_percent, update_time)
      //         VALUES (?, ?, ?, 'yaodi_signal', 1, ?, ?, ?, ?)`)
      //       .run(s.code, stockName, bjNow(), parseFloat(s.price)||0, parseFloat(s.pre_close)||0, parseFloat(s.change_percent)||0, bjNow());
      //     } else {
      //       db.prepare("UPDATE user_stock_pool SET is_favorite=1, add_source='yaodi_signal', update_time=? WHERE code=?").run(bjNow(), s.code);
      //     }
      //   }
      //   console.log(`[尧帝→收藏] ${yaodiStocks.slice(0,5).length}只股票已加入favorites`);
      // } catch(e) { console.error('[尧帝→收藏] 失败:', e.message); }
    }

    return { success: true, signals: signalsGenerated, environment: currentEnv };

  } catch (err) {
    console.error('信号生成错误:', err);
    return { success: false, error: err.message };
  }
}

// 策略配置表
function getStrategyConfig(strategy) {
  const configs = {
    'macd_model': { bullBias: true, bearBias: false, meanReversion: false },
    'rsi_model': { bullBias: false, bearBias: true, meanReversion: true },
    'ma_system': { bullBias: true, bearBias: false, meanReversion: false },
    'kdj_model': { bullBias: false, bearBias: true, meanReversion: true },
    'bollinger': { bullBias: false, bearBias: false, meanReversion: true },
    'support_resist': { bullBias: true, bearBias: true, meanReversion: false },
    'fibonacci': { bullBias: true, bearBias: false, meanReversion: false },
    'chan_theory': { bullBias: true, bearBias: true, meanReversion: false },
    'momentum': { bullBias: true, bearBias: false, meanReversion: false },
    'reversal': { bullBias: false, bearBias: true, meanReversion: true },
    'trend_follow': { bullBias: true, bearBias: false, meanReversion: false },
    'long': { bullBias: true, bearBias: false, meanReversion: false },
    'short': { bullBias: false, bearBias: true, meanReversion: false },
    'value': { bullBias: true, bearBias: false, meanReversion: false },
    'growth': { bullBias: true, bearBias: false, meanReversion: false },
    'default': { bullBias: true, bearBias: false, meanReversion: false }
  };
  return configs[strategy] || configs['default'];
}


// 启动演化引擎
function startEvolutionEngine() {
  if (evolutionEngineRunning) {
    console.log('⚠️ 演化引擎已在运行中');
    return;
  }

  // 先校正数据
  calibrateYaodiData();

  // 🔧 同步演化计数:从 evolution_history 取真实值
  const realCount = db.prepare('SELECT COUNT(*) as c FROM evolution_history').get()?.c || 0;
  const main0 = db.prepare('SELECT evolution_count FROM yaodi_main WHERE id = 1').get();
  if (main0 && realCount !== main0.evolution_count) {
    db.prepare('UPDATE yaodi_main SET evolution_count = ? WHERE id = 1').run(realCount);
    console.log(`🔧 演化计数同步:${main0.evolution_count} → ${realCount}`);
  }

  evolutionEngineRunning = true;
  // 速度: 1=最慢60秒/次, 60=标准1秒/次, 100=最快(≤1秒)
  const mainCfg = db.prepare("SELECT evolution_speed FROM yaodi_main WHERE id = 1").get() || { evolution_speed: 50 };
  // FIX: 公式改为正向(speed↑=interval↓),并确保正常范围
  const rawInterval = Math.round(60000 / Math.max(1, Math.min(100, mainCfg.evolution_speed)));
  const evolutionIntervalMs = mainCfg.evolution_speed <= 0 ? 0 : Math.max(1000, rawInterval);
  if (evolutionIntervalMs === 0) { console.log('⏸ 演化暂停(速度=0)'); return; }
  console.log(`🚀 演化引擎启动,速度=${mainCfg.evolution_speed},间隔=${evolutionIntervalMs}ms`);


  evolutionInterval = setInterval(() => {
    const _evoStart = Date.now();
    try {
      // 【时段互斥】交易时段禁止演化升级,仅执行 L1/L2/L3
      if (isTradingHours()) {
        YaodiBrain.systemModules.evolutionEngine.status    = 'standby';
        YaodiBrain.systemModules.evolutionEngine.health    = 80;
        YaodiBrain.systemModules.evolutionEngine.lastCheck = bjISO();
        return;
      }
      // ── 同步演化引擎状态到 YaodiBrain.systemModules ───────────────
      YaodiBrain.systemModules.evolutionEngine.status    = 'online';
      YaodiBrain.systemModules.evolutionEngine.health    = 100;
      YaodiBrain.systemModules.evolutionEngine.lastCheck = bjISO();

      // ── 同步舜帝交易引擎状态 ──────────────────────────────────────
      YaodiBrain.systemModules.shundiEngine.status    = shundiRunning ? 'online' : 'offline';
      YaodiBrain.systemModules.shundiEngine.health    = shundiRunning ? 100 : 0;
      YaodiBrain.systemModules.shundiEngine.lastCheck = bjISO();

      // ── 同步红后运行引擎状态 ─────────────────────────────────────
      YaodiBrain.systemModules.redqueenEngine.status    = redqueenRunning ? 'online' : 'offline';
      YaodiBrain.systemModules.redqueenEngine.health    = redqueenRunning ? 100 : 0;
      YaodiBrain.systemModules.redqueenEngine.lastCheck = bjISO();

      // ── 同步尧帝智能体状态 ─────────────────────────────────────────
      YaodiBrain.systemModules.yaodiAgent.status    = yaodiEvolutionRunning ? 'online' : 'offline';
      YaodiBrain.systemModules.yaodiAgent.health    = yaodiEvolutionRunning ? 100 : 0;
      YaodiBrain.systemModules.yaodiAgent.lastCheck = bjISO();

      // ── 同步数据源管理状态 ─────────────────────────────────────────
      YaodiBrain.systemModules.dataSource.status    = 'online';
      YaodiBrain.systemModules.dataSource.health    = 100;
      YaodiBrain.systemModules.dataSource.lastCheck = bjISO();

      // ── 同步学习系统状态 ──────────────────────────────────────────
      YaodiBrain.systemModules.learningSystem.status    = 'online';
      YaodiBrain.systemModules.learningSystem.health    = 100;
      YaodiBrain.systemModules.learningSystem.lastCheck = bjISO();

      // ── 同步分支管理状态 ──────────────────────────────────────────
      YaodiBrain.systemModules.branchManager.status    = 'online';
      YaodiBrain.systemModules.branchManager.health    = 100;
      YaodiBrain.systemModules.branchManager.lastCheck = bjISO();

      // 使用环境适应性演化
      const adaptation = environmentAdaptiveEvolution();

      if (adaptation.parentId) {
        const parent = db.prepare('SELECT * FROM yaodi_branch WHERE id = ?').get(adaptation.parentId);
        if (parent) {
          const result = evolveBranch(parent.id, parent.is_tech_model === 1);

          if (result.success) {
            const adaptTag = adaptation.isAdapted ? '✅适应' : '🔄随机';
            console.log(`🧬 ${adaptTag}[${adaptation.environment}] ${parent.name} -> ${result.newBranch.name} (准确率: ${result.newBranch.accuracy.toFixed(1)}%)`);
          }
        }
      }

      // 实时统计演化计数(从 evolution_history 取值,避免与分支数混淆)
      const count = db.prepare('SELECT COUNT(*) as c FROM evolution_history').get()?.c || 0;
      db.prepare('UPDATE yaodi_main SET evolution_count = ? WHERE id = 1').run(count);

      // 每50次演化,模拟一次分支表现
      const main = db.prepare('SELECT evolution_count FROM yaodi_main LIMIT 1').get();
      if (main && main.evolution_count % 50 === 0) {
        simulateBranchPerformance();
      }

      // 每100次演化,进行一次对抗训练
      if (main && main.evolution_count % 100 === 0) {
        adversarialTraining();
      }

      // 【改进】演化类型多样化
      // 每50次:跨品类杂交(crossover)- 优秀分支交叉产生更强后代
      if (main && main.evolution_count % 50 === 0) {
        try {
          const elites = db.prepare('SELECT id, name, is_tech_model FROM yaodi_branch WHERE active=1 AND accuracy > 70 ORDER BY accuracy DESC LIMIT 10').all();
          if (elites.length >= 2) {
            const p1 = elites[Math.floor(Math.random() * elites.length)];
            const p2 = elites.filter(e => e.id !== p1.id)[Math.floor(Math.random() * (elites.length - 1))];
            if (p1 && p2) crossoverBranches(p1.id, p2.id, p1.is_tech_model === 1);
          }
        } catch (e) { /* 静默失败 */ }
      }

      // 【新】每200次演化:回测驱动优化 - 淘汰回测表现差的分支,强化表现好的
      if (main && main.evolution_count % 200 === 0) {
        try {
          // 找出回测胜率最高的分支,作为强化目标
          const topBacktest = db.prepare(`
            SELECT b.id, b.name, b.accuracy, b.strategy,
                   COALESCE(bt.win_rate, 0) as bt_win_rate, COALESCE(bt.total_trades, 0) as bt_trades
            FROM yaodi_branch b
            LEFT JOIN strategy_backtest_stats bt ON bt.branch_id = b.id
            WHERE b.active = 1 AND bt.total_trades >= 5
            ORDER BY bt.win_rate DESC LIMIT 3
          `).all();
          // 找出回测表现差的分支进行淘汰
          const weakBranches = db.prepare(`
            SELECT b.id, b.name
            FROM yaodi_branch b
            LEFT JOIN strategy_backtest_stats bt ON bt.branch_id = b.id
            WHERE b.active = 1 AND (bt.total_trades >= 10 AND bt.win_rate < 40)
            LIMIT 5
          `).all();
          // 淘汰弱分支
          weakBranches.forEach(wb => {
            db.prepare('UPDATE yaodi_branch SET active = 0 WHERE id = ?').run(wb.id);
            console.log(`📊 [回测淘汰] ${wb.name} (回测胜率<40%)`);
          });
          // 对强分支进行微调进化
          if (topBacktest.length > 0) {
            const best = topBacktest[0];
            evolveBranch(best.id, best.is_tech_model === 1);
            console.log(`📊 [回测强化] ${best.name} (回测胜率${best.bt_win_rate?.toFixed(1)}%)`);
          }
        } catch (e) { /* 静默失败 */ }
      }

      // 【新】每150次演化:竞争淘汰 - 模拟分支间竞争,淘汰最弱的5%
      if (main && main.evolution_count % 150 === 0) {
        try {
          const total = db.prepare('SELECT COUNT(*) as c FROM yaodi_branch WHERE active = 1').get()?.c || 0;
          if (total > 100) {
            const cullCount = Math.max(1, Math.floor(total * 0.05));
            db.prepare(`
              UPDATE yaodi_branch SET active = 0
              WHERE id IN (
                SELECT id FROM yaodi_branch WHERE active = 1
                ORDER BY accuracy ASC LIMIT ?
              )
            `).run(cullCount);
            console.log(`⚔️ [竞争淘汰] 淘汰${cullCount}个最弱分支(共${total}个)`);
          }
        } catch (e) { /* 静默失败 */ }
      }

      // 每30次演化,生成交易信号(关键!舜帝依赖此信号)
      if (main && main.evolution_count % 30 === 0) {
        generateTradingSignals();
      }

      // ═══════════════════════════════════════════════════════════════
      // ═══════════════════════════════════════════════════════════════

    } catch (e) {
      console.error('演化错误:', e.message);
    }
    const _evoMs = Date.now() - _evoStart;
    if (_evoMs > 50) console.log(`⏱️ [CPU] evolutionInterval: ${_evoMs}ms`);
  }, evolutionIntervalMs);

  console.log('✅ 演化引擎已启动 (每60秒演化一次)');

  // ═══════════════════════════════════════════════════════════════
  // 红后级别实时BUG监控 - 独立于演化循环
  // ═══════════════════════════════════════════════════════════════
  startRedQueenMonitoring();

  // ═══════════════════════════════════════════════════════════════
  // 自我守护 - 服务自愈能力
  // ═══════════════════════════════════════════════════════════════
  startSelfGuard();

  // ═══════════════════════════════════════════════════════════════
  // XGBoost自动训练 - 基于真实数据实时训练
  // ═══════════════════════════════════════════════════════════════
  let xgboostTrainInterval = null;

  function startXGBoostAutoTrain() {
    if (xgboostTrainInterval) clearInterval(xgboostTrainInterval);
    if (!xgboostAutoTrainConfig.autoTrain) {
      console.log('⏸ XGBoost自动训练已禁用');
      return;
    }
    const intervalMs = xgboostAutoTrainConfig.intervalMinutes * 60 * 1000;
    console.log(`🤖 XGBoost自动训练启动,间隔${xgboostAutoTrainConfig.intervalMinutes}分钟`);

    // 启动时立即训练一次(除非设置了跳过启动训练)
    (async () => {
      try {
        if (SKIP_STARTUP_TRAINING) {
          console.log('⏭️ [XGBoost] 跳过启动训练(SKIP_STARTUP_TRAINING=true)');
          return;
        }
        if (threeLayerSelector?.aiScorer) {
          await threeLayerSelector.aiScorer.train(365);
          xgboostAutoTrainConfig.lastAutoTrain = bjISO();
          console.log('✅ XGBoost首次自动训练完成');
        }
      } catch(e) { console.error('XGBoost首次训练失败:', e.message); }
    })();

    xgboostTrainInterval = setInterval(async () => {
      if (!xgboostAutoTrainConfig.autoTrain) return;
      try {
        // 检查模型是否过期或不存在
        const modelRow = db.prepare('SELECT data FROM ai_fine_model WHERE id = 1').get();
        let needTrain = !modelRow;
        if (modelRow) {
          const m = JSON.parse(modelRow.data);
          needTrain = m.expires_at ? new Date(m.expires_at) < toBeijingTime() : true;
        }

        if (needTrain && threeLayerSelector?.aiScorer) {
          console.log('🤖 XGBoost自动训练触发(模型过期)');
          await threeLayerSelector.aiScorer.train(365);
          xgboostAutoTrainConfig.lastAutoTrain = bjISO();
          console.log('✅ XGBoost自动训练完成');
        }
      } catch(e) { console.error('XGBoost自动训练失败:', e.message); }
    }, intervalMs);
  }
  startXGBoostAutoTrain();
}

// ═══════════════════════════════════════════════════════════════
// 红后级别实时BUG监控系统
// 扫描频率:10秒关键指标 / 60秒完整扫描
// 响应速度:毫秒级
// 扫描范围:全系统(日志、API、数据库、内存、CPU、网络)
// 自主决策:高危立即修复,中危队列处理,低危记录
// 学习进化:BUG模式学习 + 策略优化
// ═══════════════════════════════════════════════════════════════
let redQueenInterval = null;
let redQueenRunning = false;
let bugQueue = []; // 待处理BUG队列
let bugHistory = []; // BUG历史记录(用于学习)
let systemHealthScore = 100; // 系统健康分数

function startRedQueenMonitoring() {
  if (redQueenRunning) {
    console.log('⚠️ 红后监控已在运行中');
    return;
  }

  redQueenRunning = true;
  console.log('🔴 [红后] 实时BUG监控系统启动');
  console.log('   - 关键指标扫描:每30秒(优化后)');
  console.log('   - 完整系统扫描:每3分钟(优化后)');
  console.log('   - 响应机制:仅记录,不自动修复');

  let scanCount = 0;

  redQueenInterval = setInterval(async () => {
    const _rqStart = Date.now();
    scanCount++;
    const now = bjDate();

    try {
      // 每30秒:关键指标快速扫描
      const quickScan = await quickHealthCheck();

      // 每3分钟:完整系统扫描(每6次扫描 = 3分钟)
      const fullScan = scanCount % 6 === 0 ? await fullSystemScan() : null;

      // 合并扫描结果
      const allIssues = [...quickScan.issues, ...(fullScan?.issues || [])];

      if (allIssues.length > 0) {
        // 按严重性分类
        const highBugs = allIssues.filter(b => b.severity === 'high');
        const mediumBugs = allIssues.filter(b => b.severity === 'medium');
        const lowBugs = allIssues.filter(b => b.severity === 'low');

        // 更新系统健康分数(优化权重:区分核心问题与外部依赖)
        // 【优化 2026-05-07】外部依赖问题(新闻源、上交所等)不扣分或轻扣分
        // 【优化 2026-05-07】降低中危BUG扣分权重,避免健康分过低
        const coreHighBugs = highBugs.filter(b => !isExternalDependency(b));
        const externalBugs = highBugs.filter(b => isExternalDependency(b));

        // 核心高危:每只扣8分(最多40分) - 降低扣分
        const highPenalty = Math.min(coreHighBugs.length, 5) * 8;
        // 外部依赖问题:不扣分(系统已自动切换备用数据源)
        const externalPenalty = 0;
        // 中危:每只扣1分(最多10分) - 大幅降低扣分
        const mediumPenalty = Math.min(mediumBugs.length, 10) * 1;
        // 低危:不扣分(仅记录)
        const lowPenalty = 0;

        // 【新增】基础分70分 + 演化引擎加成10分 + 系统稳定加成10分
        const baseScore = 70;
        const evolutionBonus = evolutionEngineRunning ? 10 : 0;
        const stableBonus = (bugQueue.length < 10 && bugHistory.length < 50) ? 10 : 0;

        systemHealthScore = Math.max(50, Math.min(100, baseScore + evolutionBonus + stableBonus - highPenalty - externalPenalty - mediumPenalty - lowPenalty));

        // 辅助函数:判断是否为外部依赖问题
        function isExternalDependency(bug) {
          const keywords = ['新闻', '新闻源', '东财', '新浪', '腾讯', '网易', '财联社',
                           '上交所', '深交所', '北向', 'socket hang up', '外部API',
                           'fetch', 'axios', 'HTTP undefined', 'timeout'];
          return keywords.some(kw => (bug.message || '').includes(kw));
        }

        // 高危BUG:仅记录,不自动修复(避免引入新问题)
        if (highBugs.length > 0) {
          console.log(`🚨 [红后] 检测到 ${highBugs.length} 个高危BUG,已记录`);
          // 自动修复已禁用,防止语法错误累积
        }

        // 中危BUG:去重后加入队列(队列最多保留50个)
        if (mediumBugs.length > 0) {
          const seenKeys = new Set(bugQueue.map(b => `${b.type}:${b.message}`));
          const newMedium = mediumBugs.filter(b => {
            const key = `${b.type}:${b.message}`;
            if (seenKeys.has(key)) return false;
            seenKeys.add(key);
            return true;
          });
          bugQueue.push(...newMedium);
          if (bugQueue.length > 50) bugQueue = bugQueue.slice(-50); // 限制队列大小
          if (newMedium.length > 0) console.log(`⚠️ [红后] ${newMedium.length} 个新中危BUG已加入队列(队列: ${bugQueue.length})`);
        }

        // 低危BUG:去重后记录(历史最多保留100条)
        if (lowBugs.length > 0) {
          const seenKeys = new Set(bugHistory.map(b => `${b.type}:${b.message}`));
          const newLow = lowBugs.filter(b => {
            const key = `${b.type}:${b.message}`;
            if (seenKeys.has(key)) return false;
            seenKeys.add(key);
            return true;
          }).map(b => ({ ...b, detectedAt: now }));
          bugHistory.push(...newLow);
          if (bugHistory.length > 100) bugHistory = bugHistory.slice(-100);
        }

        // BUG模式学习
        if (scanCount % 6 === 0) {
          await learnBugPatterns(allIssues);
        }
      }

      // 处理队列中的中危BUG(每次处理1个)
      if (bugQueue.length > 0 && scanCount % 3 === 0) {
        const bug = bugQueue.shift();
        await queuedFix(bug);
      }

      // 每6次扫描输出一次状态
      if (scanCount % 6 === 0) {
        console.log(`🔴 [红后] 系统健康分数: ${systemHealthScore}/100 | 队列: ${bugQueue.length} | 历史: ${bugHistory.length}`);
      }

    } catch (e) {
      console.error('🔴 [红后] 监控错误:', e.message);
    }
    const _rqMs = Date.now() - _rqStart;
    if (_rqMs > 50) console.log(`⏱️ [CPU] redQueenInterval: ${_rqMs}ms`);
  }, 10000); // 每10秒扫描一次

  console.log('✅ 红后监控已启动 (实时连续扫描)');
}

// ═══════════════════════════════════════════════════════════════
// 红后级别自我守护 - 服务自愈能力
// ═══════════════════════════════════════════════════════════════
let selfGuardRunning = false;
let selfGuardInterval = null;
let lastGuardCheck = Date.now();
let guardRestartAttempts = 0;
const MAX_GUARD_RESTARTS = 5; // 最大重启尝试次数

function startSelfGuard() { return; // 【已禁用】2026-05-23
  if (selfGuardRunning) {
    console.log('⚠️ 自我守护已在运行中');
    return;
  }

  selfGuardRunning = true;
  console.log('🛡️ [自我守护] 红后级别自愈系统启动');
  console.log('   - 组件监控:每30秒');
  console.log('   - 内存监控:每30秒');
  console.log('   - 数据清理:每10分钟');
  console.log('   - 自动恢复:检测即响应');

  let scanCount = 0; // 扫描计数器

  selfGuardInterval = setInterval(() => {
    scanCount++;
    const now = bjDate();
    lastGuardCheck = now;

    try {
      // 1. 演化引擎守护
      if (!evolutionEngineRunning) {
        console.log('🛡️ [守护] 检测到演化引擎停止,尝试重启...');
        startEvolutionEngine();
        guardRestartAttempts++;
      }

      // 2. 红后监控守护
      if (!redQueenRunning) {
        console.log('🛡️ [守护] 检测到红后监控停止,尝试重启...');
        startRedQueenMonitoring();
        guardRestartAttempts++;
      }

      // 3. 内存泄漏检测
      const memUsage = process.memoryUsage();
      const heapUsedMB = memUsage.heapUsed / 1024 / 1024;
      const heapTotalMB = memUsage.heapTotal / 1024 / 1024;
      const memRatio = heapUsedMB / heapTotalMB;

      if (heapUsedMB > 1500) {
        console.log(`🛡️ [守护] ⚠️ 内存使用过高: ${heapUsedMB.toFixed(0)}MB (${(memRatio * 100).toFixed(1)}%)`);

        // 尝试垃圾回收(如果可用)
        if (global.gc) {
          console.log('🛡️ [守护] 尝试触发垃圾回收...');
          global.gc();
          const afterGC = process.memoryUsage().heapUsed / 1024 / 1024;
          console.log(`🛡️ [守护] GC后内存: ${afterGC.toFixed(0)}MB (释放 ${(heapUsedMB - afterGC).toFixed(0)}MB)`);
        }

        // 内存超过2000MB才重启(尧帝2.0扫描峰值约1.4GB,需留足余量)
        if (heapUsedMB > 2500) {
          console.log('🔴 [守护] 内存超过500MB,主动退出防止拖累系统...');
          logSelfGuardAction('memory_overflow', { heapUsedMB, memRatio });
          process.exit(1); // 让PM2或守护进程重启
        }
      }

      // 4. 事件循环阻塞检测
      const eventLoopDelay = now - (lastGuardCheck - 30000);
      if (eventLoopDelay > 35000) { // 预期30秒,超过35秒说明有阻塞
        console.log(`🛡️ [守护] ⚠️ 事件循环阻塞: ${eventLoopDelay}ms`);
      }

      // 5. 数据库连接检测
      try {
        db.prepare('SELECT 1').get();
      } catch (dbErr) {
        console.log('🛡️ [守护] ⚠️ 数据库连接异常:', dbErr.message);
        // 尝试重新初始化数据库连接
        try {
          db = new Database(DB_FILE);
          console.log('🛡️ [守护] ✅ 数据库连接已恢复');
        } catch (reconnectErr) {
          console.log('🔴 [守护] 数据库重连失败:', reconnectErr.message);
        }
      }

      // 6. 重启尝试次数检查
      if (guardRestartAttempts > MAX_GUARD_RESTARTS) {
        console.log('🔴 [守护] 重启尝试次数过多,记录并重置');
        logSelfGuardAction('too_many_restarts', { attempts: guardRestartAttempts });
        guardRestartAttempts = 0;
      }

      // 7. 系统健康分数检查
      if (systemHealthScore < 50) {
        console.log(`🛡️ [守护] ⚠️ 系统健康分数过低: ${systemHealthScore}`);
        // 触发完整系统扫描
        fullSystemScan().catch(e => console.log('守护扫描错误:', e.message));
      }

      // 8. 定期数据清理(每10分钟执行一次)
      if (scanCount % 20 === 0) { // 30秒 * 20 = 10分钟
        console.log('🛡️ [守护] 执行定期数据清理...');

        // 8.1 清理非活跃分支(保留最近1000条)
        try {
          const deleteResult = db.prepare(`
            DELETE FROM yaodi_branch
            WHERE active = 0
            AND id NOT IN (
              SELECT id FROM yaodi_branch WHERE active = 0 ORDER BY last_mutated DESC LIMIT 1000
            )
          `).run();
          if (deleteResult.changes > 0) {
            console.log(`🛡️ [守护] 清理 ${deleteResult.changes} 条非活跃分支`);
          }
        } catch (e) {
          console.log('🛡️ [守护] 分支清理失败:', e.message);
        }

        // 8.2 清理 bugHistory 数组(保留最近200条)
        if (bugHistory.length > 200) {
          const removed = bugHistory.length - 200;
          bugHistory = bugHistory.slice(-200);
          console.log(`🛡️ [守护] 清理 ${removed} 条BUG历史记录`);
        }

        // 8.3 清理过期黑天鹅事件
        const beforeClean = recentBlackSwans.length;
        recentBlackSwans = recentBlackSwans.filter(ev => !ev.expireAt || Date.now() < ev.expireAt);
        if (recentBlackSwans.length < beforeClean) {
          console.log(`🛡️ [守护] 清理 ${beforeClean - recentBlackSwans.length} 条过期黑天鹅事件`);
        }

        // 8.4 清理演化日志(保留最近7天)
        try {
          const logResult = db.prepare(`
            DELETE FROM evolution_logs
            WHERE timestamp < ?
          `).run(bjPast(7));
          if (logResult.changes > 0) {
            console.log(`🛡️ [守护] 清理 ${logResult.changes} 条过期演化日志`);
          }
        } catch (e) {}

        console.log(`🛡️ [守护] 清理完成 | 分支: ${db.prepare('SELECT COUNT(*) as c FROM yaodi_branch').get()?.c} | BUG历史: ${bugHistory.length} | 黑天鹅: ${recentBlackSwans.length}`);
      }

    } catch (e) {
      console.error('🛡️ [守护] 守护错误:', e.message);
    }
  }, 30000); // 每30秒检查一次

  console.log('✅ 自我守护已启动');
}

// 记录自我守护行为
function logSelfGuardAction(action, data) {
  try {
    const logEntry = {
      timestamp: Date.now(),
      action,
      ...data
    };

    // 写入日志文件
    const logPath = join(__dirname, '../logs/self_guard.log');
    const logDir = dirname(logPath);
    if (!fs.existsSync(logDir)) {
      fs.mkdirSync(logDir, { recursive: true });
    }
    fs.appendFileSync(logPath, JSON.stringify(logEntry) + '\n');
  } catch (e) {
    console.error('守护日志写入失败:', e.message);
  }
}

// 优雅退出处理
process.on('SIGTERM', () => {
  console.log('🛡️ [守护] 收到SIGTERM,准备优雅退出...');

  // 停止定时器
  if (evolutionInterval) clearInterval(evolutionInterval);
  if (redQueenInterval) clearInterval(redQueenInterval);
  if (selfGuardInterval) clearInterval(selfGuardInterval);

  // 保存状态
  console.log('🛡️ [守护] 保存系统状态...');

  // 关闭数据库
  try {
    db.close();
  } catch (e) {}

  console.log('🛡️ [守护] 优雅退出完成');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('🛡️ [守护] 收到SIGINT,准备优雅退出...');
  process.emit('SIGTERM');
});

// 未捕获异常处理
process.on('uncaughtException', (err) => {
  console.error('🔴 [守护] 未捕获异常:', err.message);
  console.error('   堆栈:', err.stack);

  logSelfGuardAction('uncaught_exception', {
    message: err.message,
    stack: err.stack
  });

  // 如果是严重错误,退出让PM2重启
  if (err.message.includes('ENOMEM') ||
      err.message.includes('EADDRINUSE') ||
      err.message.includes('database disk image is malformed')) {
    console.log('🔴 [守护] 严重错误,主动退出等待重启...');
    process.exit(1);
  }
});

// 未处理的Promise拒绝
process.on('unhandledRejection', (reason, promise) => {
  console.error('🔴 [守护] 未处理的Promise拒绝:', reason);

  logSelfGuardAction('unhandled_rejection', {
    reason: String(reason)
  });
});

// 快速健康检查(关键指标)- 红后级别全面BUG扫描
async function quickHealthCheck() {
  const issues = [];
  const now = bjDate();

  try {
    // ═══════════════════════════════════════════════════════════════
    // 1. 功能错误检查
    // ═══════════════════════════════════════════════════════════════

    // 1.1 API端点完整性检查(功能缺失)
    const criticalEndpoints = [
      '/api/health', '/api/stocks', '/api/indices', '/api/stats',
      '/api/pool/list', '/api/capital', '/api/selection/load', '/api/pool/prices', '/api/pool/realtime',
      '/api/blackswan/history', '/api/yaodi/status',
      // 【新增 2026-05-07】尧帝V2核心API - 红后白名单
      '/api/yaodi-v2/stats', '/api/yaodi-v2/status', '/api/yaodi-v2/l1-pool', '/api/yaodi-v2/l2-pool',
      '/api/risk/dynamic-position', '/api/evolution/status', '/api/redqueen/status', '/api/shundi/stats'
    ];
    for (const endpoint of criticalEndpoints) {
      try {
        await new Promise((resolve, reject) => {
          const req = http.request({
            hostname: 'localhost',
            port: PORT,  // 【BUGFIX 2026-05-07】使用实际运行端口8768
            path: endpoint,
            method: 'GET',
            timeout: 3000
          }, res => resolve(res.statusCode));
          req.on('error', reject);
          req.on('timeout', () => reject(new Error('超时')));
          req.end();
        });
      } catch (e) {
        issues.push({
          type: 'function_missing',
          category: '功能错误',
          severity: 'high',
          message: `API端点不可用: ${endpoint} - ${e.message}`,
          detectedAt: now
        });
      }
    }

    // 1.2 数据完整性检查(功能异常)
    try {
      const stockCount = db.prepare('SELECT COUNT(*) as count FROM stocks').get()?.count || 0;
      if (stockCount === 0) {
        issues.push({
          type: 'function_abnormal',
          category: '功能错误',
          severity: 'high',
          message: '股票数据库为空,数据加载功能异常',
          detectedAt: now
        });
      }

      // 检查关键表是否存在
      const requiredTables = ['stocks', 'yaodi_branch', 'yaodi_main', 'selection_snapshots', 'evolution_logs'];
      for (const table of requiredTables) {
        const exists = db.prepare(`SELECT name FROM sqlite_master WHERE type='table' AND name=?`).get(table);
        if (!exists) {
          issues.push({
            type: 'function_missing',
            category: '功能错误',
            severity: 'high',
            message: `数据库表缺失: ${table}`,
            detectedAt: now
          });
        }
      }
    } catch (e) {
      issues.push({
        type: 'function_abnormal',
        category: '功能错误',
        severity: 'high',
        message: `数据库功能异常: ${e.message}`,
        detectedAt: now
      });
    }

    // 1.3 边界条件检查
    try {
      // 检查数值字段是否有异常值(如负数价格、超大数值等)
      const abnormalStocks = db.prepare(`
        SELECT code, name, price FROM stocks
        WHERE price < 0 OR price > 10000 OR volume < 0
        LIMIT 5
      `).all();
      if (abnormalStocks.length > 0) {
        issues.push({
          type: 'boundary_error',
          category: '功能错误',
          severity: 'medium',
          message: `边界条件异常: ${abnormalStocks.length} 只股票数据异常`,
          details: abnormalStocks.map(s => s.code).join(','),
          detectedAt: now
        });
      }
    } catch (e) {}

    // ═══════════════════════════════════════════════════════════════
    // 2. 性能问题检查
    // ═══════════════════════════════════════════════════════════════

    // 2.1 API响应时间检查(响应迟缓)
    const apiStart = Date.now();
    try {
      await new Promise((resolve, reject) => {
        const req = http.request({
          hostname: 'localhost',
          port: PORT,  // 【BUGFIX 2026-05-07】使用实际运行端口8768
          path: '/api/health',
          method: 'GET',
          timeout: 5000
        }, res => resolve());
        req.on('error', reject);
        req.on('timeout', () => reject(new Error('API超时')));
        req.end();
      });
      const apiLatency = Date.now() - apiStart;
      if (apiLatency > 1000) {
        issues.push({
          type: 'performance_slow',
          category: '性能问题',
          severity: apiLatency > 5000 ? 'high' : 'medium',
          message: `API响应迟缓: ${apiLatency}ms`,
          detectedAt: now
        });
      }
    } catch (e) {
      issues.push({
        type: 'function_missing',
        category: '功能错误',
        severity: 'high',
        message: `API不可用: ${e.message}`,
        detectedAt: now
      });
    }

    // 2.2 资源消耗检查(内存、CPU)
    const memUsage = process.memoryUsage();
    const memPercent = memUsage.heapUsed / memUsage.heapTotal * 100;
    if (memPercent > 85) {
      issues.push({
        type: 'performance_resource',
        category: '性能问题',
        severity: memPercent > 95 ? 'high' : 'medium',
        message: `内存消耗过大: ${memPercent.toFixed(1)}% (${(memUsage.heapUsed / 1024 / 1024).toFixed(0)}MB)`,
        detectedAt: now
      });
    }

    // 2.3 并发性能检查(通过演化引擎状态判断)
    if (evolutionEngineRunning) {
      try {
        const main = db.prepare('SELECT * FROM yaodi_main LIMIT 1').get();
        if (main && main.evolution_count > 0) {
          const evolutionRate = main.evolution_count / ((Date.now() - (main.last_evolution ? new Date(main.last_evolution).getTime() : Date.now())) / 60000);
          if (evolutionRate < 0.5) { // 每分钟演化次数过低
            issues.push({
              type: 'performance_concurrency',
              category: '性能问题',
              severity: 'medium',
              message: `演化引擎性能下降: 每分钟 ${evolutionRate.toFixed(2)} 次`,
              detectedAt: now
            });
          }
        }
      } catch (e) {}
    }

    // ═══════════════════════════════════════════════════════════════
    // 3. 兼容性问题检查
    // ═══════════════════════════════════════════════════════════════

    // 3.1 Node.js版本兼容性
    const nodeVersion = process.version;
    const nodeMajor = parseInt(nodeVersion.replace('v', '').split('.')[0]);
    if (nodeMajor < 18) {
      issues.push({
        type: 'compatibility_os',
        category: '兼容性问题',
        severity: 'high',
        message: `Node.js版本过低: ${nodeVersion},建议 >= v18`,
        detectedAt: now
      });
    }

    // 3.2 依赖包兼容性检查(只检查实际使用的依赖)
    try {
      const packageJson = JSON.parse(fs.readFileSync(join(__dirname, '../package.json'), 'utf-8'));
      const deps = { ...packageJson.dependencies, ...packageJson.devDependencies };
      const criticalDeps = ['better-sqlite3']; // 只检查实际使用的依赖
      for (const dep of criticalDeps) {
        if (!deps[dep]) {
          issues.push({
            type: 'compatibility_dependency',
            category: '兼容性问题',
            severity: 'high',
            message: `关键依赖缺失: ${dep}`,
            detectedAt: now
          });
        }
      }
    } catch (e) {}

    // 3.3 数据库文件兼容性
    try {
      const dbPath = DB_FILE;
      const dbStats = fs.statSync(dbPath);
      if (dbStats.size === 0) {
        issues.push({
          type: 'compatibility_data',
          category: '兼容性问题',
          severity: 'high',
          message: '数据库文件为空,可能损坏',
          detectedAt: now
        });
      }
    } catch (e) {
      issues.push({
        type: 'compatibility_data',
        category: '兼容性问题',
        severity: 'high',
        message: `数据库文件访问失败: ${e.message}`,
        detectedAt: now
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // 4. 安全漏洞检查
    // ═══════════════════════════════════════════════════════════════

    // 4.1 敏感数据泄露检查
    try {
      const envFiles = ['.env', '.env.local', '.env.production'];
      for (const envFile of envFiles) {
        const envPath = join(__dirname, '..', envFile);
        if (fs.existsSync(envPath)) {
          const envContent = fs.readFileSync(envPath, 'utf-8');
          if (/password|secret|token|api_key/i.test(envContent) && !/^\s*#/.test(envContent)) {
            issues.push({
              type: 'security_leak',
              category: '安全漏洞',
              severity: 'high',
              message: `敏感配置可能泄露: ${envFile} 包含明文密钥`,
              detectedAt: now
            });
          }
        }
      }
    } catch (e) {}

    // 4.2 SQL注入风险检查(仅记录,不作为高危问题)
    // 注意:db.prepare()使用的是参数化查询,是安全的
    // 这里只作为信息记录,不加入issues数组

    // 4.3 权限检查(API是否有适当的访问控制)
    try {
      // 检查是否有未保护的敏感API
      const sensitiveEndpoints = ['/api/yaodi/evolve', '/api/admin'];
      for (const endpoint of sensitiveEndpoints) {
        // 这里只是标记,实际权限检查需要在路由中实现
      }
    } catch (e) {}

    // ═══════════════════════════════════════════════════════════════
    // 5. 安装与部署问题检查
    // ═══════════════════════════════════════════════════════════════

    // 5.1 关键文件存在性检查(只检查服务器端文件)
    const criticalFiles = [
      'data_server.js',
      '../package.json',
      '../database/stocks.db'
    ];
    for (const file of criticalFiles) {
      const filePath = join(__dirname, file);
      if (!fs.existsSync(filePath)) {
        issues.push({
          type: 'deploy_missing',
          category: '安装部署',
          severity: 'high',
          message: `关键文件缺失: ${file}`,
          detectedAt: now
        });
      }
    }

    // 5.2 配置完整性检查
    try {
      const config = db.prepare('SELECT * FROM yaodi_main LIMIT 1').get();
      if (!config) {
        issues.push({
          type: 'deploy_config',
          category: '安装部署',
          severity: 'high',
          message: '尧帝主配置缺失,系统未正确初始化',
          detectedAt: now
        });
      }
    } catch (e) {}

    // 5.3 端口占用检查
    try {
      const portCheck = execSync('lsof -i :8767 2>/dev/null | grep LISTEN | wc -l').toString().trim();
      if (parseInt(portCheck) > 1) {
        issues.push({
          type: 'deploy_port',
          category: '安装部署',
          severity: 'medium',
          message: '端口8767可能被多个进程占用',
          detectedAt: now
        });
      }
    } catch (e) {}

    // ═══════════════════════════════════════════════════════════════
    // 6. 界面交互问题检查
    // ═══════════════════════════════════════════════════════════════

    // 6.1 前端API调用匹配检查
    const frontendApiCalls = [
      '/api/stocks', '/api/indices', '/api/stats', '/api/pool/list',
      '/api/selection/load', '/api/blackswan/history'
    ];
    // 这些API在后端应该都有对应的路由,已在前面检查

    // 6.2 错误提示清晰度检查(检查日志中是否有难以理解的错误)
    const logFile = '/tmp/fqm_server.log';
    if (fs.existsSync(logFile)) {
      const logs = fs.readFileSync(logFile, 'utf-8').split('\n').slice(-100);
      for (const log of logs) {
        // 检查是否有仅显示错误代码而无解释的情况
        if (/Error:\s*\d{3,5}\s*$/.test(log) || /ECONNREFUSED|ETIMEDOUT|ENOTFOUND/.test(log)) {
          issues.push({
            type: 'ui_unclear',
            category: '界面交互',
            severity: 'low',
            message: `错误提示不清晰: ${log.substring(0, 100)}`,
            detectedAt: now
          });
          break;
        }
        // 检查运行时错误
        if (/TypeError|ReferenceError|SyntaxError/.test(log)) {
          issues.push({
            type: 'runtime_error',
            category: '功能错误',
            severity: 'high',
            message: `运行时错误: ${log.substring(0, 200)}`,
            detectedAt: now
          });
          break;
        }
      }
    }

    // 6.3 演化引擎状态检查
    if (!evolutionEngineRunning) {
      issues.push({
        type: 'function_abnormal',
        category: '功能错误',
        severity: 'medium',
        message: '演化引擎已停止运行',
        detectedAt: now
      });
    }

    // 检查红后监控状态
    if (!redQueenRunning) {
      issues.push({
        type: 'function_abnormal',
        category: '功能错误',
        severity: 'medium',
        message: '红后BUG监控已停止',
        detectedAt: now
      });
    }

  } catch (e) {
    issues.push({
      type: 'scan_error',
      category: '系统错误',
      severity: 'low',
      message: `健康检查扫描错误: ${e.message}`,
      detectedAt: now
    });
  }

  return { issues, timestamp: now };
}

