// 立即修复(高危BUG)
async function immediateFix(bug) {
  console.log(`🔧 [红后] 立即修复: ${bug.type} - ${bug.message?.substring(0, 50)}`);
  const startTime = Date.now();

  try {
    let fixed = false;
    let action = '';

    switch (bug.type) {
      case 'api_unavailable':
        // 尝试重启服务
        action = 'service_restart';
        console.log('   → 尝试重启服务...');
        // 这里不能真的重启,但可以记录并通知
        fixed = false; // 需要人工介入
        break;

      case 'memory_high':
        // 触发垃圾回收
        action = 'gc';
        if (global.gc) {
          global.gc();
          fixed = true;
        }
        break;

      case 'database_error':
        // 尝试重新连接
        action = 'db_reconnect';
        try {
          db.prepare('SELECT 1').get();
          fixed = true;
        } catch (e) {
          fixed = false;
        }
        break;

      case 'runtime_error':
        // 记录并创建修复分支
        action = 'create_fix_branch';
        const branchName = `URGENT_FIX_${bug.type}_${Date.now()}`;
        try {
          db.prepare(`
            INSERT INTO yaodi_branch (name, strategy, accuracy, created_at, mutation_history)
            VALUES (?, ?, ?, ?, ?)
          `).run(branchName, 'urgent_fix', 50, bjNow(), JSON.stringify({
            targetBug: bug,
            status: 'urgent',
            createdAt: bjISO()
          }));
          fixed = true;
        } catch (e) {}
        break;

      default:
        action = 'log_only';
        fixed = false;
    }

    const duration = Date.now() - startTime;

    // 记录修复结果
    try {
      db.prepare(`
        INSERT INTO evolution_logs (event_type, message, details, timestamp)
        VALUES (?, ?, ?, ?)
      `).run('red_queen_fix', action, JSON.stringify({
        bug: bug.message?.substring(0, 200),
        fixed,
        duration,
        severity: bug.severity
      }), bjISO());
    } catch (e) {}

    // 【新增】记录到代码修改历史
    if (fixed) {
      autonomyController.recordModification({
        type: bug.type,
        description: `[红后自动修复] ${bug.message || bug.type}`,
        severity: bug.severity === 'high' ? 'P1_HIGH' : 'P2_MEDIUM',
        file: 'data_server.js',
        action,
        autoFix: true
      });
    }

    console.log(`   ✓ 修复${fixed ? '成功' : '失败'} (${duration}ms)`);
    return { fixed, action, duration };

  } catch (e) {
    console.error('   ✗ 修复错误:', e.message);
    return { fixed: false, error: e.message };
  }
}

// 队列修复(中危BUG) - 已禁用自动修复
async function queuedFix(bug) {
  console.log(`🔧 [红后] 队列修复已禁用: ${bug.type}`);
  return { fixed: false, reason: 'auto-fix disabled' };
}

// BUG模式学习
async function learnBugPatterns(issues) {
  if (issues.length === 0) return;

  try {
    // 统计BUG类型分布
    const typeCount = {};
    issues.forEach(b => {
      const key = b.type || 'unknown';
      typeCount[key] = (typeCount[key] || 0) + 1;
    });

    // 统计严重性分布
    const severityCount = { high: 0, medium: 0, low: 0 };
    issues.forEach(b => {
      severityCount[b.severity] = (severityCount[b.severity] || 0) + 1;
    });

    // 计算系统稳定性趋势
    const recentBugs = bugHistory.slice(-100);
    const avgBugsPerScan = recentBugs.length / Math.max(1, Math.floor(recentBugs.length / 10));

    // 保存学习结果
    db.prepare(`
      INSERT INTO evolution_logs (event_type, message, details, timestamp)
      VALUES (?, ?, ?, ?)
    `).run('bug_learning', 'pattern_analysis', JSON.stringify({
      typeDistribution: typeCount,
      severityDistribution: severityCount,
      avgBugsPerScan: avgBugsPerScan.toFixed(2),
      systemHealthScore,
      totalIssues: issues.length
    }), bjISO());

    console.log(`🧠 [红后] BUG模式学习: ${Object.keys(typeCount).length} 种类型, 平均每扫描 ${avgBugsPerScan.toFixed(1)} 个BUG`);

  } catch (e) {
    console.error('🧠 [红后] 学习错误:', e.message);
  }
}

// 停止演化引擎
function stopEvolutionEngine() {
  if (evolutionInterval) {
    clearInterval(evolutionInterval);
    evolutionInterval = null;
  }
  evolutionEngineRunning = false;
  console.log('⏹️ 演化引擎已停止');
}

