        const shares = data.shares || data.quantity || 0;
        const profit = (data.current_price || price) - price;
        const profitPct = price > 0 ? (profit / price * 100) : 0;
        db.prepare(`INSERT OR REPLACE INTO mock_holdings
          (code, name, shares, avg_cost, current_price, market_value, profit, profit_percent, update_time, pnl)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0)`).run(
          data.code, data.name, shares, price, data.current_price || price, (data.current_price || price) * shares, profit, profitPct, bjNow()
        );
