      req.on('data', chunk => body += chunk);
      req.on('end', () => {
        const data = JSON.parse(body);
        const codes = Array.isArray(data.codes) ? data.codes : (data.code ? [data.code] : []);
        if (codes.length === 0) { res.end(JSON.stringify({ success: false, error: 'no code' })); return; }
        const placeholders = codes.map(() => '?').join(',');
        db.prepare(`UPDATE user_stock_pool SET user_deleted=1 WHERE code IN (${placeholders})`).run(...codes);
        db.prepare(`DELETE FROM favorites WHERE code IN (${placeholders})`).run(...codes);
        res.end(JSON.stringify({ success: true, removed: codes.length }));
      });
