    let recentReward = { avg: 0 };

    try {
      // 实际表名是 learning_history(q_learning 表不存在)
      const stateCount = db.prepare("SELECT COUNT(DISTINCT state) as total FROM learning_history").get() || { total: 0 };
      const recentCount = db.prepare("SELECT COUNT(*) as c FROM learning_history WHERE timestamp > ?").get(bjPast(1)) || { c: 0 };
      const recentAvg = db.prepare("SELECT AVG(reward) as avg FROM learning_history WHERE timestamp > ?").get(bjPast(1)) || { avg: 0 };
      qStats = { total: stateCount.total };
      recentTrades = { c: recentCount.c };
      recentReward = { avg: recentAvg.avg || 0 };
    } catch(e) {
      // 表不存在,使用默认值
    }

