// 辅助函数:计算平均值
function avg(arr) {
  if (!arr || arr.length === 0) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

// 辅助函数:计算简单技术特征
function computeSimpleFeatures(ohlcv) {
  const { open, high, low, close, volume } = ohlcv;
  const len = close.length;

  return {
    // 移动平均
    MA5: avg(close.slice(-5)),
    MA10: avg(close.slice(-10)),
    MA20: avg(close.slice(-20)),

    // 价格位置
    PriceVsMA5: (close[len-1] - avg(close.slice(-5))) / avg(close.slice(-5)) * 100,
    PriceVsMA20: (close[len-1] - avg(close.slice(-20))) / avg(close.slice(-20)) * 100,

    // 波动率
    Volatility5: Math.sqrt(close.slice(-5).reduce((s, c, i, a) => s + (i > 0 ? Math.pow(c/a[i-1] - 1, 2) : 0), 0) / 4) * 100,
    Volatility20: Math.sqrt(close.slice(-20).reduce((s, c, i, a) => s + (i > 0 ? Math.pow(c/a[i-1] - 1, 2) : 0), 0) / 19) * 100,

    // 成交量
    VolumeRatio: avg(volume.slice(-5)) / avg(volume.slice(-20)),

    // 振幅
    Range5: (Math.max(...high.slice(-5)) - Math.min(...low.slice(-5))) / avg(close.slice(-5)) * 100,

    // 动量
    Momentum5: (close[len-1] - close[len-6]) / close[len-6] * 100,
    Momentum10: (close[len-1] - close[len-11]) / close[len-11] * 100,

    // 最近收盘价
    LastClose: close[len-1]
  };
}

