// 红后自主运行引擎
// ═══════════════════════════════════════════════════════════════
let redqueenRunning = false;
let redqueenDecisions = [];
let redqueenTimer = null;
const redqueenLogs = [];

function addRedQueenLog(message, type = 'system') {
  redqueenLogs.unshift({ time: bjISO(), message, type });
  if (redqueenLogs.length > 100) redqueenLogs.pop();
}

function makeAutonomousDecision() {
  // 【P0修复】舜帝自主决策:从 shundi_mock_holdings 读持仓,读 yaodi_config 取阈值
  addRedQueenLog(`[红后] makeAutonomousDecision 触发,舜帝=${shundiRunning} 红后=${redqueenRunning}`, "system");
  const holdings = db.prepare("SELECT * FROM shundi_mock_holdings").all();
  const signals = db.prepare("SELECT * FROM trade_signals WHERE expires_at > ? ORDER BY confidence DESC LIMIT 5").all(bjNow());
  const decisions = [];
  // 【P1修复】从 yaodi_config 读取止盈止损阈值,替代硬编码
  const rqStopPct = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='default_stop_loss_pct'").get()?.value || '3.0');
  const rqTakePct = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='default_take_profit_ratio'").get()?.value || '1.03');
  const rqStopPctNeg = -Math.max(rqStopPct * 2, 5);  // 默认 -6%(2倍配置)
  const rqTakePctPos = parseFloat((rqTakePct - 1) * 100).toFixed(1);  // 1.05 -> 5.0%
  holdings.forEach(h => {
    if (!canSellByT1(h.buy_date)) return; // T+1限制:当日买入不可自动止损/止盈
    if (h.profit_percent <= rqStopPctNeg) decisions.push({ type: 'stop_loss', priority: 10, code: h.code, name: h.name, reason: '止损', action: 'sell' });
    else if (h.profit_percent >= rqTakePctPos) decisions.push({ type: 'take_profit', priority: 8, code: h.code, name: h.name, reason: '止盈', action: 'sell' });
  });
  if (signals.length > 0) decisions.push({ type: 'buy', priority: 7, code: signals[0].code, reason: signals[0].reason, action: 'buy' });

  // 持久化决策到数据库
  if (decisions.length > 0) {
    try {
      const timestamp = bjISO();
      decisions.forEach(d => {
        db.prepare(`
          INSERT INTO trading_decisions (timestamp, type, priority, code, reason, action, status)
          VALUES (?, ?, ?, ?, ?, ?, 'pending')
        `).run(timestamp, d.type, d.priority || 0, d.code || '', d.reason || '', d.action || '');
      });
    } catch (e) {
      // 表不存在时忽略
    }
  }

  return { timestamp: bjISO(), decisions };
}

// 红后自主运行周期(每30秒执行一次)
async function redqueenAutoCycle() {
  if (!redqueenRunning) return;
  try {
    // 【P0修复 2026-04-28】非交易时段硬拦截:红后在A股交易时段之外禁止交易执行
    // 根因:凌晨2点红后仍在执行止损/加仓,makeAutonomousDecision()无交易时段检查
    if (!isTradingHours()) {
      console.log('[红后周期] 非交易时段,跳过交易决策');
      return;
    }
    console.log('[红后周期] 运行');
    // ── 执行红后自主决策(止损止盈+信号买入)─────────────
    try { makeAutonomousDecision(); } catch(madErr) { console.error('[红后] makeAutonomousDecision异常:', madErr.message); }
    // ── 同步红后运行引擎状态到 YaodiBrain.systemModules ─────────────
    YaodiBrain.systemModules.redqueenEngine.status    = 'online';
    YaodiBrain.systemModules.redqueenEngine.health    = 100;
    YaodiBrain.systemModules.redqueenEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.yaodiAgent.status    = yaodiEvolutionRunning ? 'online' : 'standby';
    YaodiBrain.systemModules.yaodiAgent.health    = yaodiEvolutionRunning ? 100 : 50;
    YaodiBrain.systemModules.yaodiAgent.lastCheck = bjISO();

    YaodiBrain.systemModules.shundiEngine.status    = shundiRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.shundiEngine.health    = shundiRunning ? 100 : 0;
    YaodiBrain.systemModules.shundiEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.evolutionEngine.status    = evolutionInterval !== null ? 'online' : 'standby';
    YaodiBrain.systemModules.evolutionEngine.health    = evolutionInterval !== null ? 100 : 50;
    YaodiBrain.systemModules.evolutionEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.stopLossMonitor.status    = stopLossMonitorRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.stopLossMonitor.health    = stopLossMonitorRunning ? 100 : 0;
    YaodiBrain.systemModules.stopLossMonitor.lastCheck = bjISO();

    YaodiBrain.systemModules.watchdog.status    = watchdogInterval !== null ? 'online' : 'offline';
    YaodiBrain.systemModules.watchdog.health    = watchdogInterval !== null ? 100 : 0;
    YaodiBrain.systemModules.watchdog.lastCheck = bjISO();

    YaodiBrain.systemModules.dataServer.status    = 'online';
    YaodiBrain.systemModules.dataServer.health    = 100;
    YaodiBrain.systemModules.dataServer.lastCheck = bjISO();

    YaodiBrain.systemModules.database.status    = 'online';
    YaodiBrain.systemModules.database.health    = 100;
    YaodiBrain.systemModules.database.lastCheck = bjISO();

    YaodiBrain.systemModules.frontend.status    = 'online';
    YaodiBrain.systemModules.frontend.health    = 100;
    YaodiBrain.systemModules.frontend.lastCheck = bjISO();

    YaodiBrain.systemModules.dataSource.status    = 'online';
    YaodiBrain.systemModules.dataSource.health    = 100;
    YaodiBrain.systemModules.dataSource.lastCheck = bjISO();

    YaodiBrain.systemModules.learningSystem.status    = 'online';
    YaodiBrain.systemModules.learningSystem.health    = 100;
    YaodiBrain.systemModules.learningSystem.lastCheck = bjISO();

    YaodiBrain.systemModules.branchManager.status    = 'online';
    YaodiBrain.systemModules.branchManager.health    = 100;
    YaodiBrain.systemModules.branchManager.lastCheck = bjISO();

    // 1. 刷新持仓市值(主账户+舜帝模拟盘)
    refreshHoldingsValue();
    refreshShundiHoldingsValue();  // 新增:刷新舜帝持仓市值
    refreshStockPoolPrices();       // 新增:刷新收藏股实时价格
        // 2. 读取资金配置
    const capital = db.prepare("SELECT * FROM shundi_capital_config WHERE id = 1").get() || { total_capital: 1000000 };
    const holdings = db.prepare("SELECT * FROM shundi_mock_holdings ORDER BY profit_percent ASC").all();
    const totalPos = holdings.reduce((s, h) => s + (h.market_value || 0), 0);
    const available = capital.total_capital - totalPos;

    const posRatio = totalPos / capital.total_capital * 100;

    // 3. Q-Learning 学习【P0重写:让hold状态也能学习真实盈亏】
    const marketStats = db.prepare("SELECT * FROM market_stats ORDER BY id DESC LIMIT 1").get();
    const upRatio = marketStats ? (marketStats.up_count || 0) / Math.max(marketStats.total_count || 1, 1) : 0.5;
    const sentiment = (db.prepare("SELECT fear_greed_index FROM sentiment_index ORDER BY id DESC LIMIT 1").get()?.fear_greed_index || 50) / 100 - 0.5;
    // 3. Q-Learning 学习(try-catch保护,避免阻塞决策)
    try {
    const state = encodeState({ upRatio }, totalPos / capital.total_capital, sentiment);
    const action = qLearnSelectAction(state);
    const shundiHolding = db.prepare("SELECT * FROM shundi_mock_holdings ORDER BY rowid DESC LIMIT 1").get();
    const shundiProfit = shundiHolding ? parseFloat(shundiHolding.profit_percent || 0) : 0;
    let reward = shundiProfit / 5;
    reward += upRatio > 0.55 ? 0.2 : upRatio > 0.48 ? 0.05 : -0.15;
    reward += posRatio > 20 && posRatio < 80 ? 0.1 : -0.05;
    const shundiStats = db.prepare("SELECT COUNT(*) as cnt, SUM(CASE WHEN profit>0 THEN 1 ELSE 0 END) as wins FROM shundi_backtest_history WHERE trade_type='sell'").get();
    if (shundiStats && shundiStats.cnt > 0) {
      reward += (shundiStats.wins / shundiStats.cnt) > 0.5 ? 0.1 : -0.1;
    }
    qLearnUpdate(state, action, reward, state);
    } catch(qlErr) { console.error('[Q-Learning] 错误:', qlErr.message); }

    // 4. 读取交易信号
    const signals = db.prepare("SELECT * FROM trade_signals WHERE expires_at > ? ORDER BY confidence DESC LIMIT 100").all(bjNow());  // 【优化】读取更多信号
    const decisions = [];
    const _cfgStopPct = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='default_stop_loss_pct'").get()?.value || '3.0');
    const _cfgTakePct = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='default_take_profit_ratio'").get()?.value || '1.03');
    const stopLossT = capital.risk_level === 'aggressive' ? -(_cfgStopPct * 2) : capital.risk_level === 'conservative' ? -_cfgStopPct : -(_cfgStopPct * 1.4);
    const takeProfitT = capital.risk_level === 'aggressive' ? (_cfgTakePct - 1) * 100 * 2 : capital.risk_level === 'conservative' ? (_cfgTakePct - 1) * 100 : (_cfgTakePct - 1) * 100 * 1.4;
    const analysisTime = toBeijingTime();
    const nextCheckTime = new Date(analysisTime.getTime() + 30000); // 30秒后再次检查
    const formatTime = (d) => d.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

    holdings.forEach(h => {
      const sig = signals.find(s => s.code === h.code);
      const pct = parseFloat(h.profit_percent || 0);
      const atr = calculateATR(h.code);

      // 【新增2026-04-25】计算持仓天数:从首次买入日算起
      const firstBuy = db.prepare(
        "SELECT created_at FROM shundi_mock_trades WHERE code=? AND (type='buy' OR type='尧帝信号执行') ORDER BY created_at ASC LIMIT 1"
      ).get(h.code);
      const holdDays = firstBuy
        ? Math.floor((Date.now() - new Date(firstBuy.created_at).getTime()) / 86400000)
        : 0;

      // 【新增2026-04-25】峰值价格:取持仓期间最高价
      const peakRow = db.prepare(
        "SELECT MAX(high) as peak FROM stock_history WHERE code=? ORDER BY date DESC LIMIT 60"
      ).get(h.code);
      const peakPrice = Math.max(h.current_price, peakRow?.peak || h.current_price);

      // ATR动态止损/止盈(传入持仓天数和峰值价用于跟踪止损)
      const stopLossPrice = atrStopLoss(h.code, h.avg_cost, 'long', {
        atr, currentPrice: h.current_price, peakPrice, holdDays
      });
      const takeProfitPrice = atrTakeProfit(h.code, h.avg_cost, 'long', {
        atr, currentPrice: h.current_price
      });

      // 基础决策对象(含时效性字段和止损/目标价)
      const dec = {
        code: h.code,
        name: h.name,
        shares: h.shares,
        avgCost: h.avg_cost,
        currentPrice: h.current_price,
        profitPct: pct,
        profit: h.profit,
        signal: sig?.signal,
        confidence: sig?.confidence,
        reason: sig?.reason || '',
        actions: [],
        priority: 0,
        yaodi_branch_id: h.yaodi_branch_id || null,
        // 时效性字段
        last_analysis_time: formatTime(analysisTime),
        signal_expiry_hours: 24, // 默认24小时有效
        next_check_time: formatTime(nextCheckTime),
        analysis_timestamp: bjISO(analysisTime),
        // 风控价格字段
        stopLossPrice: Math.round(stopLossPrice * 100) / 100,  // 止损价(保留2位小数)
        takeProfitPrice: Math.round(takeProfitPrice * 100) / 100,  // 目标价(保留2位小数)
        targetPrice: sig?.target_price || Math.round(takeProfitPrice * 100) / 100,  // 策略目标价或止盈价
        potentialGain: Math.round((takeProfitPrice / h.current_price - 1) * 1000) / 10,  // 潜在收益%
        potentialLoss: Math.round((stopLossPrice / h.current_price - 1) * 1000) / 10  // 潜在亏损%
      };
      // 止损触发:当前价低于ATR止损价
      if (h.current_price <= stopLossPrice) {
        dec.actions.push({
          type: '止损',
          direction: '卖出',
          amount: h.market_value,
          shares: h.shares,
          stopPrice: Math.round(h.current_price * 0.995 * 100) / 100,  // 建议卖出价(低于现价0.5%)
          reason: `当前价¥${h.current_price}跌破ATR止损价¥${stopLossPrice.toFixed(2)}(${ATR_CONFIG.STOP_MULTIPLIER}倍ATR=${(atr*ATR_CONFIG.STOP_MULTIPLIER).toFixed(2)}),建议立即卖出`,
          urgent: true
        });
        dec.priority = 100 + Math.abs(pct);
        dec.signal_expiry_hours = 1; // 止损信号1小时有效
        addRedQueenLog(`🔴 止损: ${h.name} 跌破ATR止损价¥${stopLossPrice.toFixed(2)}`, 'warning');
      } else if (h.current_price >= takeProfitPrice) {  // 止盈触发:当前价高于ATR止盈价
        if (capital.risk_level === 'aggressive') {
          const half = Math.floor(h.shares / 2);
          dec.actions.push({
            type: '部分止盈',
            direction: '卖出',
            amount: h.current_price * half,
            shares: half,
            targetPrice: Math.round(h.current_price * 1.005 * 100) / 100,  // 建议卖出价
            reason: `当前价¥${h.current_price}达到ATR止盈价¥${takeProfitPrice.toFixed(2)}(${ATR_CONFIG.PROFIT_MULTIPLIER}倍ATR=${(atr*ATR_CONFIG.PROFIT_MULTIPLIER).toFixed(2)}),减半仓锁利`,
            urgent: false
          });
          dec.actions.push({ type: '持有', direction: '持有', reason: `剩余${h.shares - half}股等待更高目标`, urgent: false });
        } else {
          dec.actions.push({
            type: '止盈',
            direction: '卖出',
            amount: h.market_value,
            shares: h.shares,
            targetPrice: Math.round(h.current_price * 1.005 * 100) / 100,  // 建议卖出价
            reason: `当前价¥${h.current_price}达到ATR止盈价¥${takeProfitPrice.toFixed(2)}(${ATR_CONFIG.PROFIT_MULTIPLIER}倍ATR=${(atr*ATR_CONFIG.PROFIT_MULTIPLIER).toFixed(2)}),建议卖出`,
            urgent: false
          });
        }
        dec.priority = 80 + pct;
        dec.signal_expiry_hours = 4; // 止盈信号4小时有效
        addRedQueenLog(`🎯 止盈: ${h.name} 达到ATR止盈价¥${takeProfitPrice.toFixed(2)}`, 'decision');
      } else if (sig && sig.signal === 'buy' && sig.confidence >= 90 && posRatio < 75 && available > 500) {
        // 【仓位优化v3】加仓也受集中度限制:加仓后单只不超过总资产20%
        const maxBySingle = Math.floor((h.market_value + available * 0.5) < netValue * 0.2 ? available * 0.5 : Math.max(0, netValue * 0.2 - h.market_value));
        const maxAdd = Math.min(sig.target_price * 100, maxBySingle, capital.max_single_position * 0.3);
        const addShares = Math.floor(maxAdd / sig.target_price / 100) * 100;
        if (addShares > 0) {
          dec.actions.push({
            type: '加仓',
            direction: '买入',
            amount: addShares * sig.target_price,
            shares: addShares,
            targetPrice: Math.round(sig.target_price * 100) / 100,  // 目标买入价
            stopPrice: Math.round(sig.target_price * 0.95 * 100) / 100,  // 加仓止损价(-5%)
            reason: `信号强度${sig.confidence}%,建议加仓${addShares}股,止损价¥${(sig.target_price * 0.95).toFixed(2)}`,
            urgent: false
          });
          dec.priority = sig.confidence;
          dec.signal_expiry_hours = 12; // 加仓信号12小时有效
          addRedQueenLog(`📈 加仓: ${h.name} 置信度${sig.confidence}%`, 'decision');
        } else {
          dec.actions.push({ type: '持有', direction: '持有', reason: `盈亏${pct.toFixed(1)}%,资金不足加仓`, urgent: false });
          dec.priority = 1;
        }
      } else {
        dec.actions.push({
          type: '持有',
          direction: '持有',
          reason: pct >= 0 ? `盈利${pct.toFixed(1)}%,继续持有,目标¥${takeProfitPrice.toFixed(2)}` : `亏损${pct.toFixed(1)}%,等待反弹,止损线¥${stopLossPrice.toFixed(2)}`,
          urgent: false
        });
        dec.priority = 1;
      }
      decisions.push(dec);
    });
    // 6. 新标的推荐(舜帝资金驱动)
    const shundiCap = db.prepare("SELECT * FROM shundi_capital_config WHERE id=1").get() || { total_capital: 1000000, max_single_position: 200000, risk_level: 'moderate' };
    const shundiHoldings = db.prepare("SELECT * FROM shundi_mock_holdings").all();
    const shundiTotalPos = shundiHoldings.reduce((s,h) => s + (h.market_value || 0), 0);
    const shundiAvailable = shundiCap.total_capital - shundiTotalPos;
    const shundiPosRatio = shundiTotalPos / shundiCap.total_capital * 100;
    const shundiHeldCodes = shundiHoldings.map(h => h.code);
    // 【仓位优化v3】集中度风险控制
    const MAX_TOTAL_RATIO = 75;        // 总仓位上限75%(原90%过高)
    const MAX_SINGLE_RATIO = 20;       // 单只持仓占比上限20%(防集中度过高)
    const MAX_HOLDINGS = 20;           // 最大持仓数量
    const _cfgRiskPct = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='risk_per_stock_pct'").get()?.value || '10');
    const riskPerStock = shundiCap.risk_level === 'aggressive' ? _cfgRiskPct * 1.5 : shundiCap.risk_level === 'conservative' ? _cfgRiskPct * 0.8 : _cfgRiskPct;
    const perStockBudget = Math.floor(shundiCap.total_capital * riskPerStock / 100 / 100) * 100;
    // 【仓位优化v3】舜帝独立选股:信号+仓位双重过滤
    const newSigs = signals.filter(s => {
      if (shundiHeldCodes.includes(s.code)) return false;
      if (shundiPosRatio >= MAX_TOTAL_RATIO) return false;     // 总仓位达到上限,不再新开仓
      if (shundiHoldings.length >= MAX_HOLDINGS) return false;   // 持仓数达到上限
      // 【优化 2026-05-07】信号强度过滤:尧帝标签60%起步,舜帝扫描70%起步
      if (s.signal === 'buy' && s.confidence >= 60 && s._src === 'yaodi_tag') return true;
      if (s.signal === 'potential_buy' && s.confidence >= 70 && s._src === 'shundi_scan') return true;
      return false;
    }).slice(0, 5);
    // 先算每只新标的的可买股数
    const newSigDetails = newSigs.map(s => {
      // 【仓位优化v3】单只预算受限于:可用资金70%、单仓上限、总资产20%(集中度控制)
      const maxByTotal = Math.floor(shundiCap.total_capital * MAX_SINGLE_RATIO / 100 / 100) * 100;
      const budgetForStock = Math.min(shundiAvailable * 0.7, shundiCap.max_single_position, maxByTotal);
      const maxShares = Math.floor(budgetForStock / s.target_price / 100) * 100;
      // 【P0修复2026-05-06】提高置信度阈值: 70%→80%, 减少低质量信号
      const confBonus = s.confidence >= 80 ? 1.5 : s.confidence >= 75 ? 1.3 : s.confidence >= 70 ? 1.15 : 1.0;
      const buyShares = Math.floor(maxShares * confBonus / 100) * 100;
      return { sig: s, buyShares, buyAmount: buyShares * s.target_price, budgetForStock };
    });
    // 可买入的进决策,买不起的进关注
    const affordable = newSigDetails.filter(d => d.buyShares >= 100);
    const tooExpensive = newSigDetails.filter(d => d.buyShares < 100);

    affordable.forEach(({ sig: s, buyShares, buyAmount, budgetForStock }) => {
      // 【Phase3】多周期技术信号检查
      try {
        const techSignal = calculateMultiPeriodTechSignal(s.code, db);
        s.techSignal = techSignal;
        // 卖出信号跳过买入
        if (techSignal.signal === 'sell') {
          console.log(`[Phase3] ${s.name} 技术信号=${techSignal.signal}(${techSignal.score}),跳过买入`);
          return; // 跳过此股票
        }
        // 买入信号加成置信度
        if (techSignal.signal === 'strong_buy') {
          s.confidence = Math.min(100, s.confidence + 15);
          console.log(`[Phase3] ${s.name} 强买信号,置信度+15→${s.confidence}%`);
        } else if (techSignal.signal === 'buy') {
          s.confidence = Math.min(100, s.confidence + 5);
        }
      } catch (e) {
        console.error(`[Phase3] 技术信号计算失败: ${s.code}`, e.message);
      }
      
      // 舜帝买入止损价:ATR动态止损(使用统一ATR_CONFIG基础止损3.5x)
      const atr = calculateATR(s.code);
      const atrPct = atr / s.price;
      const buyStopLoss = Math.max(0.01, Math.round((s.price - atr * Math.max(ATR_CONFIG.LOW_VOL_STOP, ATR_CONFIG.STOP_MULTIPLIER)) * 100) / 100);
      // 舜帝买入目标价:信号目标价(已有)
      const buyTargetPrice = Math.round(s.target_price * 100) / 100;

      if (buyShares >= 100) {
        decisions.push({
          code: s.code,
          name: s.name,
          shares: 0,
          avgCost: 0,
          currentPrice: s.price,
          profitPct: 0,
          profit: 0,
          signal: s.signal,
          confidence: s.confidence,
          reason: s.reason,
          actions: [{
            type: '舜帝买入',
            direction: '买入',
            amount: buyAmount,
            shares: buyShares,
            targetPrice: buyTargetPrice,  // 目标买入价
            stopPrice: buyStopLoss,  // 止损价
            reason: `置信度${s.confidence}%[${capital.risk_level}],买入${buyShares}股约¥${Math.round(buyAmount).toLocaleString()},止损价¥${buyStopLoss.toFixed(2)},占总资金${(buyAmount / capital.total_capital * 100).toFixed(1)}%`,
            urgent: false
          }],
          priority: s.confidence + 1.0,
          // 时效性字段(新标的信号更紧急)
          last_analysis_time: formatTime(analysisTime),
          signal_expiry_hours: 6, // 舜帝买入信号6小时有效
          next_check_time: formatTime(nextCheckTime),
          analysis_timestamp: bjISO(analysisTime),
          // 风控价格字段
          stopLossPrice: buyStopLoss,
          takeProfitPrice: Math.round(s.target_price * 1.10 * 100) / 100,  // 目标止盈价+10%
          targetPrice: buyTargetPrice,
          potentialGain: Math.round((s.target_price / s.price - 1) * 1000) / 10,  // 潜在收益%
          potentialLoss: -5.0  // 固定止损-5%
        });
      }
    });
    // 买不起的新标的→关注信号
    tooExpensive.forEach(({ sig: s, buyShares, buyAmount, budgetForStock }) => {
      const neededAmount = Math.ceil(s.target_price * 100);
      decisions.push({
        code: s.code, name: s.name,
        shares: 0, avgCost: 0,
        currentPrice: s.price, profitPct: 0, profit: 0,
        signal: s.signal, confidence: s.confidence,
        reason: s.reason,
        actions: [{
          type: '关注信号', direction: '买入',
          amount: 0, shares: 0,
          targetPrice: s.target_price,
          stopPrice: Math.round(s.price * 0.95 * 100) / 100,
          reason: `尧帝买入信号 conf=${s.confidence}%,需¥${neededAmount.toLocaleString()}买100股,可用¥${shundiAvailable.toFixed(0)},预算不足`,
          urgent: false
        }],
        priority: s.confidence * 0.5,
        stopLossPrice: Math.round(s.price * 0.95 * 100) / 100,
        takeProfitPrice: Math.round(s.target_price * 1.10 * 100) / 100,
        targetPrice: s.target_price,
        potentialGain: Math.round((s.target_price / s.price - 1) * 1000) / 10,
        potentialLoss: -5.0
      });
    });
    if (affordable.length > 0) addRedQueenLog(`📡 新标的:${affordable[0].sig.name}置信度${affordable[0].sig.confidence}%`, 'decision');

    // 6b. 关注信号:尧帝信号即使资金不足也展示给用户
    const watchSigs = signals.filter(s => s.signal === 'buy' && !shundiHeldCodes.includes(s.code) && s.confidence >= 60 && !newSigs.find(ns => ns.code === s.code));
    watchSigs.forEach(s => {
      const neededAmount = Math.ceil(s.target_price * 100);
      decisions.push({
        code: s.code, name: s.name,
        shares: 0, avgCost: 0,
        currentPrice: s.price, profitPct: 0, profit: 0,
        signal: s.signal, confidence: s.confidence,
        reason: s.reason,
        actions: [{
          type: '关注信号', direction: '买入',
          amount: 0, shares: 0,
          targetPrice: s.target_price,
          stopPrice: Math.round(s.price * 0.95 * 100) / 100,
          reason: `尧帝${s.signal}信号 conf=${s.confidence}%,需¥${neededAmount.toLocaleString()}买100股,可用¥${shundiAvailable.toFixed(0)}`,
          urgent: false
        }],
        priority: s.confidence * 0.5,
        stopLossPrice: Math.round(s.price * 0.95 * 100) / 100,
        takeProfitPrice: Math.round(s.target_price * 1.10 * 100) / 100,
        targetPrice: s.target_price,
        potentialGain: Math.round((s.target_price / s.price - 1) * 1000) / 10,
        potentialLoss: -5.0
      });
    });

    // 【P0修复】舜帝止损止盈:从 yaodi_config 读取阈值,不再硬编码
    const rqStopPctVal = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='default_stop_loss_pct'").get()?.value || '3.0');
    const rqTakeRatioVal = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='default_take_profit_ratio'").get()?.value || '1.03');
    const rqStopNeg = Math.max(rqStopPctVal * 2, 5);   // 默认 -6%(2倍配置)
    const rqProfitPos = parseFloat(((rqTakeRatioVal - 1) * 100).toFixed(2)); // 5.0%
    // shundiHoldings已在上方第6步声明,此处复用
    shundiHoldings.forEach(h => {
      if (!canSellByT1(h.buy_date)) return; // T+1限制:当日买入不可自动止损/止盈
      const pct = parseFloat(h.profit_percent || 0);
      // 【真实成交量限制】舜帝卖出数量 = min(持仓量, 日成交量5%)
      const rtVol = db.prepare("SELECT volume FROM stock_realtime WHERE code=?").get(h.code)?.volume || 100000;
      const volShares = Math.max(100, Math.floor(rtVol * 0.05 / 100) * 100);
      const sig = signals.find(s => s.code === h.code);  // signals已经是活跃尧帝信号
      // 【P1修复】profit_percent统一为百分比格式,无需再乘100
      const profitPctDisplay = parseFloat(h.profit_percent || 0);
      if (profitPctDisplay <= -rqStopNeg) {
        decisions.push({
          code: h.code, name: h.name,
          currentPrice: h.current_price, avgCost: h.avg_cost,
          profitPct: profitPctDisplay, profit: h.profit,
          signal: 'sell', confidence: 95,
          reason: `📉 舜帝止损:${h.name}亏损${profitPctDisplay.toFixed(1)}%,超过-${rqStopNeg.toFixed(0)}%阈值`,
          actions: [{
            type: '止损', direction: '卖出', shares: Math.min(h.shares, volShares),
            stopPrice: Math.round(h.current_price * 0.995 * 100) / 100,
            reason: `舜帝止损:买价¥${h.avg_cost},现价¥${h.current_price},亏损${profitPctDisplay.toFixed(1)}%,卖出全部${h.shares}股`,
            urgent: true
          }],
          priority: 95 + Math.abs(profitPctDisplay)
        });
        addRedQueenLog(`📉 舜帝止损: ${h.name} 亏损${profitPctDisplay.toFixed(1)}% (-${rqStopNeg.toFixed(0)}%阈值)`, 'warning');

      } else if (profitPctDisplay >= rqProfitPos) {
        decisions.push({
          code: h.code, name: h.name,
          currentPrice: h.current_price, avgCost: h.avg_cost,
          profitPct: profitPctDisplay, profit: h.profit,
          signal: 'sell', confidence: 85,
          reason: `📊 舜帝止盈:${h.name}盈利${profitPctDisplay.toFixed(1)}%,达到${rqProfitPos}%止盈阈值`,
          actions: [{
            type: '止盈', direction: '卖出', shares: Math.min(h.shares, volShares),
            targetPrice: Math.round(h.current_price * 1.005 * 100) / 100,
            reason: `舜帝止盈:盈利${profitPctDisplay.toFixed(1)}%,卖出全部${h.shares}股`,
            urgent: false
          }],
          priority: 85 + profitPctDisplay
        });
      }
    });

    // 【P0修复 2026-04-28】非交易时段硬拦截:红后止损/止盈也必须在交易时段内执行
    // 凌晨2点仍在执行交易的根因:此处缺少 isTradingHours() 检查
    if (!isTradingHours()) {
      console.log('[红后] 非交易时段,跳过所有止损/止盈/买入执行(仅记录决策)');
      // 【规则2】生成延迟交易前校验持仓状态
      const currentHoldings = db.prepare(`SELECT code, shares FROM shundi_mock_holdings`).all();
      const holdingMap = new Map(currentHoldings.map(h => [h.code, h.shares]));

      decisions.forEach(d => {
        const a = d.actions[0];
        if (a) addRedQueenLog(`⏸️ 非交易时段拦截: ${d.name || d.code} ${a.type} ${a.direction} - 将在下次交易时段执行`, 'warning');
      });
      // 将待执行决策存入数据库,等交易时段再执行
      // 【去重修复】只插入该股票尚无pending记录的交易
      // 【规则2】卖出前校验持仓是否存在及数量匹配
      try {
        decisions.forEach(d => {
          const a = d.actions[0];
          if (a && (a.direction === '卖出' || a.direction === '买入')) {
            // 卖出校验:检查是否仍持有该股票
            if (a.direction === '卖出') {
              const holdingShares = holdingMap.get(d.code);
              if (!holdingShares) {
                addRedQueenLog(`🚫 延迟交易跳过: ${d.name} 已无持仓,不再生成卖出记录`, 'info');
                return; // 跳过此条决策
              }
              // 更新卖出数量为实际持仓数量
              a.shares = Math.min(a.shares || holdingShares, holdingShares);
            }
            // 检查是否已存在相同的pending记录
            const existing = db.prepare(`SELECT 1 FROM deferred_trades WHERE code = ? AND status = 'pending'`).get(d.code);
            if (!existing) {
              db.prepare(`INSERT INTO deferred_trades (code, name, action_type, direction, shares, amount, reason, priority, yaodi_branch_id, created_at, status)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending')`).run(
                d.code, d.name, a.type, a.direction, a.shares || 0, a.amount || 0, a.reason || '', d.priority || 0, d.yaodi_branch_id || (db.prepare("SELECT id FROM yaodi_branch WHERE accuracy > 70 ORDER BY accuracy DESC LIMIT 1").get())?.id || null, bjNow()
              );
              addRedQueenLog(`📝 延迟交易已记录: ${d.name} ${a.type} ${a.direction} 等待交易时段执行`, 'info');
            }
          }
        });
      } catch(e) { /* deferred_trades表不存在时忽略 */ }
      return; // 非交易时段直接返回,不执行任何交易
    }

    // 红后紧急卖出:只有盈利>0.5%或亏损>8%才执行,避免正常波动乱卖
    decisions.filter(d => d.actions[0]?.urgent).forEach(d => {
      const h = db.prepare("SELECT * FROM shundi_mock_holdings WHERE code = ? AND shares > 0").get(d.code);
      if (!h) return;
      const price = h.current_price || h.avg_cost;
      const profitPct = h.avg_cost > 0 ? (price - h.avg_cost) / h.avg_cost * 100 : 0;
      // 在 [-8%, 0.5%] 区间内不卖（正常波动）
      if (profitPct > -8 && profitPct < 0.5) {
        console.log(`[红后] ${h.name} 盈亏${profitPct.toFixed(1)}%,未达卖出条件,跳过`);
        return;
      }
      const pnl = (price - h.avg_cost) * h.shares;
      const oid = "RQ_SL_" + h.code + "_" + Date.now();
      if (!canSellByT1(h.buy_date)) {
        addRedQueenLog(`⚠️ A股T+1注意:${h.name} 今日买入,模拟盘允许止损但实盘受限`);
      }
      db.prepare("DELETE FROM shundi_mock_holdings WHERE code = ?").run(h.code);
      db.prepare(`INSERT INTO shundi_mock_trades (order_id, type, code, name, price, shares, amount, commission, status, filled_time, source, confidence, reason, pnl, yaodi_branch_id) VALUES (?, 'sell', ?, ?, ?, ?, ?, ?, 'filled', ?, 'redqueen', ?, ?, ?, ?)`).run(oid, h.code, h.name, price, h.shares, h.market_value, h.market_value * 0.0013, bjNow(), d.confidence || 0, d.actions[0]?.reason || '止损', pnl, h.yaodi_branch_id || d.yaodi_branch_id || null);
      
      // 【Phase 4进化 2026-07-07】记录交易反馈
      try {
        const buyTrade = db.prepare(`
          SELECT created_at, confidence, reason, source
          FROM shundi_mock_trades 
          WHERE code = ? AND type IN ('buy', '尧帝信号执行', '舜帝加仓', '智能选股新仓')
          ORDER BY created_at DESC LIMIT 1
        `).get(h.code);
        
        if (buyTrade) {
          const buyDate = buyTrade.created_at;
          const holdDays = Math.floor((Date.now() - new Date(buyDate).getTime()) / 86400000);
          
          // 获取买入时的市场格局(从decision或全局变量)
          const buyMarketRegime = globalThis._lastRegime || 'UNKNOWN';
          
          // 获取板块信息
          const codeStr = String(h.code);
          let buySector = '其他';
          if (codeStr.startsWith('6') && !codeStr.startsWith('688')) buySector = '沪市主板';
          else if (codeStr.startsWith('688')) buySector = '科创板';
          else if (codeStr.startsWith('3')) buySector = '创业板';
          else if (codeStr.startsWith('0') || codeStr.startsWith('1')) buySector = '深市主板';
          
          recordTradeFeedback({
            code: h.code,
            name: h.name,
            buyPrice: h.avg_cost,
            buyDate: buyDate,
            buyConfidence: buyTrade.confidence || d.confidence || 0,
            buyReason: buyTrade.reason || '',
            buyMarketRegime: buyMarketRegime,
            buySector: buySector,
            buySectorStrength: 'unknown',
            sellPrice: price,
            sellDate: bjNow(),
            sellType: d.actions[0]?.type || 'sell',
            holdDays: holdDays,
            profitPct: profitPct,
            pnl: pnl,
            techSignal: d.techSignal?.signal || null,
            techScore: d.techSignal?.score || null,
            stopLossPct: -8,
            takeProfitPct: 8
          });
        }
      } catch (e) {
        console.error('[Phase4反馈] 记录失败:', e.message);
      }
      
      try {
        recordBacktestTrade({ trade_type: 'sell', code: h.code, name: h.name, shares: h.shares, price, amount: h.market_value, profit: pnl, profit_percent: profitPct, strategy: d.actions[0]?.type || '止损', signal_confidence: d.confidence || 0, hold_days: Math.floor((Date.now() - new Date(h.update_time || Date.now()).getTime()) / 86400000) });
      } catch(e) { /* ignore */ }
      try { resolvePendingTrade(oid, price, Date.now()); } catch(e) { /* ignore */ }
      addRedQueenLog(`🔴 红后卖出: ${h.name} ${h.shares}股 @¥${price.toFixed(2)} 盈亏¥${pnl.toFixed(2)}(${profitPct.toFixed(1)}%)`, 'warning');
    });
    decisions.sort((a, b) => b.priority - a.priority);
    // Inject timing metadata for UI display (分析/检查)
    const _now = toBeijingTime();
    const _fmtT = (d) => d.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    decisions.forEach(d => {
      const at = d.actions[0]?.type || '';
      d.last_analysis_time = _fmtT(_now);
      d.next_check_time = _fmtT(new Date(_now.getTime() + 30000));
      if (at.includes('止损')) d.signal_expiry_hours = 1;
      else if (at.includes('止盈')) d.signal_expiry_hours = 4;
      else if (at === '舜帝加仓') d.signal_expiry_hours = 12;
      else d.signal_expiry_hours = 6;
    });
    redqueenDecisions = decisions;

    // ========== 红后协调:尧帝→舜帝信号传递 ==========
    // 将尧帝高分策略传递给舜帝
    try {
      const topYaodiStrategies = db.prepare(`
        SELECT id, name, accuracy, win_rate, level
        FROM yaodi_branch
        WHERE active = 1 AND accuracy >= 70
        ORDER BY accuracy DESC
        LIMIT 5
      `).all();

      if (topYaodiStrategies.length > 0) {
        // 记录协调日志
        addRedQueenLog(`🔗 协调: 尧帝TOP${topYaodiStrategies.length}策略传递舜帝`, 'coordination');

        // 将尧帝策略信号注入舜帝信号池
        topYaodiStrategies.forEach(strategy => {
          // 查找该策略关联的股票
          const relatedStocks = db.prepare(`
            SELECT DISTINCT code FROM trade_signals
            WHERE reason LIKE ? AND expires_at > ?
            LIMIT 3
          `).all(`%${strategy.name}%`, bjNow());

          relatedStocks.forEach(rs => {
            // 检查舜帝是否已持有
            const shundiHold = db.prepare("SELECT * FROM shundi_mock_holdings WHERE code = ?").get(rs.code);
            if (!shundiHold) {
              // 注入舜帝买入信号
              db.prepare(`
                INSERT OR REPLACE INTO trade_signals
                (code, signal, confidence, reason, source, expires_at, created_at)
                VALUES (?, 'buy', ?, ?, 'yaodi→shundi', ?, ?)
              `).run(rs.code, Math.round(strategy.accuracy), `尧帝[${strategy.name}]准确率${strategy.accuracy}%`, bjFuture(1), bjNow());
            }
          });
        });
      }
    } catch (coordErr) {
      // 协调失败不影响主流程
    }

    // ========== 【P0】A股交易时间强制检查 ==========
    // 所有自动交易(买入/卖出/止损/止盈/加仓)必须在A股交易时段内执行
    // 交易时间:09:30-11:30, 13:00-15:00,周一至周五
    const _tradeNow = toBeijingTime();
    const _tradeDow = _tradeNow.getDay();
    const _tradeH = _tradeNow.getHours(), _tradeM = _tradeNow.getMinutes();
    const _isWeekday = _tradeDow >= 1 && _tradeDow <= 5;
    const _isMorning = (_tradeH === 9 && _tradeM >= 30) || (_tradeH >= 10 && _tradeH < 12);
    const _isAfternoon = _tradeH >= 13 && _tradeH < 15;
    const _isAStockTradingTime = _isWeekday && (_isMorning || _isAfternoon);

    if (!_isAStockTradingTime) {
      // 非交易时段:仅更新系统状态和决策建议,不执行任何交易
      addRedQueenLog(`⏸️ 非A股交易时段(${_isWeekday ? '盘外' : '周末'} ${_tradeH}:${String(_tradeM).padStart(2,'0')}),暂停自动交易`, 'system');
      redqueenDecisions = decisions;
      return;
    }

    // ========== 自动执行交易 ==========
    const executedTrades = [];
    // 统计已分配资金(卖出释放 + 舜帝买入冻结)
    let allocatedBudget = 0;

    // 优先执行非紧急的卖出操作(止盈、部分止盈、换股)
    decisions.filter(d => !d.actions[0]?.urgent && (d.actions[0]?.type === '止盈' || d.actions[0]?.type === '部分止盈')).forEach(d => {
      const act = d.actions[0];
      if (act.direction === '卖出' && d.shares > 0) {
        const oid = "RQ_TP_" + d.code + "_" + Date.now();
        const sellShares = act.type === '部分止盈' ? act.shares : d.shares;
        // 【BUG修复2026-04-25】止盈PnL计算(原代码pnl=0)
        const tpPnl = (d.currentPrice - d.avgCost) * sellShares;
        const tpProfitPct = d.avgCost > 0 ? (d.currentPrice - d.avgCost) / d.avgCost * 100 : 0;
        db.prepare("UPDATE shundi_mock_holdings SET shares = shares - ? WHERE code = ? AND shares >= ?").run(sellShares, d.code, sellShares);
        db.prepare("DELETE FROM shundi_mock_holdings WHERE shares <= 0").run();
        // 【BUG修复2026-04-25】type从'sell'→正确止盈类型,补充pnl/confidence/strategy字段
        db.prepare(`INSERT INTO shundi_mock_trades (order_id, type, code, name, price, shares, amount, commission, status, filled_time, source, confidence, reason, pnl, strategy, yaodi_branch_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'filled', ?, 'redqueen', ?, ?, ?, ?, ?)`)
          .run(oid, act.type, d.code, d.name, d.currentPrice, sellShares, act.amount, calcAStockCost(act.amount, 'sell').total, bjNow(), d.confidence || 80, act.reason, tpPnl, 'ATR止盈');
        allocatedBudget -= act.amount; // 卖出释放资金
        executedTrades.push({ type: '止盈卖出', name: d.name, shares: sellShares, amount: act.amount });
        addRedQueenLog(`💰 止盈: ${d.name} 卖出${sellShares}股 @¥${d.currentPrice.toFixed(2)} 盈亏¥${tpPnl.toFixed(2)}(${tpProfitPct.toFixed(1)}%)`, 'success');
        // 【BUG修复2026-04-25】止盈→尧帝学习闭环(原代码缺失)
        recordBacktestTrade({
          trade_type: 'sell', code: d.code, name: d.name,
          shares: sellShares, price: d.currentPrice, amount: act.amount, profit: tpPnl, profit_percent: tpProfitPct,
          strategy: act.type, signal_confidence: d.confidence || 80,
          hold_days: Math.floor((Date.now() - new Date(d.avgCost ? Date.now() : Date.now()).getTime()) / 86400000)
        });
        // 【BUG修复2026-04-25】止盈→尧帝V2增量学习反馈
        try {
          if (yaodiV2Core?.incrementalLearning?.recordSignalOutcome) {
            yaodiV2Core.recordOutcome(d.code, {
              code: d.code, outcome: tpPnl > 0 ? 'win' : 'loss',
              returnPct: tpProfitPct, holdDays: 1, timestamp: bjISO()
            });
          }
        } catch (v2e) { /* V2反馈失败不阻塞 */ }
      }
    });

    // 执行舜帝新标的买入(按优先级分配资金)
    const buyDecisions = decisions.filter(d => d.shares === 0 && (d.actions[0]?.type === '舜帝买入' || d.actions[0]?.type === '尧帝信号执行') && d.actions[0]?.shares >= 100);
    // 按优先级从高到低分配预算
    let remainingBudget = available + allocatedBudget; // 当前可用(含卖出释放)
    buyDecisions.forEach(d => {
      // 【BUGFIX 2026-04-25】止损冷却期:止损后2小时内不买回同一股票
      const stopLossCooldownRQ = db.prepare("SELECT id FROM shundi_mock_trades WHERE code=? AND type IN ('止损','shundi_stoploss','止损出局','止损保护') AND filled_time > ?").get(d.code, bjPast(2/24));
      if (stopLossCooldownRQ) {
        addRedQueenLog(`🚫 RQ止损冷却期: ${d.name} 2小时内止损过,不买回`, 'warning');
        return;
      }
      const act = d.actions[0];
      const maxAffordable = Math.floor(remainingBudget * 0.8 / d.actions.length); // 保留20%现金
      if (act.shares * act.amount / (act.shares || 1) <= maxAffordable && act.shares >= 100) {
        const cost = act.shares * d.currentPrice;
        const oid = "RQ_BUY_" + d.code + "_" + Date.now();
        // 【修复】自动检测高分分支作为默认值
        const bestBranch = db.prepare("SELECT id FROM yaodi_branch WHERE accuracy > 70 ORDER BY accuracy DESC LIMIT 1").get();
        const branchId = d.yaodi_branch_id || bestBranch?.id || null;
        db.prepare("INSERT INTO shundi_mock_holdings (code, name, shares, avg_cost, current_price, market_value, profit, profit_percent, update_time, yaodi_branch_id) VALUES (?, ?, ?, ?, ?, ?, 0, 0, ?, ?)").run(d.code, d.name, act.shares, d.currentPrice, d.currentPrice, cost, bjNow(), branchId);
        db.prepare("INSERT INTO shundi_mock_trades (order_id, type, code, name, price, shares, amount, commission, status, filled_time, source, reason, yaodi_branch_id) VALUES (?, 'buy', ?, ?, ?, ?, ?, ?, 'filled', ?, 'redqueen', ?, ?)").run(oid, d.code, d.name, d.currentPrice, act.shares, cost, cost * 0.0013, bjNow(), act.reason, branchId);
        remainingBudget -= cost;
        executedTrades.push({ type: '买入', name: d.name, shares: act.shares, amount: cost });
        addRedQueenLog(`📈 买入: ${d.name} ${act.shares}股 ¥${cost.toFixed(0)}`, 'success');
      }
    });

    // 执行持仓加仓(如果有充足预算)
    const addDecisions = decisions.filter(d => d.shares > 0 && d.actions[0]?.type === '加仓' && remainingBudget > 2000);
    addDecisions.forEach(d => {
      const act = d.actions[0];
      const cost = act.shares * d.currentPrice;
      if (cost <= remainingBudget * 0.3 && act.shares >= 100) {
        // 更新持仓:增加股数,降低平均成本
        const h = db.prepare("SELECT * FROM shundi_mock_holdings WHERE code = ?").get(d.code);
        if (h) {
          const newShares = h.shares + act.shares;
          const newAvgCost = (h.avg_cost * h.shares + d.currentPrice * act.shares) / newShares;
          const oid = "RQ_ADD_" + d.code + "_" + Date.now();
          db.prepare("UPDATE shundi_mock_holdings SET shares = ?, avg_cost = ?, current_price = ?, market_value = ? * shares, profit = (?-avg_cost)*shares, profit_percent=(?-avg_cost)/avg_cost*100, update_time=? WHERE code = ?").run(newShares, newAvgCost, d.currentPrice, newAvgCost, newAvgCost, newAvgCost, bjNow(), d.code);
          db.prepare("INSERT INTO shundi_mock_trades (order_id, type, code, name, price, shares, amount, commission, status, filled_time, source, reason, yaodi_branch_id) VALUES (?, 'buy', ?, ?, ?, ?, ?, ?, 'filled', ?, 'redqueen', ?, ?)").run(oid, d.code, d.name, d.currentPrice, act.shares, cost, cost * 0.0013, bjNow(), act.reason, branchId);
          remainingBudget -= cost;
          executedTrades.push({ type: '加仓', name: d.name, shares: act.shares, amount: cost });
          addRedQueenLog(`📈 加仓: ${d.name} +${act.shares}股 ¥${cost.toFixed(0)}`, 'success');
        }
      }
    });

    if (executedTrades.length > 0) {
      addRedQueenLog(`✅ 自动交易完成: ${executedTrades.length}笔 | 剩余可用¥${remainingBudget.toFixed(0)}`, 'success');
    }

    addRedQueenLog(`✅ 分析完成 | ${holdings.length}只持仓 | ${newSigs.length}个新信号 | 仓位${posRatio.toFixed(0)}%`, 'success');
  } catch(e) {
    addRedQueenLog(`❌ 运行异常: ${e.message}`, 'error');
  }
}

function startRedQueen() {
  if (redqueenRunning) return;
  redqueenRunning = true;
  addRedQueenLog('🔴 红后引擎启动,开始分析舜帝持仓...', 'system');
  // [CPU监控] 包装redqueenAutoCycle添加耗时日志
  const _redqueenAutoCycleTimed = async () => { const t=Date.now(); await redqueenAutoCycle(); const ms=Date.now()-t; if(ms>100) console.log(`⏱️ [CPU] redqueenAutoCycle: ${ms}ms`); };
  redqueenTimer = setInterval(_redqueenAutoCycleTimed, 30000);

  // 【新增】收藏股独立定时刷新(每5分钟)
  const stockPoolTimer = setInterval(() => {
    try {
      refreshStockPoolPrices();
      const tenMinAgo = bjPast(1/144);
      const pool = db.prepare("SELECT COUNT(*) as cnt FROM user_stock_pool WHERE update_time > ?").get(tenMinAgo);
      console.log(`⭐ [收藏股] 已刷新 ${pool.cnt} 只价格`);
    } catch (e) {
      console.error(`⭐ [收藏股] 刷新失败: ${e.message}`);
    }
  }, 5 * 60 * 1000);  // 5分钟
  setTimeout(redqueenAutoCycle, 1000);
}

function stopRedQueen() {
  redqueenRunning = false;
  if (redqueenTimer) { clearInterval(redqueenTimer); redqueenTimer = null; }
  addRedQueenLog('⏹ 红后引擎已停止', 'system');
}

