// 改进0: 智能选股系统(舜帝核心能力)
// ═══════════════════════════════════════════════════════════════

/**
 * 获取尧帝演化高分分支作为选股策略源
 */
function getTopStrategiesForShundi(count = 5) {
  try {
    return db.prepare(`
      SELECT id, branch_name, accuracy, evolution_level,
             reliability_score, total_trades, win_trades
      FROM yaodi_branch
      WHERE accuracy >= 60 AND total_trades >= 5
      ORDER BY accuracy DESC, reliability_score DESC
      LIMIT ?
    `).all(count);
  } catch (e) {
    return [];
  }
}

/**
 * 计算技术指标评分(0-100)
 */
function calculateTechScore(stock) {
  let score = 50; // 基础分

  const price = stock.price || stock.current_price || 0;
  const preClose = stock.pre_close || price;
  const high = stock.high || price;
  const low = stock.low || price;

  if (!price || price <= 0) return 50;

  // 1. 价格相对位置(接近低分高)
  const pricePosition = preClose > 0 ? (price - low) / Math.max(high - low, 0.01) : 0.5;
  if (pricePosition < 0.3) score += 15; // 接近最低价,加分
  else if (pricePosition > 0.7) score -= 10; // 接近最高价,减分

  // 2. 涨跌幅评分(小跌或横盘优先)
  const changePct = stock.change_percent || stock.pct_chg || 0;
  if (changePct >= -3 && changePct <= 0) score += 10; // 小跌加分
  else if (changePct > 0 && changePct <= 3) score += 5; // 小涨中性
  else if (changePct > 5) score -= 10; // 大涨追高风险

  // 3. 成交量评分(放量优先)
  const volume = stock.volume || 0;
  const avgVolume = stock.avg_volume || volume;
  if (avgVolume > 0 && volume > avgVolume * 1.5) score += 10;

  // 4. 换手率评分(适中换手最佳)
  const turnover = stock.turnover_rate || 0;
  if (turnover >= 2 && turnover <= 8) score += 10;
  else if (turnover > 10) score -= 5;

  return Math.max(0, Math.min(100, score));
}

/**
 * 计算动量评分(0-100)
 */
function calculateMomentumScore(stock) {
  let score = 50;

  // 涨跌幅作为动量指标
  const changePct = stock.change_percent || stock.pct_chg || 0;

  // 温和上涨动量最佳(2-5%)
  if (changePct >= 2 && changePct <= 5) {
    score += 20;
  } else if (changePct > 0 && changePct < 2) {
    score += 10;
  } else if (changePct >= -2 && changePct < 0) {
    score += 5; // 小跌视为调整机会
  } else if (changePct < -5) {
    score -= 15; // 大跌风险
  }

  // 量价配合
  const volume = stock.volume || 0;
  if (changePct > 0 && volume > (stock.avg_volume || volume)) {
    score += 10; // 放量上涨
  }

  return Math.max(0, Math.min(100, score));
}

/**
 * 计算均值回归评分(0-100)
 */
function calculateMeanReversionScore(stock) {
  let score = 50;

  const price = stock.price || stock.current_price || 0;
  const preClose = stock.pre_close || price;

  if (!price || price <= 0) return 50;

  // 相对昨日收盘价位置
  const changeFromPreClose = preClose > 0 ? (price - preClose) / preClose * 100 : 0;

  // 下跌越多,回归潜力越大
  if (changeFromPreClose <= -3 && changeFromPreClose >= -7) {
    score += 25; // 最佳回归区间
  } else if (changeFromPreClose < -7) {
    score += 10; // 过度下跌风险
  } else if (changeFromPreClose > 5) {
    score -= 15; // 过度上涨
  }

  return Math.max(0, Math.min(100, score));
}

/**
 * 计算支撑阻力评分(0-100)
 */
function calculateSupportResistanceScore(stock) {
  let score = 50;

  const price = stock.price || stock.current_price || 0;
  const low = stock.low || price;
  const high = stock.high || price;
  const preClose = stock.pre_close || price;

  if (!price || price <= 0) return 50;

  // 计算当前价格在日内的位置
  const dailyRange = high - low;
  const positionInRange = dailyRange > 0 ? (price - low) / dailyRange : 0.5;

  // 接近日内低点,支撑强
  if (positionInRange < 0.2) {
    score += 20;
  } else if (positionInRange > 0.8) {
    score -= 15; // 接近日内高点,阻力强
  }

  // 相对昨收位置
  if (price < preClose * 0.97) {
    score += 15; // 接近支撑位
  }

  return Math.max(0, Math.min(100, score));
}

/**
 * ══════════════════════════════════════════════════════════════════
 * 【Phase 3进化 2026-07-07】多周期技术信号引擎
 * 基于RSI/MACD/KDJ/BOLL多周期共振，生成买卖点信号
 * ══════════════════════════════════════════════════════════════════
 */
function calculateMultiPeriodTechSignal(code, db) {
  if (!db) db = globalThis._db || require('better-sqlite3')(DB_FILE);
  
  // 获取最近60日K线数据
  const rows = db.prepare(`
    SELECT date, open, high, low, close, volume 
    FROM stock_history 
    WHERE code = ? AND volume > 0 
    ORDER BY date DESC LIMIT 60
  `).all(code);
  
  if (rows.length < 30) {
    return { score: 50, signal: 'neutral', reasons: ['数据不足'], confidence: 0 };
  }
  
  // 反转顺序(从旧到新)
  rows.reverse();
  const closes = rows.map(r => r.close);
  const highs = rows.map(r => r.high);
  const lows = rows.map(r => r.low);
  const volumes = rows.map(r => r.volume);
  
  // ── 1. 多周期RSI分析 ──
  const rsi6 = calcRSI(closes, 6);
  const rsi12 = calcRSI(closes, 12);
  const rsi24 = calcRSI(closes, 24);
  
  let rsiSignal = 0;
  const rsiReasons = [];
  
  // 多周期超卖共振
  if (rsi6 < 30 && rsi12 < 40 && rsi24 < 50) {
    rsiSignal = 100; // 强买入
    rsiReasons.push('RSI多周期超卖共振(6/12/24)');
  } else if (rsi6 < 30 || rsi12 < 35) {
    rsiSignal = 70;
    rsiReasons.push(`RSI超卖(${rsi6.toFixed(0)}/${rsi12.toFixed(0)})`);
  } else if (rsi6 > 70 && rsi12 > 60 && rsi24 > 50) {
    rsiSignal = -100; // 强卖出
    rsiReasons.push('RSI多周期超买共振');
  } else if (rsi6 > 70 || rsi12 > 70) {
    rsiSignal = -70;
    rsiReasons.push(`RSI超买(${rsi6.toFixed(0)})`);
  } else {
    rsiSignal = (50 - rsi6) * 0.5; // 中性区间
  }
  
  // ── 2. MACD分析 ──
  const macd = calcMACD(closes);
  const macdCross = calcMACDCross(closes);
  
  let macdSignal = 0;
  const macdReasons = [];
  
  if (macdCross === 1 && macd.hist > 0) {
    macdSignal = 90;
    macdReasons.push('MACD金叉+红柱');
  } else if (macdCross === 1) {
    macdSignal = 70;
    macdReasons.push('MACD金叉');
  } else if (macdCross === -1 && macd.hist < 0) {
    macdSignal = -90;
    macdReasons.push('MACD死叉+绿柱');
  } else if (macd.hist > 0) {
    macdSignal = 40;
    macdReasons.push('MACD红柱');
  } else if (macd.hist < 0) {
    macdSignal = -40;
    macdReasons.push('MACD绿柱');
  }
  
  // ── 3. KDJ分析 ──
  const kdj = calcKDJ(highs, lows, closes);
  
  let kdjSignal = 0;
  const kdjReasons = [];
  
  if (kdj.j < 10) {
    kdjSignal = 100;
    kdjReasons.push(`KDJ极度超卖(J=${kdj.j.toFixed(0)})`);
  } else if (kdj.j < 20) {
    kdjSignal = 80;
    kdjReasons.push(`KDJ超卖(J=${kdj.j.toFixed(0)})`);
  } else if (kdj.j > 90) {
    kdjSignal = -100;
    kdjReasons.push(`KDJ极度超买(J=${kdj.j.toFixed(0)})`);
  } else if (kdj.j > 80) {
    kdjSignal = -80;
    kdjReasons.push(`KDJ超买(J=${kdj.j.toFixed(0)})`);
  } else if (kdj.k > kdj.d && kdj.j < 50) {
    kdjSignal = 50;
    kdjReasons.push('KDJ金叉低位');
  } else if (kdj.k < kdj.d && kdj.j > 50) {
    kdjSignal = -50;
    kdjReasons.push('KDJ死叉高位');
  }
  
  // ── 4. BOLL布林带分析 ──
  const boll = calcBOLL(closes);
  const currentPrice = closes[closes.length - 1];
  
  let bollSignal = 0;
  const bollReasons = [];
  
  const bollPosition = (currentPrice - boll.lower) / (boll.upper - boll.lower);
  
  if (currentPrice <= boll.lower * 1.01) {
    bollSignal = 90;
    bollReasons.push('触及BOLL下轨');
  } else if (bollPosition < 0.2) {
    bollSignal = 70;
    bollReasons.push('接近BOLL下轨');
  } else if (currentPrice >= boll.upper * 0.99) {
    bollSignal = -90;
    bollReasons.push('触及BOLL上轨');
  } else if (bollPosition > 0.8) {
    bollSignal = -70;
    bollReasons.push('接近BOLL上轨');
  } else if (currentPrice > boll.mid && closes[closes.length - 2] <= boll.mid) {
    bollSignal = 50;
    bollReasons.push('突破BOLL中轨');
  }
  
  // ── 5. 综合评分与共振检测 ──
  const weights = { rsi: 0.3, macd: 0.3, kdj: 0.25, boll: 0.15 };
  
  const rawScore = 
    rsiSignal * weights.rsi +
    macdSignal * weights.macd +
    kdjSignal * weights.kdj +
    bollSignal * weights.boll;
  
  // 共振检测:同向信号>=3个
  const signals = [rsiSignal, macdSignal, kdjSignal, bollSignal];
  const bullishCount = signals.filter(s => s > 50).length;
  const bearishCount = signals.filter(s => s < -50).length;
  
  let resonanceBonus = 1.0;
  if (bullishCount >= 3) {
    resonanceBonus = 1.3;
    rsiReasons.push('⚡多头共振');
  } else if (bearishCount >= 3) {
    resonanceBonus = 1.3;
    rsiReasons.push('⚡空头共振');
  }
  
  const finalScore = Math.max(0, Math.min(100, 50 + rawScore * resonanceBonus * 0.5));
  
  // 判断信号方向
  let signal = 'neutral';
  let confidence = 0;
  
  if (finalScore >= 70) {
    signal = 'strong_buy';
    confidence = finalScore;
  } else if (finalScore >= 60) {
    signal = 'buy';
    confidence = finalScore;
  } else if (finalScore <= 30) {
    signal = 'strong_sell';
    confidence = 100 - finalScore;
  } else if (finalScore <= 40) {
    signal = 'sell';
    confidence = 100 - finalScore;
  }
  
  const allReasons = [...rsiReasons, ...macdReasons, ...kdjReasons, ...bollReasons];
  
  return {
    score: finalScore,
    signal,
    confidence,
    reasons: allReasons,
    details: {
      rsi: { rsi6: rsi6.toFixed(1), rsi12: rsi12.toFixed(1), rsi24: rsi24.toFixed(1) },
      macd: { macd: macd.macd.toFixed(4), signal: macd.signal.toFixed(4), hist: macd.hist.toFixed(4), cross: macdCross },
      kdj: { k: kdj.k.toFixed(1), d: kdj.d.toFixed(1), j: kdj.j.toFixed(1) },
      boll: { upper: boll.upper.toFixed(2), mid: boll.mid.toFixed(2), lower: boll.lower.toFixed(2), position: (bollPosition * 100).toFixed(1) + '%' }
    }
  };
}

/**
 * ══════════════════════════════════════════════════════════════════
 * 【Phase 4进化 2026-07-07】反馈学习引擎
 * 基于历史交易胜率+盈亏，驱动参数自优化
 * ══════════════════════════════════════════════════════════════════
 */

/**
 * 记录交易反馈
 */
function recordTradeFeedback(params) {
  const { 
    code, name, buyPrice, buyDate, buyConfidence, buyReason,
    buyMarketRegime, buySector, buySectorStrength,
    sellPrice, sellDate, sellType, holdDays,
    profitPct, pnl, techSignal, techScore,
    stopLossPct, takeProfitPct
  } = params;
  
  try {
    db.prepare(`
      INSERT INTO shundi_trade_feedback (
        code, name, buy_price, buy_date, buy_confidence, buy_reason,
        buy_market_regime, buy_sector, buy_sector_strength,
        sell_price, sell_date, sell_type, hold_days,
        profit_pct, pnl, is_win, tech_signal, tech_score,
        stop_loss_pct, take_profit_pct
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      code, name, buyPrice, buyDate, buyConfidence, buyReason,
      buyMarketRegime, buySector, buySectorStrength,
      sellPrice, sellDate, sellType, holdDays,
      profitPct, pnl, profitPct > 0 ? 1 : 0, techSignal, techScore,
      stopLossPct, takeProfitPct
    );
    
    console.log(`[Phase4反馈] ${code} 记录成功: 盈亏${profitPct.toFixed(1)}%`);
  } catch (e) {
    console.error(`[Phase4反馈] 记录失败:`, e.message);
  }
}

/**
 * 分析参数效果
 */
function analyzeParamEffectiveness() {
  const results = {};
  
  // 1. 按置信度区间分析
  try {
    const confStats = db.prepare(`
      SELECT 
        CASE 
          WHEN buy_confidence < 60 THEN '50-60'
          WHEN buy_confidence < 70 THEN '60-70'
          WHEN buy_confidence < 80 THEN '70-80'
          ELSE '80+'
        END as conf_range,
        COUNT(*) as total,
        SUM(is_win) as wins,
        ROUND(AVG(profit_pct), 2) as avg_pnl,
        ROUND(SUM(is_win) * 100.0 / COUNT(*), 1) as win_rate
      FROM shundi_trade_feedback
      WHERE buy_confidence IS NOT NULL
      GROUP BY conf_range
      ORDER BY conf_range
    `).all();
    
    results.byConfidence = confStats;
  } catch (e) {
    results.byConfidence = [];
  }
  
  // 2. 按市场格局分析
  try {
    const regimeStats = db.prepare(`
      SELECT 
        buy_market_regime as regime,
        COUNT(*) as total,
        SUM(is_win) as wins,
        ROUND(AVG(profit_pct), 2) as avg_pnl,
        ROUND(SUM(is_win) * 100.0 / COUNT(*), 1) as win_rate
      FROM shundi_trade_feedback
      WHERE buy_market_regime IS NOT NULL
      GROUP BY regime
      ORDER BY regime
    `).all();
    
    results.byRegime = regimeStats;
  } catch (e) {
    results.byRegime = [];
  }
  
  // 3. 按卖出类型分析
  try {
    const sellTypeStats = db.prepare(`
      SELECT 
        sell_type,
        COUNT(*) as total,
        SUM(is_win) as wins,
        ROUND(AVG(profit_pct), 2) as avg_pnl,
        ROUND(SUM(is_win) * 100.0 / COUNT(*), 1) as win_rate
      FROM shundi_trade_feedback
      GROUP BY sell_type
      ORDER BY total DESC
    `).all();
    
    results.bySellType = sellTypeStats;
  } catch (e) {
    results.bySellType = [];
  }
  
  // 4. 按技术信号分析
  try {
    const techStats = db.prepare(`
      SELECT 
        tech_signal,
        COUNT(*) as total,
        SUM(is_win) as wins,
        ROUND(AVG(profit_pct), 2) as avg_pnl,
        ROUND(SUM(is_win) * 100.0 / COUNT(*), 1) as win_rate
      FROM shundi_trade_feedback
      WHERE tech_signal IS NOT NULL
      GROUP BY tech_signal
      ORDER BY total DESC
    `).all();
    
    results.byTechSignal = techStats;
  } catch (e) {
    results.byTechSignal = [];
  }
  
  // 5. 总体统计
  try {
    const overall = db.prepare(`
      SELECT 
        COUNT(*) as total_trades,
        SUM(is_win) as total_wins,
        ROUND(SUM(is_win) * 100.0 / COUNT(*), 1) as overall_win_rate,
        ROUND(AVG(CASE WHEN profit_pct > 0 THEN profit_pct END), 2) as avg_win,
        ROUND(AVG(CASE WHEN profit_pct < 0 THEN profit_pct END), 2) as avg_loss,
        ROUND(AVG(profit_pct), 2) as avg_pnl,
        ROUND(SUM(pnl), 2) as total_pnl
      FROM shundi_trade_feedback
    `).get();
    
    results.overall = overall;
  } catch (e) {
    results.overall = {};
  }
  
  return results;
}

/**
 * 参数自优化
 */
function optimizeTradingParams() {
  const analysis = analyzeParamEffectiveness();
  const optimizations = [];
  
  // 1. 置信度权重优化
  if (analysis.byConfidence && analysis.byConfidence.length > 0) {
    analysis.byConfidence.forEach(stat => {
      if (stat.total >= 10) { // 样本数>=10才优化
        let weight = 1.0;
        let reason = '';
        
        if (stat.win_rate < 35) {
          weight = 0.5;
          reason = `胜率${stat.win_rate}%过低,降权50%`;
        } else if (stat.win_rate < 45) {
          weight = 0.7;
          reason = `胜率${stat.win_rate}%偏低,降权30%`;
        } else if (stat.win_rate > 65) {
          weight = 1.3;
          reason = `胜率${stat.win_rate}%优秀,提权30%`;
        } else if (stat.win_rate > 55) {
          weight = 1.15;
          reason = `胜率${stat.win_rate}%良好,提权15%`;
        }
        
        if (weight !== 1.0) {
          try {
            db.prepare(`
              INSERT OR REPLACE INTO shundi_param_learning 
              (param_name, param_value, sample_count, win_count, win_rate, avg_pnl, weight, optimized_at, reason)
              VALUES ('confidence_range', ?, ?, ?, ?, ?, ?, datetime('now','+8 hours'), ?)
            `).run(stat.conf_range, stat.total, stat.wins, stat.win_rate, stat.avg_pnl, weight, reason);
            
            optimizations.push({ param: `confidence_${stat.conf_range}`, weight, reason });
          } catch (e) {}
        }
      }
    });
  }
  
  // 2. 市场格局优化
  if (analysis.byRegime && analysis.byRegime.length > 0) {
    analysis.byRegime.forEach(stat => {
      if (stat.total >= 10) {
        let weight = 1.0;
        let reason = '';
        
        if (stat.win_rate < 30) {
          weight = 0.0;
          reason = `${stat.regime}格局胜率${stat.win_rate}%极低,暂停买入`;
        } else if (stat.win_rate < 40) {
          weight = 0.5;
          reason = `${stat.regime}格局胜率${stat.win_rate}%偏低,降权50%`;
        } else if (stat.win_rate > 60) {
          weight = 1.2;
          reason = `${stat.regime}格局胜率${stat.win_rate}%良好,提权20%`;
        }
        
        if (weight !== 1.0) {
          try {
            db.prepare(`
              INSERT OR REPLACE INTO shundi_param_learning 
              (param_name, param_value, sample_count, win_count, win_rate, avg_pnl, weight, optimized_at, reason)
              VALUES ('market_regime', ?, ?, ?, ?, ?, ?, datetime('now','+8 hours'), ?)
            `).run(stat.regime, stat.total, stat.wins, stat.win_rate, stat.avg_pnl, weight, reason);
            
            optimizations.push({ param: `regime_${stat.regime}`, weight, reason });
          } catch (e) {}
        }
      }
    });
  }
  
  console.log(`[Phase4优化] 完成${optimizations.length}项参数优化`);
  
  return optimizations;
}

/**
 * 获取优化后的参数权重
 */
function getOptimizedWeights() {
  const weights = {
    confidence: {},
    regime: {}
  };
  
  try {
    const rows = db.prepare(`
      SELECT param_name, param_value, weight
      FROM shundi_param_learning
      WHERE weight != 1.0
    `).all();
    
    rows.forEach(row => {
      if (row.param_name === 'confidence_range') {
        weights.confidence[row.param_value] = row.weight;
      } else if (row.param_name === 'market_regime') {
        weights.regime[row.param_value] = row.weight;
      }
    });
  } catch (e) {}
  
  return weights;
}

/**
 * 应用学习权重到置信度
 */
function applyLearningWeight(confidence, marketRegime) {
  const weights = getOptimizedWeights();
  
  // 置信度区间权重
  const confRange = confidence < 60 ? '50-60' : confidence < 70 ? '60-70' : confidence < 80 ? '70-80' : '80+';
  const confWeight = weights.confidence[confRange] || 1.0;
  
  // 格局权重
  const regimeWeight = weights.regime[marketRegime] || 1.0;
  
  // 组合权重
  const finalWeight = confWeight * regimeWeight;
  
  // 应用到置信度
  return Math.round(confidence * finalWeight);
}

// 辅助函数(如果ml_models.mjs中已定义,这里不需要重复)
function calcRSI(prices, period = 14) {
  if (prices.length < period + 1) return 50;
  let gains = 0, losses = 0;
  for (let i = 1; i <= period; i++) {
    const change = prices[prices.length - i] - prices[prices.length - i - 1];
    if (change > 0) gains += change;
    else losses -= change;
  }
  const avgGain = gains / period;
  const avgLoss = losses / period || 0.001;
  const rs = avgGain / avgLoss;
  return 100 - (100 / (1 + rs));
}

function calcMACD(prices, fast = 12, slow = 26, signal = 9) {
  if (prices.length < slow + signal) return { macd: 0, signal: 0, hist: 0 };
  const ema = (data, period) => {
    const k = 2 / (period + 1);
    let ema = data[0];
    for (let i = 1; i < data.length; i++) ema = data[i] * k + ema * (1 - k);
    return ema;
  };
  const emaFast = prices.map((_, i) => ema(prices.slice(0, i + 1), fast));
  const emaSlow = prices.map((_, i) => ema(prices.slice(0, i + 1), slow));
  const macdLine = emaFast.map((f, i) => f - emaSlow[i]);
  const signalLine = macdLine.map((_, i) => ema(macdLine.slice(0, i + 1), signal));
  const last = prices.length - 1;
  return {
    macd: macdLine[last] || 0,
    signal: signalLine[last] || 0,
    hist: (macdLine[last] - signalLine[last]) || 0
  };
}

function calcMACDCross(prices, fast = 12, slow = 26, signal = 9) {
  if (prices.length < slow + signal + 5) return 0;
  const ema = (data, period) => {
    const k = 2 / (period + 1);
    let ema = data[0];
    for (let i = 1; i < data.length; i++) ema = data[i] * k + ema * (1 - k);
    return ema;
  };
  const lookback = Math.min(30, prices.length - 1);
  const macd历史 = [];
  for (let i = prices.length - lookback; i < prices.length; i++) {
    const fastEMA = ema(prices.slice(0, i + 1), fast);
    const slowEMA = ema(prices.slice(0, i + 1), slow);
    macd历史.push(fastEMA - slowEMA);
  }
  for (let i = macd历史.length - 2; i >= 0; i--) {
    const prev = macd历史[i], curr = macd历史[i + 1];
    if ((prev < 0 && curr >= 0) || (prev > 0 && curr <= 0)) {
      return curr > 0 ? 1 : -1;
    }
  }
  return 0;
}

function calcKDJ(highs, lows, closes, period = 9) {
  if (highs.length < period) return { k: 50, d: 50, j: 50 };
  const recentHighs = highs.slice(-period);
  const recentLows = lows.slice(-period);
  const highestHigh = Math.max(...recentHighs);
  const lowestLow = Math.min(...recentLows);
  const currentClose = closes[closes.length - 1];
  const rsv = highestHigh > lowestLow ? (currentClose - lowestLow) / (highestHigh - lowestLow) * 100 : 50;
  const k = rsv;
  const d = k;
  const j = 3 * k - 2 * d;
  return { k, d, j };
}

function calcBOLL(prices, period = 20, multiplier = 2) {
  if (prices.length < period) return { upper: prices[prices.length-1], mid: prices[prices.length-1], lower: prices[prices.length-1] };
  const recent = prices.slice(-period);
  const mid = recent.reduce((a, b) => a + b) / period;
  const std = Math.sqrt(recent.reduce((sum, p) => sum + Math.pow(p - mid, 2), 0) / period);
  return {
    upper: mid + multiplier * std,
    mid,
    lower: mid - multiplier * std
  };
}

/**
 * 【改造v2】舜帝智能选股主函数
 * 架构变更:尧帝只负责信号标注(打标签),舜帝独立综合评分决策
 * 舜帝从全市场量化筛选候选股,独立进行多维度评分,不依赖尧帝信号数量
 */

// ═══ TWAP智能拆单路由 ═══
function smartOrderRouter({ code, totalQty, totalBudget, direction }) {
  const qty = parseInt(totalQty) || 100;
  const budget = parseFloat(totalBudget) || qty * 10;
  const avgPrice = budget / qty;

  // 简单TWAP: 将订单分成3-5笔
  const sliceCount = qty <= 200 ? 3 : qty <= 1000 ? 5 : 8;
  const qtyPerSlice = Math.floor(qty / sliceCount);
  const budgetPerSlice = budget / sliceCount;
  const slices = [];

  for (let i = 0; i < sliceCount; i++) {
    const isLast = i === sliceCount - 1;
    slices.push({
      index: i + 1,
      qty: isLast ? qty - qtyPerSlice * (sliceCount - 1) : qtyPerSlice,
      budget: isLast ? budget - budgetPerSlice * (sliceCount - 1) : budgetPerSlice,
      interval: Math.round(60 + Math.random() * 120),
      timeLabel: `T+${i + 1}`
    });
  }

  return {
    strategy: 'twap',
    code,
    direction: direction || 'buy',
    totalQty: qty,
    totalBudget: budget,
    avgPrice,
    sliceCount,
    slices,
    impactPct: parseFloat((sliceCount * 0.05).toFixed(2)),
    estimatedTime: slices.reduce((s, sl) => s + sl.interval, 0),
    timestamp: Date.now()
  };
}

function smartStockSelection(count = 5, signalDirection = 'buy', filterMarket = true, period = 'manual', force = false) {
  // 【2026-05-20】手动模式自动强制选股
  const actualForce = force || period === 'manual';

  const periodLabel = period === 'morning' ? '早盘' : period === 'evening' ? '尾盘' : period === 'midday' ? '午盘' : '手动';
  console.log('[智能选股] ' + periodLabel + '选股开始, count=' + count + (actualForce ? ' (强制模式)' : ''));

  try {
    // 【修复】检查是否在交易时段(使用正确的函数名)
    if (!actualForce && !isTradingHours()) {
      console.log('[智能选股] 当前非交易时段, 暂停选股 (手动模式已强制)');
      return [];
    }

    // 获取上证指数了解大盘情况
    const indexRow = db.prepare("SELECT change_percent FROM stock_realtime WHERE code='sh000001' LIMIT 1").get();
    const indexChange = indexRow ? indexRow.change_percent : 0;

    // 获取市场统计数据
    const mktStats = db.prepare("SELECT up_count, total_count FROM market_stats ORDER BY id DESC LIMIT 1").get();
    const upRatio = mktStats ? (mktStats.up_count || 0) / Math.max(mktStats.total_count || 1, 1) : 0.5;

    // 大盘状态判断
    let marketRegime = 'neutral';
    if (indexChange <= -2 && upRatio < 0.2) marketRegime = 'crash';  // 需同时满足大跌+普跌
    else if (indexChange < -0.5 || upRatio < 0.35) marketRegime = 'bear';
    else if (indexChange > 0.8 && upRatio > 0.6) marketRegime = 'bull';

    // 崩盘时不选股
    if (marketRegime === 'crash') {
      console.log('[智能选股] 大盘崩盘, 暂停选股');
      return [];
    }

    // 获取候选股票池 - 使用ML预测的3日收益率排序
    // 【2026-05-20】改为按 ml_ensemble_score 排序(预测未来3天涨幅)
    // 【2026-06-05修复】l2_score是0-1小数，阈值改为0.68/0.66
    let candidates;
    if (signalDirection === 'buy') {
      candidates = db.prepare(`
        SELECT s.*, sr.price, sr.change_percent, yl.l2_score as ml_ensemble_score
        FROM stock_realtime sr
        LEFT JOIN stocks s ON s.code = sr.code
        LEFT JOIN yaodi_l2_cache yl ON yl.code = s.code
        WHERE yl.l2_score > 0.68
        ORDER BY yl.l2_score DESC
        LIMIT 200
      `).all();
    } else {
      candidates = db.prepare(`
        SELECT s.*, sr.price, sr.change_percent, yl.l2_score as ml_ensemble_score
        FROM stock_realtime sr
        LEFT JOIN stocks s ON s.code = sr.code
        LEFT JOIN yaodi_l2_cache yl ON yl.code = s.code
        WHERE yl.l2_score < 0.66
        ORDER BY yl.l2_score ASC
        LIMIT 200
      `).all();
    }

    if (!candidates || candidates.length === 0) {
      return [];
    }

    // 过滤并评分
    let scored = candidates.map(s => {
      let score = 50;
      const pct = s.change_percent || 0;

      // 涨跌评分: 涨幅越大分数越高
      if (pct > 5) score += 20;
      else if (pct > 2) score += 15;
      else if (pct > 0) score += 10;
      else if (pct > -2) score += 5;

      // 早盘追强势股, 尾盘捡超跌反弹
      if (period === 'morning' && pct > 3) score += 10;
      if (period === 'evening' && pct < -3) score += 10;

      // 排除ST股票
      if (s.name && s.name.includes('ST')) score -= 20;

      // 【优化】板块轮动感知:增加板块热度因子
      try {
        // 获取个股所属板块
        const sectorRow = db.prepare("SELECT sector_code FROM stock_fundamentals_v2 WHERE code = ? LIMIT 1").get(s.code);
        if (sectorRow && sectorRow.sector_code) {
          // 计算板块平均涨幅
          const sectorStats = db.prepare(`
            SELECT AVG(CAST(sr.change_percent AS REAL)) as avg_pct, COUNT(*) as cnt
            FROM stock_realtime sr
            JOIN stock_fundamentals_v2 sf ON sr.code = sf.code
            WHERE sf.sector_code = ? AND CAST(sr.change_percent AS REAL) IS NOT NULL
          `).get(sectorRow.sector_code);
          if (sectorStats && sectorStats.cnt >= 5) {
            const sectorAvgPct = sectorStats.avg_pct || 0;
            // 板块涨幅加成: 板块涨>2%加10分,涨>1%加5分
            if (sectorAvgPct > 2) score += 10;
            else if (sectorAvgPct > 1) score += 5;
            else if (sectorAvgPct < -1) score -= 5; // 弱势板块减分
          }
        }
      } catch (e) { /* 板块数据缺失时静默跳过 */ }

      return { ...s, score, final: score };
    });

    // 【修复】过滤指数(sh/sz开头)和科创板(688)和北交所(8开头)
    scored = scored.filter(s => {
      const code = s.code || '';
      // 过滤指数:sh/sz开头的代码(如 sh000001, sz399001)
      if (code.startsWith('sh') || code.startsWith('sz')) return false;
      // 过滤科创板
      if (code.startsWith('688')) return false;
      // 过滤北交所(8开头且长度为6位)
      if (code.startsWith('8') && code.length === 6) return false;
      return true;
    });

    // 过滤科创板和北交所(空值保护,二次过滤)
    if (filterMarket) {
      scored = scored.filter(s => s.code && !s.code.startsWith('688') && !s.code.startsWith('8'));
    }

    // 【2026-06-05修复】过滤停牌股：数据超过2天未更新视为停牌
    scored = scored.filter(s => {
      const updateTime = s.update_time || '';
      if (updateTime) {
        const ageMs = Date.now() - new Date(updateTime).getTime();
        const ageHours = ageMs / (1000 * 60 * 60);
        if (ageHours > 48) return false; // 48小时未更新视为停牌
      }
      return true;
    });

    // 过滤分数太低的(70分以下不买,提高选股质量)
    scored = scored.filter(s => s.final >= 70);

    // 按分数排序返回
    return scored
      .sort((a, b) => b.final - a.final)
      .slice(0, count);

  } catch(e) {
    console.error('智能选股错误:', e.message);
    return [];
  }
}


function kellyPosition(winRate, avgWin, avgLoss, atrPercent = null, confidence = null, recentTrend = null) {
  const p = winRate / 100;
  const q = 1 - p;
  const b = avgWin / Math.max(avgLoss, 0.01);

  // 凯利公式基础值
  let kelly = (p * b - q) / b;

  // 【优化v3】精细化凯利调整因子

  // 1. 波动率因子(ATR): 波动越大,凯利越低
  if (atrPercent != null && atrPercent > 0) {
    const atrFactor = Math.max(0.4, Math.min(1.0, 2.0 / (atrPercent + 1))); // ATR>2%时仓位降至40%
    kelly *= atrFactor;
  }

  // 2. 信心指数因子: 高置信度可适度提高
  if (confidence != null) {
    const confFactor = 0.8 + (confidence / 100) * 0.4; // 置信度0-100对应0.8-1.2
    kelly *= confFactor;
  }

  // 3. 近期趋势因子: 胜率上升趋势提高仓位
  if (recentTrend != null && recentTrend > 0.05) {
    kelly *= Math.min(1.3, 1 + recentTrend); // 趋势越好仓位越高
  } else if (recentTrend != null && recentTrend < -0.05) {
    kelly *= Math.max(0.7, 1 + recentTrend); // 趋势越差仓位越低
  }

  // 4. 基础安全系数: 四分凯利(0.25)更稳健
  kelly = Math.min(kelly * 0.25, 0.20);

  // 5. 市场环境调整
  const marketStats = db.prepare("SELECT * FROM market_stats ORDER BY id DESC LIMIT 1").get();
  if (marketStats) {
    const upRatio = (marketStats.up_count || 0) / Math.max(marketStats.total_count || 1, 1);
    if (upRatio < 0.35) kelly *= 0.7;       // 熊市降低仓位
    else if (upRatio > 0.65) kelly *= 1.2; // 牛市提高仓位
  }

  // 6. 动态范围调整: 高胜率时上限20%,低胜率时上限10%
  const maxKelly = p > 0.6 ? 0.20 : p > 0.5 ? 0.15 : 0.10;

  return Math.max(0.01, Math.min(maxKelly, kelly));
}

/**
 * 从尧帝分支获取策略统计数据
 */
function getStrategyStats(branchId) {
  try {
    const branch = db.prepare("SELECT * FROM yaodi_branch WHERE id = ?").get(branchId);
    if (!branch) return { winRate: 50, avgWin: 5, avgLoss: 3 };

    // 使用分支的准确率作为胜率
    const winRate = branch.accuracy || 50;

    // 估算盈亏比(基于演化等级)
    const avgWin = 5 + (branch.evolution_level || 1) * 0.5;
    const avgLoss = 3 + (10 - Math.min(branch.evolution_level || 1, 10)) * 0.2;

    return { winRate, avgWin, avgLoss, reliability: branch.reliability_score || 50 };
  } catch (e) {
    return { winRate: 50, avgWin: 5, avgLoss: 3 };
  }
}

// ═══════════════════════════════════════════════════════════════
// 改进2: ATR自适应止损系统
// ═══════════════════════════════════════════════════════════════

/**
 * 计算指数移动平均线 EMA
 */
function calcEMA(values, period) {
  if (!values || values.length < period) return values ? values[values.length - 1] : 0;
  const k = 2 / (period + 1);
  let ema = values.slice(0, period).reduce((s, v) => s + v, 0) / period;
  for (let i = period; i < values.length; i++) {
    ema = values[i] * k + ema * (1 - k);
  }
  return ema;
}

/**
 * 基于历史K线数据计算 ATR(不依赖代码)
 */
function calcATRHist(highs, lows, closes, period = 14) {
  if (highs.length < period + 1) return closes[closes.length - 1] * 0.02; // 默认2%波动
  const trs = [0];
  for (let i = 1; i < highs.length; i++) {
    trs.push(Math.max(
      highs[i] - lows[i],
      Math.abs(highs[i] - closes[i - 1]),
      Math.abs(lows[i] - closes[i - 1])
    ));
  }
  return trs.slice(-period).reduce((s, v) => s + v, 0) / period;
}

/**
 * 计算ATR(平均真实波幅)
 * 使用简化版本:基于日内波动
 */
function calculateATR(code, period = 14) {
  try {
    // 从实时数据估算ATR
    const stock = db.prepare(`
      SELECT price, high, low, pre_close
      FROM stock_realtime
      WHERE code = ?
    `).get(code);

    if (!stock || !stock.price) return stock?.price ? stock.price * 0.03 : 0.5;

    // 真实波幅计算
    const high = stock.high || stock.price;
    const low = stock.low || stock.price;
    let preClose = stock.pre_close;

    // 【BUGFIX-2026-04-25】pre_close=0 导致 ATR 计算异常
    // fallback: 查前一日K线收盘价
    if (!preClose || preClose === 0) {
      const yesterday = db.prepare(`
        SELECT close FROM stock_history
        WHERE code = ? AND date < date('now')
        ORDER BY date DESC LIMIT 1
      `).get(code);
      preClose = yesterday?.close || null;
    }
    // 【增强-2026-05-06】若仍然无preClose,用当前价替代(避免计算出荒谬的ATR)
    if (!preClose || preClose === 0) {
      preClose = stock.price;
    }

    const tr1 = high - low;
    const tr2 = Math.abs(high - preClose);
    const tr3 = Math.abs(low - preClose);
    const tr = Math.max(tr1, tr2, tr3);

    // ATR下限: 至少价格 * 1%,避免极小止损
    return Math.max(tr, stock.price * 0.01);
  } catch (e) {
    return 0.5;
  }
}

/**
 * ATR自适应止损价格
 */
/**
 * 改进3: 波动率自适应止损/止盈
 * 根据ATR占价格比例动态调整倍数
 * 【BUGFIX-舜帝止损】原2.0x基础止损过窄,634笔全亏→改为3.5x基础止损
 * - 高波动(ATR>3%): 宽止损(4.0x), 宽止盈(4.5x)
 * - 正常波动(1-3%): 标准止损(3.5x), 标准止盈(4.0x)
 * - 低波动(<1%): 适中止损(3.0x), 适中止盈(3.5x)
 */
const ATR_CONFIG = Object.freeze({
  STOP_MULTIPLIER: 8.0,   // 【调整2026-05-29】基础止损从5.0x→8.0x,避免正常波动被震出
  PROFIT_MULTIPLIER: 8.0, // 【调整2026-05-29】基础止盈从5.0x→8.0x,给仓位更多运行空间
  ADJUST_RANGE: 0.5,      // Q-Learning调整幅度
  HIGH_VOL_STOP: 6.0,    // 高波动(ATR>3%)宽止损
  NORM_VOL_STOP: 5.0,    // 正常波动(1-3%)标准止损
  LOW_VOL_STOP: 4.0,      // 低波动(<1%)紧止损
  HIGH_VOL_PROFIT: 6.0,  // 高波动宽止盈
  NORM_VOL_PROFIT: 5.0,  // 正常波动标准止盈
  LOW_VOL_PROFIT: 4.0,   // 低波动紧止盈
  STOP_FLOOR: 0.05,      // 止损最小百分比(5%强制底部保护)
  PROFIT_FLOOR: 0.05,      // 止盈最小5%（避免过早止盈）
  STABILITY_DAYS: 3,     // 持仓稳定期N天内不执行严格止损
  TRAILING_TRIGGER: 0.10, // 盈利超过10%后激活跟踪止损
  TRAILING_FLOOR: 0.10,   // 跟踪止损距高点不超10%（放宽）
  TAKE_PROFIT_THRESHOLD: 0.02, // 【调整2026-04-25】盈利>2%就开始考虑止盈(原5%过高)
});

function atrStopLoss(code, buyPrice, direction = 'long', opts = {}) {
  // opts: { currentPrice, peakPrice, holdDays, atr }
  try {
    const atr = opts.atr || calculateATR(code);
    const atrPct = atr / buyPrice;  // ATR占价格比例
    const baseMultiplier = ATR_CONFIG.STOP_MULTIPLIER;

    // Q-Learning动态止损倍数(根据最近市场状态自适应)
    const qState = buildMarketState();
    const qRow = Q_LEARNING.qTable[qState] || { buy: 0, sell: 0 };
    const qMarketQuality = Math.max(0, qRow.buy - qRow.sell); // Q-Learning评估的市场质量
    const qMultiplierAdj = Math.max(-0.5, Math.min(0.5, qMarketQuality * 0.2)); // ±0.5调整

    // 波动率自适应倍数
    let multiplier = baseMultiplier + qMultiplierAdj;  // 基础5.0x + Q-Learning调整
    if (atrPct > 0.03) {
      multiplier = ATR_CONFIG.HIGH_VOL_STOP + qMultiplierAdj;  // 高波动: 放宽止损到6.0x
    } else if (atrPct < 0.01) {
      multiplier = ATR_CONFIG.LOW_VOL_STOP + qMultiplierAdj;  // 低波动: 收紧到4.0x
    }

    // 【新增2026-04-25】稳定期保护:持仓<3天时,用更宽止损
    let floorPct = ATR_CONFIG.STOP_FLOOR; // 5%基础
    if (opts.holdDays !== undefined && opts.holdDays < ATR_CONFIG.STABILITY_DAYS) {
      floorPct = Math.min(0.10, 0.05 + (ATR_CONFIG.STABILITY_DAYS - opts.holdDays) * 0.02); // 新仓更宽:最多10%
    }

    let stopLoss = direction === 'long'
      ? Math.max(buyPrice * (1 - floorPct), buyPrice - atr * multiplier)
      : Math.min(buyPrice * (1 + floorPct), buyPrice + atr * multiplier);

    // 【新增2026-04-25】跟踪止损:盈利>10%后,止损跟随峰值
    // 盈利超过阈值时,止损从成本跟随到 峰值 - 一定比例
    const currentPrice = opts.currentPrice || buyPrice;
    const peakPrice = opts.peakPrice || currentPrice;
    const profitFromCost = (currentPrice - buyPrice) / buyPrice;
    if (profitFromCost >= ATR_CONFIG.TRAILING_TRIGGER && peakPrice > buyPrice) {
      // 跟踪止损:峰值回撤8%即触发(但不低于成本-10%)
      const trailingStop = peakPrice * (1 - ATR_CONFIG.TRAILING_FLOOR);
      const costFloor = buyPrice * (1 - ATR_CONFIG.TRAILING_TRIGGER); // 跟踪止损不低于成本-10%
      stopLoss = Math.max(costFloor, trailingStop);
    }

    return Math.max(0.01, parseFloat(stopLoss.toFixed(2)));
  } catch (e) {
    // 异常时用8%固定止损兜底
    return direction === 'long' ? buyPrice * 0.92 : buyPrice * 1.08;
  }
}

function atrTakeProfit(code, buyPrice, direction = 'long', opts = {}) {
  // opts: { currentPrice, peakPrice }
  try {
    const atr = opts.atr || calculateATR(code);
    const atrPct = atr / buyPrice;
    const baseMultiplier = ATR_CONFIG.PROFIT_MULTIPLIER;  // 5.0x 基础止盈

    // Q-Learning动态止盈倍数(市场好→宽止盈持长;市场差→紧止盈保盈)
    const qState = buildMarketState();
    const qRow = Q_LEARNING.qTable[qState] || { buy: 0, sell: 0 };
    const qBuyQuality = Math.max(0, qRow.buy); // Q-Learning对买入的信心
    const qTakeAdj = Math.max(-0.5, Math.min(1.0, qBuyQuality * 0.3)); // 信心高→宽止盈

    // 波动率自适应倍数
    let multiplier = baseMultiplier + qTakeAdj;
    if (atrPct > 0.03) {
      multiplier = ATR_CONFIG.HIGH_VOL_PROFIT + qTakeAdj;  // 高波动: 放宽止盈到6.0x
    } else if (atrPct < 0.01) {
      multiplier = ATR_CONFIG.LOW_VOL_PROFIT + qTakeAdj;  // 低波动: 收紧到4.0x
    }

    // 【优化 2026-05-07】优先使用L3动态止盈比例,其次用配置下限
    let floorPct = ATR_CONFIG.PROFIT_FLOOR; // 默认3%
    try {
      const l3Signal = db.prepare("SELECT take_profit_pct FROM yaodi_l3_signals WHERE code = ?").get(code);
      if (l3Signal && l3Signal.take_profit_pct > 0) {
        floorPct = l3Signal.take_profit_pct / 100; // 转小数
        multiplier = 0; // 有动态止盈%时不再用ATR倍数
      }
    } catch (_) { /* db未初始化时跳过 */ }

    // 【新增2026-04-25】盈利阈值:盈利<5%时不考虑止盈
    const currentPrice = opts.currentPrice || buyPrice;
    const profitFromCost = (currentPrice - buyPrice) / buyPrice;
    if (profitFromCost < ATR_CONFIG.TAKE_PROFIT_THRESHOLD) {
      // 盈利不足:止盈价 = 当前价 + 一个合理距离
      const profitTarget = direction === 'long'
        ? buyPrice * (1 + ATR_CONFIG.TAKE_PROFIT_THRESHOLD)
        : buyPrice * (1 - ATR_CONFIG.TAKE_PROFIT_THRESHOLD);
      return parseFloat(profitTarget.toFixed(2));
    }

    // 盈利充足时:用动态止盈%(优先)或ATR倍数计算目标价
    const takeProfit = direction === 'long'
      ? Math.max(buyPrice * (1 + floorPct), buyPrice + atr * multiplier)
      : Math.min(buyPrice * (1 - floorPct), buyPrice - atr * multiplier);

    return parseFloat(takeProfit.toFixed(2));
  } catch (e) {
    // 异常时用10%固定止盈兜底
    return direction === 'long' ? buyPrice * 1.10 : buyPrice * 0.90;
  }
}

// ═══════════════════════════════════════════════════════════════
// 改进3: 多账户协同系统
// ═══════════════════════════════════════════════════════════════

/**
 * 获取红后持仓信息
 */
function getRedqueenHoldings() {
  try {
    return db.prepare(`
      SELECT code, name, shares, avg_cost, current_price,
             profit_percent, market_value, source
      FROM holdings
      WHERE source = 'redqueen' OR source LIKE 'redqueen_%'
    `).all();
  } catch (e) {
    return [];
  }
}

/**
 * 多账户协同分析
 * 比较舜帝和红后的持仓差异,发现套利机会
 */
function multiAccountAnalysis() {
  const shundiHoldings = db.prepare("SELECT * FROM shundi_mock_holdings").all();
  const redqueenHoldings = getRedqueenHoldings();

  const analysis = {
    shundi: { count: shundiHoldings.length, value: 0, profit: 0 },
    redqueen: { count: redqueenHoldings.length, value: 0, profit: 0 },
    overlap: [], // 重叠持仓
    divergence: [], // 分歧持仓
    arbitrage: [] // 套利机会
  };

  // 计算舜帝统计
  shundiHoldings.forEach(h => {
    analysis.shundi.value += h.market_value || 0;
    analysis.shundi.profit += h.profit || 0;
  });

  // 计算红后统计
  redqueenHoldings.forEach(h => {
    analysis.redqueen.value += h.market_value || 0;
    analysis.redqueen.profit += h.profit || 0;
  });

  // 找出重叠和分歧
  const shundiCodes = new Set(shundiHoldings.map(h => h.code));
  const redqueenCodes = new Set(redqueenHoldings.map(h => h.code));

  // 重叠持仓
  shundiHoldings.forEach(sh => {
    if (redqueenCodes.has(sh.code)) {
      const rh = redqueenHoldings.find(h => h.code === sh.code);
      if (rh) {
        const shPct = sh.profit_percent || 0;
        const rhPct = rh.profit_percent || 0;
        analysis.overlap.push({
          code: sh.code,
          name: sh.name,
          shundi: { shares: sh.shares, profit: shPct },
          redqueen: { shares: rh.shares, profit: rhPct },
          divergence: Math.abs(shPct - rhPct)
        });
      }
    }
  });

  // 舜帝独有持仓
  shundiHoldings.forEach(sh => {
    if (!redqueenCodes.has(sh.code)) {
      analysis.divergence.push({
        code: sh.code,
        name: sh.name,
        holder: 'shundi',
        shares: sh.shares,
        profit: sh.profit_percent || 0
      });
    }
  });

  // 红后独有持仓
  redqueenHoldings.forEach(rh => {
    if (!shundiCodes.has(rh.code)) {
      analysis.divergence.push({
        code: rh.code,
        name: rh.name,
        holder: 'redqueen',
        shares: rh.shares,
        profit: rh.profit_percent || 0
      });
    }
  });

  // 发现套利机会:两账户收益差异大的股票
  analysis.overlap.forEach(o => {
    if (o.divergence > 5) {
      analysis.arbitrage.push({
        code: o.code,
        name: o.name,
        type: o.shundi.profit > o.redqueen.profit ? 'sell_shundi' : 'sell_redqueen',
        reason: `收益差异${o.divergence.toFixed(1)}%`
      });
    }
  });

  return analysis;
}

// ═══════════════════════════════════════════════════════════════
// 改进4: 回测对比系统
// ═══════════════════════════════════════════════════════════════

/**
 * 计算账户绩效
 */
function calculateAccountPerformance(accountType) {
  // 【核查修复】已平仓交易只统计卖出类型(买入=未平仓≠亏损)
  const allTrades = accountType === 'shundi'
    ? db.prepare("SELECT * FROM shundi_mock_trades WHERE status = 'filled'").all()
    : db.prepare("SELECT * FROM shundi_mock_trades WHERE status = 'filled' AND source LIKE 'redqueen%'").all();

  // 已平仓交易 = sell/止盈/止损(买入是开仓,不是平仓)
  const closedTrades = allTrades.filter(t => ['sell', '止盈', 'ATR止盈', '止损'].includes(t.type));

  if (allTrades.length === 0) {
    return { trades: 0, winRate: 0, totalPnl: 0, avgPnl: 0, maxWin: 0, maxLoss: 0, sharpe: 0 };
  }

  let wins = 0, totalPnl = 0, maxWin = 0, maxLoss = 0;
  const returns = [];

  allTrades.forEach(t => {
    const pnl = Number(t.pnl) || 0;
    totalPnl += pnl;
    const amount = Number(t.amount) || 0;
    if (amount > 0) {
      returns.push(pnl / amount);
    }
  });

  // 只用已平仓交易计算胜率
  closedTrades.forEach(t => {
    const pnl = Number(t.pnl) || 0;
    if (pnl > 0) {
      wins++;
      maxWin = Math.max(maxWin, pnl);
    } else {
      maxLoss = Math.min(maxLoss, pnl);
    }
  });

  // 胜率 = 盈利卖出/总卖出次数(不含买入)
  const winRate = closedTrades.length > 0 ? (wins / closedTrades.length * 100) : 0;
  const avgPnl = closedTrades.length > 0 ? totalPnl / closedTrades.length : 0;

  // 夏普比率(简化版)
  const avgReturn = returns.length > 0 ? returns.reduce((a, b) => a + b, 0) / returns.length : 0;
  const stdReturn = returns.length > 1
    ? Math.sqrt(returns.reduce((s, r) => s + Math.pow(r - avgReturn, 2), 0) / returns.length)
    : 0.01;
  const sharpe = stdReturn > 0 ? avgReturn / stdReturn * Math.sqrt(252) : 0;

  return {
    trades: allTrades.length,
    closedTrades: closedTrades.length,
    wins,
    losses: closedTrades.length - wins,
    winRate: Number(winRate.toFixed(1)),
    totalPnl: Number(totalPnl.toFixed(2)),
    avgPnl: Number(avgPnl.toFixed(2)),
    maxWin: Number(maxWin.toFixed(2)),
    maxLoss: Number(maxLoss.toFixed(2)),
    sharpe: Number(sharpe.toFixed(2))
  };
}

/**
 * 舜帝vs红后对比报告
 */
function compareShundiVsRedqueen() {
  const shundiPerf = calculateAccountPerformance('shundi');
  const redqueenPerf = calculateAccountPerformance('redqueen');
  const multiAnalysis = multiAccountAnalysis();

  return {
    shundi: shundiPerf,
    redqueen: redqueenPerf,
    comparison: {
      betterWinRate: shundiPerf.winRate > redqueenPerf.winRate ? 'shundi' : 'redqueen',
      betterSharpe: parseFloat(shundiPerf.sharpe) > parseFloat(redqueenPerf.sharpe) ? 'shundi' : 'redqueen',
      betterPnl: parseFloat(shundiPerf.totalPnl) > parseFloat(redqueenPerf.totalPnl) ? 'shundi' : 'redqueen'
    },
    multiAccount: multiAnalysis,
    recommendation: generateRecommendation(shundiPerf, redqueenPerf, multiAnalysis)
  };
}

/**
 * 生成投资建议
 */
function generateRecommendation(shundi, redqueen, multi) {
  const recommendations = [];

  // 根据胜率差异调整信号权重
  if (parseFloat(shundi.winRate) > parseFloat(redqueen.winRate) + 10) {
    recommendations.push({
      type: 'weight_adjust',
      action: '增加舜帝信号权重',
      reason: `舜帝胜率${shundi.winRate}%显著高于红后${redqueen.winRate}%`
    });
  } else if (parseFloat(redqueen.winRate) > parseFloat(shundi.winRate) + 10) {
    recommendations.push({
      type: 'weight_adjust',
      action: '增加红后信号权重',
      reason: `红后胜率${redqueen.winRate}%显著高于舜帝${shundi.winRate}%`
    });
  }

  // 套利机会
  if (multi.arbitrage.length > 0) {
    recommendations.push({
      type: 'arbitrage',
      action: '执行账户间套利',
      reason: `发现${multi.arbitrage.length}个套利机会`
    });
  }

  // 仓位建议
  if (multi.shundi.value > multi.redqueen.value * 1.5) {
    recommendations.push({
      type: 'position_balance',
      action: '考虑平衡两账户仓位',
      reason: '舜帝仓位过重,风险集中'
    });
  }

  return recommendations;
}

