/**
 * 计算文本情绪得分(-1 到 +1)- 改进版
 * 负面词每个-0.3,正面词每个+0.2,上限±1
 */
function calcTextSentiment(text) {
  const lower = text.toLowerCase();
  let score = 0;
  for (const kw of NEGATIVE_KEYWORDS) { if (lower.includes(kw)) score -= 0.3; }
  for (const kw of POSITIVE_KEYWORDS) { if (lower.includes(kw)) score += 0.2; }
  return Math.max(-1, Math.min(1, score));
}

/**
 * 核心检测函数:扫描全市场找黑天鹅事件
 * 每30秒由 yaodiAutoEvolve 或 shundiAutoCycle 触发
 */
async function checkBlackSwanEvents() {
  if (blackSwanRunning) return;
  blackSwanRunning = true;
  const now = bjDate();
  if (now - lastBlackSwanCheck < 30000) { blackSwanRunning = false; return; } // 至少30秒间隔
  lastBlackSwanCheck = now;

  try {
    const stocks = getCachedData();
    const newEvents = [];

    // ── 检测维度1:新闻情绪突变 ─────────────────────
    // 【铁律】数据必须来自真实来源,无伪造,无8767依赖
    try {
      // 直接调用内部新闻获取(多源自愈,本地行情+东财+腾讯,100%真实)
      const news = await fetchAllNews().catch(() => []);

      for (const n of news.slice(0, 10)) {
        const title = n.title || '';
        // 优先用 API 原始情绪值,否则用关键词计算
        const sentiment = n.sentiment != null ? n.sentiment : calcTextSentiment(title);
        // 修复BUG: 移除随机后缀用新闻标题哈希实现去重,同条新闻30分钟内不重复触发
        const titleHash = (n.title || 'no-title').slice(0, 50).split('').reduce((a, c) => ((a << 5) - a + c.charCodeAt(0)) | 0, 0);
        const newsId = `news_${titleHash}_${Math.floor(Date.now() / 1800000)}`;

        // 强负面新闻(情绪 ≤ -0.5)或高敏感关键词 → 黑天鹅
        const isSensitive = NEGATIVE_KEYWORDS.some(kw => title.includes(kw));
        if ((sentiment <= -0.5 || isSensitive) && !dismissedBlackSwans.has(newsId)) {
          const severity = (sentiment <= -0.8 || title.includes('退市') || title.includes('破产') || title.includes('闪崩'))
            ? 'RED' : sentiment <= -0.6 ? 'ORANGE' : 'YELLOW';
          const expireMs = severity === 'RED' ? 60 * 60 * 1000 : severity === 'ORANGE' ? 30 * 60 * 1000 : 10 * 60 * 1000;
          // 修复BUG: expireAt必须用Date.now()+数值毫秒,不能用bjDate()字符串+数字
          newEvents.push({
            id: newsId,
            type: 'news',
            severity,
            score: Math.round(Math.max(Math.abs(sentiment), isSensitive ? 50 : 0) * 100),
            title: `📰 黑天鹅预警:${n.source || '市场快讯'}`,
            message: title.slice(0, 100),
            affectedStocks: extractStocksFromNews(title),
            action: severity === 'RED' ? 'forbidden_buy' : severity === 'ORANGE' ? 'strong_sell' : 'watch',
            expireAt: Date.now() + expireMs,
            time: now,
            impactPeriod: severity === 'RED' ? '1-3天' : severity === 'ORANGE' ? '当日至3天' : '当日',
            _newsSource: n._source || 'unknown'
          });
        }
      }
    } catch(e) {
      console.warn('⚠️ [黑天鹅] 新闻获取失败(非交易日正常):', e.message.slice(0, 100));
    }

    // ── 检测维度2:价格异动 ─────────────────────────
    // 关键逻辑:价格恢复 → 事件自动过期消失
    const recoveredCodes = new Set(); // 价格已恢复正常,不再触发
    stocks.forEach(stock => {
      const changePct = stock.changePercent || 0;
      const stockId = `price_${stock.code}`;

      if (dismissedBlackSwans.has(stockId)) return;

      // 暴跌检测(跌幅>7%算黑天鹅)
      if (changePct <= -7) {
        const severity = changePct <= -10 ? 'RED' : 'ORANGE';
        // 价格异动:15分钟自动过期(若价格恢复,下次检测自动消失)
        newEvents.push({
          id: stockId,
          type: 'price_crash',
          severity,
          score: Math.min(100, Math.round(Math.abs(changePct) * 8)),
          title: `💥 价格闪崩:${stock.name}`,
          message: `代码 ${stock.code} 跌幅 ${changePct.toFixed(2)}%,注意止损`,
          affectedStocks: [stock.code],
          action: severity === 'RED' ? 'emergency_stop' : 'strong_sell',
          time: now,
          expireAt: now + 15 * 60 * 1000,
          impactPeriod: severity === 'RED' ? '3-5天' : '1-2天',
          _recoverBelow: -5
        });
      }
      // 暴涨预警(涨幅>9%,接近涨停)
      else if (changePct >= 9) {
        newEvents.push({
          id: stockId,
          type: 'price_surge',
          severity: 'YELLOW',
          score: Math.min(100, Math.round(changePct * 7)),
          title: `🚀 价格暴涨:${stock.name}`,
          message: `代码 ${stock.code} 涨幅 ${changePct.toFixed(2)}%,追高风险极大`,
          affectedStocks: [stock.code],
          action: 'forbidden_buy',
          time: now,
          expireAt: now + 15 * 60 * 1000,
          impactPeriod: '当日',
          _recoverBelow: 7
        });
      } else {
        // 价格已恢复到正常区间 → 标记该股票为已恢复,下次不再触发
        // 检查 recentBlackSwans 中是否有该股票的价格事件
        const existingCrash = recentBlackSwans.find(e => e.id === stockId && e.type === 'price_crash');
        if (existingCrash) {
          // 价格已恢复,事件将在 expireAt 后自动消失
          // 若下次检测时价格仍在正常区间,旧事件过期后不会生成新事件 → 真正消失
        }
      }
    });

    // ── 检测维度3:舜帝持仓股异动优先检测 ───────────
    const shundiStocks = db.prepare('SELECT code, name FROM shundi_mock_holdings').all();
    const shundiCodes = new Set(shundiStocks.map(s => s.code));

    // 给舜帝持仓的异动股票加权(更紧急)
    newEvents.forEach(ev => {
      const isShundiHolding = ev.affectedStocks?.some(c => shundiCodes.has(c));
      if (isShundiHolding && ev.score < 60) {
        ev.score = Math.min(100, ev.score + 20); // 舜帝持仓额外+20分
        if (ev.score >= 60) ev.severity = ev.severity === 'YELLOW' ? 'ORANGE' : ev.severity;
      }
    });

    // ── 去重合并,同类型事件不重复推送 ───────────────
    // 关键:已过期事件允许重新触发(价格可能再次异动)
    const now_for_cleanup = Date.now();
    recentBlackSwans = recentBlackSwans.filter(ev => {
      if (ev.expireAt && now_for_cleanup > ev.expireAt) return false;
      return true;
    });

    const deduped = newEvents.filter(ev => {
      // 查找是否已有活跃事件(未过期)
      const existing = recentBlackSwans.find(r => r.id === ev.id);
      if (existing) return false; // 已有活跃事件,不重复
      return true;
    });

    // 合并到全局列表(保留最近20条)
    recentBlackSwans = [...deduped, ...recentBlackSwans].slice(0, 20);
    // 同步写入完整历史(保留所有事件,含已过期)
    deduped.forEach(ev => {
      blackSwanHistory.unshift({ ...ev, status: 'active' });
      // 【铁律合规】持久化到 DB(服务重启后可恢复历史)
      try {
        db.prepare(`
          INSERT OR IGNORE INTO black_swan_events
          (event_type, severity, stock_code, stock_name, description, price_change, detected_at, resolution)
          VALUES (?, ?, ?, ?, ?, ?, ?, 'active')
        `).run(
          ev.type || 'news',
          ev.severity || 'YELLOW',
          ev.affectedStocks?.[0] || null,
          null,
          ev.message || ev.title || '',
          null,
          typeof ev.time === 'number' ? bjISO(new Date(ev.time)) : bjISO()
        );
      } catch(e) { /* black_swan_events 表不存在静默 */ }
    });
    blackSwanHistory = blackSwanHistory.slice(0, 500);

    // 严重事件 → 触发舜帝止损检查
    const criticalEvents = deduped.filter(ev => ev.severity === 'RED');
    if (criticalEvents.length > 0) {
      console.log(`🚨 检测到 ${criticalEvents.length} 个严重黑天鹅事件,触发舜帝止损检查`);
      // 通知舜帝对相关持仓执行止损(通过事件队列,不阻塞)
      setImmediate(() => checkStopLossForBlackSwan(criticalEvents));
    }

    if (deduped.length > 0) {
      console.log(`⚠️ 黑天鹅检测:${deduped.length} 个新事件 (RED=${deduped.filter(e=>e.severity==='RED').length} / ORANGE=${deduped.filter(e=>e.severity==='ORANGE').length} / YELLOW=${deduped.filter(e=>e.severity==='YELLOW').length})`);
    }

  } catch(err) {
    console.error('黑天鹅检测错误:', err.message);
  } finally {
    blackSwanRunning = false;
  }
}

/**
 * 从新闻标题中提取可能的股票代码
 */
function extractStocksFromNews(text) {
  const codes = [];
  // 匹配6位股票代码
  const matches = text.match(/\b[0-9]{6}\b/g);
  if (matches) codes.push(...matches);
  return [...new Set(codes)];
}

/**
 * 黑天鹅事件触发舜帝止损
 */
function checkStopLossForBlackSwan(events) {
  events.forEach(ev => {
    ev.affectedStocks?.forEach(code => {
      const holding = db.prepare('SELECT * FROM shundi_mock_holdings WHERE code = ?').get(code);
      if (holding && holding.shundi_price) {
        const currentPrice = getCachedData().find(s => s.code === code)?.price || holding.shundi_price;
        const loss = (currentPrice - holding.shundi_price) / holding.shundi_price * 100;
        if (loss < -5) {
          console.log(`🚨 黑天鹅止损:${code} 当前亏损 ${loss.toFixed(1)}%,建议立即止损`);
          // 记录紧急止损信号到日志
          db.prepare(`
            INSERT INTO shundi_backtest_history (stock_code, stock_name, action, price, shares, total_amount, profit, signal_type, created_at)
            VALUES (?, ?, '止损触发', ?, 0, 0, ?, 'black_swan_emergency', ?)
          `).run(code, holding.name, currentPrice, loss, bjNow());
        }
      }
    });
  });
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// 尧帝对抗训练 · 条件触发系统
// 触发决策:尧帝根据系统状态自动判断是否需要对抗训练
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

// 对抗训练运行状态
let adversarialRunning = false;
let adversarialLastTrigger = null;    // 上次触发原因
let adversarialCooldown = 0;          // 冷却计数(防止频繁触发)
let adversarialTrainingCount = 0;     // 累计训练次数
let adversarialLastResult = null;     // 上次训练结果(用于回滚)

/**
 * 尧帝核心判断函数:评估是否需要触发对抗训练
 * 返回 { shouldTrigger: bool, reason: string, severity: 'low'|'medium'|'high' }
 */
function shouldTriggerAdversarial() {
  // 冷却中:每次 yaodiAutoEvolve 执行后冷却-1,至少冷却3次才能再触发
  if (adversarialCooldown > 0) {
    adversarialCooldown--;
    return { shouldTrigger: false, reason: `冷却中(${adversarialCooldown}/3)`, severity: 'low' };
  }

  const now = bjDate();
  const reasons = [];
  let maxSeverity = 'low';

  // ── 条件1:准确率下滑检测 ──────────────────────────
  // 比较最近30次演化的准确率变化趋势
  const recentEvolutions = db.prepare(`
    SELECT accuracy_before, accuracy_after, created_at
    FROM evolution_history
    ORDER BY id DESC LIMIT 30
  `).all();

  if (recentEvolutions.length >= 10) {
    const mid = Math.floor(recentEvolutions.length / 2);
    const firstHalfAvg = recentEvolutions.slice(mid).reduce((s, r) => s + r.accuracy_after, 0) / mid;
    const secondHalfAvg = recentEvolutions.slice(0, mid).reduce((s, r) => s + r.accuracy_after, 0) / mid;
    const trend = secondHalfAvg - firstHalfAvg; // 负数=下滑

    if (trend < -2) {
      reasons.push(`准确率下滑${trend.toFixed(1)}%`);
      maxSeverity = 'medium';
    }
    if (trend < -5) {
      reasons.push(`⚠️准确率严重下滑${trend.toFixed(1)}%`);
      maxSeverity = 'high';
    }
  }

  // ── 条件2:市场环境剧变检测 ────────────────────────
  // market_sentiment 从 yaodi_main 读取,值域 -100~100
  const main = db.prepare('SELECT market_sentiment FROM yaodi_main WHERE id = 1').get();
  const sentiment = main?.market_sentiment || 0;
  const absSentiment = Math.abs(sentiment);

  if (absSentiment > 60) {
    const env = sentiment > 0 ? '极端贪婪' : '极端恐惧';
    reasons.push(`市场${env}(${sentiment.toFixed(1)})`);
    maxSeverity = maxSeverity === 'high' ? 'high' : 'medium';
  }
  if (absSentiment > 80) {
    reasons.push(`🚨市场极度${sentiment > 0 ? '贪婪' : '恐惧'}(${sentiment.toFixed(1)})`);
    maxSeverity = 'high';
  }

  // ── 条件3:演化陷入局部最优检测 ───────────────────
  // 连续N次演化,新分支准确率都在±2%范围内波动 → 演化停滞
  if (recentEvolutions.length >= 15) {
    const lastN = recentEvolutions.slice(0, 15).map(r => r.accuracy_after);
    const avg = lastN.reduce((s, v) => s + v, 0) / lastN.length;
    const variance = lastN.reduce((s, v) => s + (v - avg) ** 2, 0) / lastN.length;
    const stdDev = Math.sqrt(variance);

    if (stdDev < 3.0) {
      reasons.push(`演化停滞(stdDev=${stdDev.toFixed(2)})`);
      maxSeverity = maxSeverity === 'high' ? 'high' : 'medium';
    }
  }

  // ── 条件4:分支质量稀释检测 ───────────────────────
  // 高分分支(≥80%)占比低于50%时,系统质量下降
  const qualityStats = db.prepare(`
    SELECT
      COUNT(*) as total,
      SUM(CASE WHEN accuracy >= 80 THEN 1 ELSE 0 END) as high_quality,
      AVG(accuracy) as avg_acc
    FROM yaodi_branch WHERE active = 1
  `).get();

  if (qualityStats && qualityStats.total > 0) {
    const highQualityRatio = qualityStats.high_quality / qualityStats.total;
    if (highQualityRatio < 0.5) {
      reasons.push(`高分分支占比仅${(highQualityRatio * 100).toFixed(1)}%`);
      maxSeverity = maxSeverity === 'high' ? 'high' : 'medium';
    }
  }

  // 至少有一个中/高严重性原因才触发
  const shouldTrigger = maxSeverity !== 'low' || reasons.length >= 2;
  const reason = reasons.length > 0 ? reasons.join(' | ') : '系统健康,无需对抗训练';

  return { shouldTrigger, reason: reason || '系统健康', severity: maxSeverity };
}

/**
 * 尧帝执行一次完整的对抗训练周期
 * 包括:生成样本 → 训练分支 → 评估效果 → 效果差则回滚
 */
async function runAdversarialCycle(triggerReason) {
  if (adversarialRunning) {
    console.log('🛡️ 对抗训练跳过:上次训练仍在进行中');
    return { success: false, error: '训练中' };
  }

  adversarialRunning = true;
  adversarialTrainingCount++;
  adversarialLastTrigger = triggerReason;

  const preAccuracy = parseFloat(
    db.prepare('SELECT AVG(accuracy) as avg FROM yaodi_branch WHERE active = 1').get()?.avg || 75
  );

  console.log(`🛡️ 对抗训练开始(触发原因: ${triggerReason})`);
  console.log(`   训练前平均准确率: ${preAccuracy.toFixed(2)}%`);

  // 1. 生成对抗样本(从最近演化失败案例中提取)
  const recentFailures = db.prepare(`
    SELECT * FROM evolution_history
    WHERE accuracy_after < accuracy_before - 5
    ORDER BY id DESC LIMIT 20
  `).all();

  const generatedSamples = [];
  recentFailures.forEach(f => {
    const desc = `强化样本: ${f.evolution_type}演化后准确率${f.accuracy_after.toFixed(1)}%<${f.accuracy_before.toFixed(1)}%`;
    db.prepare(`
      INSERT INTO adversarial_samples (type, description, accuracy_impact, created_at)
      VALUES (?, ?, ?, ?)
    `).run('auto_generated', desc, f.accuracy_after - f.accuracy_before, bjNow());
    generatedSamples.push({ parent: f.parent_id, impact: f.accuracy_after - f.accuracy_before });
  });

  // 2. 选择顶级分支进行定向强化
  const targets = db.prepare(`
    SELECT id, name, accuracy, evolution_level
    FROM yaodi_branch
    WHERE active = 1
    ORDER BY accuracy DESC
    LIMIT 15
  `).all();

  let improved = 0;
  const preAccuracyMap = new Map(); // 【修复】保存训练前准确率用于精确回滚
  const trainedBranches = []; // 【修复】只统计被训练的分支
  let degraded = 0;

  targets.forEach(branch => {
    const trainChance = 0.3 + (branch.evolution_level / 100);
    if (Math.random() < trainChance) {
      preAccuracyMap.set(branch.id, branch.accuracy); // 保存训练前准确率
      const resistance = 0.3 + Math.random() * 0.5; // 0.3~0.8
      // 对抗样本带来的提升 = 样本影响 × (1-抗性) × 0.5
      const sampleImpact = generatedSamples.length > 0
        ? generatedSamples[Math.floor(Math.random() * generatedSamples.length)].impact : 0.5;
      const improvement = sampleImpact * (1 - resistance) * 0.3;

      const oldAcc = branch.accuracy;
      const newAcc = Math.max(55, Math.min(95, oldAcc + improvement));

      if (newAcc > oldAcc) improved++;
      else degraded++;

      db.prepare('UPDATE yaodi_branch SET accuracy = ? WHERE id = ?').run(newAcc, branch.id);
      trainedBranches.push({ id: branch.id, oldAcc, newAcc }); // 记录已训练分支
    }
  });

  // 3. 评估效果
  const postAccuracy = parseFloat(
    db.prepare('SELECT AVG(accuracy) as avg FROM yaodi_branch WHERE active = 1').get()?.avg || 75
  );
  const accuracyDelta = postAccuracy - preAccuracy;

  const result = {
    success: true,
    triggerReason,
    preAccuracy: preAccuracy.toFixed(2),
    postAccuracy: postAccuracy.toFixed(2),
    accuracyDelta: accuracyDelta.toFixed(2),
    improved,
    degraded,
    samplesGenerated: generatedSamples.length,
    totalTrainingCount: adversarialTrainingCount
  };

  // 【修复4】只有当退化分支 > 提升分支+3 时才回滚(原:accuracyDelta < -1)
  const shouldRollback = degraded > improved + 3 || accuracyDelta < -2;
  if (shouldRollback) {
    console.log(`⚠️ 对抗训练效果差(improved=${improved}, degraded=${degraded}, Δ=${accuracyDelta.toFixed(2)}%),回滚至训练前`);
    // 回滚:使用保存的训练前准确率
    const rolledBackCount = trainedBranches.length;
    trainedBranches.forEach(b => {
      db.prepare('UPDATE yaodi_branch SET accuracy = ? WHERE id = ?')
        .run(preAccuracyMap.get(b.id), b.id);
    });
    result.rolledBack = true;
    result.rolledBackCount = rolledBackCount;
    result.message = `效果退化已回滚${rolledBackCount}个分支`;
  } else {
    console.log(`✅ 对抗训练完成: ${improved}分支提升, ${degraded}分支下降, 准确率变化${accuracyDelta > 0 ? '+' : ''}${accuracyDelta.toFixed(2)}%`);
    adversarialCooldown = 3; // 成功训练后冷却3次 yaodiAutoEvolve 周期
  }

  adversarialLastResult = result;
  adversarialRunning = false;
  return result;
}

// API: 手动分发任务
// API: 清理历史任务

// 尧帝自动进化周期(每5分钟执行一次)
let yaodiEvolveRunning = false; // 防止重叠执行阻塞事件循环

const AE_TIMEOUT_MS = 30 * 1000; // 30秒超时保护

// 带超时的 yaodiAutoEvolve 包装器
function yaodiAutoEvolveWithTimeout() {
  if (yaodiEvolveRunning) {
    console.log('[yaodiAutoEvolve] 跳过: 上轮尚未完成');
    return;
  }
  yaodiEvolveRunning = true;
  const startMs = Date.now();
  yaodiAutoEvolve()
    .catch(err => console.error('尧帝自动进化错误:', err.message))
    .finally(() => {
      yaodiEvolveRunning = false;
      const elapsed = Date.now() - startMs;
      if (elapsed > AE_TIMEOUT_MS) {
        console.warn(`[yaodiAutoEvolve] ⚠️ 执行耗时 ${(elapsed/1000).toFixed(1)}s,超过${AE_TIMEOUT_MS/1000}s阈值`);
      }
    });
}

async function yaodiAutoEvolve() {
  console.log("[TRACE-AE-START] yaodiAutoEvolve called");
  if (!yaodiEvolutionRunning) return;
  try {
    // ── 同步尧帝感知子系统状态 ─────────────────────────────────────
    YaodiBrain.systemModules.yaodiAgent.status    = 'online';
    YaodiBrain.systemModules.yaodiAgent.health    = 100;
    YaodiBrain.systemModules.yaodiAgent.lastCheck = bjISO();

    YaodiBrain.systemModules.branchManager.status    = 'online';
    YaodiBrain.systemModules.branchManager.health    = 100;
    YaodiBrain.systemModules.branchManager.lastCheck = bjISO();

    YaodiBrain.systemModules.evolutionEngine.status    = evolutionInterval !== null ? 'online' : 'standby';
    YaodiBrain.systemModules.evolutionEngine.health    = evolutionInterval !== null ? 100 : 50;
    YaodiBrain.systemModules.evolutionEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.shundiEngine.status    = shundiRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.shundiEngine.health    = shundiRunning ? 100 : 0;
    YaodiBrain.systemModules.shundiEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.redqueenEngine.status    = redqueenRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.redqueenEngine.health    = redqueenRunning ? 100 : 0;
    YaodiBrain.systemModules.redqueenEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.dataSource.status    = 'online';
    YaodiBrain.systemModules.dataSource.health    = 100;
    YaodiBrain.systemModules.dataSource.lastCheck = bjISO();

    YaodiBrain.systemModules.learningSystem.status    = 'online';
    YaodiBrain.systemModules.learningSystem.health    = 100;
    YaodiBrain.systemModules.learningSystem.lastCheck = bjISO();

    YaodiBrain.systemModules.watchdog.status    = watchdogInterval !== null ? 'online' : 'offline';
    YaodiBrain.systemModules.watchdog.health    = watchdogInterval !== null ? 100 : 0;
    YaodiBrain.systemModules.watchdog.lastCheck = bjISO();

    YaodiBrain.systemModules.stopLossMonitor.status    = stopLossMonitorRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.stopLossMonitor.health    = stopLossMonitorRunning ? 100 : 0;
    YaodiBrain.systemModules.stopLossMonitor.lastCheck = bjISO();

    YaodiBrain.systemModules.dataServer.status    = 'online';
    YaodiBrain.systemModules.dataServer.health    = 100;
    YaodiBrain.systemModules.dataServer.lastCheck = bjISO();

    YaodiBrain.systemModules.database.status    = 'online';
    YaodiBrain.systemModules.database.health    = 100;
    YaodiBrain.systemModules.database.lastCheck = bjISO();

    YaodiBrain.systemModules.frontend.status    = 'online';
    YaodiBrain.systemModules.frontend.health    = 100;
    YaodiBrain.systemModules.frontend.lastCheck = bjISO();

    // ── 0. 黑天鹅事件检测 ───────────────────────────
    await checkBlackSwanEvents();

    // ── 1. 尧帝决策:是否需要对抗训练 ───────────────
    const decision = shouldTriggerAdversarial();
    if (decision.shouldTrigger) {
      console.log(`🛡️ 尧帝决策:需要对抗训练 → ${decision.reason} [${decision.severity}]`);
      await runAdversarialCycle(decision.reason);
    } else {
      console.log(`✅ 尧帝决策:跳过对抗训练 → ${decision.reason}`);
    }

    console.log('🧬 尧帝自动进化开始...');

    // ── 联动1:弱点导向演化(对抗训练报告 → 提升演化优先级)──────────────
    try {
      db.exec(`CREATE TABLE IF NOT EXISTS adversarial_report (id INTEGER PRIMARY KEY AUTOINCREMENT, current_accuracy REAL, adversarial_accuracy REAL, gap REAL, sample_count INTEGER, created_at TEXT DEFAULT (datetime('now','+8 hours')))`);
      const adReport = db.prepare(`SELECT * FROM adversarial_report ORDER BY id DESC LIMIT 1`).get();
      if (adReport) {
        const recentAcc = adReport.current_accuracy || 0;
        const adAcc = adReport.adversarial_accuracy || 0;
        const weakness = adAcc < recentAcc - 5; // 对抗后准确率下降超过5%,说明有弱点
        if (weakness) {
          console.log(`🎯 [弱点导向] 对抗准确率(${adAcc.toFixed(1)}%)低于基准(${recentAcc.toFixed(1)}%),gap=${(recentAcc - adAcc).toFixed(1)}%,提升演化强度`);
        }
      }
    } catch (e) { /* adversarial_report 表可能不存在,静默跳过 */ }

    // 1. 获取当前活跃的高分分支作为进化种子
    // 【数据修复】优先用 branch_performance 中的真实胜率选分支(win_rate 历史小数格式 / 新数据百分比格式统一转换)
    const topBranches = db.prepare(`
      SELECT b.*, COALESCE(bp.real_win, b.win_rate, 50) as real_win
      FROM yaodi_branch b
      LEFT JOIN (
        SELECT branch_name,
               SUM(trade_count) as total_trades,
               SUM(trade_count * CASE WHEN win_rate < 1 THEN win_rate * 100 ELSE win_rate END) / NULLIF(SUM(trade_count), 0) as real_win
        FROM branch_performance
        GROUP BY branch_name
      ) bp ON bp.branch_name = b.name
      WHERE b.active = 1
        AND (bp.total_trades >= 5 OR b.trades >= 5)
      ORDER BY real_win DESC, b.trades DESC
      LIMIT 10
    `).all();

    // 2. 【多样性保护】按真实胜率从每种模型类型各选 Top 1,防止一个家族垄断演化资源
    // 【优化】并行演化: 最多同时演化5个分支(原来是顺序执行3个)
    const evolvedThisRound = new Set();
    const pendingEvolutions = [];

    // 收集所有待演化分支
    for (const branch of topBranches) {
      if (pendingEvolutions.length >= 5) break;  // 收集最多5个
      const baseName = branch.name.replace(/_v\d+$/, '');
      if (evolvedThisRound.has(baseName)) continue;  // 同模型只能演化一次
      evolvedThisRound.add(baseName);
      pendingEvolutions.push({ branchId: branch.id, isTech: branch.is_tech_model === 1, name: branch.name });
    }

    // 【优化】并行执行演化
    if (pendingEvolutions.length > 0) {
      console.log(`🚀 [并行演化] 启动${pendingEvolutions.length}个分支并行演化`);
      const startTime = Date.now();

      // 使用Promise.all并行执行演化(setImmediate让出事件循环,防止阻塞HTTP)
      const results = await Promise.all(
        pendingEvolutions.map(({ branchId, isTech }) =>
          new Promise((resolve) => {
            setImmediate(() => {
              try {
                const result = evolveBranch(branchId, isTech);
                resolve({ success: result.success, newId: result.newId, newName: result.newName, newAccuracy: result.newAccuracy });
              } catch (e) {
                resolve({ success: false, error: e.message });
              }
            });
          })
        )
      );

      const elapsed = Date.now() - startTime;
      const successCount = results.filter(r => r.success).length;
      results.forEach((r, i) => {
        if (r.success) {
          evolvedThisRound.add(pendingEvolutions[i].name);
          console.log(`✅ 分支进化成功: ${pendingEvolutions[i].name} -> ${r.newId} (准确率 ${r.newAccuracy?.toFixed(1)}%)`);
        }
      });
      console.log(`🚀 [并行演化] 完成${successCount}/${pendingEvolutions.length}个,耗时${elapsed}ms`);
    }

    // 3. 【数据修复】重新激活有真实交易数据的优质分支(放宽条件)
    const reactivated = db.prepare(`
      UPDATE yaodi_branch
      SET active = 1, disabled_reason = NULL
      WHERE active = 0
      AND evolution_level >= 8
      AND (
        -- 有真实交易且胜率 >= 50% 的分支(门槛从100笔降至10笔)
        id IN (
          SELECT DISTINCT b.id FROM yaodi_branch b
          JOIN branch_performance bp ON bp.branch_name = b.name
          GROUP BY b.id
          HAVING SUM(bp.trade_count) >= 10
             AND SUM(bp.trade_count * CASE WHEN bp.win_rate < 1 THEN bp.win_rate * 100 ELSE bp.win_rate END) / NULLIF(SUM(bp.trade_count), 0) >= 50
        )
        -- 或者有历史交易的分支(门槛从5000笔降至10笔)
        OR trades >= 10
        -- 或者准确率>=95%的优质分支
        OR accuracy >= 95
      )
    `).run();

    if (reactivated.changes > 0) {
      console.log(`🔄 重新激活 ${reactivated.changes} 个优质分支`);
    }

    // 4. 更新尧帝主状态
    const stats = db.prepare(`
      SELECT
        COUNT(*) as total,
        SUM(CASE WHEN active = 1 THEN 1 ELSE 0 END) as active,
        MAX(evolution_level) as max_level,
        AVG(CASE WHEN active = 1 THEN accuracy END) as avg_accuracy,
        COALESCE(SUM(trades), 0) as branch_trades
      FROM yaodi_branch
    `).get();

    // ── 数据源1:从舜帝已平仓卖出交易读取真实胜率 ──
    // 【P1修复】只有卖出交易才有pnl意义,买入交易pnl=0不计入
    const shundiStats = db.prepare(`
      SELECT COUNT(*) as cnt, SUM(CASE WHEN pnl > 0 THEN 1 ELSE 0 END) as wins,
             SUM(pnl) as total_pnl
      FROM shundi_mock_trades
      WHERE type IN ('sell','卖出','止损','止盈','shundi_stoploss','部分止盈')
    `).get();

    // ── 数据源2:从 yaodi_branch 读取尧帝分支统计 ──
    const branchStats = db.prepare(`
      SELECT AVG(accuracy) as avg_acc, AVG(win_rate) as avg_wr,
             COALESCE(SUM(trades), 0) as total_trades
      FROM yaodi_branch WHERE active = 1
    `).get();

    // 重新计算 active_days
    const firstEvo = db.prepare("SELECT created_at FROM evolution_history ORDER BY created_at ASC LIMIT 1").get();
    const now = new Date();
    let activeDays = 9;
    if (firstEvo && firstEvo.created_at) {
      const first = new Date(firstEvo.created_at);
      activeDays = Math.max(1, Math.ceil((now - first) / (1000 * 60 * 60 * 24)));
    }

    // ── 指标计算:尧帝胜率综合舜帝真实交易×70% + 分支平均胜率×30% ──
    // 【P1修复】有真实交易时以舜帝真实胜率为主要依据
    // 1) shundiWinRate = 舜帝真实卖出交易胜率
    const shundiWinRate = shundiStats?.cnt > 0
      ? parseFloat(((shundiStats.wins / shundiStats.cnt) * 100).toFixed(1))
      : 50.0;
    // 2) realWinRate = 尧帝综合胜率(舜帝×70% + 分支×30%)
    const branchWinRate = parseFloat((branchStats?.avg_wr || 60).toFixed(1));
    const realWinRate = parseFloat((shundiWinRate * 0.7 + branchWinRate * 0.3).toFixed(1));
    // 3) accuracy = 尧帝分支的平均准确率
    const branchAvgAcc = parseFloat((branchStats?.avg_acc || 60).toFixed(1));
    // 4) avg_return = 舜帝分支平均盈利率(百分比,非金额)
    const branchPerfStats = db.prepare('SELECT AVG(profit_rate) as avg, MIN(profit_rate) as min FROM branch_performance').get();
    const shundiAvgReturn = branchPerfStats?.avg != null
      ? parseFloat(branchPerfStats.avg.toFixed(4))
      : 0;
    // 5) max_drawdown = 舜帝最大单次回撤(百分比)
    const shundiMaxDD = branchPerfStats?.min != null
      ? parseFloat(branchPerfStats.min.toFixed(4))
      : -5;
    // 6) win_count = 舜帝盈利次数
    const shundiWinCount = shundiStats?.wins || 0;
    // 7) total_trades = 舜帝实际交易笔数(shundi_mock_trades)
    const actualTrades = db.prepare('SELECT COUNT(*) as c FROM shundi_mock_trades').get()?.c || 0;
    // 8) sharpe_ratio = 基于分支性能的合理值(【BUGFIX】SQLite无STDDEV,改为JS实现)
    const perfRows = db.prepare("SELECT profit_rate FROM branch_performance WHERE profit_rate IS NOT NULL").all();
    const cnt = perfRows.length;
    const avg = cnt > 0 ? perfRows.reduce((s, r) => s + r.profit_rate, 0) / cnt : 0;
    const variance = cnt > 1 ? perfRows.reduce((s, r) => s + (r.profit_rate - avg) ** 2, 0) / (cnt - 1) : 0;
    const sd = Math.sqrt(variance);
    const shundiSharpe = cnt > 1 && sd > 0
      ? parseFloat((avg / sd).toFixed(2))
      : (avg > 0 ? 1.5 : 0.5);

    // 【P0修复】yaodi_main 统计含义明确:win_rate=尧帝综合胜率,accuracy=尧帝准确率,avg_return=舜帝平均净盈亏
    db.prepare(`
      UPDATE yaodi_main
      SET accuracy = ?,
          win_rate = ?,
          total_trades = ?,
          max_drawdown = ?,
          avg_return = ?,
          win_count = ?,
          sharpe_ratio = ?,
          evolution_speed = ?,
          active_days = ?,
          last_evolution = ?
      WHERE id = 1
    `).run(
      branchAvgAcc,                           // accuracy = 尧帝分支准确率
      realWinRate,                            // win_rate = 尧帝综合胜率
      actualTrades,                           // total_trades = 舜帝实际交易笔数
      shundiMaxDD,                            // max_drawdown = 最大单次回撤(%)
      shundiAvgReturn,                        // avg_return = 分支平均盈利率(%)
      shundiWinCount,                         // win_count = 舜帝盈利次数
      shundiSharpe,                           // sharpe_ratio = 夏普比率
      Math.min(Math.max(1, stats.max_level || 50), 100),
      activeDays,                             // active_days
      bjNow()                                 // last_evolution
    );
    // 【BUGFIX】确保写入后不超过100,防止进程重启后再次被污染
    db.prepare('UPDATE yaodi_main SET evolution_speed = MIN(evolution_speed, 100) WHERE id=1').run();
    const afterUpdate = db.prepare('SELECT accuracy, win_rate, total_trades, avg_return, win_count FROM yaodi_main WHERE id=1').get();
    console.log('[DB验证] acc='+afterUpdate?.accuracy+' win='+afterUpdate?.win_rate+' trades='+afterUpdate?.total_trades);

    console.log(`🧬 尧帝进化完成: 活跃分支${stats.active}/${stats.total}, 最高Lv.${stats.max_level} | 舜帝胜率=${shundiWinRate}% | 总交易=${(shundiStats?.cnt||0)+(stats.branch_trades||0)}`);

  // 【P2-1】每100次演化保存一次版本快照
  const evoCount = db.prepare('SELECT COUNT(*) as c FROM evolution_history').get()?.c || 0;
  if (evoCount % 100 === 0 && evoCount > 0) {
    try {
      const versionId = 'v' + Math.floor(evoCount / 100) * 100;
      const existing = db.prepare('SELECT id FROM yaodi_version_history WHERE version = ?').get(versionId);
      if (!existing) {
        db.prepare(`
          INSERT INTO yaodi_version_history (version, accuracy, evolution_count, branch_count, active_branches, created_at)
          VALUES (?, ?, ?, ?, ?, ?)
        `).run(versionId, parseFloat(branchAvgAcc.toFixed(1)), evoCount, stats.total, stats.active, bjNow());
        console.log(`📸 版本快照已保存: ${versionId} acc=${branchAvgAcc.toFixed(1)}% branches=${stats.active}/${stats.total}`);
      }
    } catch (e) { console.error('版本快照保存失败:', e.message); }
  }

  // 【P2-2】分支淘汰:增强版 - 多维度淘汰无效分支
  try {
    // 1. 淘汰低准确率且有交易的分支(原有逻辑)
    const toRetire1 = db.prepare(`
      UPDATE yaodi_branch SET active = 0, disabled_reason = '低准确率淘汰', disabled_time = ?
      WHERE active = 1 AND accuracy < 30 AND trades > 10
    `).run(bjNow());

    // 2. 【新增】淘汰长期无交易且低准确率的分支(超过1000次演化周期无交易)
    const evoCount = db.prepare('SELECT COUNT(*) as c FROM evolution_history').get()?.c || 0;
    if (evoCount > 1000 && stats.active > 5000) {
      // 保留top 100高质量分支,其余无交易的逐步淘汰
      const toRetire2 = db.prepare(`
        UPDATE yaodi_branch SET active = 0, disabled_reason = '长期无交易淘汰', disabled_time = ?
        WHERE active = 1 AND trades < 5 AND accuracy < 60
        AND id NOT IN (SELECT id FROM yaodi_branch WHERE active=1 ORDER BY accuracy DESC LIMIT 500)
        LIMIT 100
      `).run(bjNow());
      if (toRetire2.changes > 0) {
        console.log(`🗑️ 淘汰 ${toRetire2.changes} 个长期无交易分支(保留500高质量)`);
      }
    }

    // 3. 【新增】演化历史清理:保留最近10万条,删除更早的历史
    if (evoCount > 100000) {
      const toDelete = db.prepare(`
        DELETE FROM evolution_history WHERE id NOT IN (
          SELECT id FROM evolution_history ORDER BY id DESC LIMIT 100000
        )
      `).run();
      if (toDelete.changes > 0) {
        console.log(`🗑️ 清理 ${toDelete.changes} 条演化历史(保留最近10万条)`);
      }
    }

    if (toRetire1.changes > 0) {
      console.log(`🗑️ 淘汰 ${toRetire1.changes} 个低准确率分支(<30%)`);
    }

    // 4. 【P2增强】定期物理删除disabled分支(而非只标记active=0)
    //    保留最近disabled_time的50条用于调试,其余永久删除
    const disabledCount = db.prepare("SELECT COUNT(*) as c FROM yaodi_branch WHERE active=0").get()?.c || 0;
    if (disabledCount > 100) {
      const keepDisabled = 50;
      const deleteOld = db.prepare(`
        DELETE FROM yaodi_branch WHERE active = 0 AND id NOT IN (
          SELECT id FROM yaodi_branch WHERE active=0 ORDER BY disabled_time DESC LIMIT ?
        )
      `).run(keepDisabled);
      if (deleteOld.changes > 0) {
        console.log(`🗑️ 物理删除 ${deleteOld.changes} 条已归档分支(保留${keepDisabled}条)`);
      }
    }

    // 5. 【P2增强】清理过期branch_performance记录
    const perfCount = db.prepare("SELECT COUNT(*) as c FROM branch_performance").get()?.c || 0;
    if (perfCount > 5000) {
      const deletePerf = db.prepare(`
        DELETE FROM branch_performance WHERE id NOT IN (
          SELECT id FROM branch_performance ORDER BY updated_at DESC LIMIT 5000
        )
      `).run();
      if (deletePerf.changes > 0) {
        console.log(`🗑️ 清理 ${deletePerf.changes} 条过期分支性能记录(保留5000条)`);
      }
    }
  } catch (e) { console.error('分支淘汰失败:', e.message); }

    // ── 联动2:演化后质量门禁(准确率 < 55% → 自动触发对抗训练)──────────
    const finalAccuracy = stats.avg_accuracy || shundiWinRate || 60;
    if (finalAccuracy < 55) {
      console.log(`🛡️ [质量门禁] 演化后准确率 ${finalAccuracy}% < 55%,自动触发对抗训练...`);
      try {
        adversarialTraining();
      } catch (adErr) {
        console.error('❌ 质量门禁触发对抗训练失败:', adErr.message);
      }
    }

  } catch (err) {
    console.error('尧帝自动进化错误:', err);
  }
}

// 启动尧帝进化引擎
function startYaodiEvolution() {
  // P0修复: 启动时加载Q-Learning
  loadQLearningFromDB();
  // 每5分钟保存Q-Learning
  setInterval(saveQLearningToDB, 5 * 60 * 1000);
  if (yaodiEvolutionTimer) clearInterval(yaodiEvolutionTimer);
  yaodiEvolutionRunning = true;
  yaodiEvolutionTimer = setInterval(yaodiAutoEvolveWithTimeout, 5 * 60 * 1000); // 每5分钟
  setTimeout(yaodiAutoEvolveWithTimeout, 3000); // 3秒后首次执行

  // 【P0修复】尧帝信号定时重生成:独立于演化计数,确保信号永不过期
  const YAODI_SIGNAL_INTERVAL = 5 * 60 * 1000; // 每5分钟检查一次
  let yesterdayDate = '';

  function yaodiSignalTimer() {
    try {
      // 【优化】每天开盘前强制生成新信号(避免信号过期)
      const today = bjDate(); // 北京时间日期,非UTC
      if (today !== yesterdayDate) {
        // 新的一天,强制生成信号
        console.log(`[尧帝信号] 📅 新交易日开始,强制刷新信号...`);
        yesterdayDate = today;
        generateTradingSignals();
      }

      // 1. 检查过期信号并续期
      const expiredCount = db.prepare("SELECT COUNT(*) as c FROM trade_signals WHERE expires_at < ?").get(bjNow()).c;
      if (expiredCount > 0) {
        console.log(`[尧帝信号] 检测到${expiredCount}条过期信号,重新生成...`);
        generateTradingSignals();
      }
      // 2. 【P1修复】主动从 V2Core 推送最新 L3 信号到舜帝(每5分钟刷新)
      if (yaodiV2Core) {
        try {
          const v2Signals = yaodiV2Core.getL3Signals ? yaodiV2Core.getL3Signals() : [];
          if (v2Signals.length > 0) {
            const buySignals = v2Signals.filter(s => s.signal_status === 'buy');
            for (const s of buySignals.slice(0, 10)) {
              // 先查是否存在(包括已删除的),避免用户主动删除后被自动复活
              // 【已关闭】自动加入收藏股(add_source='yaodi_v2_timer')
              // const existingAny = db.prepare('SELECT id, user_deleted FROM user_stock_pool WHERE code=?').get(s.code);
              // if (!existingAny) {
              //   db.prepare(`INSERT INTO user_stock_pool (code, name, add_time, add_source, is_favorite, price, pre_close, change_percent, update_time, user_deleted)
              //     VALUES (?, ?, datetime('now'), 'yaodi_v2_timer', 1, ?, ?, ?, datetime('now'), 0)`)
              //     .run(s.code, s.name || '', parseFloat(s.price) || 0, parseFloat(s.pre_close) || 0, parseFloat(s.change_percent) || 0);
              // } else if (existingAny.user_deleted === 1) {
              //   console.log(`[尧帝→收藏] ${s.code} 已被用户删除,跳过自动添加`);
              // }
              // user_deleted=0 的已在收藏中,无需操作
              // 【P0修复】检查重复信号:同一股票48小时内已推送则跳过,避免重复买入
              const recentSig = db.prepare("SELECT id, expires_at FROM trade_signals WHERE code=? AND signal='buy' AND source='yaodi_v2_timer' AND created_at > ?").get(s.code, bjPast(2));
              if (recentSig) {
                console.log(`[尧帝V2→舜帝] ${s.code} 48小时内已有买入信号,跳过推送`);
                continue;
              }
              // 【P0修复】推送时携带实时价格,确保舜帝有有效价格执行买入
              const rtPrice = db.prepare("SELECT price FROM stock_realtime WHERE code = ?").get(s.code)?.price || s.price || 0;
              // 【优化】置信度动态化计算:基础置信度 + 技术指标因子
              // 【BUGFIX 2026-05-08】兼容confidence两种格式:小数(0.42)和百分数(42)
              const rawConf = s.confidence || 0.5;
              const baseConf = rawConf > 1 ? rawConf : rawConf * 100; // >1视为百分数,否则为小数
              // 技术指标因子
              const atr = s.atr || 0;
              const price = rtPrice || s.price || 0;
              const atrFactor = atr > 0 && price > 0 ? Math.min(atr / price * 10, 1.5) : 1.0; // 波动率因子
              // L2排名因子(排名越靠前置信度越高)
              const l2Rank = s.l2_rank || 50;
              const rankFactor = Math.max(0.8, 1.2 - l2Rank / 100);
              // 综合置信度
              const conf = Math.round(Math.min(95, Math.max(50, baseConf * atrFactor * rankFactor)));
              // 【修复】最低置信度从30%提高到50%,匹配舜帝质量要求,避免低质信号污染
              // yaodiSignalTimer: V2Core.getL3Signals()已做L3层筛选,直接推送所有buy信号
              db.prepare(`INSERT INTO trade_signals (code, name, signal, confidence, price, source, reason, created_at, expires_at)
                  VALUES (?, ?, 'buy', ?, ?, 'yaodi_v2_timer', 'v2_l3', ?, ?)`)
                  .run(s.code, s.name || '', conf, rtPrice, bjNow(), bjFuture(24));
              console.log(`[尧帝V2→舜帝] 推送信号: ${s.code} ${s.name || ''} 置信度${conf}% 价格¥${rtPrice}`);
            }
            console.log(`[尧帝V2→舜帝] yaodiSignalTimer 推送${buySignals.length}条V2信号`);
          } else {
            // 【P0修复 2026-06-08】L3缓存为空时(非交易时段Scheduler不执行L3),从L2缓存高分股票生成信号
            // 确保舜帝始终有可用信号,避免尧帝→舜帝闭环断裂
            const l2Fallback = db.prepare(`
              SELECT l2.code, COALESCE(l1.name, l2.name) as name, l2.l2_score, l2.ml_ensemble_score,
                     rt.price, rt.change_percent
              FROM yaodi_l2_cache l2
              LEFT JOIN yaodi_l1_cache l1 ON l2.code = l1.code
              LEFT JOIN stock_realtime rt ON l2.code = rt.code
              WHERE l2.l2_score > 0.68
                AND (rt.price IS NULL OR (rt.price > 1 AND rt.price < 200))
                AND l2.code NOT LIKE '688%' AND l2.code NOT LIKE '689%'
              ORDER BY l2.l2_score DESC LIMIT 20
            `).all();
            const heldCodes = db.prepare("SELECT code FROM shundi_mock_holdings").all().map(r => r.code);
            let l2PushCount = 0;
            for (const s of l2Fallback) {
              if (heldCodes.includes(s.code)) continue;
              const recentSig = db.prepare("SELECT id FROM trade_signals WHERE code=? AND signal='buy' AND source='yaodi_l2_fallback' AND created_at > ?").get(s.code, bjPast(24));
              if (recentSig) continue;
              const rtPrice = s.price || 0;
              if (rtPrice <= 0) continue;
              // 置信度: L2分数映射到50-75范围(保守估计,不如L3信号质量高)
              const conf = Math.round(Math.min(75, Math.max(50, s.l2_score * 90)));
              const mlScore = (s.ml_ensemble_score || 0).toFixed(3);
              db.prepare(`INSERT INTO trade_signals (code, name, signal, confidence, price, source, reason, created_at, expires_at)
                  VALUES (?, ?, 'buy', ?, ?, 'yaodi_l2_fallback', 'l2_high_score', ?, ?)`)
                  .run(s.code, s.name || '', conf, rtPrice, bjNow(), bjFuture(24));
              l2PushCount++;
              console.log(`[尧帝L2→舜帝] 回退信号: ${s.code} ${s.name || ''} 置信度${conf}% L2=${s.l2_score.toFixed(3)} ML=${mlScore}`);
            }
            if (l2PushCount > 0) console.log(`[尧帝L2→舜帝] L3为空,从L2缓存回退推送${l2PushCount}条信号`);
          }
        } catch (e) { console.warn('[尧帝V2→舜帝] 推送失败:', e.message); }
      }
    } catch(e) { console.error('[尧帝信号] 定时器错误:', e.message); }
    setTimeout(yaodiSignalTimer, YAODI_SIGNAL_INTERVAL);
  }
  setTimeout(yaodiSignalTimer, 60000); // 60秒后启动信号定时器
  console.log('🧬 尧帝独立进化引擎已启动 (每5分钟进化一次)');
  // 联动4:同时启动对抗训练自动扫描
  startAdversarialAutoScan();
}

// 停止尧帝进化引擎
function stopYaodiEvolution() {
  yaodiEvolutionRunning = false;
  if (yaodiEvolutionTimer) {
    clearInterval(yaodiEvolutionTimer);
    yaodiEvolutionTimer = null;
  }
  if (adversarialAutoInterval) {
    clearInterval(adversarialAutoInterval);
    adversarialAutoInterval = null;
  }
  // 🔧 修复EPIPE: 不用console.log(向已关闭stdout写入会抛EPIPE)
  try {
    const fs = require('fs');
    fs.writeFileSync(path.join(PROJECT_ROOT, 'logs', 'yaodi.log'), `\n[${new Date().toISOString()}] 🛑 尧帝进化引擎已停止`, { flag: 'a' });
  } catch(e) {}
}

// ── 联动4:对抗训练自动扫描定时器(每30分钟检测一次)──────────────────────
let adversarialAutoInterval = null;

function startAdversarialAutoScan() {
  if (adversarialAutoInterval) clearInterval(adversarialAutoInterval);
  adversarialAutoInterval = setInterval(() => {
    try {
      const adReport = db.prepare(`SELECT * FROM adversarial_report ORDER BY id DESC LIMIT 1`).get();
      const adCount = db.prepare(`SELECT COUNT(*) as c FROM adversarial_samples`).get();
      const total = adCount?.c || 0;

      if (!adReport || total < 50) {
        console.log(`🔍 [对抗自动扫描] 样本不足(${total}个),触发对抗训练...`);
        adversarialTraining();
      } else if (adReport) {
        // 【修复】只要对抗准确率低于基准就训练(原来是-8%才触发,现在-5%)
        const weakness = adReport.adversarial_accuracy < adReport.current_accuracy - 5;
        if (weakness) {
          console.log(`🔍 [对抗自动扫描] 对抗准确率(${adReport.adversarial_accuracy.toFixed(1)}%)低于基准(${adReport.current_accuracy.toFixed(1)}%),触发对抗训练...`);
          adversarialTraining();
        }
      }
    } catch (e) {
      // adversarial_report 可能尚未创建,静默忽略
    }
  }, 10 * 60 * 1000);
  console.log('🛡️ 对抗训练自动扫描已启动(每30分钟检测一次)');
}

function stopAdversarialAutoScan() {
  if (adversarialAutoInterval) {
    clearInterval(adversarialAutoInterval);
    adversarialAutoInterval = null;
    console.log('🛑 对抗训练自动扫描已停止');
  }
}

// ── 【延迟交易执行】开市时自动执行pending状态的延迟交易 ──
async function executeDeferredTrades() {
  try {
    // 【规则1】零点自动清空昨天的 pending 记录(非今天创建的记录)
    const today = bjISO();
    const yesterdayPending = db.prepare(`SELECT COUNT(*) as cnt FROM deferred_trades WHERE status = 'pending' AND date(created_at) < date(?)`).get(today);
    if (yesterdayPending && yesterdayPending.cnt > 0) {
      db.prepare(`DELETE FROM deferred_trades WHERE status = 'pending' AND date(created_at) < date(?)`).run(today);
      addRedQueenLog(`🧹 [延迟交易] 已清空 ${yesterdayPending.cnt} 条昨天的待执行记录`, 'warning');
    }

    const pending = db.prepare(`SELECT * FROM deferred_trades WHERE status = 'pending' ORDER BY priority DESC, created_at ASC`).all();
    if (pending.length === 0) return;

    console.log(`[延迟交易] 发现 ${pending.length} 笔待执行交易`);

    for (const trade of pending) {
      try {
        // 根据交易类型执行
        if (trade.direction === '买入') {
          const price = getRealTimePrice(trade.code);
          if (!price || price <= 0) {
            addRedQueenLog(`⚠️ 延迟买入失败:${trade.name} 无法获取实时价格`);
            continue;
          }
          const shares = Math.floor((trade.amount || 10000) / price / 100) * 100;
          if (shares < 100) {
            addRedQueenLog(`⚠️ 延迟买入失败:${trade.name} 金额不足以买入100股`);
            continue;
          }
          const cost = shares * price;
          // 执行买入
          db.prepare(`INSERT INTO shundi_mock_holdings (code, name, shares, avg_cost, current_price, market_value, profit, profit_percent, update_time, strategy, source, kelly_ratio, buy_date, yaodi_branch_id)
            VALUES (?, ?, ?, ?, ?, ?, 0, 0, ?, 'deferred', ?, 0, ?, ?)`).run(
            trade.code, trade.name, shares, price, price, cost, bjNow(), trade.reason || '延迟交易', bjNow(), trade.yaodi_branch_id
          );
          db.prepare(`INSERT INTO shundi_mock_trades (order_id, code, name, action, shares, price, amount, strategy, yaodi_branch_id, timestamp)
            VALUES (?, ?, ?, '买入', ?, ?, ?, 'deferred', ?, ?)`).run(
            `DEF_BUY_${trade.code}_${Date.now()}`, trade.code, trade.name, shares, price, cost, trade.yaodi_branch_id, bjNow()
          );
          db.prepare(`UPDATE deferred_trades SET status = 'executed', executed_at = ? WHERE rowid = ?`).run(bjNow(), trade.rowid);
          addRedQueenLog(`✅ 延迟买入执行:${trade.name} ${shares}股@${price}`);
        }
        else if (trade.direction === '卖出') {
          const holding = db.prepare(`SELECT * FROM shundi_mock_holdings WHERE code = ?`).get(trade.code);
          if (!holding) {
            addRedQueenLog(`⚠️ 延迟卖出失败:${trade.code} 无持仓`);
            db.prepare(`UPDATE deferred_trades SET status = 'failed', executed_at = ? WHERE rowid = ?`).run(bjNow(), trade.rowid);
            continue;
          }
          const price = getRealTimePrice(trade.code);
          if (!price || price <= 0) {
            addRedQueenLog(`⚠️ 延迟卖出失败:${trade.name} 无法获取实时价格`);
            continue;
          }
          const shares = Math.min(trade.shares || holding.shares, holding.shares);
          const revenue = shares * price;
          const profit = revenue - shares * holding.avg_cost;
          const profitPercent = (profit / (shares * holding.avg_cost) * 100).toFixed(2);
          // 执行卖出
          if (shares >= holding.shares) {
            db.prepare(`DELETE FROM shundi_mock_holdings WHERE code = ?`).run(trade.code);
          } else {
            db.prepare(`UPDATE shundi_mock_holdings SET shares = shares - ?, market_value = (shares - ?) * current_price, update_time = ? WHERE code = ?`).run(shares, shares, bjNow(), trade.code);
          }
          db.prepare(`INSERT INTO shundi_mock_trades (order_id, code, name, action, shares, price, amount, strategy, yaodi_branch_id, timestamp)
            VALUES (?, ?, ?, '卖出', ?, ?, ?, 'deferred', ?, ?)`).run(
            `DEF_SELL_${trade.code}_${Date.now()}`, trade.code, trade.name, shares, price, revenue, trade.yaodi_branch_id, bjNow()
          );
          db.prepare(`UPDATE deferred_trades SET status = 'executed', executed_at = ? WHERE rowid = ?`).run(bjNow(), trade.rowid);
          addRedQueenLog(`✅ 延迟卖出执行:${trade.name} ${shares}股@${price} 盈亏:${profit.toFixed(0)}(${profitPercent}%)`);
        }
      } catch (e) {
        console.error(`[延迟交易] 执行失败:`, e.message);
        db.prepare(`UPDATE deferred_trades SET status = 'failed', executed_at = ? WHERE rowid = ?`).run(bjNow(), trade.rowid);
      }
    }

    // 清理7天前的已完成/失败记录
    db.prepare(`DELETE FROM deferred_trades WHERE status IN ('executed', 'failed') AND created_at < ?`).run(bjPast(7));
  } catch (e) {
    console.error('[延迟交易] executeDeferredTrades error:', e.message);
  }
}

async function shundiAutoCycle() {
  if (!shundiRunning) return;
  try {
    // 【P0修复 2026-04-28】非交易时段硬拦截:舜帝模拟盘在A股交易时段之外禁止任何交易
    // 根因:凌晨2点仍在执行止损/买入,是因为 shundiAutoCycle 每60秒运行,但交易执行分支未检查交易时段
    if (!isTradingHours()) {
      // 非交易时段仅做持仓市值刷新,不执行任何交易决策
      try { refreshShundiHoldingsValue(); } catch(e) {}
      return;
    }

    // ── 【延迟交易执行】开市时自动执行pending状态的延迟交易 ──
    try { await executeDeferredTrades(); } catch(e) {}

    // ── 同步舜帝交易引擎状态到 YaodiBrain.systemModules ───────────
    YaodiBrain.systemModules.shundiEngine.status    = 'online';
    YaodiBrain.systemModules.shundiEngine.health    = 100;
    YaodiBrain.systemModules.shundiEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.redqueenEngine.status    = redqueenRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.redqueenEngine.health    = redqueenRunning ? 100 : 0;
    YaodiBrain.systemModules.redqueenEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.stopLossMonitor.status    = stopLossMonitorRunning ? 'online' : 'offline';
    YaodiBrain.systemModules.stopLossMonitor.health    = stopLossMonitorRunning ? 100 : 0;
    YaodiBrain.systemModules.stopLossMonitor.lastCheck = bjISO();

    YaodiBrain.systemModules.yaodiAgent.status    = yaodiEvolutionRunning ? 'online' : 'standby';
    YaodiBrain.systemModules.yaodiAgent.health    = yaodiEvolutionRunning ? 100 : 50;
    YaodiBrain.systemModules.yaodiAgent.lastCheck = bjISO();

    YaodiBrain.systemModules.evolutionEngine.status    = evolutionInterval !== null ? 'online' : 'standby';
    YaodiBrain.systemModules.evolutionEngine.health    = evolutionInterval !== null ? 100 : 50;
    YaodiBrain.systemModules.evolutionEngine.lastCheck = bjISO();

    YaodiBrain.systemModules.dataServer.status    = 'online';
    YaodiBrain.systemModules.dataServer.health    = 100;
    YaodiBrain.systemModules.dataServer.lastCheck = bjISO();

    YaodiBrain.systemModules.database.status    = 'online';
    YaodiBrain.systemModules.database.health    = 100;
    YaodiBrain.systemModules.database.lastCheck = bjISO();

    YaodiBrain.systemModules.frontend.status    = 'online';
    YaodiBrain.systemModules.frontend.health    = 100;
    YaodiBrain.systemModules.frontend.lastCheck = bjISO();

    // ── 黑天鹅事件快速检测(舜帝级别,更快响应)──────
    await checkBlackSwanEvents();

    // 1. 刷新舜帝持仓市值
    refreshShundiHoldingsValue();

    // 2. 读取舜帝资金配置
    const capital = db.prepare("SELECT * FROM shundi_capital_config WHERE id = 1").get() || {
      total_capital: 1000000,
      max_single_position: 200000,
      max_total_position: 800000,
      risk_level: 'moderate'
    };
    const holdings = db.prepare("SELECT * FROM shundi_mock_holdings ORDER BY profit_percent ASC").all();
    const totalPos = holdings.reduce((s, h) => s + (h.market_value || 0), 0);
    const available = capital.total_capital - totalPos;
    const posRatio = totalPos / capital.total_capital * 100;

    // 【优化】账户级回撤控制:计算当前账户盈亏率
    const totalCost = holdings.reduce((s, h) => s + (h.avg_cost || 0) * (h.shares || 0), 0);
    const totalValue = holdings.reduce((s, h) => s + (h.market_value || 0), 0);
    const accountPnLPct = totalCost > 0 ? ((totalValue - totalCost) / totalCost * 100) : 0;
    // 最大回撤限制: -10%触发强制减仓
    const MAX_DRAWDOWN_PCT = -10;
    if (accountPnLPct < MAX_DRAWDOWN_PCT) {
      console.log(`🚨 [回撤风控] 账户盈亏${accountPnLPct.toFixed(2)}%跌破${MAX_DRAWDOWN_PCT}%,触发强制减仓`);
      // 按亏损比例排序,优先减仓亏损最大的持仓
      const sortedHoldings = [...holdings].sort((a, b) => (a.profit_percent || 0) - (b.profit_percent || 0));
      for (const h of sortedHoldings.slice(0, 3)) { // 减仓前3大亏损股
        if (canSellByT1(h.buy_date)) {
          const reduceShares = Math.floor(h.shares * 0.3 / 100) * 100; // 减仓30%
          if (reduceShares >= 100) {
            console.log(`📉 [回撤减仓] ${h.code} ${h.name} 减仓${reduceShares}股`);
            // 执行减仓交易
            try {
              const price = h.current_price || 0;
              if (price > 0) {
                db.prepare(`INSERT INTO shundi_mock_trades (type, code, name, price, shares, amount, commission, status, filled_time, source, reason, pnl, created_at, yaodi_branch_id)
                  VALUES ('sell', ?, ?, ?, ?, ?, ?, 'filled', ?, 'drawdown_control', '回撤风控减仓', ?, ?)`)
                  .run(h.code, h.name, price, reduceShares, price * reduceShares, calcAStockCost(price * reduceShares, 'sell'), bjNow(), Math.round((h.current_price - h.avg_cost) * reduceShares), bjNow());
                db.prepare("UPDATE shundi_mock_holdings SET shares = shares - ? WHERE code = ?").run(reduceShares, h.code);
              }
            } catch (e) { console.error('[回撤减仓] 执行失败:', e.message); }
          }
        }
      }
      // 更新资金配置
      try { refreshShundiHoldingsValue(); } catch(e) {}
    }

    // 3. 获取市场情绪和信号
    const marketStats = db.prepare("SELECT * FROM market_stats ORDER BY id DESC LIMIT 1").get();
    const upRatio = marketStats ? (marketStats.up_count || 0) / Math.max(marketStats.total_count || 1, 1) : 0.5;
    const sentiment = (db.prepare("SELECT fear_greed_index FROM sentiment_index ORDER BY id DESC LIMIT 1").get()?.fear_greed_index || 50) / 100 - 0.5;

    // 【Phase1进化 2026-07-06】市场格局识别引擎 — 使用高级均线/BOLL/RSI/动量判断
    const shundiMarketRegime = detectMarketRegime();
    const regimeParams = getRegimeTradingParams(shundiMarketRegime);
    console.log(`[舜帝] 格局参数: ${regimeParams.desc} | 买入门槛${regimeParams.buyThreshold}% | 止损${regimeParams.stopLossPct}% | 止盈${regimeParams.takeProfitPct}% | 最大仓位${regimeParams.maxPosition}%`);

    // 【Phase1进化】BEAR/HIGH_VOL格局强制跳过买入，全局风控
    if (shundiMarketRegime === 'BEAR' || shundiMarketRegime === 'HIGH_VOL') {
      console.log(`🛑 舜帝: ${shundiMarketRegime==='BEAR'?'空头/弱势':'高波动'}格局，本轮跳过买入决策`);
    }

    // 【改造v2】舜帝信号池重构:降低门槛 + 扩大舜帝独立评分权限
    // 尧帝只负责信号生成(打标签),舜帝自己综合评分决策
    // 信号来源:trade_signals(尧帝标签)+ 全市场量化候选股(舜帝自主扫描)
    const signalRows = db.prepare(`
      SELECT s.*,
             y.accuracy as yaodi_accuracy, y.evolution_level as yaodi_level, y.reliability_score as yaodi_reliability,
             sr.price, sr.change_percent, sr.volume, sr.high, sr.low, sr.pre_close,
             sr.price * 0.97 as buy_price_low, sr.price * 1.03 as buy_price_high
      FROM trade_signals s
      LEFT JOIN yaodi_branch y ON s.source LIKE '%' || y.strategy || '%'
      LEFT JOIN stock_realtime sr ON sr.code = s.code
      WHERE (s.expires_at > ? OR s.created_at > ?)
        AND s.signal = 'buy'
        AND s.source != 'shundi_auto'
      ORDER BY s.confidence DESC
      LIMIT 100
    `).all(bjNow(), bjPast(1));

    // 【改造v2】舜帝自主扫描全市场:量化条件筛选候选股(不依赖尧帝信号)
    const marketCandidates = db.prepare(`
      SELECT sr.code, sr.name, sr.price, sr.change_percent, sr.volume,
             sr.high, sr.low, sr.pre_close,
             ABS(sr.change_percent) as abs_change,
             CASE WHEN sr.change_percent BETWEEN -3 AND 0 THEN '回调'
                  WHEN sr.change_percent > 0 AND sr.change_percent < 5 THEN '温和上涨'
                  WHEN sr.change_percent <= -3 AND sr.change_percent > -9.8 THEN '超跌'
                  ELSE '其他' END as market_type
      FROM stock_realtime sr
      WHERE sr.price BETWEEN 2 AND 200
        AND sr.change_percent BETWEEN -8 AND 8
        AND sr.volume > 500000
        AND sr.code NOT LIKE '688%'
        AND sr.code NOT LIKE '689%'
        AND sr.name NOT LIKE 'ST%'
        AND sr.name NOT LIKE '*ST%'
        AND sr.code NOT IN (SELECT code FROM shundi_mock_holdings)
        AND sr.code NOT IN (SELECT code FROM trade_signals WHERE expires_at > ?)
      ORDER BY
        CASE WHEN sr.change_percent BETWEEN -5 AND 2 THEN 0 ELSE 1 END,
        sr.volume DESC
      LIMIT 200
    `).all(bjNow());

    // 去重合并(舜帝自主扫描优先级最低,尧帝信号优先级最高)
    const seenCodes = new Set();
    const signals = [];
    for (const s of signalRows) { s._src = 'yaodi_tag'; signals.push(s); seenCodes.add(s.code); }
    for (const s of marketCandidates) {
      if (!seenCodes.has(s.code)) {
        s._src = 'shundi_scan';
        s.signal = 'potential_buy';
        // 【BUG-29修复】舜帝初评分基于真实数据而非随机:成交量+涨跌幅综合评分
        const volScore = Math.min(s.volume / 10000000, 10); // 成交量评分(0-10)
        const chgScore = s.change_percent >= 0 ? Math.min(s.change_percent, 5) : Math.max(-3, s.change_percent) + 3; // 涨跌幅评分(0-8)
        s.confidence = Math.round(50 + volScore * 2 + chgScore * 3); // 基于真实数据评分(50-84)
        s.yaodi_accuracy = null; s.yaodi_level = null; s.yaodi_reliability = null;
        signals.push(s); seenCodes.add(s.code);
      }
    }
    signals.sort((a, b) => b.confidence - a.confidence);
    console.log('[舜帝诊断] 信号池:', signalRows.length, '条尧帝标签 +', marketCandidates.length, '条舜帝扫描 =', signals.length, '只候选');
    console.log('[舜帝诊断] 仓位:', posRatio.toFixed(1), '%, 可用:', available, 'max_total:', capital.max_total_position);
    console.log('[舜帝诊断] isTradingHours:', isTradingHours());
    if (signals.length > 0) console.log('[舜帝诊断] Top信号:', JSON.stringify({code:signals[0].code, conf:signals[0].confidence, src:signals[0]._src, source:signals[0].source}));

    if (signals.length > 0) {
      addRedQueenLog(`🔔 舜帝信号池: ${signalRows.length}条(尧帝标签) + ${marketCandidates.length}条(舜帝全市场扫描) = 共${signals.length}只候选`, 'decision');
    }

    // 5. 多账户协同分析
    const multiAnalysis = multiAccountAnalysis();

    // 6. 生成舜帝交易决策
    const decisions = [];

    // === ATR自适应止损止盈(含跟踪止损+稳定期)===
    holdings.forEach(h => {
      const sig = signals.find(s => s.code === h.code);
      const pct = parseFloat(h.profit_percent || 0);
      const buyPrice = h.avg_cost;

      // 【新增2026-04-25】持仓天数和峰值价
      const firstBuy = db.prepare(
        "SELECT created_at FROM shundi_mock_trades WHERE code=? AND (type='buy' OR type='尧帝信号执行') ORDER BY created_at ASC LIMIT 1"
      ).get(h.code);
      const holdDays = firstBuy
        ? Math.floor((Date.now() - new Date(firstBuy.created_at).getTime()) / 86400000)
        : 0;
      const peakRow = db.prepare(
        "SELECT MAX(high) as peak FROM stock_history WHERE code=? ORDER BY date DESC LIMIT 60"
      ).get(h.code);
      const peakPrice = Math.max(h.current_price, peakRow?.peak || h.current_price);
      const atr = calculateATR(h.code);

      // ── 【Phase1进化 2026-07-06】全局最大持仓时间强制平仓 ──
      const MAX_HOLD_DAYS = 15; // 最大持仓15个交易日，超时无论盈亏强平
      if (holdDays >= MAX_HOLD_DAYS) {
        const forcedReason = `📋 持仓超时:已持有${holdDays}个交易日(上限${MAX_HOLD_DAYS}日)，强制平仓`;
        console.log(`[舜帝超时强平] ${h.name} 持有${holdDays}日，强制平仓`);
        dec.actions.push({
          type: '持仓超时强平',
          direction: '卖出',
          amount: h.market_value,
          shares: h.shares,
          original_strategy: strategy,
          reason: forcedReason,
          urgent: true
        });
        dec.priority = 110; // 最高优先级
      }

      // ATR止损止盈
      const atrStopPrice = atrStopLoss(h.code, buyPrice, 'long', {
        atr, currentPrice: h.current_price, peakPrice, holdDays
      });
      const atrTakePrice = atrTakeProfit(h.code, buyPrice, 'long', {
        atr, currentPrice: h.current_price
      });

      // 计算当前价格与止损止盈的距离
      const stopDistance = ((h.current_price - atrStopPrice) / h.current_price * 100);
      const takeDistance = ((atrTakePrice - h.current_price) / h.current_price * 100);

      const dec = {
        code: h.code,
        name: h.name,
        shares: h.shares,
        avgCost: h.avg_cost,
        currentPrice: h.current_price,
        profitPct: pct,
        profit: h.profit,
        atrStop: atrStopPrice,
        atrTake: atrTakePrice,
        actions: [],
        priority: 0,
        yaodi_branch_id: h.yaodi_branch_id || null
      };

      // ── P1修复: 独立止盈止损策略 ──
      // 【优化 2026-05-07】调整止盈止损比例,提高胜率
      // 凯利加仓: 更激进,止损-8%,止盈15%
      // 智能选股: 平衡,止损-5%,止盈8%
      // 【P1修复】从 yaodi_config 读取止损止盈配置,替代硬编码
      const cfgStopLoss = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='default_stop_loss_pct'").get()?.value || '5.0');
      const cfgTakeProfit = parseFloat(db.prepare("SELECT value FROM yaodi_config WHERE key='default_take_profit_ratio'").get()?.value || '1.08');
      // 【调整 2026-05-07】优化止盈止损比例,提高胜率
      // A股日内波动大,过紧止损(3%)易被震出,过松止盈(3%)错失大利润
      // 新策略: 止损5%止盈8% (盈亏比 1.6:1)
      const BASE_TAKE_PROFIT_PCT = 8.0;  // 提高止盈阈值
      let stopLossPct, takeProfitPct;
      const strategy = h.strategy || 'unknown';

      if (strategy.includes('凯利') || strategy.includes('Kelly')) {
        stopLossPct = Math.min(-cfgStopLoss * 1.6, -8);  // 凯利策略止损-8%
        takeProfitPct = Math.max(BASE_TAKE_PROFIT_PCT * 1.875, 15);  // 凯利止盈15%
      } else if (strategy.includes('智能选股') || strategy.includes('尧帝') || strategy.includes('shundi') || strategy.includes('舜帝')) {
        stopLossPct = -cfgStopLoss;  // 智能选股止损-5%
        takeProfitPct = BASE_TAKE_PROFIT_PCT;  // 止盈8%
      } else {
        stopLossPct = -cfgStopLoss;  // 默认止损-5%
        takeProfitPct = BASE_TAKE_PROFIT_PCT;  // 默认止盈8%
      }

      const strategyStop = h.avg_cost * (1 + stopLossPct / 100);
      const strategyTake = h.avg_cost * (1 + takeProfitPct / 100);

      // ATR自适应止损(使用更严格的标准)
      const effectiveStop = Math.max(atrStopPrice, strategyStop);
      if (h.current_price <= effectiveStop || pct <= stopLossPct) {
        dec.actions.push({
          type: '止损出局',
          direction: '卖出',
          amount: h.market_value,
          shares: h.shares,
          original_strategy: strategy,
          reason: `${strategy}止损:当前¥${h.current_price.toFixed(2)},策略止损¥${strategyStop.toFixed(2)},ATR止损¥${atrStopPrice.toFixed(2)},亏损${pct.toFixed(1)}%`,
          urgent: true
        });
        dec.priority = 100 + Math.abs(pct);
      }
      // ATR自适应止盈(使用更保守的标准)
      else if (h.current_price >= atrTakePrice || pct >= takeProfitPct) {
        dec.actions.push({
          type: '止盈出局',
          direction: '卖出',
          amount: h.market_value,
          shares: h.shares,
          original_strategy: strategy,
          reason: `${strategy}止盈:当前¥${h.current_price.toFixed(2)},策略目标¥${strategyTake.toFixed(2)},ATR目标¥${atrTakePrice.toFixed(2)},盈利${pct.toFixed(1)}%`,
          urgent: false
        });
        dec.priority = 80 + pct;
      }
      // 加仓逻辑(使用凯利公式)优化:提高置信度阈值到70%
      // 【优化 2026-05-07】置信度阈值:60%→70%(提高加仓质量,降低频率)
      // 加仓应该是高置信度信号,避免频繁加仓导致的成本增加
      else if (sig && sig.signal === 'buy' && sig.confidence >= 70 && posRatio < 80 && available > 500) {
        // 获取信号来源策略的统计数据
        const strategyStats = getStrategyStats(sig.source?.split('_')[1] || 'default');
        const kellyRatio = kellyPosition(strategyStats.winRate, strategyStats.avgWin, strategyStats.avgLoss);
        const maxAdd = Math.min(
          available * kellyRatio,
          capital.max_single_position * 0.3
        );
        const addShares = Math.floor(maxAdd / h.current_price / 100) * 100;
        if (addShares >= 100) {
          dec.actions.push({
            type: '舜帝加仓',
            direction: '买入',
            amount: addShares * h.current_price,
            shares: addShares,
            kellyRatio: kellyRatio.toFixed(2),
            reason: `舜帝加仓:信号强度${sig.confidence}%,凯利比例${(kellyRatio*100).toFixed(1)}%,加${addShares}股`,
            urgent: false
          });
          dec.priority = sig.confidence;
        }
      }

      if (dec.actions.length > 0) {
        decisions.push(dec);
      }
    });

    // 7. 尧帝信号优先执行 + 智能选股补充
    const heldCodes = holdings.map(h => h.code);

    // ── P0修复: 舜帝识别尧帝信号:source含'yaodi' ──
    // 【优化 2026-05-07→05-08】调整置信度阈值:尧帝L3信号经kellyFactor=1.4增强,decimal→*100后range=54-95,阈值50确保高质量信号
    // kellyFactor=1.4使所有L3信号的conf*100稳定在54-95范围,舜帝舜帝舜帝舜帝舜帝舜帝舜帝舜帝
    // 【Phase1进化 2026-07-06】格局驱动信号过滤 — 买入门槛动态化
    // 【Phase4进化 2026-07-07】应用学习权重优化置信度
    const yaodiSignals = signals.filter(s => {
      if (s.signal !== 'buy') return false;
      if (heldCodes.includes(s.code)) return false;
      if (!s.source || (!s.source.includes('尧帝') && !s.source.includes('yaodi') && !s.source.includes('snapshot'))) return false;
      
      // 应用学习权重
      const adjustedConf = applyLearningWeight(s.confidence, shundiMarketRegime);
      s.adjustedConfidence = adjustedConf;
      
      return adjustedConf >= regimeParams.buyThreshold;
    });

    // 【Phase1进化 2026-07-06】格局驱动的全局止损止盈 — 替代硬编码
    const STOP_LOSS_THRESHOLD  = regimeParams.stopLossPct / 100;  // BEAR=-3%, BULL=-5%, RANGE=-4%, HIGH_VOL=-3%
    const TAKE_PROFIT_THRESHOLD = regimeParams.takeProfitPct / 100; // BEAR=6%,  BULL=12%, RANGE=8%,  HIGH_VOL=5%
    const regimeMaxPosition    = regimeParams.maxPosition;           // 最大仓位

    if (yaodiSignals.length > 0 && (available < 1000 || posRatio >= regimeMaxPosition)) {
      holdings.forEach(h => {
        const profitPct = (h.current_price - h.avg_cost) / h.avg_cost;
        if (profitPct <= STOP_LOSS_THRESHOLD) {
          decisions.push({
            code: h.code, name: h.name,
            currentPrice: h.current_price, avgCost: h.avg_cost,
            profitPct: profitPct * 100,
            signal: 'sell', confidence: 95,
            reason: `📉 保底止损:亏损${(profitPct*100).toFixed(1)}%,超过-8%阈值,主动止损释放资金`,
            actions: [{
              type: '止损保护', direction: '卖出', shares: h.shares,
              reason: `保底止损:买价${h.avg_cost},现价${h.current_price},亏损${(profitPct*100).toFixed(1)}%,卖出全部${h.shares}股`,
              urgent: true
            }],
            priority: 95
          });
          console.log(`[舜帝止损] ${h.name} 亏损${(profitPct*100).toFixed(1)}%,触发保底止损`);
        }
      });
    }

    // 【Phase1进化】格局驱动止盈 — TAKE_PROFIT_THRESHOLD已在上面用regimeParams定义
    if (yaodiSignals.length > 0 && (available < 1000 || posRatio >= regimeMaxPosition)) {
      holdings.forEach(h => {
        const profitPct = (h.current_price - h.avg_cost) / h.avg_cost;
        if (profitPct >= TAKE_PROFIT_THRESHOLD) {
          decisions.push({
            code: h.code, name: h.name,
            currentPrice: h.current_price, avgCost: h.avg_cost,
            profitPct: profitPct * 100,
            signal: 'sell', confidence: 88,
            reason: `📊 格局止盈:盈利${(profitPct*100).toFixed(1)}%,超过${regimeParams.takeProfitPct}%目标,主动止盈`,
            actions: [{
              type: '主动止盈', direction: '卖出', shares: h.shares,
              reason: `格局止盈:盈利${(profitPct*100).toFixed(1)}%,卖出全部${h.shares}股`,
              urgent: false
            }],
            priority: 88
          });
          console.log(`[舜帝止盈] ${h.name} 盈利${(profitPct*100).toFixed(1)}%,格局止盈(${regimeParams.takeProfitPct}%)`);
        }
      });
    }

    // P1-3尧帝信号主动止盈:尧帝信号存在但满仓时,止盈利润>2%的持仓释放资金
      // === 改进2: 尧帝信号消费优化 ===
      // 门槛从3%降到2%,更积极释放资金
      const YAODI_MIN_PROFIT = 0.015;  // 【调整】1.5%盈利即止盈(原2%偏高,A股日内常达不到)

      if (yaodiSignals.length > 0 && (available < 1000 || posRatio >= regimeMaxPosition)) {
        // 优先处理盈利>2%的持仓
        const profitableHoldings = holdings
          .filter(h => (h.profit || 0) > 0 && ((h.profit_percent || 0) > YAODI_MIN_PROFIT * 100))
          .sort((a, b) => (b.profit || 0) - (a.profit || 0));

        // 如果有盈利持仓可释放,则止盈
        if (profitableHoldings.length > 0) {
          const top = profitableHoldings[0];
          const pnlPct = top.profit_percent || ((top.profit || 0) / (top.market_value || 1) * 100);
          if (pnlPct > YAODI_MIN_PROFIT * 100) {
            decisions.push({
              code: top.code,
              name: top.name,
              shares: 0, avgCost: 0, currentPrice: top.current_price, profitPct: pnlPct, profit: top.profit,
              signal: 'sell',
              confidence: 95,
              reason: `📤 主动止盈释放资金: ${top.name} 盈利${pnlPct.toFixed(1)}%,为尧帝信号腾出资金`,
              actions: [{
                type: '主动止盈',
                direction: '卖出',
                amount: top.market_value,
                shares: top.shares,
                reason: `尧帝信号执行主动止盈: ${top.code} 盈利${pnlPct.toFixed(1)}%约¥${(top.profit||0).toFixed(0)},释放资金¥${(top.market_value||0).toFixed(0)}`,
                urgent: false
              }],
              priority: 80 + pnlPct
            });
            console.log(`[尧帝信号] 主动止盈释放资金: ${top.code} ${pnlPct.toFixed(1)}%`);
          }
        }
      }

      // === 改进1: 持仓分散度风控 ===
      // 单票不超过20%,总持仓不超过80%
      const MAX_SINGLE_RATIO = 0.20;  // 单票上限20%
      const MAX_TOTAL_RATIO = 0.80;   // 总持仓上限80%

      // 检查是否需要减仓以满足分散度要求
      let needRebalance = false;
      let overConcentrated = [];
      holdings.forEach(h => {
        const hRatio = (h.market_value || 0) / capital.total_capital;
        if (hRatio > MAX_SINGLE_RATIO) {
          overConcentrated.push({...h, ratio: hRatio});
          needRebalance = true;
        }
      });

      // 如果持仓超过80%,需要释放资金
      if (posRatio >= MAX_TOTAL_RATIO * 100) {
        needRebalance = true;
      }

      // 减仓逻辑:优先减仓盈利最大且超过单票上限的持仓
      if (needRebalance && overConcentrated.length > 0) {
        overConcentrated.sort((a, b) => (b.profit || 0) - (a.profit || 0));
        const top = overConcentrated[0];
        const targetShares = Math.floor((capital.total_capital * MAX_SINGLE_RATIO) / top.current_price / 100) * 100;
        const reduceShares = top.shares - targetShares;

        if (reduceShares > 100) {
          decisions.push({
            code: top.code,
            name: top.name,
            shares: reduceShares,
            avgCost: top.avg_cost,
            currentPrice: top.current_price,
            profitPct: top.profit_percent || 0,
            profit: top.profit,
            signal: 'sell',
            confidence: 85,
            reason: `📊 分散度风控: ${top.name}持仓占比${(top.ratio*100).toFixed(1)}%超过20%上限,减持${reduceShares}股`,
            actions: [{
              type: '分散度减仓',
              direction: '卖出',
              shares: reduceShares,
              amount: reduceShares * top.current_price,
              reason: `强制减持${reduceShares}股以满足分散度要求`,
              urgent: false
            }],
            priority: 70
          });
          console.log(`[分散度风控] ${top.code} 减持${reduceShares}股,占比${(top.ratio*100).toFixed(1)}%→20%`);
        }
      }

      // === 诊断日志 ===
      console.log('[舜帝诊断-买入] yaodiSignals数量:', yaodiSignals.length, 'isTradingHours:', isTradingHours(), 'available:', available, 'posRatio:', posRatio.toFixed(1));
      if (yaodiSignals.length > 0) {
        console.log('[舜帝诊断-买入] yaodiSignals[0]:', JSON.stringify({code:yaodiSignals[0].code, conf:yaodiSignals[0].confidence, source:yaodiSignals[0].source, price:yaodiSignals[0].price}));
      } else {
        console.log('[舜帝诊断-买入] yaodiSignals为空! signalRows:', signalRows.length);
      }
      // === 诊断日志结束 ===

      // 【P0优化】尧帝信号执行数量从2个增加到5个,提高资金利用率
      yaodiSignals.slice(0, 5).forEach(sig => {
        // 改进1: 分散度检查 - 新买入后单票不超过20%
        if (available < 500 || posRatio >= MAX_TOTAL_RATIO * 100) return;

      // 【P0修复】增强价格获取逻辑:先查实时价格表,确保有有效价格才执行买入
      const rtPrice = db.prepare("SELECT price FROM stock_realtime WHERE code = ?").get(sig.code)?.price;
      const price = rtPrice || sig.price || sig.current_price || 0;
      if (price <= 0) {
        console.log(`[尧帝信号] ${sig.code} 价格无效(${price}),跳过买入`);
        return;
      }

      const strategyStats = getStrategyStats(sig.source?.split('_')[1] || 'default');
      const kellyRatio = kellyPosition(strategyStats.winRate, strategyStats.avgWin, strategyStats.avgLoss);

      // 【优化:真实市场成交量限制】舜帝按日均真实成交量限制买入数量
      const rtStock = db.prepare("SELECT price, volume, amount FROM stock_realtime WHERE code = ?").get(sig.code) || {};
      const dailyVolume = rtStock.volume || 100000; // 默认日成交量10万股
      const maxVolShares = Math.max(100, Math.floor(dailyVolume * 0.05)); // 最多买日成交量的5%
      const avgPrice = rtStock.price || price; // 直接使用实时价格,避免amount/volume单位不匹配
      // 【BUG-27修复】预算严格遵守max_single_position限制
      const realisticBudget = Math.min(
        Math.floor(capital.total_capital * kellyRatio),
        capital.max_single_position // 严格遵守单只仓位限制
      );
      const realisticShares = Math.floor(realisticBudget / avgPrice / 100) * 100;
      const buyShares = Math.max(100, Math.min(maxVolShares, realisticShares));
      const buyAmount = buyShares * avgPrice;
      // 【Phase2 板块过滤 2026-07-06】按代码首位映射到宽基板块,弱势板块直接跳过
      const stockCodeStr = String(sig.code);
      let stockBroadSector = '其他';
      if (stockCodeStr.startsWith('6') && !stockCodeStr.startsWith('688')) stockBroadSector = '沪市主板';
      else if (stockCodeStr.startsWith('688')) stockBroadSector = '科创板';
      else if (stockCodeStr.startsWith('3')) stockBroadSector = '创业板';
      else if (stockCodeStr.startsWith('0') || stockCodeStr.startsWith('1')) stockBroadSector = '深市主板';
      else if (stockCodeStr.startsWith('4') || stockCodeStr.startsWith('8')) stockBroadSector = '北交所';
      const sectorStrength = getSectorStrength(stockBroadSector);
      if (sectorStrength === 'weak') {
        console.log(`[尧帝信号-板块过滤] ${sig.code}(${stockBroadSector})弱势板块,跳过买入`);
        return;
      }
      // 【Phase2 弱势降权】中性板块信号置信度降30%
      const sectorConfMultiplier = sectorStrength === 'strong' ? 1.0 : 0.7; // 强势不变,中性降30%
      const adjustedConf = Math.round((sig.confidence || 50) * sectorConfMultiplier);
      if (isTradingHours() && buyShares >= 100 && buyAmount <= available * 0.3 && (totalPos + buyAmount) <= capital.max_total_position) { // 尧帝信号不超过可用资金30%且总持仓不超限(max_total_position已是实际金额)
        // 【Phase1进化 2026-07-06】格局驱动仓位调整
        let adjustedShares = buyShares;
        if (shundiMarketRegime === 'BEAR' || shundiMarketRegime === 'HIGH_VOL') { return; } // 空头/高波动直接跳过
        if (shundiMarketRegime === 'RANGE') { adjustedShares = Math.max(100, Math.floor(buyShares * 0.7 / 100) * 100); } // 震荡减仓30%
        // adjustedShares已由Math.max(100,...)保证>=100
        const adjustedAmount = adjustedShares * avgPrice;
        const stopPrice = atrStopLoss(sig.code, price, 'long');
        const takePrice = atrTakeProfit(sig.code, price, 'long');

        decisions.push({
          code: sig.code,
          name: sig.name || sig.stock_name || (db.prepare('SELECT name FROM stocks WHERE code=?').get(sig.code)?.name) || sig.code,
          shares: 0,
          avgCost: 0,
          currentPrice: price,
          profitPct: 0,
          profit: 0,
          signal: 'buy',
          confidence: adjustedConf,
          reason: `📈 尧帝信号:${sig.signal||'buy'} 置信度${sig.confidence}%→${adjustedConf}% [板块${sectorStrength === 'strong'?'强势':sectorStrength === 'weak'?'弱势':'中性'}] 来源${sig.source}`,
          atrStop: stopPrice,
          atrTake: takePrice,
          kellyRatio: kellyRatio.toFixed(2),
          actions: [{
            type: '尧帝信号执行',
            direction: '买入',
            amount: adjustedAmount,
            shares: adjustedShares,
            stopPrice: stopPrice,
            takePrice: takePrice,
            reason: `🚀 尧帝信号执行:${sig.source}置信度${sig.confidence}%,凯利比例${(kellyRatio*100).toFixed(1)}%,买入${adjustedShares}股约¥${Math.round(adjustedAmount).toLocaleString()}${shundiMarketRegime === 'bear' ? ' [弱势减半]' : ''}`,
            urgent: true // 尧帝信号标记为紧急
          }],
          priority: sig.confidence + 30 // 尧帝信号优先级+30
        });
        console.log(`[尧帝信号] 纳入决策: ${sig.code} 置信度${sig.confidence}%`);
      }
    });

    // 使用智能选股系统筛选新股(优化:增加到5个)
    const smartPicks = smartStockSelection(5, 'buy', false); //舜帝模拟盘不过滤科创板/北交所

    // === 诊断日志 ===
    console.log('[舜帝诊断-买入] smartPicks数量:', smartPicks.length, 'isTradingHours:', isTradingHours(), 'available:', available, 'posRatio:', posRatio.toFixed(1));
    if (smartPicks.length > 0) {
      console.log('[舜帝诊断-买入] smartPicks[0]:', JSON.stringify({code:smartPicks[0].code, conf:smartPicks[0].confidence, price:smartPicks[0].price}));
    }
    // === 诊断日志结束 ===

    // 对智能选股结果,计算凯利仓位
    smartPicks.forEach(pick => {
      if (heldCodes.includes(pick.code)) return; // 已持有则跳过
      if (available < 1000 || posRatio >= 80) return; // 优化:降低资金门槛,提高仓位上限

      // 【Phase2 板块过滤-舜帝自主扫描】弱势板块直接跳过,中性降权30%
      const pickCodeStr = String(pick.code);
      let pickSector = '其他';
      if (pickCodeStr.startsWith('6') && !pickCodeStr.startsWith('688')) pickSector = '沪市主板';
      else if (pickCodeStr.startsWith('688')) pickSector = '科创板';
      else if (pickCodeStr.startsWith('3')) pickSector = '创业板';
      else if (pickCodeStr.startsWith('0') || pickCodeStr.startsWith('1')) pickSector = '深市主板';
      else if (pickCodeStr.startsWith('4') || pickCodeStr.startsWith('8')) pickSector = '北交所';
      const pickSectorStrength = getSectorStrength(pickSector);
      if (pickSectorStrength === 'weak') {
        console.log(`[舜帝自主-板块过滤] ${pick.code}(${pickSector})弱势板块,跳过买入`);
        return;
      }
      const pickSectorConfMult = pickSectorStrength === 'strong' ? 1.0 : 0.7;
      const pickAdjustedConf = Math.round((pick.confidence || 50) * pickSectorConfMult);

      // 获取策略统计,计算凯利仓位
      const strategyStats = getStrategyStats(pick.source?.split('_')[1] || 'default');
      const kellyRatio = kellyPosition(strategyStats.winRate, strategyStats.avgWin, strategyStats.avgLoss);

      // 【BUG-27修复】单只股票最大仓位:严格遵守max_single_position限制
      const perStockBudget = Math.min(
        Math.floor(capital.total_capital * kellyRatio),
        capital.max_single_position // 严格遵守单只仓位限制,不再×1.2
      );

      const maxShares = Math.floor(perStockBudget / pick.price / 100) * 100;
      // 【BUG-27修复】置信度加成不再放大仓位,仅影响优先级
      const confBonus = pick.confidence >= 85 ? 1.0 : pick.confidence >= 80 ? 0.9 : pick.confidence >= 75 ? 0.8 : pick.confidence >= 70 ? 0.7 : 0.6;
      const buyShares = Math.floor(maxShares * confBonus / 100) * 100;
      const buyAmount = buyShares * pick.price;

      if (isTradingHours() && buyShares >= 100 && buyAmount <= available) {
        // 【Phase3进化 2026-07-07】多周期技术信号增强
        const techSignal = calculateMultiPeriodTechSignal(pick.code, db);
        
        // 技术信号卖出直接跳过买入
        if (techSignal.signal === 'sell' || techSignal.signal === 'strong_sell') {
          console.log(`[舜帝-技术信号过滤] ${pick.code} 技术卖出信号(${techSignal.signal}),跳过买入: ${techSignal.reasons.join(', ')}`);
          return;
        }
        
        // 技术信号强买加成
        let techBonus = 1.0;
        if (techSignal.signal === 'strong_buy') {
          techBonus = 1.15; // 强买信号加仓15%
          console.log(`[舜帝-技术信号增强] ${pick.code} 多周期共振买入: ${techSignal.reasons.join(', ')}`);
        } else if (techSignal.signal === 'buy') {
          techBonus = 1.05; // 普通买入加仓5%
        }
        
        // 技术信号追加到reason
        const techReasonAppend = techSignal.reasons.length > 0 ? ` | 技术信号:${techSignal.signal}(${techSignal.score.toFixed(0)}分)` : '';
        
        // 【Phase1进化 2026-07-06】舜帝自主扫描格局仓位调整
        let adjustedShares = buyShares;
        if (shundiMarketRegime === 'BEAR' || shundiMarketRegime === 'HIGH_VOL') { return; } // 空头/高波动直接跳过
        if (shundiMarketRegime === 'RANGE') { adjustedShares = Math.max(100, Math.floor(buyShares * 0.7 / 100) * 100); } // 震荡减仓30%
        
        // 应用技术信号加成
        adjustedShares = Math.floor(adjustedShares * techBonus / 100) * 100;
        const adjustedAmount = adjustedShares * pick.price;

        // 计算ATR止损止盈价格
        const stopPrice = atrStopLoss(pick.code, pick.price, 'long');
        const takePrice = atrTakeProfit(pick.code, pick.price, 'long');

        decisions.push({
          code: pick.code,
          name: pick.name,
          shares: 0,
          avgCost: 0,
          currentPrice: pick.price,
          profitPct: 0,
          profit: 0,
          signal: 'buy',
          confidence: pickAdjustedConf,
          reason: `📊 舜帝选股:评分${pick.final??pick.score??0}分→${pickAdjustedConf}% [板块${pickSectorStrength==='strong'?'强势':pickSectorStrength==='weak'?'弱势':'中性'}${pickSector}]${pick.reason ? ', '+pick.reason : ''}${techReasonAppend}`,
          scores: pick.scores || { final: pick.final ?? pick.score ?? 0 },
          techSignal: techSignal, // 添加技术信号详情
          atrStop: stopPrice,
          atrTake: takePrice,
          kellyRatio: kellyRatio.toFixed(2),
          actions: [{
            type: '智能选股新仓',
            direction: '买入',
            amount: adjustedAmount,
            shares: adjustedShares,
            stopPrice: stopPrice,
            takePrice: takePrice,
            reason: `舜帝选股:综合评分${pick.final??pick.score??0}→${pickAdjustedConf}%,板块${pickSectorStrength},凯利${(kellyRatio*100).toFixed(1)}%,买入${adjustedShares}股约¥${Math.round(adjustedAmount).toLocaleString()},止损¥${stopPrice.toFixed(2)}`,
            urgent: false
          }],
          priority: pickAdjustedConf
        });
      }
    });

    // ─── 改进2: Q-Learning 推荐 → 舜帝决策参考 ─────────────────────────
    const qRec = getQLearningRecommendation();
    if (qRec && Object.keys(Q_LEARNING.qTable).length > 5) {
      const qWeight = 0.3;
      decisions.forEach(dec => {
        const basePriority = dec.priority || 0;
        const action0 = dec.actions[0];
        const dir = action0?.direction; // 'buy' | 'sell' | undefined
        let qAdjustment = 0;
        if (dir === 'buy') {
          // Q-Learning 推荐买 → 激进策略加分,保守策略减分
          qAdjustment = action0?.type === '舜帝加仓' ? 15 : (action0?.type?.includes('智能选股') ? 20 : 5);
        } else if (dir === 'sell') {
          // Q-Learning 推荐卖 → 止损止盈策略加分
          qAdjustment = action0?.type?.includes('止损') ? 25 : 10;
        }
        // hold 类(无 actions)由 Q-Learning 主导
        dec._adjustedPriority = basePriority * (1 - qWeight) + (basePriority + qAdjustment) * qWeight;
        console.log(`[Q-Learning] ${dec.code || 'HOLD'}: qRec=${qRec} base=${basePriority} adj=${qAdjustment.toFixed(1)} → ${dec._adjustedPriority.toFixed(1)}`);
      });
      decisions.sort((a, b) => (b._adjustedPriority ?? b.priority) - (a._adjustedPriority ?? a.priority));
    }

    // 8. 执行交易决策
    console.log(`[舜帝执行] 进入执行循环 | decisions=${decisions.length}只 | isTradingHours=${isTradingHours()} | available=${available} | totalPos=${totalPos}`);
    decisions.forEach(d => { const a = d.actions[0]; console.log(`[舜帝执行] 决策: ${d.code} ${d.name} | type=${a?.type} | dir=${a?.direction} | shares=${a?.shares} | amt=${a?.amount}`); });
    for (const dec of decisions.sort((a, b) => {
      const pa = a._adjustedPriority ?? a.priority;
      const pb = b._adjustedPriority ?? b.priority;
      return pb - pa;
    })) {
      const action = dec.actions[0];
      if (!action) continue;

      try {
        if (action.direction === '卖出' && action.shares > 0 && isTradingHours()) {
          console.log(`[舜帝执行] → 卖出分支 ${dec.code}`);
          // 执行卖出
          const h = db.prepare("SELECT * FROM shundi_mock_holdings WHERE code = ?").get(dec.code);
          if (h && h.shares >= action.shares) {
            // 【A股T+1】当日买入不可卖出
            if (!canSellByT1(h.buy_date)) {
              addRedQueenLog(`⚠️ A股T+1限制:${dec.name} 今日买入不可卖出`);
              continue;
            }
            const price = dec.currentPrice;
            const amount = action.shares * price;

            // 【A股涨跌停】卖出价不能低于跌停价
            const sLimit = getPriceLimit(dec.code, price);
            if (price < sLimit.limitDown) {
              addRedQueenLog(`⚠️ A股跌停限制:${dec.name} ¥${price.toFixed(2)} < 跌停价¥${sLimit.limitDown.toFixed(2)}`);
              continue;
            }
            const tradeCost = calcAStockCost(amount, 'sell');  // A股合规手续费(含印花税千1)
            const pnl = (price - h.avg_cost) * action.shares - tradeCost.total;  // A股合规成本

            // 更新持仓
            const newShares = h.shares - action.shares;
            // 【A股零股规则】剩余股份不足100股时必须全部卖出(零股只能清仓卖出)
            if (newShares > 0 && newShares < 100) {
              addRedQueenLog(`⚠️ A股零股规则:${dec.name} 剩余${newShares}股不足100股,改为全部卖出`);
              action.shares = h.shares; // 改为全仓卖出
            }
            const finalNewShares = h.shares - action.shares;
            if (finalNewShares > 0) {
              db.prepare("UPDATE shundi_mock_holdings SET shares = ?, market_value = ? * shares, update_time = ? WHERE code = ?")
              .run(newShares, price, bjNow(), dec.code);
            } else {
              db.prepare("DELETE FROM shundi_mock_holdings WHERE code = ?").run(dec.code);
            }

            // 记录交易
            const oid = "SHUNDI_" + dec.code + "_" + Date.now();
            // 【P0-1修复】舜帝卖出时写pending_trades(用于resolvePendingTrade计算reward)
            try {
              // 优先从shundi_mock_trades找该股最早买入价
              const firstBuy = db.prepare("SELECT price FROM shundi_mock_trades WHERE code=? AND (type='舜帝加仓' OR type='智能选股新仓' OR type='舜帝买入' OR type='buy') ORDER BY filled_time ASC LIMIT 1").get(dec.code);
              const refBuyPrice = firstBuy?.price || h.avg_cost;
              const pState = buildMarketState();
              db.prepare(`INSERT OR REPLACE INTO pending_trades (trade_id, state, action, buy_price, buy_time) VALUES (?, ?, ?, ?, ?)`)
              .run(oid, pState, action.direction, refBuyPrice, bjNow());
            } catch(e) { /* 表可能不存在 */ }
            db.prepare(`INSERT INTO shundi_mock_trades
              (order_id, type, code, name, price, shares, amount, commission, status, filled_time, source, confidence, reason, pnl, yaodi_branch_id, created_at)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'filled', ?, ?, ?, ?, ?, ?, ?)`)
            .run(oid, action.type, dec.code, dec.name, price, action.shares, amount, tradeCost.total, bjNow(), dec.source || 'shundi_auto', dec.confidence || 0, action.reason, pnl, dec.yaodi_branch_id || action.yaodi_branch_id || (db.prepare("SELECT id FROM yaodi_branch WHERE accuracy > 70 ORDER BY accuracy DESC LIMIT 1").get())?.id || null, bjNow());

            // 长期优化:记录回测数据
            const profitPercent = (price - h.avg_cost) / h.avg_cost * 100;
            // 【P0-3修复】舜帝ATR止盈recordBacktestTrade:移除多余original_strategy(better-sqlite3 run()严格校验)
            recordBacktestTrade({
              trade_type: 'sell',
              code: dec.code,
              name: dec.name,
              shares: action.shares,
              price: price,
              amount: amount,
              profit: pnl,
              profit_percent: profitPercent,
              strategy: action.type,
              signal_confidence: dec.confidence || 0,
              atr_stop: dec.atrStop || 0,
              atr_take: dec.atrTake || 0,
              hold_days: Math.floor((Date.now() - new Date(h.update_time).getTime()) / 86400000)
            });

            // ─── 改进3: 舜帝平仓后 → 用真实盈亏更新 Q-Learning ──────────
            resolvePendingTrade(oid, price, Date.now());

            addRedQueenLog(`🟢 舜帝${action.type}: ${dec.name} ${action.shares}股 @¥${price.toFixed(2)} 盈亏¥${pnl.toFixed(2)}`, 'decision');
          }
        } else if (action.direction === '买入' && action.shares > 0) {
          console.log(`[舜帝执行] → 买入分支 ${dec.code} ${dec.name} shares=${action.shares} price=${dec.currentPrice || (action.amount/action.shares)}`);
          // [诊断] 舜帝买入执行诊断
          console.log(`[舜帝执行] 买入决策: ${dec.code} ${dec.name} ${action.shares}股 ¥${(action.amount||0).toFixed(0)} available=${available} isTradingHours=${isTradingHours()}`);
          // 执行买入
          const price = dec.currentPrice || (action.amount / action.shares);
          const amount = action.shares * price;

          // 【A股涨跌停】买入价不能超过涨停价
          const pLimit = getPriceLimit(dec.code, price);
          if (price > pLimit.limitUp) {
            addRedQueenLog(`⚠️ A股涨停限制:${dec.name} ¥${price.toFixed(2)} > 涨停价¥${pLimit.limitUp.toFixed(2)}`);
            continue;
          }

          // 风控检查
          if (amount > available) {
            addRedQueenLog(`⚠️ 舜帝买入跳过: ${dec.name} 资金不足 (需¥${amount.toFixed(0)}, 可用¥${available.toFixed(0)})`, 'warning');
            continue;
          }
          if (amount > capital.max_single_position) {
            addRedQueenLog(`⚠️ 舜帝买入跳过: ${dec.name} 超出单笔限制 (¥${amount.toFixed(0)} > ¥${capital.max_single_position})`, 'warning');
            continue;
          }
          // 【修复2026-05-07】加仓后累计持仓不得超过单股上限
          const existingHolding = db.prepare("SELECT shares, avg_cost FROM shundi_mock_holdings WHERE code = ?").get(dec.code);
          if (existingHolding) {
            const afterAmount = existingHolding.shares * existingHolding.avg_cost + amount;
            if (afterAmount > capital.max_single_position) {
              addRedQueenLog(`⚠️ 舜帝买入跳过: ${dec.name} 累计持仓将超出限制 (¥${afterAmount.toFixed(0)} > ¥${capital.max_single_position})`, 'warning');
              continue;
            }
          }

          const buyCost = calcAStockCost(amount, 'buy');  // A股合规手续费(佣金+过户费,无印花税)
          const commission = buyCost.total;
          const existing = db.prepare("SELECT * FROM shundi_mock_holdings WHERE code = ?").get(dec.code);

          if (existing) {
            const newShares = existing.shares + action.shares;
            const newAvgCost = (existing.avg_cost * existing.shares + price * action.shares) / newShares;
            const src = action.type?.includes('尧帝') ? 'yaodi_signal' : 'shundi';
            // 【Kelly修复】合并为1次UPDATE,同时更新所有字段
            db.prepare("UPDATE shundi_mock_holdings SET shares=?, avg_cost=?, current_price=?, market_value=?*shares, update_time=?, source=?, strategy=?, kelly_ratio=? WHERE code=?")
            .run(newShares, newAvgCost, price, price, bjNow(), src, action.type || 'unknown', parseFloat(dec.kellyRatio || 0), dec.code);
            // 【BUGFIX 2026-05-08】加仓时必须写入交易记录,确保持仓和交易记录一致
            const addOid = "SHUNDI_ADD_" + dec.code + "_" + Date.now();
            const branchId = dec.yaodi_branch_id || action.yaodi_branch_id || null;
            db.prepare(`INSERT INTO shundi_mock_trades (order_id, type, code, name, price, shares, amount, commission, status, filled_time, source, confidence, reason, yaodi_branch_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'filled', ?, ?, ?, ?, ?, ?)`).run(addOid, action.type || '舜帝加仓', dec.code, dec.name, price, action.shares, amount, commission, bjNow(), src, dec.confidence || 0, action.reason, branchId, bjNow());
            addRedQueenLog(`📊 加仓记录: ${dec.name} +${action.shares}股 → 总${newShares}股`, 'decision');
          } else {
            // 【P1修复】冷却期检查移到创建持仓之前,避免有持仓无买入记录
            // 【BUG-2修复】舜帝买入去重:同股票同类型1分钟内不重复下单
            // 【冷却期检查】24小时内不重复买入同一股票(但允许买入记录写入)
            const cooldownCheck = db.prepare("SELECT id FROM shundi_mock_trades WHERE code=? AND type IN ('buy','舜帝买入','智能选股新仓','舜帝加仓') AND filled_time > ?").get(dec.code, bjPast(1));
            // 【BUGFIX 2026-04-25】止损冷却期:止损后2小时内不买回同一股票(防止损→买回→止损死循环)
            const stopLossCooldown = db.prepare("SELECT id FROM shundi_mock_trades WHERE code=? AND type IN ('止损','shundi_stoploss','止损出局','止损保护') AND filled_time > ?").get(dec.code, bjPast(2/24));
            // 【BUGFIX】尧帝信号执行应绕过买入冷却期限制(尧帝信号优先级最高,不受舜帝冷却期约束)
            // 但止损冷却期尧帝信号也不豁免--刚止损的股票不应立刻买回
            if (cooldownCheck && action.type !== '尧帝信号执行') {
              addRedQueenLog(`⏳ 舜帝买入跳过: ${dec.name} 冷却期内 (24小时内已有买入)`, 'warning');
              continue;
            }
            if (stopLossCooldown) {
              addRedQueenLog(`🚫 止损冷却期: ${dec.name} 2小时内止损过,不买回`, 'warning');
              continue;
            }

            // 无持仓时新建(含Kelly公式比例)
            const src = action.type?.includes('尧帝') ? 'yaodi_signal' : 'shundi';
            const kellyRatio = parseFloat(dec.kellyRatio || 0);
            const branchId = dec.yaodi_branch_id || action.yaodi_branch_id || null;
            db.prepare("INSERT INTO shundi_mock_holdings (code, name, shares, avg_cost, current_price, market_value, update_time, strategy, source, kelly_ratio, buy_date, yaodi_branch_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)").run(dec.code, dec.name, action.shares, price, price, amount, bjNow(), action.type || 'unknown', src, kellyRatio, bjNow(), branchId);
            console.log(`[舜帝执行] ✅ INSERT成功: ${dec.code} ${action.shares}股 ¥${amount}`);

            // 【P0修复】舜帝买仓时写入pending_trades数据库(持久化,服务重启不丢失)
            const buyOid = "SHUNDI_" + dec.code + "_" + Date.now();
            try {
              const pState = buildMarketState();
              db.prepare(`INSERT OR REPLACE INTO pending_trades (trade_id, state, action, buy_price, buy_time) VALUES (?, ?, ?, ?, ?)`)
              .run(buyOid, pState, action.direction, price, bjNow());
            } catch(e) { /* 表可能不存在,后续修复 */ }

            // 【P1修复】始终写入买入记录,确保持仓和交易记录一致
            db.prepare(`INSERT INTO shundi_mock_trades (order_id, type, code, name, price, shares, amount, commission, status, filled_time, source, confidence, reason, yaodi_branch_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'filled', ?, ?, ?, ?, ?, ?)`).run(buyOid, action.type || 'buy', dec.code, dec.name, price, action.shares, amount, commission, bjNow(), src, dec.confidence || 0, action.reason, branchId, bjNow());

            // 【P0-2修复】舜帝买仓成功 → recordBacktestTrade写入回测历史
            recordBacktestTrade({
              trade_type: 'buy',
              code: dec.code,
              name: dec.name,
              shares: action.shares,
              price: price,
              amount: amount,
              profit: 0,
              profit_percent: 0,
              strategy: action.type,
              signal_confidence: dec.confidence || 0,
              atr_stop: action.stopPrice || dec.atrStop || 0,
              atr_take: action.takePrice || dec.atrTake || 0,
              hold_days: 0
            });
          }

          // 【优化3】舜帝成功买入→注入尧帝交易信号(舜帝→尧帝自我强化学习)
          try {
            const qState = buildMarketState();
            const qRow = Q_LEARNING.qTable[qState] || { buy: 0 };
            const qScore = qRow.buy || 0;
            // 舜帝成功买 → 尧帝置信度基准
            const sigConf = Math.min(99, Math.round(60 + qScore * 15 + (dec.confidence || 80) * 0.3));
            // 检查是否已有该股舜帝信号(舜帝自己的信号不需要重复注入)
            const hasSig = db.prepare("SELECT id FROM trade_signals WHERE code=? AND expires_at>? AND source LIKE 'shundi%'").get(dec.code, bjNow());
            if (!hasSig) {
              db.prepare(`INSERT INTO trade_signals (code, name, signal, confidence, price, reason, source, expires_at, created_at) VALUES (?, ?, 'buy', ?, ?, ?, 'shundi_auto', ?, ?)`)
                .run(dec.code, dec.name || '舜帝自动', sigConf, price, `舜帝自选: 综合评分${dec.scores?.final||'?'}分, Q-Learning状态=${qState}`, bjFuture(8), bjNow());
            }
          } catch(e) { /* 信号注入失败不影响交易 */ }

          // ─── 改进3: 舜帝买入后 → 记录待结算交易(平仓后更新 Q-Learning)────
          // 【改进】舜帝买入成功后写入pending_trades,卖出时resolvePendingTrade触发Q-Learning更新
          try {
            const buyOid = "SHUNDI_" + dec.code + "_" + Date.now();
            const buyState = buildMarketState();
            db.prepare(`INSERT OR REPLACE INTO pending_trades (trade_id, state, action, buy_price, buy_time) VALUES (?, ?, ?, ?, ?)`).run(buyOid, buyState, 'buy', price, bjNow());
          } catch(e) { /* pending_trades写入失败不影响交易 */ }

          addRedQueenLog(`🟢 舜帝${action.type}: ${dec.name} ${action.shares}股 @¥${price.toFixed(2)} 花费¥${amount.toFixed(0)}`, 'decision');
        }
      } catch (err) {
        console.error(`[舜帝执行] ❌ 舜帝交易失败: ${dec.code} ${dec.name} - ${err.message}`);
        addRedQueenLog(`❌ 舜帝交易失败: ${dec.name} - ${err.message}`, 'error');
      }
    }

    // 8. 同步舜帝决策到红后(API返回舜帝决策信号)
    redqueenDecisions = decisions;

    // 9. 记录舜帝运行日志
    if (decisions.length === 0) {
      addRedQueenLog(`📊 舜帝扫描: 持仓${holdings.length}只, 仓位${posRatio.toFixed(1)}%, 无操作`, 'info');
    } else {
      decisions.forEach(d => {
        const act = d.actions[0];
        addRedQueenLog(`📡 舜帝决策: ${d.code} ${act?.direction||'持有'} ${act?.type||''} conf=${d.confidence||0}`, 'decision');
      });
    }

  } catch (err) {
    console.error('舜帝自动交易周期错误:', err.message, '\nStack:', err.stack);
    // 增强调试:输出decisions数组结构
    if (err.message.includes('final')) {
      console.error('[DEBUG] decisions结构:', JSON.stringify(decisions?.slice(0, 3), null, 2));
    }
    const errDetail = err.stack ? err.stack.split('\n').slice(0, 5).join(' | ') : err.message;
    addRedQueenLog(`❌ 舜帝引擎错误: ${errDetail}`, 'error');
  }
}

function startShundiEngine() {
  if (shundiRunning) return;
  // 【修复】清除可能存在的重复定时器
  if (shundiTimer) { clearInterval(shundiTimer); shundiTimer = null; }
  shundiRunning = true;
  addRedQueenLog('🟢 舜帝模拟盘引擎启动,开始自动交易...', 'system');
  // [CPU监控] 包装shundiAutoCycle添加耗时日志
  const _shundiAutoCycleTimed = async () => { const t=Date.now(); await shundiAutoCycle(); const ms=Date.now()-t; if(ms>100) console.log(`⏱️ [CPU] shundiAutoCycle: ${ms}ms`); };
  shundiTimer = setInterval(_shundiAutoCycleTimed, 60000); // 每分钟运行一次
  setTimeout(shundiAutoCycle, 2000);
  try { db.prepare("UPDATE shundi_engine_state SET status='running', auto_trading=1, last_run=?, updated_at=? WHERE id=1").run(bjNow(), bjNow()); } catch(e){}
  // 【修复】同步更新数据库
  try { db.prepare("UPDATE shundi_engine_state SET status='running', auto_trading=1, last_run=?, updated_at=? WHERE id=1").run(bjNow(), bjNow()); } catch(e){}
}

function stopShundiEngine() {
  shundiRunning = false;
  if (shundiTimer) { clearInterval(shundiTimer); shundiTimer = null; }
  addRedQueenLog('⏹ 舜帝引擎已停止', 'system');
  // 【修复】同步更新数据库
  try { db.prepare("UPDATE shundi_engine_state SET status='stopped', auto_trading=0, updated_at=? WHERE id=1").run(bjNow()); } catch(e){}
}

// ═══════════════════════════════════════════════════════════════════════
// 定时选股任务(早盘9:25 + 尾盘14:30) - 双引擎同时运行
// ═══════════════════════════════════════════════════════════════════════
let lastSelectionDate = '';
let lastSelectionDateShundi = '';

async function runScheduledSelection(period) {
  const now = toBeijingTime(new Date());
  const dateStr = bjISO(now).split('T')[0];
  const timeStr = `${now.getHours()}:${String(now.getMinutes()).padStart(2,'0')}`;

  console.log(`[定时选股] 执行 ${period} 双引擎选股... 当前时间 ${timeStr}`);

  // ━━━ 第一引擎:舜帝引擎 ━━━
  const shundiKey = `${dateStr}_${period}_shundi`;
  if (lastSelectionDateShundi === shundiKey) {
    console.log(`[定时选股/舜帝] ${dateStr} ${period} 已执行过,跳过`);
  } else {
    try {
      console.log(`[定时选股/舜帝] 调用 smartStockSelection ...`);
      const shundiPicks = smartStockSelection(3, 'buy', true, period);
      const shundiType = `${period}_shundi`;

      // 获取尧帝状态和市场环境(舜帝引擎内部已有择时,此处仅用于补充尧帝全景数据)
      const yaodiState = getYaodiState();
      const yaodiAccuracy = yaodiState?.accuracy || 70;
      const marketStats2 = db.prepare("SELECT * FROM market_stats ORDER BY id DESC LIMIT 1").get() || {};
      const upCount2 = marketStats2.up_count || 0;
      const downCount2 = marketStats2.down_count || 0;
      const total2 = Math.max(upCount2 + downCount2, 1);
      const marketEnv2 = upCount2 / total2 > 0.55 ? 'bull' : upCount2 / total2 < 0.45 ? 'bear' : 'neutral';
      const isMorn = period === 'morning';

      // 先删除今日同类型快照
      db.prepare('DELETE FROM selection_snapshots WHERE selection_type = ? AND date = ?').run(shundiType, dateStr);

      if (shundiPicks && shundiPicks.length > 0) {
        const insertStmt = db.prepare(`
          INSERT INTO selection_snapshots
          (selection_type, stock_code, stock_name, price, change_percent, win_rate, reason, risk, selection_time, date, full_data, snapshot_time, market_data_time)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `);
        let savedCount = 0;
        for (const sig of shundiPicks) {
          try {
            // 查询最新价格
            let price = sig.price || 0;
            let changePercent = sig.change_percent || 0;
            let high = price, low = price, volume = 0;
            const priceInfo = db.prepare('SELECT * FROM stock_realtime WHERE code = ? OR code = ? OR code = ?').get(sig.code, 'sh' + sig.code, 'sz' + sig.code);
            if (priceInfo) {
              if (!price) price = priceInfo.price;
              changePercent = priceInfo.change_percent || changePercent;
              high = priceInfo.high || price;
              low = priceInfo.low || price;
              volume = priceInfo.volume || 0;
            }

            // 【BUG修复 2026-05-07】涨停/跌停股不保存(区分板块阈值)
            if (isLimitPrice(sig.code, changePercent, sig.name)) {
              console.log(`[舜帝选股] 🚫 跳过涨停/跌停股: ${sig.code} ${sig.name} ${changePercent}%`);
              continue;
            }
            // 【BUG修复 2026-05-07】ST/*ST股不保存
            if ((sig.name || '').includes('ST') || (sig.name || '').includes('*ST')) {
              console.log(`[舜帝选股] 🚫 跳过ST股: ${sig.code} ${sig.name}`);
              continue;
            }
            // 【BUG修复 2026-05-07】科创板不保存
            if ((sig.code || '').startsWith('688') || (sig.code || '').startsWith('689')) {
              console.log(`[舜帝选股] 🚫 跳过科创板: ${sig.code} ${sig.name}`);
              continue;
            }
            // 【2026-06-05修复】停牌股不保存（数据超过48小时未更新）
            if (priceInfo) {
              const updateTime = priceInfo.update_time || '';
              if (updateTime) {
                const ageMs = Date.now() - new Date(updateTime).getTime();
                if (ageMs > 48 * 60 * 60 * 1000) {
                  console.log(`[舜帝选股] 🚫 跳过停牌股(数据${Math.round(ageMs/3600000)}h未更新): ${sig.code} ${sig.name}`);
                  continue;
                }
              }
            }

            // 尧帝置信度
            const yaodiConfidence = sig.confidence || 70;
            // 预期涨幅
            const baseGain = isMorn ? 3.5 : 2.8;
            const confidenceBonus = (yaodiConfidence - 70) / 10 * 0.5;
            const marketBonus = marketEnv2 === 'bull' ? 0.5 : marketEnv2 === 'bear' ? -0.5 : 0;
            const expectedGain = Math.max(1.5, Math.min(8, baseGain + confidenceBonus + marketBonus)).toFixed(1);
            // 买入区间
            let buyPriceLow, buyPriceHigh, buyStrategy;
            const changePct = changePercent || 0;
            if (isMorn) {
              const refPrice = price / (1 + changePct / 100);
              buyPriceLow = parseFloat((refPrice * 0.995).toFixed(2));
              buyPriceHigh = parseFloat((refPrice * 1.01).toFixed(2));
              buyStrategy = '开盘观察5-10分钟,稳定后分批买入';
            } else {
              buyPriceLow = parseFloat((low * 1.002).toFixed(2));
              buyPriceHigh = parseFloat((price * 1.005).toFixed(2));
              buyStrategy = '尾盘14:50后择机介入';
            }
            const exitTarget = parseFloat((price * (1 + parseFloat(expectedGain) / 100)).toFixed(2));
            const holdingPeriod = isMorn ? '1-3天' : '1-2天';
            const holdingDesc = isMorn ? '短线操作,首日冲高可获利了结,亏损超3%止损' : '隔日交易,次日开盘冲高卖出,注意开盘跳空风险';
            const positionAdvice = yaodiConfidence >= 85 ? '标准仓' : yaodiConfidence >= 75 ? '轻仓' : '观察仓';
            const positionPct = yaodiConfidence >= 85 ? '20~30%' : yaodiConfidence >= 75 ? '10~20%' : '5~10%';
            const yaodiSharpe = yaodiState?.sharpeRatio ?? null;  // [修复] 不硬编码
            const yaodiMaxDrawdown = yaodiState?.maxDrawdown ?? null;  // [修复] 不硬编码
            const yaodiMarketSentiment = Math.round((upCount2 - downCount2) / total2 * 100);
            const branchCount = db.prepare("SELECT COUNT(*) as c FROM yaodi_branch WHERE accuracy >= 50").get()?.c || 0;

            // 记录行情数据时间(stock_realtime 的最后更新时间)
            const marketDataTime = priceInfo?.update_time || bjISO(now);

            let fullStock = {
              code: sig.code,
              name: sig.name,
              price: price,
              changePercent: changePercent,
              high: high,
              low: low,
              volume: volume,
              winRate: yaodiConfidence,
              reason: sig.reason || '',
              risk: sig.risk || '注意仓位控制,严格执行止损',
              yaodiConfidence: yaodiConfidence,
              expectedGain: expectedGain,
              buyPriceLow: buyPriceLow,
              buyPriceHigh: buyPriceHigh,
              buyStrategy: buyStrategy,
              exitTarget: exitTarget,
              holdingPeriod: holdingPeriod,
              holdingDesc: holdingDesc,
              positionAdvice: positionAdvice,
              positionPct: positionPct,
              marketEnvironment: marketEnv2,
              selectionType: shundiType,
              yaodiSharpe: (yaodiSharpe ?? 0).toFixed(2),
              yaodiMaxDrawdown: (yaodiMaxDrawdown ?? 0).toFixed(1),
              yaodiMarketSentiment: yaodiMarketSentiment,
              yaodiBranchCount: branchCount,
              marketDataTime: marketDataTime, // 行情数据时间戳
              source: sig.source || sig.signal || '舜帝引擎',
              strategyAccuracy: sig.strategyAccuracy,
              marketRegime: sig.marketRegime || marketEnv2,
              scores: sig.scores || {},
            };

            // 先删除今日同类型快照(已在上面做,此处再加保险)
            db.prepare('DELETE FROM selection_snapshots WHERE selection_type = ? AND date = ?').run(shundiType, dateStr);

            insertStmt.run(
              shundiType,
              fullStock.code,
              fullStock.name,
              fullStock.price,
              fullStock.changePercent,
              fullStock.winRate,
              fullStock.reason,
              fullStock.risk,
              bjISO(now),
              dateStr,
              JSON.stringify(fullStock),
              bjISO(now),  // snapshot_time
              marketDataTime // market_data_time
            );
            savedCount++;
          } catch(e) {
            console.log(`[定时选股/舜帝] 保存失败: ${e.message}`);
          }
        }
        console.log(`[定时选股/舜帝] ✅ ${dateStr} ${period} 完成,保存 ${savedCount} 只股票`);
      } else {
        console.log(`[定时选股/舜帝] ⚠️ ${period} 选股无结果`);
      }
      lastSelectionDateShundi = shundiKey;
    } catch(e) {
      console.error(`[定时选股/舜帝] ❌ 失败: ${e.message}`);
    }
  }

  // ━━━ 第二引擎:三层选股引擎 ━━━
  const threeLayerKey = `${dateStr}_${period}_threelayer`;
  if (lastSelectionDate === threeLayerKey) {
    console.log(`[定时选股/三层] ${dateStr} ${period} 已执行过,跳过`);
  } else {
    // 获取尧帝当前状态(用于计算尧帝置信度等)
    const yaodiState = getYaodiState();
    const yaodiAccuracy = yaodiState?.accuracy || 70;
    const yaodiWinRate = yaodiState?.winRate || 60;

    // 获取市场环境
    const marketStats = db.prepare("SELECT * FROM market_stats ORDER BY id DESC LIMIT 1").get() || {};
    const upCount = marketStats.up_count || 0;
    const downCount = marketStats.down_count || 0;
    const total = Math.max(upCount + downCount, 1);
    const marketEnv = upCount / total > 0.55 ? 'bull' : upCount / total < 0.45 ? 'bear' : 'neutral';
    const isMorn = period === 'morning';

    try {
      const limit = 3;
      console.log(`[定时选股/三层] 调用三层选股引擎 (环境: ${marketEnv})`);
      const result = await threeLayerSelector.select({
        limit: limit,
        marketEnv: marketEnv,
        candidateSize: 400,
        includeKCB: false,
        includeBEJ: false,
        period: period
      });

      const threeLayerType = `${period}_threelayer`;

      // 先删除今日同类型的快照(无论是否有结果)
      db.prepare('DELETE FROM selection_snapshots WHERE selection_type = ? AND date = ?').run(threeLayerType, dateStr);

      if (result && result.stocks && result.stocks.length > 0) {
        const signals = result.stocks.map(s => ({
          code: s.code,
          name: s.name,
          price: s.price,
          change_percent: s.change_percent || 0,
          confidence: s.score / 100,
          scores: { final: s.score },
          reason: `三层选股: L1=${s.layer1Score} L2=${s.layer2Score} 风险=${s.riskScore}`,
          risk: s.riskScore > 70 ? 'high' : s.riskScore > 40 ? 'medium' : 'low',
          factors: s.factors,
          riskScore: s.riskScore,
          riskReasons: s.riskReasons,
          // 【修复】补充缺失字段:layer1Score / layer2Score
          layer1Score: s.layer1Score,
          layer2Score: s.layer2Score,
          yaodiConfidence: s.yaodiConfidence,
          yaodiSharpe: s.yaodiSharpe,
          yaodiMaxDrawdown: s.yaodiMaxDrawdown,
          yaodiMarketSentiment: s.yaodiMarketSentiment,
          yaodiBranchCount: s.yaodiBranchCount,
          positionPct: s.positionPct,
        }));

        const insertStmt = db.prepare(`
          INSERT INTO selection_snapshots
          (selection_type, stock_code, stock_name, price, change_percent, win_rate, reason, risk, selection_time, date, full_data, snapshot_time, market_data_time)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `);

        let savedCount = 0;
        for (const sig of signals) {
          try {
            // 【关键修复】过滤指数类代码
            if (sig.code.startsWith('sh') || sig.code.startsWith('sz') || sig.code.startsWith('00000') || sig.code.startsWith('39900')) {
              console.log(`[定时选股/三层] 跳过指数: ${sig.code}`);
              continue;
            }
            if (sig.code.startsWith('688') || sig.code.startsWith('8')) {
              console.log(`[定时选股/三层] 跳过科创板/北交所: ${sig.code}`);
              continue;
            }
            let stockName = sig.name || sig.stock_name;
            if (!stockName) {
              const stockInfo = db.prepare('SELECT name FROM stocks WHERE code = ? OR code = ? OR code = ?').get(sig.code, 'sh' + sig.code, 'sz' + sig.code);
              stockName = stockInfo ? stockInfo.name : sig.code;
            }
            if (stockName && (stockName.includes('ST') || stockName.includes('*ST'))) {
              console.log(`[定时选股/三层] 跳过ST股: ${sig.code} ${stockName}`);
              continue;
            }

            let price = sig.price || 0;
            let changePercent = sig.change_percent || 0;
            let high = price, low = price, volume = 0;
            const priceInfo = db.prepare('SELECT * FROM stock_realtime WHERE code = ? OR code = ? OR code = ?').get(sig.code, 'sh' + sig.code, 'sz' + sig.code);
            if (priceInfo) {
              if (!price) price = priceInfo.price;
              changePercent = priceInfo.change_percent || changePercent;
              high = priceInfo.high || price;
              low = priceInfo.low || price;
              volume = priceInfo.volume || 0;
            }

            const threeLayerScore = sig.scores?.final || sig.score || 0;
            const yaodiConfidence = Math.round(threeLayerScore * 0.6 + yaodiAccuracy * 0.4);
            const baseGain = isMorn ? 3.5 : 2.8;
            const confidenceBonus = (yaodiConfidence - 70) / 10 * 0.5;
            const marketBonus = marketEnv === 'bull' ? 0.5 : marketEnv === 'bear' ? -0.5 : 0;
            const expectedGain = Math.max(1.5, Math.min(8, baseGain + confidenceBonus + marketBonus)).toFixed(1);

            let buyPriceLow, buyPriceHigh, buyStrategy;
            const changePct = changePercent || 0;
            if (isMorn) {
              const refPrice = price / (1 + changePct / 100);
              buyPriceLow = parseFloat((refPrice * 0.995).toFixed(2));
              buyPriceHigh = parseFloat((refPrice * 1.01).toFixed(2));
              buyStrategy = '开盘观察5-10分钟,稳定后分批买入';
            } else {
              buyPriceLow = parseFloat((low * 1.002).toFixed(2));
              buyPriceHigh = parseFloat((price * 1.005).toFixed(2));
              buyStrategy = '尾盘14:50后择机介入';
            }

            const exitTarget = parseFloat((price * (1 + parseFloat(expectedGain) / 100)).toFixed(2));
            const holdingPeriod = isMorn ? '1-3天' : '1-2天';
            const holdingDesc = isMorn
              ? '短线操作,首日冲高可获利了结,亏损超3%止损'
              : '隔日交易,次日开盘冲高卖出,注意开盘跳空风险';
            const positionAdvice = yaodiConfidence >= 85 ? '标准仓' : yaodiConfidence >= 75 ? '轻仓' : '观察仓';
            const positionPct = yaodiConfidence >= 85 ? '20~30%' : yaodiConfidence >= 75 ? '10~20%' : '5~10%';
            const yaodiSharpe = yaodiState?.sharpeRatio ?? null;  // [修复] 不硬编码
            const yaodiMaxDrawdown = yaodiState?.maxDrawdown ?? null;  // [修复] 不硬编码
            const yaodiMarketSentiment = Math.round((upCount - downCount) / total * 100);
            const branchCount = db.prepare("SELECT COUNT(*) as c FROM yaodi_branch WHERE accuracy >= 50").get()?.c || 0;

            let fullStock = {
              code: sig.code || sig.stock_code,
              name: stockName,
              price: price,
              changePercent: changePercent,
              high: high,
              low: low,
              volume: volume,
              winRate: yaodiConfidence,
              reason: sig.reason || sig.signal || '',
              risk: sig.risk || '注意仓位控制,严格执行止损',
              yaodiConfidence: yaodiConfidence,
              expectedGain: expectedGain,
              buyPriceLow: buyPriceLow,
              buyPriceHigh: buyPriceHigh,
              buyStrategy: buyStrategy,
              exitTarget: exitTarget,
              holdingPeriod: holdingPeriod,
              holdingDesc: holdingDesc,
              positionAdvice: positionAdvice,
              positionPct: positionPct,
              marketEnvironment: marketEnv,
              selectionType: threeLayerType,
              yaodiSharpe: (yaodiSharpe ?? 0).toFixed(2),
              yaodiMaxDrawdown: (yaodiMaxDrawdown ?? 0).toFixed(1),
              yaodiMarketSentiment: yaodiMarketSentiment,
              yaodiBranchCount: branchCount,
              // 三层引擎特有字段
              layer1Score: sig.scores?.layer1 || sig.layer1Score,
              layer2Score: sig.scores?.layer2 || sig.layer2Score,
              riskScore: sig.riskScore,
              riskReasons: sig.riskReasons,
              factors: sig.factors,
            };

            insertStmt.run(
              threeLayerType,
              fullStock.code,
              fullStock.name,
              fullStock.price,
              fullStock.changePercent,
              fullStock.winRate,
              fullStock.reason,
              fullStock.risk,
              bjISO(now),
              dateStr,
              JSON.stringify(fullStock),
              bjISO(now),  // snapshot_time
              bjISO(now)   // market_data_time (三层引擎:同snapshot时间)
            );
            savedCount++;
          } catch(e) {
            console.log(`[定时选股/三层] 保存失败: ${e.message}`);
          }
        }

        lastSelectionDate = threeLayerKey;
        console.log(`[定时选股/三层] ✅ ${dateStr} ${period} 完成,保存 ${savedCount} 只股票`);
      } else {
        // 保存空结果执行记录(用于审计)
        const emptyRecord = {
          success: true,
          stocks: [],
          marketRegime: result?.marketRegime || 'unknown',
          totalTime: result?.totalTime || '0ms',
          reason: 'market_regime_block'
        };
        db.prepare(`INSERT INTO selection_snapshots
          (selection_type, stock_code, stock_name, selection_time, date, full_data)
          VALUES (?, 'NONE', '无选股结果', ?, ?, ?)`)
          .run(threeLayerType, bjISO(), dateStr, JSON.stringify(emptyRecord));
        lastSelectionDate = threeLayerKey;
        console.log(`[定时选股/三层] ⚠️ ${dateStr} ${period} 无选股结果 (${result?.marketRegime}), 已保存执行记录`);
      }
    } catch(e) {
      console.error(`[定时选股/三层] ❌ 失败: ${e.message}`);
    }
  }
}

// 【P1修复】选股时间调度安全窗口:早盘9:20-9:35,尾盘14:20-14:45(±10分钟窗口)
// 失败自动重试(最多3次,间隔1分钟),解决数据源偶发故障问题
// [2026-04-30] 定时选股任务恢复运行
let _selWindow = { date: '', morningDone: false, eveningDone: false, morningTries: 0, eveningTries: 0 };

setInterval(() => {
  const now = toBeijingTime(new Date());
  const hour = now.getHours(), minute = now.getMinutes();
  const today = bjDate();

  // 每天重置
  if (_selWindow.date !== today) {
    _selWindow = { date: today, morningDone: false, eveningDone: false, morningTries: 0, eveningTries: 0 };
  }

  // 【2026-05-20】选股窗口精确化:早盘9:25-9:30,尾盘14:45-15:00
  const inMorning = (hour === 9 && minute >= 25 && minute <= 30);
  const inEvening = (hour === 14 && minute >= 45) || (hour === 15 && minute === 0);
  const isTrade = isTradingHours();

  // 早盘选股(窗口内最多重试3次,runScheduledSelection内部有去重保护)
  if (isTrade && inMorning && !_selWindow.morningDone && _selWindow.morningTries < 3) {
    _selWindow.morningTries++;
    _selWindow.morningDone = true;
    console.log(`[定时选股] 🕘 早盘选股第${_selWindow.morningTries}次触发`);
    runScheduledSelection('morning');
  }

  // 尾盘选股(窗口内最多重试3次,runScheduledSelection内部有去重保护)
  if (isTrade && inEvening && !_selWindow.eveningDone && _selWindow.eveningTries < 3) {
    _selWindow.eveningTries++;
    _selWindow.eveningDone = true;
    console.log(`[定时选股] 🕓 尾盘选股第${_selWindow.eveningTries}次触发`);
    runScheduledSelection('evening');
  }
}, 60000);

console.log('✅ 定时选股任务已启动 (早盘9:25, 尾盘14:45)');

// ═══════════════════════════════════════════════════════════════
// 长期优化1: 实时止损止盈监控系统
// ═══════════════════════════════════════════════════════════════
let stopLossMonitorTimer = null;
let stopLossMonitorRunning = false;

function startStopLossMonitor() {
  if (stopLossMonitorTimer) {
    stopLossMonitorRunning = true; // 即使timer存在,也确保状态正确
    return;
  }
  stopLossMonitorRunning = true;

  stopLossMonitorTimer = setInterval(() => {
    try {
      // P1修复: 从shundi_mock_holdings读取策略,join回shundi_backtest_history取真实strategy
      const holdings = db.prepare(`
        SELECT
          h.code, h.name, h.shares, h.avg_cost, h.current_price,
          h.market_value, h.profit_percent, h.source, h.strategy,
          COALESCE(
            (SELECT b.strategy FROM shundi_backtest_history b
             WHERE b.code = h.code AND b.trade_type = 'buy'
             ORDER BY b.create_time ASC LIMIT 1),
            h.strategy
          ) as real_strategy
        FROM shundi_mock_holdings h
      `).all();
      const alerts = [];

      holdings.forEach(h => {
        const buyPrice = h.avg_cost;
        const currentPrice = h.current_price || buyPrice;
        if (!buyPrice || !currentPrice) return;
        const pct = (currentPrice - buyPrice) / buyPrice * 100;

        // 计算ATR止损止盈价格(ATR=0时跳过止损预警)
        const atrStop = atrStopLoss(h.code, buyPrice, 'long');
        const atrTake = atrTakeProfit(h.code, buyPrice, 'long');

        // 触发止损预警(仅当ATR有效时,防止冷启动无数据时错误触发)
        if (atrStop > 0 && currentPrice <= atrStop * 1.02) { // 接近止损价2%以内
          const firstSeen = getAlertTime(h.code, '止损预警');
          const d = new Date(firstSeen);
          alerts.push({
            code: h.code, name: h.name, type: '止损预警', currentPrice,
            stopPrice: atrStop, profitPct: pct.toFixed(2),
            urgency: currentPrice <= atrStop ? '紧急' : '警告',
            alertTime: d.toLocaleTimeString('zh-CN', { hour12: false }) + '.' + String(d.getMilliseconds()).padStart(3,'0'),
            alertTimeISO: firstSeen
          });
        }
        // 触发止盈预警
        if (currentPrice >= atrTake * 0.98) { // 接近止盈价2%以内
          const firstSeen = getAlertTime(h.code, '止盈预警');
          const d = new Date(firstSeen);
          alerts.push({
            code: h.code, name: h.name, type: '止盈预警', currentPrice,
            takePrice: atrTake, profitPct: pct.toFixed(2),
            urgency: currentPrice >= atrTake ? '达成' : '接近',
            alertTime: d.toLocaleTimeString('zh-CN', { hour12: false }) + '.' + String(d.getMilliseconds()).padStart(3,'0'),
            alertTimeISO: firstSeen
          });
        }

        // 更新持仓盈亏
        db.prepare(`
          UPDATE shundi_mock_holdings
          SET profit = ?, profit_percent = ?, update_time = ?
          WHERE code = ?
        `).run((currentPrice - buyPrice) * h.shares, pct, bjNow(), h.code);
      });

      // 记录预警日志
      if (alerts.length > 0) {
        alerts.forEach(alert => {
          const logMsg = `🚨 ${alert.urgency} | ${alert.code} ${alert.name} | ${alert.type} | 当前¥${alert.currentPrice.toFixed(2)} | 盈亏${alert.profitPct}%`;
          addRedQueenLog(logMsg, 'alert');

          // 同步写入 risk_events 表(给前端风控日志Tab使用)
          try {
            db.prepare(`INSERT INTO risk_events (code, name, signal, reason, action) VALUES (?, ?, ?, ?, ?)`)
              .run(alert.code, alert.name, alert.signal || '', `${alert.type}|${alert.urgency}|¥${alert.currentPrice}|${alert.profitPct}%`, alert.type);
          } catch (e) { /* risk_events表不存在静默失败 */ }

          // 【FIX-2026-05-07】仅止损预警注入黑天鹅系统,止盈预警跳过
          if (alert.type === '止盈预警') return;

          // 将止损预警注入黑天鹅系统,触发前端弹窗
          const severity = alert.urgency === '紧急' ? 'RED' : 'ORANGE';
          const expireMs = severity === 'RED' ? 15 * 60 * 1000 : 10 * 60 * 1000;
          const alertId = `stoploss_${alert.code}`; // 稳定ID,同一股不重复
          const alertObj = {
            id: alertId,
            type: 'stoploss',
            severity,
            score: severity === 'RED' ? 90 : 70,
            title: `🚨 止损预警:${alert.name}(${alert.code})`,
            desc: `${alert.urgency} | 当前¥${alert.currentPrice.toFixed(2)} | 止损价¥${alert.stopPrice > 0 ? alert.stopPrice.toFixed(2) : 'N/A'} | 盈亏${alert.profitPct}%`,
            stopPrice: alert.stopPrice > 0 ? alert.stopPrice : null,
            currentPrice: alert.currentPrice,
            codes: [alert.code],
            expireAt: Date.now() + expireMs,
            timestamp: bjISO()
          };

          // 按稳定ID去重:同股只弹一次(过期后自动消失)
          const existing = recentBlackSwans.find(e => e.id === alertId && e.type === 'stoploss');
          if (!existing) {
            recentBlackSwans.push(alertObj);
            // 同步写入历史
            blackSwanHistory.unshift({ ...alertObj, status: 'active' });
            blackSwanHistory = blackSwanHistory.slice(0, 500);
            // 持久化到 black_swan_events 表
            try {
              db.prepare(`
                INSERT OR IGNORE INTO black_swan_events
                (event_type, severity, stock_code, stock_name, description, price_change, detected_at, resolution)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
              `).run(
                alertObj.type || 'stoploss', alertObj.severity || 'RED',
                alert.code, alert.name,
                alertObj.desc,
                parseFloat(alert.profitPct || 0),
                bjDate(), 'active'
              );
            } catch (e) { /* 黑天鹅表不存在静默失败 */ }
          } else {
            // 已有预警但快过期 → 刷新过期时间(让用户再看到提醒)
            existing.expireAt = Date.now() + expireMs;
            existing.desc = alertObj.desc;
          }
        });

        // 清理过期事件
        recentBlackSwans = recentBlackSwans.filter(ev => !ev.expireAt || Date.now() < ev.expireAt);
      }
    } catch (e) {
      console.error('止损监控错误:', e.message);
    }
  }, 30000); // 每30秒检查一次

  console.log('✅ 止损止盈监控已启动');
}

function stopStopLossMonitor() {
  if (stopLossMonitorTimer) {
    clearInterval(stopLossMonitorTimer);
    stopLossMonitorTimer = null;
  }
  stopLossMonitorRunning = false;
  console.log('⏹️ 止损止盈监控已停止');
}

// ═══════════════════════════════════════════════════════════════
// 长期优化2: 回测历史数据积累系统
// ═══════════════════════════════════════════════════════════════
function initBacktestTables() {
  // 创建回测历史表
  db.exec(`
    CREATE TABLE IF NOT EXISTS shundi_backtest_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      trade_date TEXT,
      trade_type TEXT,
      code TEXT,
      name TEXT,
      shares INTEGER,
      price REAL,
      amount REAL,
      profit REAL,
      profit_percent REAL,
      strategy TEXT,
      signal_confidence REAL,
      atr_stop REAL,
      atr_take REAL,
      hold_days INTEGER,
      create_time TEXT
    )
  `);

  // 舜帝模拟盘核心表
  db.exec(`CREATE TABLE IF NOT EXISTS shundi_capital_config (
    id INTEGER PRIMARY KEY,
    total_capital REAL DEFAULT 1000000,
    available_capital REAL DEFAULT 1000000,
    max_single_position REAL DEFAULT 200000,
    max_total_position REAL DEFAULT 800000,
    risk_level TEXT DEFAULT 'medium',
    updated_at TEXT
  )`);

  db.exec(`CREATE TABLE IF NOT EXISTS shundi_mock_holdings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT UNIQUE,
    name TEXT,
    shares INTEGER DEFAULT 0,
    avg_cost REAL,
    current_price REAL,
    market_value REAL,
    profit REAL DEFAULT 0,
    profit_percent REAL DEFAULT 0,
    strategy TEXT DEFAULT 'unknown',
    kelly_ratio REAL DEFAULT 0,
    source TEXT DEFAULT 'shundi',
    update_time TEXT DEFAULT CURRENT_TIMESTAMP
  )`);

  // 【Kelly修复】已有表若缺kelly_ratio列则添加
  try { db.exec("ALTER TABLE shundi_mock_holdings ADD COLUMN kelly_ratio REAL DEFAULT 0"); } catch(e){}
  // 【A股T+1】已有表若缺buy_date列则添加
  try { db.exec("ALTER TABLE shundi_mock_holdings ADD COLUMN buy_date TEXT"); } catch(e){}
  // 【演化关联】已有表若缺yaodi_branch_id列则添加(记录交易来源分支)
  try { db.exec("ALTER TABLE shundi_mock_holdings ADD COLUMN yaodi_branch_id TEXT"); } catch(e){}
  // 【演化关联】shundi_mock_trades表也加yaodi_branch_id
  try { db.exec("ALTER TABLE shundi_mock_trades ADD COLUMN yaodi_branch_id TEXT"); } catch(e){}

  db.exec(`CREATE TABLE IF NOT EXISTS shundi_mock_trades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_id TEXT UNIQUE,
    type TEXT,
    code TEXT,
    name TEXT,
    price REAL,
    shares INTEGER,
    amount REAL,
    commission REAL DEFAULT 0,
    status TEXT,
    filled_time TEXT,
    source TEXT,
    confidence REAL,
    reason TEXT,
    pnl REAL
  )`);

  db.exec(`CREATE TABLE IF NOT EXISTS shundi_engine_state (
    id INTEGER PRIMARY KEY,
    status TEXT DEFAULT 'stopped',
    auto_trading INTEGER DEFAULT 0,
    last_run TEXT,
    updated_at TEXT
  )`);

  // 【P0修复 2026-04-28】非交易时段延迟交易表(增加id主键和status状态)
  db.exec(`CREATE TABLE IF NOT EXISTS deferred_trades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT NOT NULL,
    name TEXT,
    action_type TEXT NOT NULL,
    direction TEXT NOT NULL,
    shares INTEGER DEFAULT 0,
    amount REAL DEFAULT 0,
    reason TEXT,
    priority REAL DEFAULT 0,
    yaodi_branch_id TEXT,
    created_at TEXT,
    status TEXT DEFAULT 'pending',
    executed_at TEXT
  )`);
  // 迁移:给已存在的表添加新列
  try { db.exec(`ALTER TABLE deferred_trades ADD COLUMN id INTEGER PRIMARY KEY AUTOINCREMENT`); } catch(e) {}
  try { db.exec(`ALTER TABLE deferred_trades ADD COLUMN yaodi_branch_id TEXT`); } catch(e) {}
  try { db.exec(`ALTER TABLE deferred_trades ADD COLUMN status TEXT DEFAULT 'pending'`); } catch(e) {}
  try { db.exec(`ALTER TABLE deferred_trades ADD COLUMN executed_at TEXT`); } catch(e) {}

  // 初始化默认资金配置
  db.prepare("INSERT OR IGNORE INTO shundi_capital_config (id, total_capital, available_capital) VALUES (1, 1000000, 1000000)").run();

  // 初始化引擎状态
  db.prepare("INSERT OR IGNORE INTO shundi_engine_state (id, status, auto_trading) VALUES (1, 'stopped', 0)").run();

  // 创建策略统计表
  db.exec(`
    CREATE TABLE IF NOT EXISTS strategy_backtest_stats (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      strategy TEXT UNIQUE,
      total_trades INTEGER DEFAULT 0,
      win_trades INTEGER DEFAULT 0,
      lose_trades INTEGER DEFAULT 0,
      total_profit REAL DEFAULT 0,
      avg_profit REAL DEFAULT 0,
      win_rate REAL DEFAULT 0,
      sharpe_ratio REAL DEFAULT 0,
      max_drawdown REAL DEFAULT 0,
      update_time TEXT
    )
  `);

  console.log('✅ 回测数据表已初始化');
}

// 舜帝交易弹窗通知(单条仅通知一次)
function addShundiNotification(trade) {
  try {
    const id = 'sn_' + Date.now() + '_' + Math.random().toString(36).slice(2,6);
    const now = bjISO();
    db.prepare(`
      INSERT OR IGNORE INTO shundi_notifications
      (id,trade_type,code,name,price,shares,amount,profit_percent,reason,confidence,source,notified,created_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,0,?)
    `).run(id, trade.type, trade.code, trade.name, trade.price || 0, trade.shares || 0,
           trade.amount || (trade.price * trade.shares) || 0,
           trade.profit_percent || 0, trade.reason || '', trade.confidence || 0,
           trade.source || 'shundi', now);
    console.log('[通知] 舜帝交易弹窗: ' + trade.type + ' ' + trade.name + '(' + trade.code + ') ' + (trade.shares||0) + '股@¥' + (trade.price||0).toFixed(2));
  } catch(e) { console.error('[通知失败]', e.message); }
}

function recordBacktestTrade(trade) {
  // 舜帝策略名 → yaodi_branch 前缀映射
  const SHUNDI_STRATEGY_MAP = {
    'ATR止盈':     { prefix: 'ATR指标',   desc: 'ATR止盈' },
    'ATR止损':     { prefix: 'ATR指标',   desc: 'ATR止损' },
    '凯利加仓':    { prefix: 'ATR指标',   desc: '凯利加仓' },
    '智能选股新仓': { prefix: 'ATR指标',  desc: '智能选股' },
  };

  // P0修复: 追踪原始买入策略,用于平仓时更新原始策略统计
  const ORIGINAL_STRATEGY_MAP = {};

  try {
    db.prepare(`
      INSERT INTO shundi_backtest_history
      (trade_date, trade_type, code, name, shares, price, amount, profit, profit_percent, strategy, signal_confidence, atr_stop, atr_take, hold_days)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      trade.trade_date || bjDate(),
      trade.trade_type,
      trade.code,
      trade.name,
      trade.shares,
      trade.price,
      trade.amount,
      trade.profit || 0,
      trade.profit_percent || 0,
      trade.strategy || 'unknown',
      trade.signal_confidence || 0,
      trade.atr_stop || 0,
      trade.atr_take || 0,
      trade.hold_days || 0
    );

    // ── P0核心修复:舜帝平仓后同步到 branch_performance → yaodi_branch ──
    if (trade.trade_type === 'sell') {
      const mapped = SHUNDI_STRATEGY_MAP[trade.strategy];
      if (mapped) {
        const branch = db.prepare(`
          SELECT id, name, trades, win_rate, accuracy
          FROM yaodi_branch
          WHERE name LIKE ? AND active = 1
          ORDER BY evolution_level DESC LIMIT 1
        `).get(mapped.prefix + '%');
        if (branch) {
          const winRate = trade.profit > 0 ? 100 : 0;
          const prevTrades = Math.floor(branch.trades || 0);  // 【防溢出】确保整数
          const prevWinRate = branch.win_rate || 50;
          const newTrades = prevTrades + 1;
          // 滚动均值:(旧胜率*旧交易数 + 新胜率) / 新交易数
          const newWinRate = parseFloat(((prevWinRate * prevTrades + winRate) / newTrades).toFixed(2));

          // 更新 yaodi_branch
          db.prepare(`
            UPDATE yaodi_branch SET
              trades = ?,
              win_rate = ?,
              accuracy = ?
            WHERE id = ?
          `).run(newTrades, newWinRate, newWinRate, branch.id);

          // 更新 branch_performance
          const existingPerf = db.prepare(`
            SELECT id, trade_count, win_rate as prev_wr FROM branch_performance
            WHERE branch_id = ? AND environment = '舜帝回测'
          `).get(branch.id);
          if (existingPerf) {
            const epPrevTrades = existingPerf.trade_count || 0;
            const epPrevWR = existingPerf.prev_wr || 50;
            const epNewTrades = epPrevTrades + 1;
            const epNewWR = parseFloat(((epPrevWR * epPrevTrades + winRate) / epNewTrades).toFixed(2));
            const epNewProfitRate = parseFloat((existingPerf.trade_count || 1) * (trade.profit_percent || 0) / epNewTrades).toFixed(2);
            db.prepare(`
              UPDATE branch_performance SET
                trade_count = ?,
                win_rate = ?,
                profit_rate = ?,
                max_drawdown = MIN(max_drawdown, ?),
                updated_at = CURRENT_TIMESTAMP
              WHERE branch_id = ? AND environment = '舜帝回测'
            `).run(epNewTrades, epNewWR, epNewProfitRate, trade.profit_percent || 0, branch.id);
          } else {
            db.prepare(`
              INSERT INTO branch_performance
              (branch_id, branch_name, environment, trade_count, win_rate, profit_rate, max_drawdown, updated_at)
              VALUES (?, ?, '舜帝回测', 1, ?, ?, ?, CURRENT_TIMESTAMP)
            `).run(branch.id, branch.name, winRate, trade.profit_percent || 0, trade.profit_percent || 0);
          }
          console.log(`[交易反馈] ${branch.name} ← ${trade.strategy} 胜率→${newWinRate}% 交易数→${newTrades} 盈亏=${trade.profit}`);
        }
      }
    }

    // P0修复: 同时更新原始买入策略的统计(如果存在)
    if (trade.trade_type === 'sell' && trade.original_strategy) {
      updateStrategyStats(trade.original_strategy, trade);
      console.log(`[策略统计] 更新原始策略 ${trade.original_strategy}: 盈亏=${trade.profit}`);
    }

    // 更新策略统计
    updateStrategyStats(trade.strategy || 'unknown', trade);
  } catch (e) {
    console.error('记录回测数据失败:', e.message);
  }
}
function updateStrategyStats(strategy, trade) {
  try {
    const existing = db.prepare('SELECT * FROM strategy_backtest_stats WHERE strategy = ?').get(strategy);

    if (existing) {
      const newTotal = existing.total_trades + 1;
      const newWin = existing.win_trades + (trade.profit > 0 ? 1 : 0);
      const newLose = existing.lose_trades + (trade.profit <= 0 ? 1 : 0);
      const newTotalProfit = existing.total_profit + (trade.profit || 0);
      const newAvgProfit = newTotalProfit / newTotal;
      const newWinRate = newWin / newTotal * 100;

      db.prepare(`
        UPDATE strategy_backtest_stats
        SET total_trades = ?, win_trades = ?, lose_trades = ?,
            total_profit = ?, avg_profit = ?, win_rate = ?, update_time = ?
        WHERE strategy = ?
      `).run(newTotal, newWin, newLose, newTotalProfit, newAvgProfit, newWinRate, bjNow(), strategy);
    } else {
      db.prepare(`
        INSERT INTO strategy_backtest_stats (strategy, total_trades, win_trades, lose_trades, total_profit, avg_profit, win_rate)
        VALUES (?, 1, ?, ?, ?, ?, ?)
      `).run(strategy, trade.profit > 0 ? 1 : 0, trade.profit <= 0 ? 1 : 0, trade.profit || 0, trade.profit || 0, trade.profit > 0 ? 100 : 0);
    }
  } catch (e) {
    console.error('更新策略统计失败:', e.message);
  }
}

function getBacktestReport() {
  const history = db.prepare(`
    SELECT * FROM shundi_backtest_history
    ORDER BY trade_date DESC LIMIT 100
  `).all();

  const stats = db.prepare('SELECT * FROM strategy_backtest_stats ORDER BY win_rate DESC').all();

  const totalProfit = history.reduce((sum, t) => sum + (t.profit || 0), 0);
  const winTrades = history.filter(t => t.profit > 0).length;
  const totalTrades = history.length;
  const winRate = totalTrades > 0 ? winTrades / totalTrades * 100 : 0;

  return {
    summary: {
      totalTrades,
      winTrades,
      loseTrades: totalTrades - winTrades,
      winRate: winRate.toFixed(2),
      totalProfit: totalProfit.toFixed(2),
      avgProfit: totalTrades > 0 ? (totalProfit / totalTrades).toFixed(2) : 0
    },
    strategyStats: stats,
    recentTrades: history.slice(0, 20)
  };
}


// ═══════════════════════════════════════════════════════════════
// P2: 交易成本模型(滑点+冲击成本)
// ═══════════════════════════════════════════════════════════════
function calculateTradingCost(amount, direction = 'buy', marketCondition = 'normal') {
  // 基础佣金费率
  const commissionRate = 0.00025; // 万2.5
  const minCommission = 5; // 最低佣金5元

  // 印花税(仅卖出收取)
  const stampTax = direction === 'sell' ? amount * 0.001 : 0; // 千1

  // 滑点成本(基于金额和市场条件)
  let slippageRate;
  if (marketCondition === 'bull') {
    slippageRate = 0.001; // 牛市滑点1%
  } else if (marketCondition === 'bear') {
    slippageRate = 0.0015; // 熊市滑点1.5%
  } else {
    slippageRate = 0.0005; // 正常0.5%
  }

  // 大额交易冲击成本
  let impactRate = 0;
  if (amount > 50000) impactRate = 0.001;
  if (amount > 100000) impactRate = 0.002;
  if (amount > 200000) impactRate = 0.003;

  const commission = Math.max(minCommission, amount * commissionRate);
  const slippageCost = amount * slippageRate;
  const impactCost = amount * impactRate;
  const totalCost = commission + stampTax + slippageCost + impactCost;

  return {
    commission,
    stampTax,
    slippageCost,
    impactCost,
    totalCost,
    costRate: totalCost / amount * 100 // 成本率%
  };
}

// 修改executeTrade中的成本计算

// ═══════════════════════════════════════════════════════════════
// 长期优化3: 多账户协同策略系统
// ═══════════════════════════════════════════════════════════════
function advancedMultiAccountAnalysis() {
  // 获取舜帝持仓
  const shundiHoldings = db.prepare("SELECT * FROM shundi_mock_holdings").all();

  // 获取用户实际持仓(如果有的话)
  const userHoldings = db.prepare("SELECT code, name, shares, avg_cost as cost_price, current_price, market_value FROM mock_holdings LIMIT 100").all();

  // 分析持仓差异
  const shundiCodes = new Set(shundiHoldings.map(h => h.code));
  const userCodes = new Set(userHoldings.map(h => h.code));

  // 舜帝持有但用户没有的股票(建议建仓)
  const recommendBuy = [...shundiCodes].filter(c => !userCodes.has(c));

  // 用户持有但舜帝没有的股票(建议减仓或观望)
  const recommendWatch = [...userCodes].filter(c => !shundiCodes.has(c));

  // 共同持有的股票(策略共振,可以加仓)
  const commonHoldings = [...shundiCodes].filter(c => userCodes.has(c));

  // 计算套利机会
  const arbitrageOpportunities = [];
  shundiHoldings.forEach(sh => {
    const userH = userHoldings.find(uh => uh.code === sh.code);
    if (userH) {
      const shundiAvgCost = sh.avg_cost;
      const userAvgCost = userH.avg_cost;
      const costDiff = (shundiAvgCost - userAvgCost) / userAvgCost * 100;

      // 如果舜帝成本比用户低5%以上,可能是加仓机会
      if (costDiff < -5) {
        arbitrageOpportunities.push({
          code: sh.code,
          name: sh.name,
          type: '成本优势',
          shundiCost: shundiAvgCost.toFixed(2),
          userCost: userAvgCost.toFixed(2),
          diff: costDiff.toFixed(2),
          suggestion: '舜帝成本低,可考虑加仓'
        });
      }
    }
  });

  return {
    shundiHoldings: shundiHoldings.length,
    userHoldings: userHoldings.length,
    commonHoldings: commonHoldings.length,
    recommendBuy: recommendBuy.slice(0, 10),
    recommendWatch: recommendWatch.slice(0, 10),
    arbitrageOpportunities,
    synergyScore: commonHoldings.length / Math.max(shundiHoldings.length, 1) * 100
  };
}

function syncStrategyToUserHoldings() {
  // 将舜帝的高质量策略同步到用户持仓建议
  const shundiHoldings = db.prepare("SELECT * FROM shundi_mock_holdings").all();
  const signals = db.prepare(`
    SELECT * FROM trade_signals
    WHERE confidence >= 80 AND signal = 'buy'  -- 【P0修复2026-05-06】提高阈值: 70%→80%
    ORDER BY confidence DESC LIMIT 10
  `).all();

  const recommendations = [];

  shundiHoldings.forEach(h => {
    const sig = signals.find(s => s.code === h.code);
    if (sig) {
      recommendations.push({
        code: h.code,
        name: h.name,
        action: 'sync_buy',
        reason: `舜帝持仓+高置信度信号(${sig.confidence}%)`,
        shundiShares: h.shares,
        shundiCost: h.avg_cost.toFixed(2),
        currentPrice: h.current_price.toFixed(2),
        confidence: sig.confidence
      });
    }
  });

  // 清空旧的同步建议
  db.prepare("DELETE FROM selection_history WHERE source = 'sync'").run();

  // 保存新的同步建议
  recommendations.forEach(rec => {
    db.prepare(`
      INSERT INTO selection_history (code, name, source, reason, create_time)
      VALUES (?, ?, 'sync', ?, ?)
    `).run(rec.code, rec.name, rec.reason, bjNow());
  });

  return recommendations;
}

