// ── ML自动训练调度器 ─────────────────────────────────────
async function checkAndTrainIfNeeded() {
  try {
    // 1. 检查CPU负载（临时强制训练模式：跳过CPU检查）
    const cpuLoad = os.loadavg()[0];
    const cpuCores = os.cpus().length;
    const cpuPercent = (cpuLoad / cpuCores) * 100;
    // 【强制训练模式】直接跳过CPU检查，注释掉阻止训练的逻辑
    /*
    if (cpuPercent > 95) {
      console.log(`[ML-Scheduler] CPU负载过高 (${cpuPercent.toFixed(1)}%), 跳过训练`);
      return;
    }
    */
    console.log(`[ML-Scheduler] 【强制训练】CPU=${cpuPercent.toFixed(1)}%, 强制触发训练`);
    // 2. 检查当前训练中的模型数
    const trainingCount = Object.values(_manualTrainState || {}).filter(s => s && s.status === 'training').length;
    if (trainingCount >= 2) {
      console.log(`[ML-Scheduler] 已有 ${trainingCount} 个模型在训练, 跳过`);
      return;
    }
    // 3. 找出需要训练的模型 (idle 或 24小时过期)
    const needTraining = db.prepare(`
      SELECT model_id, status, checkpoint_at
      FROM ml_training_checkpoint
      WHERE status = 'idle'
         OR (status = 'completed' AND datetime('now', '-1 day') > checkpoint_at)
      ORDER BY CASE WHEN status = 'idle' THEN 1 ELSE 2 END, checkpoint_at ASC
      LIMIT 1
    `).all();
    if (!needTraining || needTraining.length === 0) {
      // console.log('[ML-Scheduler] 所有模型都是最新的, 无需训练');
      return;
    }
    const modelId = needTraining[0].model_id;
    console.log(`[ML-Scheduler] 自动触发训练: ${modelId}`);
    // 4. 加载ML模型处理器
    if (!globalThis._mlModels) {
      try {
        const mod = await import('./ml_models.mjs');
        globalThis._mlModels = mod.ML_MODELS;
      } catch(e) {
        try {
          const mod2 = await import('./ml_models.mjs');
          globalThis._mlModels = mod2.ML_MODELS;
        } catch(e2) {
          console.error('[ML-Scheduler] 加载ML模型失败:', e2.message);
          return;
        }
      }
    }
    const mlHandler = globalThis._mlModels[modelId];
    if (!mlHandler) {
      console.warn(`[ML-Scheduler] 未找到模型处理器: ${modelId}`);
      return;
    }
    // 5. 更新状态并触发训练(Worker线程,非阻塞主线程)
    if (!_manualTrainState[modelId]) _manualTrainState[modelId] = {};
    _manualTrainState[modelId].status = 'training';
    _manualTrainState[modelId].progress = 0;
    _manualTrainState[modelId].treesBuilt = 0;
    _manualTrainState[modelId].totalTrees = 100;
    _manualTrainState[modelId].startTime = Date.now();
    _manualTrainState[modelId].error = null;
    _manualTrainState[modelId].lastResult = null;

    const workerPath = join(__dirname, 'ml_train_worker.mjs');
    const worker = new Worker(workerPath);
    const stateKey = modelId;

    worker.on('message', (msg) => {
      if (msg.type === 'started') {
        console.log(`[ML-Scheduler] ${mlHandler.name} 训练开始`);
      } else if (msg.type === 'completed') {
        const result = msg.result;
        _manualTrainState[stateKey].status = result.success ? 'completed' : 'failed';
        _manualTrainState[stateKey].lastResult = result;
        _manualTrainState[stateKey].progress = 100;
        if (result.success) {
          db.prepare('INSERT OR REPLACE INTO ai_ml_model (id, data) VALUES (?, ?)').run(
            stateKey, JSON.stringify({ ...result, phase: mlHandler.phase, modelName: mlHandler.name })
          );
          try {
            db.prepare(`UPDATE ml_training_checkpoint SET status = 'completed' WHERE model_id = ?`).run(stateKey);
          } catch(e) {}
          console.log(`[ML-Scheduler] ${mlHandler.name} 完成: ${result.sample_count}样本`);
        } else {
          _manualTrainState[stateKey].error = result.error;
          console.error(`[ML-Scheduler] ${mlHandler.name} 失败:`, result.error);
        }
        worker.terminate().catch(() => {});
      } else if (msg.type === 'error') {
        _manualTrainState[stateKey].status = 'failed';
        _manualTrainState[stateKey].error = msg.error;
        console.error(`[ML-Scheduler] ${mlHandler.name} 错误:`, msg.error);
        // [Fix 2026-05-30] Persist failure to DB to prevent infinite retry
        try {
          const db2 = new (require('better-sqlite3'))(join(__dirname, '../database/stocks.db'));
          db2.prepare(`INSERT OR REPLACE INTO ml_training_checkpoint (model_id, status, last_error, last_updated) VALUES (?, 'failed', ?, ?)`).run(
            stateKey, String(msg.error).slice(0,500), new Date().toISOString()
          );
          db2.close();
        } catch(e) { console.error('[ML-Scheduler] Failed to save checkpoint:', e.message); }
        worker.terminate().catch(() => {});
      } else if (msg.type === 'progress') {
        if (_manualTrainState[stateKey]) {
          _manualTrainState[stateKey].progress = msg.progress || 0;
          _manualTrainState[stateKey].treesBuilt = msg.treesBuilt || 0;
          _manualTrainState[stateKey].totalTrees = msg.totalTrees || 100;
        }
      }
    });

    worker.on('error', (err) => {
      _manualTrainState[modelId].status = 'failed';
      _manualTrainState[modelId].error = err.message;
      console.error(`[ML-Scheduler] Worker 错误:`, err.message);
    });

    worker.on('exit', (code) => {
      if (code !== 0 && _manualTrainState[modelId]?.status === 'training') {
        // 只在error handler未触发时才覆盖错误信息
        _manualTrainState[modelId].status = 'failed';
        _manualTrainState[modelId].error = `Worker 退出码: ${code}`;
        console.error(`[ML-Scheduler] Worker 异常退出: ${code}`);
      }
    });

    // 启动 Worker
    worker.postMessage({ modelId, options: { targetSampleCount: 20000 }, dbPath: join(__dirname, '../database/stocks.db') });
  } catch(e) {
    console.error('[ML-Scheduler] 调度器异常:', e.message);
  }
}
