// 🔧 修复EADDRINUSE: 端口被占用时自动清理并重试
server.on('error', async (err) => {
  if (err.code === 'EADDRINUSE') {
    const fs = await import('fs');
    const logMsg = `\n[${new Date().toISOString()}] EADDRINUSE: port ${PORT} in use, cleaning up...\n`;
    try { fs.default.appendFileSync(path.join(PROJECT_ROOT, 'logs', 'eaddrinuse.log'), logMsg); } catch(e) {}
    // 尝试kill占用端口的进程
    try {
      const { execSync } = await import('child_process');
      const pid = execSync(`lsof -ti:${PORT}`).toString().trim();
      if (pid) { execSync(`kill -9 ${pid}`); }
    } catch(e) {}
    // 3秒后重试
 console.log('[DEBUG] 准备启动HTTP服务器...');
  }
});

